-- Dumping structure for procedure idesk.sp_auto_change_ticket_status
DELIMITER //
CREATE PROCEDURE `sp_auto_change_ticket_status`()
BEGIN

    DECLARE v_done_updated INT DEFAULT 0;
    DECLARE v_done_history INT DEFAULT 0;

    DECLARE v_invoice_updated INT DEFAULT 0;
    DECLARE v_invoice_history INT DEFAULT 0;


    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;


    START TRANSACTION;


    /* ============================================================
       RULE 1
       condition_done
       =>
       condition_acepted_test_auto
       after 10 days
       ============================================================ */


    UPDATE tickets t

    INNER JOIN status s
        ON s.id = (
            SELECT MAX(s2.id)
            FROM status s2
            WHERE s2.part_id = t.id
              AND s2.part_name = 'tickets'
        )

    SET t.status = 'condition_acepted_test_auto'

    WHERE LOWER(t.status) = 'condition_done'
      AND LOWER(s.status_name) = 'condition_done'
      AND s.creation_date <= DATE_SUB(NOW(), INTERVAL 10 DAY);


    SET v_done_updated = ROW_COUNT();


    /*
     * ثبت History
     *
     * این بخش علاوه بر رکوردهایی که همین الان Update شدند،
     * تیکت‌هایی مثل 1528 را هم Repair می‌کند که:
     *
     * tickets.status قبلاً تغییر کرده
     * ولی status history هنوز condition_done است.
     */

        part_id,
        status_name,
        part_name,
        user_id,
        admin_id,
        rbac_id,
        view_from,
        view_to,
        status_description
    )

    SELECT
        t.id,
        'condition_acepted_test_auto',
        'tickets',

        NULL,
        NULL,

        s.rbac_id,

        0,
        0,

        'Auto status change: condition_done -> condition_acepted_test_auto after 10 days'

    FROM tickets t

    INNER JOIN status s
        ON s.id = (
            SELECT MAX(s2.id)
            FROM status s2
            WHERE s2.part_id = t.id
              AND s2.part_name = 'tickets'
        )

    WHERE LOWER(t.status) = 'condition_acepted_test_auto'
      AND LOWER(s.status_name) = 'condition_done'
      AND s.creation_date <= DATE_SUB(NOW(), INTERVAL 10 DAY);


    SET v_done_history = ROW_COUNT();



    /* ============================================================
       RULE 2
       condition_invoice
       =>
       condition_acepted_invoice_auto
       after 12 days
       ============================================================ */


    UPDATE tickets t

    INNER JOIN status s
        ON s.id = (
            SELECT MAX(s2.id)
            FROM status s2
            WHERE s2.part_id = t.id
              AND s2.part_name = 'tickets'
        )

    SET t.status = 'condition_acepted_invoice_auto'

    WHERE LOWER(t.status) = 'condition_invoice'
      AND LOWER(s.status_name) = 'condition_invoice'
      AND s.creation_date <= DATE_SUB(NOW(), INTERVAL 12 DAY);


    SET v_invoice_updated = ROW_COUNT();


        part_id,
        status_name,
        part_name,
        user_id,
        admin_id,
        rbac_id,
        view_from,
        view_to,
        status_description
    )

    SELECT
        t.id,
        'condition_acepted_invoice_auto',
        'tickets',

        NULL,
        NULL,

        s.rbac_id,

        0,
        0,

        'Auto status change: condition_invoice -> condition_acepted_invoice_auto after 12 days'

    FROM tickets t

    INNER JOIN status s
        ON s.id = (
            SELECT MAX(s2.id)
            FROM status s2
            WHERE s2.part_id = t.id
              AND s2.part_name = 'tickets'
        )

    WHERE LOWER(t.status) = 'condition_acepted_invoice_auto'
      AND LOWER(s.status_name) = 'condition_invoice'
      AND s.creation_date <= DATE_SUB(NOW(), INTERVAL 12 DAY);


    SET v_invoice_history = ROW_COUNT();


    COMMIT;


    /*
     * فقط برای اینکه هنگام تست ببینیم چه اتفاقی افتاده
     */
    SELECT
        v_done_updated     AS done_tickets_updated,
        v_done_history     AS done_status_inserted,
        v_invoice_updated  AS invoice_tickets_updated,
        v_invoice_history  AS invoice_status_inserted;

END//
DELIMITER ;

