	(165, 10, NULL, 368, 4, 'tickets', 163, 22, 'با سلام \r\nجهت  ارتقا tls  ارتباط هر دوسوییچ با شاپرک، امادگی لازم را داشته باشید.', 0, 0, 0, 1, '2024-10-26 09:10:16', '2024-10-26 09:10:16'),
	(166, NULL, 27, 369, 2, 'tickets', NULL, NULL, 'با سلام و احترام\r\nلطفا در صورت امکان جزییات بیشتری اعلام بفرمایید\r\nبرای نمونه شماره سندی که نیاز به برگشت دارد را اعلام بفرمایید.', 0, 0, 0, 1, '2024-10-26 09:12:24', '2024-10-26 09:12:24'),
	(167, NULL, 27, 366, 2, 'tickets', NULL, NULL, 'با سلام و احترام\r\nپیرو بررسی های بعمل آمده مشخص گردید قابلیت های کارت (کف و سقف مبلغ برای مانده گیری) درست تعریف نشده است لطفا موارد مذکور بررسی و رفع گردد و مجدد تست شود.', 0, 0, 0, 1, '2024-10-26 09:24:07', '2024-10-26 09:24:07'),
	(168, NULL, 22, 370, 2, 'tickets', NULL, NULL, 'با سلام و احترام\r\nعملکرد سوئیچ درست می باشد، تسهیم دوبار اعمال شده است. لطفا برای برداشتن تسهیم رکورد مورد نظر پاک نشود و در صورت عدم نیاز غیر فعال گردد.', 0, 1, 0, 1, '2024-10-27 05:12:04', '2024-10-27 06:31:43'),
	(169, NULL, 22, 372, 2, 'tickets', NULL, NULL, 'با سلام\r\nلطفا هر دو مرجع ارسال شود', 0, 1, 0, 1, '2024-10-27 06:15:26', '2024-10-27 06:31:42'),
	(170, 31, NULL, 372, 8, 'tickets', NULL, NULL, 'با درود\r\nکد مرجع های 2 تراکنش\r\n990019194089,990019194050', 0, 0, 0, 1, '2024-10-27 06:28:03', '2024-10-27 06:28:03'),
	(171, 31, NULL, 370, 8, 'tickets', NULL, NULL, 'با درود\r\nدیتا فنی ارائه بدهید  یعنی چی حذف نکنید؟ ما به دیتابیس شما دسترسی نداریم که بخواهیم رکوردی را حذف کنیم، بر روی سامانه داخلی هم که اطلاعات توسط زمانبند برای شما ارسال می گردد اصلا کاربر امکان حذف نداردو غیر فعال کرده اند تسهیم را\r\nتنها موردی حذف شده است شریک تجاری بوده، این پاسخ کلی و بدون ارائه موارد فنی غیر قابل قبول است، مدتی است این مشکل هم برای محدودیت رسید، تسهیم و .. وجود دارد و اگر مورد کاربری نیز وجود دارد باید با پاسخ فنی وارد را عنوان کنید تا مشکل پیدا شود\r\n\r\n', 0, 0, 0, 1, '2024-10-27 07:02:38', '2024-10-27 07:02:38'),
	(172, NULL, 22, 372, 2, 'tickets', NULL, NULL, 'با سلام و احترام\r\nمورد بررسی و رفع گردید.', 0, 1, 0, 1, '2024-10-27 07:43:19', '2024-10-27 07:52:50'),
	(173, NULL, 9, 356, 2, 'tickets', NULL, NULL, 'با سلام و احترام\r\nتنظیمات وب سرویس انجام شد، به دلیل اینکه تست تراکنش باید با کارت مرتبط با پروژه مذکور انجام شود، لطفا تست بفرمائید، نتیجه تست را اعلام نمائید', 0, 0, 0, 1, '2024-10-28 07:44:45', '2024-10-28 07:44:45'),
	(174, NULL, 9, 339, 2, 'tickets', NULL, NULL, 'با سلام و احترام\r\n\r\nاین مورد رو بک آفیس تست شد و خروجی گزارش تغییر میکند بعد از تغییر فیلتر تاریخ\r\nخواهشمند است نمونه اعلام نمائید', 0, 0, 0, 1, '2024-10-28 07:53:47', '2024-10-28 07:53:47'),
	(175, NULL, 22, 372, 2, 'tickets', NULL, NULL, 'با سلام و احترام\r\nموضوع پیش آمده مربوط به بروزرسانی سوئیچ های سپ جهت مهاجرت به شاپرک 2 بوده که به دلیل عدم درخواست سابین و بروز نبودن سوئیچ آن شرکت اختلال رخ داده است. علی ایها الحال سویچ سابین نیز بروزرسانی گردید و موضوع مد نظر روز یکشنبه مورخ 1403/08/06مرتفع گردید.', 0, 1, 0, 1, '2024-10-28 09:26:28', '2024-10-28 11:32:11'),
	(176, NULL, 9, 316, 2, 'tickets', NULL, NULL, 'با سلام و احترام\r\nاین درخواست به دلایل Business ای قابل انجام نمی باشد\r\nگروه کارت جزو مدلهایی هست که اگر به اشتباه ایجاد گردد، میبایست برای حذف آن اعلام نمائید', 0, 0, 0, 1, '2024-10-28 10:30:56', '2024-10-28 10:30:56'),
