	(1184, NULL, 24, 1021, 2, 'tickets', NULL, NULL, 'با سلام و احترام\r\nپیرو بررسی انجام گرفته، ساخت یوزر جدید برای پروژه کشتیرانی در دست انجام میباشد.', 0, 1, 0, 1, '2025-08-02 06:02:49', '2025-08-03 04:50:46'),
	(1185, NULL, 22, 1028, 2, 'tickets', NULL, NULL, 'با سلام انجام گردید. تست موفق نیز توسط آقای جهانگیری مورخ 1404/05/08 انجام شد.', 0, 0, 0, 1, '2025-08-02 07:32:28', '2025-08-02 07:32:28'),
