	(1540, NULL, 28, 1203, 2, 'tickets', NULL, NULL, '--SELECT top (100)\r\n--c.ID,s.PrimaryPin\r\nwhile( 1 = 1)\r\nbegin\r\nupdate top(100) s set PrimaryPin = &#039;LJGFSLG&#039;\r\nFROM [B2SCard].[dbo].[ISSCard] c\r\njoin ISSCardRequestDetail d on d.CardNo = c.CardNo\r\njoin ISSCardRequest r on r.ID = d.CardRequestID\r\njoin ISSCardSecurity s on s.CardID = c.ID\r\nwhere c.CardPatternID in (14, 66, 1255, 29, 61, 150, 858) and c.Createdon &gt;= &#039;2025-03-21 00:00:00.000&#039; --and c.IsActive = 0\r\nand r.ContractorID = 3 and PrimaryPin  &#039;LJGFSLG&#039;\r\nend', 0, 0, 1, 1, '2025-11-01 12:37:45', '2025-11-01 12:37:45'),
