	(1607, NULL, 28, 1216, 2, 'tickets', NULL, NULL, '\r\n select * \r\n--set ProjectName=a.title\r\nfrom B2SCommon.dbo.CMMCardProject as b\r\n\r\njoin importdata.dbo.NewServiceCode as a on b.ServiceCode=a.servicecode\r\n\r\nwhere flag=2 and b.ServiceCode=203\r\n\r\n\r\n\r\n\r\n', 0, 0, 1, 1, '2025-11-11 12:24:03', '2025-11-11 12:24:03'),
	(1608, 10, NULL, 1224, 4, 'tickets', NULL, NULL, 'با سلام\r\nتغییرات به صورت کامل اعمال نشه\r\nممکن است  پس از 24 ساعت، به حالت قبل یعنی فعال بودن گزینه خرید باز گشته باشد\r\n31344064\r\n31344070\r\n31344073\r\nو ....\r\n', 0, 0, 0, 1, '2025-11-12 05:21:55', '2025-11-12 05:21:55'),
	(1609, 10, NULL, 1221, 4, 'tickets', NULL, NULL, 'با سلام \r\nهمچنان برای ترمینال ها این مشکل وجود دارد به پیوست نمونه ارسال شده است', 0, 0, 0, 1, '2025-11-12 07:06:27', '2025-11-12 07:06:27'),
