	(1634, NULL, 28, 1240, 2, 'tickets', NULL, NULL, '\r\n\r\n	select \r\n	CardNo,g.Title as CardGruop,P.Title as CardPattern,T.Title as CardType,b2smain.[dbo].[ToPersianDate](I.Createdon) as CreateOn,I.IsActive,I.IsHot,\r\n	b2smain.[dbo].[ToPersianDate](i.[ExpireDate])expireddate, i.ExtendCard\r\n	into importdata.dbo.ReportAllCardS\r\n		from B2SCard.dbo.ISSCard as I\r\n	join B2SCard.dbo.ISSCardGroup as G on I.CardGroupID=G.ID\r\n	join B2SCard.dbo.ISSCardPattern as P on P.ID=I.CardPatternID\r\n	join B2SCard.dbo.ISSCardType as T on T.ID=I.CardTypeID \r\n	where T.ID 5 and i.State = 1 and (i.IsVirtual is null or i.IsVirtual = 0)\r\n	\r\n	order by I.Createdon\r\n', 0, 0, 1, 1, '2025-11-16 12:59:47', '2025-11-16 12:59:47'),
