	(2792, NULL, 29, 1681, 2, 'tickets', NULL, NULL, 'SELECT TOP (1000) [Id]\r\n      ,[UserName]\r\n      ,[Password]\r\n      ,[FullName]\r\n      ,[Email]\r\n      ,[Key]\r\n      ,[Status]\r\n      ,[DefaultTownId]\r\n      ,[IsSupervisor]\r\n      ,[IsManager]\r\n      ,[Mac]\r\n      ,[Action]\r\n      ,[ExpirationPassDate]\r\n      ,[IsChangedByUser]\r\n      ,[FamilyName]\r\n      ,[NationalCode]\r\n      ,[AgencyName]\r\n      ,[Mobile]\r\n      ,[PersonelCode]\r\n  FROM [B2SMain].[sec].[User]\r\n  where UserName like &#039;%z.abdollahkhani%&#039;\r\n', 0, 1, 1, 1, '2026-06-07 07:22:58', '2026-06-16 09:44:26'),
