	(2838, NULL, 28, 1714, 2, 'tickets', NULL, NULL, '\r\nUPDATE y\r\nSET \r\n    y.billflag = 0,\r\n    y.voucherflag = 0\r\nFROM [B2SMain].[dbo].[AcqTerminalCapability] y\r\nJOIN [B2SMain].[dbo].[AcqTerminal] t\r\n    ON y.id = t.id\r\nWHERE EXISTS (\r\n    SELECT 1\r\n    FROM [ImportData].[dbo].[Gandom] g\r\n    WHERE g.terminalno = t.TerminalINumber\r\n)\r\n', 0, 1, 1, 1, '2026-06-13 06:20:01', '2026-06-16 09:42:47'),
