	(3117, NULL, 28, 1814, 2, 'tickets', NULL, NULL, '\r\nselect top 10 * from b2smain.dbo.AcqTerminal where TerminalINumber=32019213\r\n\r\nselect top 10 * from B2SMain.dbo.AcqCardAcceptor where id=5384900\r\n\r\n\r\nselect top 10 * from B2SMain.dbo.AcqCardAcceptorBankAccounts where PartyID=1913372\r\n', 0, 0, 1, 1, '2026-07-14 08:51:07', '2026-07-14 08:51:07'),
	(3118, NULL, 28, 1814, 2, 'tickets', NULL, NULL, 'برای ترمینال فوق دو شماره شبا در دیتابیس تعریف شده است\r\nشماره شبای ارسالی در تیکت نیز در دیتابیس موجود است\r\n', 0, 0, 1, 1, '2026-07-14 08:51:16', '2026-07-14 08:51:16'),
	(3119, NULL, 28, 1814, 2, 'tickets', NULL, NULL, 'با سلام و احترام در حال بررسی میباشد.', 0, 0, 0, 1, '2026-07-14 08:51:34', '2026-07-14 08:51:34'),
	(3120, NULL, 16, 1709, 2, 'tickets', NULL, NULL, 'پیش فاکتور اصلاحی اپلود شد', 0, 0, 0, 1, '2026-07-14 11:04:26', '2026-07-14 11:04:26'),
	(3121, NULL, 9, 1682, 2, 'tickets', NULL, NULL, 'با سلام و احترام\r\nبعد از بررسی مشخص شد این سرویس فقط برای تعریف مدل تسهیم و جزئیات میباشد\r\n(ورودی سرویس شماره ترمینال ندارد، در نتیجه بدیهی هست که بعد از صدا زدن این سرویس تسهیم به ترمینال تخصیص داده نمیشود)\r\nبا سپاس', 0, 0, 0, 1, '2026-07-14 11:05:15', '2026-07-14 11:05:15'),
	(3122, 10, NULL, 1770, 4, 'tickets', NULL, NULL, 'نمونه ترمینال های که صنف اصلاح نشده \r\n20005988 صنف 5541\r\n\r\n30877607 صنف 9805\r\n\r\n\r\n', 0, 0, 0, 1, '2026-07-14 11:44:22', '2026-07-14 11:44:22'),
	(3123, NULL, 27, 1813, 2, 'tickets', NULL, NULL, 'باسلام \r\nپیرو مذاکره اقای صدوقیان با اقای عظیمی مقادیر ارسال شده از پوز اشتباه است ، به اقای عظیمی توضیحات تکمیلی داده شده است.', 0, 0, 0, 1, '2026-07-15 06:37:04', '2026-07-15 06:37:04'),
	(3124, NULL, 27, 1563, 2, 'tickets', NULL, NULL, 'با سلام و احترام\r\n\r\nپیرو بررسی‌ها و پیگیری‌های به‌عمل‌آمده، این تراکنش از نظر سوییچ موفق بوده است؛ زیرا دارای تراکنش 220 موفق بوده و مقادیر ResponseCode و RevFlag هر دو برابر با صفر می‌باشند.\r\n\r\nدر این شرایط، تراکنش از دید سوییچ به‌صورت قطعی موفق تلقی شده و وجه می‌بایست به حساب پذیرنده واریز گردد. همچنین با توجه به اینکه RevFlag برای این تراکنش ست نشده است، تراکنش به‌صورت کامل در فرم 9 نیز قرار خواهد گرفت.', 0, 0, 1, 1, '2026-07-15 10:44:59', '2026-07-15 10:44:59'),
	(3125, NULL, 28, 1730, 2, 'tickets', NULL, NULL, '\r\n\r\n--from 2025-06-22\r\n--to 2026-04-21\r\n', 0, 0, 1, 1, '2026-07-15 10:53:51', '2026-07-15 10:53:51'),
	(3126, NULL, 28, 1730, 2, 'tickets', NULL, NULL, '-------------------------------------\r\nSELECT c.CardNo,g.BalanceAmount,g.DocumentDetailDate\r\nFROM B2SCard.dbo.ISSCard AS C\r\nLEFT JOIN B2SAccounting.dbo.GLDocumentDetail AS G\r\n    ON C.MainAccountID = G.AccountID\r\n   AND G.DocumentDetailDate ', 0, 0, 1, 1, '2026-07-15 10:56:56', '2026-07-15 10:56:56'),
	(3127, NULL, 29, 1819, 2, 'tickets', NULL, NULL, 'با سلام و احترام\r\nشماره مرجع اعلامی در دیتابیس موجود نمی باشد لطفا شماره مرجع صحیح را ارسال فرمایید.', 0, 0, 0, 1, '2026-07-15 10:57:46', '2026-07-15 10:57:46'),
	(3128, NULL, 28, 1816, 2, 'tickets', NULL, NULL, 'با سلام و احترام پورت باز میباشد.\r\nلطفا تست کرده و نتیجه را اطلاع دهید.\r\nبا تشکر', 0, 0, 0, 1, '2026-07-15 10:58:29', '2026-07-15 10:58:29'),
	(3129, NULL, 9, 1598, 2, 'tickets', NULL, NULL, 'با سلام و احترام\r\nبا توجه به صورت جلسه ثبت شده برای پروژه BNPL تمامی موارد انجام گردید\r\nبا سپاس', 0, 0, 0, 1, '2026-07-15 10:59:36', '2026-07-15 10:59:36'),
	(3130, NULL, 9, 1597, 2, 'tickets', NULL, NULL, 'با سلام و احترام\r\nتمامی موارد انجام شد بر روی بک آفیس نسخه تست آلفا پابلیش انجام شد\r\nبعد از تست در این محیط در صورت تائید پابلیش در بک آفیس اصلی انجام خواهد شد\r\n\r\nآدرس بک آفیس TestAlfa\r\nhttps://172.25.1.70/BackOffice-TestAlfa', 0, 0, 0, 1, '2026-07-15 11:02:11', '2026-07-15 11:02:11'),
	(3131, NULL, 9, 1167, 2, 'tickets', NULL, NULL, 'این تیکت مربوط به سوئیچ میباشد پیگیری ها از سمت ما تا جای ممکن انجام شد', 0, 0, 1, 1, '2026-07-15 11:13:55', '2026-07-15 11:13:55'),
	(3132, NULL, 9, 303, 2, 'tickets', NULL, NULL, 'با سلام و احترام\r\nاین تیکت خیلی قدیمی میابشد و وضعیت انجام این تیکت مشخض نگردید\r\nنیاز به پیگیری دارد که میبایست این کار انجام شود یا خیر\r\nظاهرا نوین هم پیگیر این تیکت هست\r\nلطفا از آقای بهرنگ استعلام گردد', 0, 0, 1, 1, '2026-07-15 11:19:18', '2026-07-15 11:19:18'),
	(3133, NULL, 9, 1770, 2, 'tickets', NULL, NULL, 'انجام شد لطفا تست نمائید', 0, 0, 0, 1, '2026-07-15 11:31:16', '2026-07-15 11:31:16'),
	(3134, NULL, 29, 1753, 2, 'tickets', NULL, NULL, 'با سلام و احترام\r\nلطفا موضوع تیکت را به صورت واضح و کامل شرح دهید.', 0, 0, 0, 0, '2026-07-15 11:31:36', '2026-08-03 08:34:05'),
	(3135, 37, NULL, 1597, 9, 'tickets', NULL, NULL, 'ضمن تشکر ، پس از تست اعلام نتیجه خواهد شد.لطفا امکان دریافت خروجی اکسل نیز فراهم شود.', 0, 0, 0, 1, '2026-07-15 11:33:52', '2026-07-15 11:33:52'),
	(3136, NULL, 9, 1680, 2, 'tickets', NULL, NULL, 'با سلام و احترام\r\nاگر این به موضوع پروژه ایران کیش مرتبط هست:\r\n1- نسخه های بک افیس برای پابلیش تحویل واحد پشتیبانی داده شد\r\n2- بابت دیتابیس ها نیز میبایست تمامی دیتابیس های موجود در محیط عملیاتی مشتری انتقال پیدا کند (Generate Script)', 0, 0, 1, 1, '2026-07-15 11:35:19', '2026-07-15 11:35:19'),
	(3137, NULL, 9, 1680, 2, 'tickets', NULL, NULL, 'اگر موردی باقیمانده است که مرتبط به تیم توسعه میباشد لطفا اعلام نمائید', 0, 0, 1, 1, '2026-07-15 11:36:09', '2026-07-15 11:36:09'),
	(3138, NULL, 9, 1399, 2, 'tickets', NULL, NULL, 'کار تیم توسعه بابت کد صنف هایی اعلامی از سمت نوین (خانم کمایی) انجام شده است\r\nاین تیکت نیاز به بررسی دارد توسط تیم پشتیبانی', 0, 0, 1, 1, '2026-07-15 11:37:21', '2026-07-15 11:37:21'),
	(3139, 37, NULL, 1508, 9, 'tickets', NULL, NULL, 'طی تائیدیه ای که از خانم ها تربتی و روح اله زاده در گروه تلگرام دریافت شده ، این درخواست در دوره تعطیلی جنگ انجام شده است.با سپاس', 0, 0, 0, 1, '2026-07-15 11:46:55', '2026-07-15 11:46:55'),
	(3140, NULL, 16, 1508, 2, 'tickets', NULL, NULL, 'این تیکت بدون پیش فاکتور در زمان جنگ انجام شده باید پیش فاکتور بزنیم', 0, 0, 1, 1, '2026-07-15 12:06:13', '2026-07-15 12:06:13'),
	(3141, NULL, 27, 1563, 2, 'tickets', NULL, NULL, 'با سلام و احترام\r\n\r\nپیرو بررسی‌ها و پیگیری‌های به‌عمل‌آمده، این تراکنش از نظر سوییچ موفق بوده است؛ زیرا دارای تراکنش 220 موفق بوده و مقادیر ResponseCode و RevFlag هر دو برابر با صفر می‌باشند.\r\n\r\nدر این شرایط، تراکنش از دید سوییچ به‌صورت قطعی موفق تلقی شده و وجه می‌بایست به حساب پذیرنده واریز گردد. همچنین با توجه به اینکه RevFlag برای این تراکنش ست نشده است، تراکنش به‌صورت کامل در فرم 9 نیز قرار خواهد گرفت.', 0, 0, 0, 1, '2026-07-18 08:26:56', '2026-07-18 08:26:56'),
	(3142, NULL, 27, 1563, 2, 'tickets', NULL, NULL, 'سامان درخواست داشت که یه نامه براشون بزنیم مبنی بر اینکه سوییچ توی تراکنش های فارایی اولویتش 220 هست نه 420', 0, 0, 1, 1, '2026-07-18 08:36:13', '2026-07-18 08:36:13'),
	(3143, 10, NULL, 1251, 4, 'tickets', NULL, NULL, 'با سلام خواهشمند است جهت ایجاد دسترسی IP ها را اعلام بفرمایید', 0, 0, 0, 1, '2026-07-18 08:53:30', '2026-07-18 08:53:30'),
	(3144, 26, NULL, 1813, 5, 'tickets', NULL, NULL, 'با سلام و احترام،\r\nطی بررسی مشخص گردید مقادیر ارسالی دستگاه بنا بر قوانین شاپرک صحیح میباشد. پیرو مذاکره با اقای پرویزی ترتیبی اتخاذ فرمایید بررسی های تکمیلی در خصوص عدم بروزرسانی دیتابیس صورت پذیرد.', 0, 0, 0, 1, '2026-07-18 09:21:48', '2026-07-18 09:21:48'),
	(3145, NULL, 24, 1677, 2, 'tickets', NULL, NULL, 'با سلام و احترام\r\nپیرو بررسی های صورت گرفته و هماهنگی با آقای موسوی، این مورد به دلیل بار اناختن برروی جدول اصلی تراکشها و latency برروی دیتابیس امکان پذیر نمیاشد و میبایست از سمت dataware house   این مورد صورت گیرد.', 0, 0, 1, 1, '2026-07-18 10:14:30', '2026-07-18 10:14:30'),
	(3146, NULL, 24, 1677, 2, 'tickets', NULL, NULL, 'با سلام و احترام\r\nپیرو بررسی های صورت گرفته، این مورد به دلیل بار انداختن برروی جدول اصلی تراکشها و latency برروی دیتابیس امکان پذیر نمیاشد و میبایست از سمت dataware house رفاه پردیس این مورد صورت گیرد.\r\n\r\nبا تشکر\r\n', 0, 0, 0, 1, '2026-07-18 10:16:08', '2026-07-18 10:16:08'),
	(3147, NULL, 24, 1818, 2, 'tickets', NULL, NULL, 'در حال بررسی', 0, 0, 1, 1, '2026-07-18 10:21:19', '2026-07-18 10:21:19'),
	(3148, NULL, 24, 1812, 2, 'tickets', NULL, NULL, ' --Corect\r\n   SELECT\r\n    B2STxn.dbo.FromBase64(ISNULL(ca.PanHash, N&amp;#039;MDA=&amp;#039;)) AS pan,\r\n    gp.Title\r\nFROM [B2SMain].[dbo].[AcqCardGroup] gp WITH (NOLOCK)\r\nINNER JOIN [B2SMain].[dbo].[AcqCard] ca WITH (NOLOCK)\r\n    ON ca.CardGroupId = gp.ID\r\n\r\n', 0, 0, 1, 1, '2026-07-18 10:44:09', '2026-07-18 10:44:09'),
	(3149, NULL, 24, 1812, 2, 'tickets', NULL, NULL, 'با سلام و احترام \r\nانجام گردید.', 0, 0, 0, 1, '2026-07-18 10:44:27', '2026-07-18 10:44:27'),
	(3150, NULL, 22, 1824, 2, 'tickets', NULL, NULL, 'با سلام\r\nمقرر گردید آقای موسوی زمان را اعلام کنند', 0, 0, 1, 1, '2026-07-18 11:38:59', '2026-07-18 11:38:59'),
	(3151, 37, NULL, 1769, 9, 'tickets', 3042, 9, 'با سلام و احترام، با توجه به اصلاحیه ای که روی تیکت سیمفا نیز اعمال شد قرار بر ایجاد محدودیت در 31X بجای 3X شده است.لطفا تغییرات مورد نیاز را  بر این اساس بازنگری و اعمال فرمائید. با سپاس', 0, 0, 0, 1, '2026-07-18 13:19:18', '2026-07-18 13:19:18'),
	(3152, NULL, 28, 1813, 2, 'tickets', NULL, NULL, 'با سلام و احترام مقادیر ارسالی از سمت پوز اشتباه میباشد.\r\nلطفا بررسی و اصلاح نمایید.\r\nهمچنین به صورت حضوری توضیحات به مهندس عظیمی داده شده است.', 0, 0, 0, 1, '2026-07-19 09:15:08', '2026-07-19 09:15:08'),
	(3153, NULL, 16, 1792, 2, 'tickets', NULL, NULL, 'طبق تاییداقای مقدم پیش فاکتور نیاز ندارد', 0, 0, 1, 1, '2026-07-19 11:59:20', '2026-07-19 11:59:20'),
	(3154, NULL, 16, 1541, 2, 'tickets', NULL, NULL, 'طبق تاییداقای مقدم پیش فاکتور نیاز ندارد', 0, 0, 1, 1, '2026-07-19 11:59:41', '2026-07-19 11:59:41'),
	(3155, NULL, 16, 1167, 2, 'tickets', NULL, NULL, 'طبق ارجاع ردیف 35 نامه 12096 درخواست کنسل است.( از سمت پارسیان)', 0, 0, 0, 1, '2026-07-19 12:06:56', '2026-07-19 12:06:56'),
	(3156, NULL, 16, 1167, 2, 'tickets', NULL, NULL, 'این تیکت تاییدپیش فاکتور ندارد', 0, 0, 1, 1, '2026-07-19 12:07:56', '2026-07-19 12:07:56'),
	(3157, NULL, 27, 1818, 2, 'tickets', NULL, NULL, 'با سلام و احترام\r\n\r\nکاربر با مشخصات زیر بر روی دیتابیس 54  ایجاد گردید.\r\n\r\nدسترسی‌های این کاربر مطابق هماهنگی انجام‌شده با سرکار خانم کمایی تنظیم شده و صرفاً بر روی دیتابیس‌های زیر اعمال گردیده است:\r\n\r\n* **B2STxn**\r\n\r\nUsername:pna-read\r\n**Password:** `...`\r\n', 0, 0, 0, 1, '2026-07-19 12:26:59', '2026-07-19 12:59:20'),
	(3158, NULL, 24, 1810, 2, 'tickets', NULL, NULL, 'با سلام و احترام\r\nبا استحضار میرساند، مانور سایت پشتیبان در تاریخ 26 تیر ماه از ساعت 00:00 بامداد الی 12 با حضور آقایان ایمنی، افشار و بهشتی انجام گردید.\r\n', 0, 0, 0, 1, '2026-07-19 13:19:30', '2026-07-19 13:19:30'),
	(3159, NULL, 24, 1167, 2, 'tickets', NULL, NULL, 'پیرو کامنت خانم هاشمی، این تیکت از انجام و دستور کار خارج شده است.', 0, 0, 1, 1, '2026-07-19 13:24:51', '2026-07-19 13:24:51'),
	(3160, NULL, 27, 1832, 2, 'tickets', NULL, NULL, 'با سلام \r\nلطفا شماره ترمینال ها را ارسال نمایید', 0, 0, 0, 1, '2026-07-20 08:16:31', '2026-07-20 08:16:31'),
	(3161, NULL, 27, 1832, 2, 'tickets', NULL, NULL, 'با سلام و احترام\r\n\r\nبررسی‌های لازم انجام شد و شماره شبا در دیتابیس به‌صورت صحیح ثبت شده و موجود بود.\r\nهمچنین، پیرو مذاکره تلفنی با جناب آقای پهلوان، مشکل از سمت شرکت سامان نیز برطرف شده است.', 0, 0, 0, 1, '2026-07-20 08:20:37', '2026-07-20 08:20:37'),
	(3162, 10, NULL, 1791, 4, 'tickets', NULL, NULL, 'با سلام مقرر شد این مورد سمت پرداخت نوین رفع گردد\r\n', 0, 0, 0, 1, '2026-07-20 08:33:42', '2026-07-20 08:33:42'),
	(3163, NULL, 24, 1741, 2, 'tickets', NULL, NULL, 'با سلام و احترام\r\nپیرو مکالمه تلفنی امروز با خانم کمایی، موردی برروی اپلیکیشن سان مبنی بر  خطای 500 برای تغییر حساب مشاهده نگردید.', 0, 0, 0, 1, '2026-07-20 10:23:46', '2026-07-20 10:23:46'),
	(3164, NULL, 24, 1732, 2, 'tickets', NULL, NULL, 'با سلام و احترام\r\nپیرو مکالمه تلفنی امروز با آقای پهلوان، جابجایی فیزیکی درایو H توسط واحد زیرساخت شرکت محترم سامان پرداخت انجام گردید. ', 0, 0, 0, 1, '2026-07-20 10:31:45', '2026-07-20 10:31:45'),
	(3165, NULL, 16, 1697, 2, 'tickets', NULL, NULL, 'برای این تیکت پیش فاکتور نزدیم و به صورت رایگان است و به جهت ادامه فرایند تایید پیش فاکتور زدم', 0, 0, 0, 1, '2026-07-20 10:31:54', '2026-07-20 10:31:54'),
	(3166, NULL, 24, 1732, 2, 'tickets', NULL, NULL, 'گزارش روزانه مربوط به این تیکت ثبت گردیده است.', 0, 0, 1, 1, '2026-07-20 10:38:20', '2026-07-20 10:38:20'),
	(3167, NULL, 16, 1388, 2, 'tickets', NULL, NULL, 'این نیکت  تا زمان تعیین تکلیف بسته شد', 0, 0, 0, 1, '2026-07-20 10:43:39', '2026-07-20 10:43:39'),
	(3168, NULL, 24, 1660, 2, 'tickets', NULL, NULL, 'با سلام و اخترام\r\n\r\nپیرو بررسی‌های صورت گرفته، سوییچ در صورتی که بیت ۳۵ در پیام وجود نداشته باشد، تراکنش را به شاپرک ارسال نمی‌کند و این حالت در حال حاضر کنترل می‌شود.\r\nمورد مشاهده‌شده مربوط به تراکنش‌هایی است که بیت ۳۵ از نظر ساختار پیام صحیح است، اما محتوای آن از نظر منطقی معتبر نیست. بنابراین، منشأ این مسئله عدم وجود بیت ۳۵ نیست، بلکه صحت محتوای ارسالی این فیلد است.\r\nدر صورت وجود نمونه تراکنش‌های موردنظر، لطفاً شماره مرجع یا اطلاعات آن‌ها را ارسال فرمایید تا بررسی دقیق‌تری انجام شود.\r\n\r\nبا تشکر', 0, 0, 0, 1, '2026-07-20 10:45:09', '2026-07-20 10:45:09'),
	(3169, NULL, 38, 1834, 2, 'tickets', NULL, NULL, 'هزینه واحد فروش با اقای دارایی صحبت کنند طبق آخرین استعلام توسط آقای دارای باید انجام شود و زمانبندی توسط ایشان اعلام میگردد .', 0, 0, 1, 1, '2026-07-20 10:49:57', '2026-07-20 10:49:57'),
