	(3261, NULL, 24, 1839, 2, 'tickets', NULL, NULL, 'SELECT  car.CardNo ,  car.PersianName , car.PersianFamily , Con.Destination, \r\n(SELECT top 1 Txn.CreatedOn from B2STxn.dbo.SwISSTxn  ORDER BY ID DESC) AS Last_Txn\r\n, pat.Title\r\n  FROM    B2SCard.dbo.ISSCard AS car  \r\n  INNER JOIN B2SAccounting.dbo.GLAccount Acc ON car.MainAccountID = Acc.ParentAccountID\r\n  INNER JOIN B2SAccounting.dbo.GLAccountContact Con ON Acc.ParentAccountID = Con.AccountID\r\n  INNER JOIN B2SCard.dbo.ISSCardPattern pat ON pat.ID = car.CardPatternID\r\n  INNER JOIN B2STxn.dbo.SwISSTxn txn ON car.CardNo COLLATE SQL_Latin1_General_CP1_CI_AS = txn.Pan \r\n -- INNER JOIN B2SAccounting.dbo.GLAccount Acc ON car.MainAccountID = Acc.ID\r\n  WHERE txn.Createdon &gt;= &#039;2025-03-20 00:00:00.000&#039; AND txn.Createdon ', 0, 0, 1, 1, '2026-07-29 14:18:54', '2026-07-29 14:18:54'),
