	(3528, NULL, 38, 1971, 2, 'tickets', NULL, NULL, 'خیلی با دقت شبیه این دو تا جدول ترمینال و کارت اکسپتور آپدیت کنید \r\n\r\n********* نکته خیلی مهم : کوئری برای نوین است برای سامان تغییر بدهید . ****\r\n\r\nSET NOCOUNT ON;\r\nSET DEADLOCK_PRIORITY LOW;\r\nSET LOCK_TIMEOUT 3000;\r\n\r\nDECLARE @Rows INT = 1;\r\n\r\nWHILE @Rows &gt; 0\r\nBEGIN\r\n    BEGIN TRY\r\n\r\n        UPDATE TOP (500)\r\n            [B2SMain].[dbo].[AcqTerminal] WITH (ROWLOCK, READPAST)\r\n        SET\r\n            MinTransacrionAmount = 4000\r\n        WHERE\r\n            MinTransacrionAmount &lt; 4000;\r\n\r\n        SET @Rows = @@ROWCOUNT;\r\n\r\n    END TRY\r\n    BEGIN CATCH\r\n\r\n        IF ERROR_NUMBER() = 1222\r\n        BEGIN\r\n            SET @Rows = 1;\r\n            WAITFOR DELAY &#039;00:00:01&#039;;\r\n        END\r\n        ELSE\r\n            THROW;\r\n\r\n    END CATCH;\r\n\r\n    IF @Rows = 0\r\n        BREAK;\r\n\r\n    WAITFOR DELAY &#039;00:00:00.200&#039;;\r\nEND;', 0, 0, 1, 1, '2026-09-12 06:31:42', '2026-09-12 06:31:42'),
	(3529, NULL, 29, 1972, 2, 'tickets', NULL, NULL, 'با سلام و احترام\r\nتیکت مربوط به تیم توسعه است.', 0, 0, 1, 1, '2026-09-12 07:35:00', '2026-09-12 07:35:00'),
