	(3567, NULL, 24, 1994, 2, 'tickets', NULL, NULL, 'WITH a\r\n        AS ( SELECT cu.PersianFirstName AS FirstName ,\r\n                    cu.PersianLastName AS LastName ,\r\n                    cu.FatherName AS FatherName ,\r\n                    cu.BirthCertificateNumber AS BirthCertificateNumber ,\r\n                    pa.ID AS CardPatternID ,\r\n                    p.PersianTitle AS BirthCity ,\r\n                    B2SMain.dbo.ToPersianDate(cui.BirthDate) AS BirthDate ,\r\n                    cu.NationalCodeNumber AS NationalCodeNumber ,\r\n                    cg.ID AS CardGroupID ,\r\n                    cg.Title AS GroupTitle ,\r\n                    c.CardNo AS Pan ,\r\n                    cui.MilitaryServiceCode AS OfficeCode ,\r\n                    cui.PersonnelNo AS PersonelNumber ,\r\n                    cui.Mobile AS Mobile ,\r\n                    dd.Amount AS Amount ,\r\n                    dd.RialAmount ,\r\n                    d.DocumentDate AS DocumentDate ,\r\n                    B2SMain.dbo.ToPersianDate(c.[ExpireDate]) AS CardExpireDate ,\r\n                    B2SMain.dbo.ToPersianDate(\r\n                        B2SCard.dbo.ContractCards.StartDate) AS ContractStartDate ,\r\n                    B2SMain.dbo.ToPersianDate(\r\n                        B2SCard.dbo.ContractCards.EndDate) AS ContractEndDate ,\r\n                    cui.UnitCode ,\r\n                    r.IndicatorId AS IndicatorNumber ,\r\n                    ag.ID AS AgencyID ,\r\n                    ag.Name AS AgencyTitle ,\r\n                    0 AS SegmentID ,\r\n                    N&#039;حساب اصلی&#039; AS SegmentTitle ,\r\n                    pa.Title AS PatternTitle ,\r\n                    CASE WHEN cu.GenderTypeCode = 1 THEN N&#039;زن&#039;\r\n                         ELSE N&#039;مرد&#039;\r\n                    END AS Sex ,\r\n                    depositType.PersianTitle AS DepositTypeTitle ,\r\n                    r.DepositType ,\r\n                    r.Installment AS InstallmentBit ,\r\n                    r.HasDiscount AS DiscountBit ,\r\n                    CASE WHEN r.Installment = 1 THEN N&#039;بله&#039;\r\n                         ELSE N&#039;خیر&#039;\r\n                    END AS Installment ,\r\n                    CASE WHEN r.HasDiscount = 1 THEN N&#039;بله&#039;\r\n                         ELSE N&#039;خیر&#039;\r\n                    END AS HasDiscount ,\r\n                    cg.DetailCode,\r\n					pa.Currency\r\n             FROM   B2SCard.dbo.ISSChargeRequest r WITH ( NOLOCK )\r\n                    INNER JOIN B2SCard.dbo.ISSChargeRequestDocuments crd WITH ( NOLOCK ) ON r.ID = crd.ChargeRequestId\r\n                                                                                            AND IsReversed = 0\r\n                    INNER JOIN B2SAccounting.dbo.GLDocument d WITH ( NOLOCK ) ON d.ID = crd.DocumentId\r\n                                                                                 AND d.DocumentType = 1\r\n                    INNER JOIN B2SAccounting.dbo.GLDocumentDetail dd WITH ( NOLOCK ) ON dd.DocumentID = d.ID\r\n                    INNER JOIN B2SCard.dbo.ISSCard c WITH ( NOLOCK ) ON dd.AccountID = c.MainAccountID\r\n                                                                        AND c.State = 1\r\n                    INNER JOIN B2SCard.dbo.ISSCardAdditionalInfo cai WITH ( NOLOCK ) ON c.ID = cai.CardId\r\n                    INNER JOIN B2SCard.dbo.ISSAgency ag WITH ( NOLOCK ) ON ag.ID = cai.AgencyId\r\n                    INNER JOIN B2SCard.dbo.ISSCardPattern pa WITH ( NOLOCK ) ON pa.ID = c.CardPatternID\r\n                    INNER JOIN B2SCard.dbo.ISSCardGroup cg WITH ( NOLOCK ) ON c.CardGroupID = cg.ID\r\n                    INNER JOIN B2SMain.dbo.Customer cu WITH ( NOLOCK ) ON cu.ID = c.PartyID\r\n                    INNER JOIN B2SMain.dbo.CustomerContactInfo cui WITH ( NOLOCK ) ON cui.ID = cu.ID\r\n                    LEFT OUTER JOIN B2SMain.dbo.BasicValue depositType WITH ( NOLOCK ) ON depositType.BasicTypeID = 94\r\n                                                                                          AND depositType.Identifier = r.DepositType\r\n                    LEFT OUTER JOIN B2SMain.dbo.BasicCity p WITH ( NOLOCK ) ON cu.BirthCityID = p.ID\r\n                    LEFT OUTER JOIN B2SCard.dbo.ContractCards WITH ( NOLOCK ) ON ContractCards.CardId = c.ID\r\n             UNION ALL\r\n             SELECT cu.PersianFirstName AS FirstName ,\r\n                    cu.PersianLastName AS LastName ,\r\n                    cu.FatherName AS FatherName ,\r\n                    cu.BirthCertificateNumber AS BirthCertificateNumber ,\r\n                    pa.ID AS CardPatternID ,\r\n                    p.PersianTitle AS BirthCity ,\r\n                    B2SMain.dbo.ToPersianDate(cui.BirthDate) AS BirthDate ,\r\n                    cu.NationalCodeNumber AS NationalCodeNumber ,\r\n                    cg.ID AS CardGroupID ,\r\n                    cg.Title AS GroupTitle ,\r\n                    c.CardNo AS Pan ,\r\n                    cui.MilitaryServiceCode AS OfficeCode ,\r\n                    cui.PersonnelNo AS PersonelNumber ,\r\n                    cui.Mobile AS Mobile ,\r\n                    dd.Amount AS Amount ,\r\n                    dd.RialAmount ,\r\n                    d.DocumentDate AS DocumentDate ,\r\n                    B2SMain.dbo.ToPersianDate(c.[ExpireDate]) AS CardExpireDate ,\r\n                    B2SMain.dbo.ToPersianDate(\r\n                        B2SCard.dbo.ContractCards.StartDate) AS ContractStartDate ,\r\n                    B2SMain.dbo.ToPersianDate(\r\n                        B2SCard.dbo.ContractCards.EndDate) AS ContractEndDate ,\r\n                    cui.UnitCode ,\r\n                    r.IndicatorId AS IndicatorNumber ,\r\n                    ag.ID AS AgencyID ,\r\n                    ag.Name AS AgencyTitle ,\r\n                    s.ID AS SegmentID ,\r\n                    s.Title AS SegmentTitle ,\r\n                    pa.Title AS PatternTitle ,\r\n                    CASE WHEN cu.GenderTypeCode = 1 THEN N&#039;زن&#039;\r\n                         ELSE N&#039;مرد&#039;\r\n                    END AS Sex ,\r\n                    depositType.PersianTitle AS DepositTypeTitle ,\r\n                    r.DepositType ,\r\n                    r.Installment AS InstallmentBit ,\r\n                    r.HasDiscount AS DiscountBit ,\r\n                    CASE WHEN r.Installment = 1 THEN N&#039;بله&#039;\r\n                         ELSE N&#039;خیر&#039;\r\n                    END AS Installment ,\r\n                    CASE WHEN r.HasDiscount = 1 THEN N&#039;بله&#039;\r\n                         ELSE N&#039;خیر&#039;\r\n                    END AS HasDiscount ,\r\n                    cg.DetailCode,\r\n					pa.Currency\r\n             FROM   B2SCard.dbo.ISSChargeRequest r WITH ( NOLOCK )\r\n                    INNER JOIN B2SCard.dbo.ISSChargeRequestDocuments crd WITH ( NOLOCK ) ON r.ID = crd.ChargeRequestId\r\n                                                                                            AND IsReversed = 0\r\n                    INNER JOIN B2SAccounting.dbo.GLDocument d WITH ( NOLOCK ) ON d.ID = crd.DocumentId\r\n                                                                                 AND d.DocumentType = 1\r\n                    INNER JOIN B2SAccounting.dbo.GLDocumentDetail dd WITH ( NOLOCK ) ON dd.DocumentID = d.ID\r\n                    INNER JOIN B2SAccounting.dbo.GLAccount a WITH ( NOLOCK ) ON a.ID = dd.AccountID\r\n                    INNER JOIN B2SCard.dbo.ISSCard c WITH ( NOLOCK ) ON a.ParentAccountID = c.MainAccountID\r\n                                                                        AND c.State = 1\r\n                    INNER JOIN B2SCard.dbo.ISSCardAdditionalInfo cai WITH ( NOLOCK ) ON c.ID = cai.CardId\r\n                    INNER JOIN B2SCard.dbo.ISSAgency ag WITH ( NOLOCK ) ON ag.ID = cai.AgencyId\r\n                    INNER JOIN B2SCard.dbo.ISSCardPattern pa WITH ( NOLOCK ) ON pa.ID = c.CardPatternID\r\n                    INNER JOIN B2SCard.dbo.ISSCardGroup cg WITH ( NOLOCK ) ON c.CardGroupID = cg.ID\r\n                    INNER JOIN B2SMain.dbo.Customer cu WITH ( NOLOCK ) ON cu.ID = c.PartyID\r\n                    INNER JOIN B2SMain.dbo.CustomerContactInfo cui WITH ( NOLOCK ) ON cui.ID = cu.ID\r\n                    INNER JOIN B2SCard.dbo.Segment s WITH ( NOLOCK ) ON s.HeadingId = a.AccountHeadingID\r\n                    LEFT OUTER JOIN B2SMain.dbo.BasicValue depositType WITH ( NOLOCK ) ON depositType.BasicTypeID = 94\r\n                                                                                          AND depositType.Identifier = r.DepositType\r\n                    LEFT OUTER JOIN B2SMain.dbo.BasicCity p WITH ( NOLOCK ) ON cu.BirthCityID = p.ID\r\n                    LEFT OUTER JOIN B2SCard.dbo.ContractCards WITH ( NOLOCK ) ON ContractCards.CardId = c.ID )\r\n        SELECT   a.FirstName ,\r\n                 a.LastName ,\r\n                 a.FatherName ,\r\n                 a.BirthCertificateNumber ,\r\n                 a.CardPatternID ,\r\n                 a.BirthCity ,\r\n                 a.BirthDate ,\r\n                 a.NationalCodeNumber ,\r\n                 a.CardGroupID ,\r\n                 a.GroupTitle ,\r\n                 a.Pan ,\r\n                 a.OfficeCode ,\r\n                 a.PersonelNumber ,\r\n                 a.Mobile ,\r\n                 a.Amount ,\r\n                 a.RialAmount ,\r\n                 a.DocumentDate ,\r\n                 a.CardExpireDate ,\r\n                 a.ContractStartDate ,\r\n                 a.ContractEndDate ,\r\n                 a.UnitCode ,\r\n                 a.IndicatorNumber ,\r\n                 a.AgencyID ,\r\n                 a.AgencyTitle ,\r\n                 a.SegmentID ,\r\n                 a.SegmentTitle ,\r\n                 a.PatternTitle ,\r\n                 a.Sex ,\r\n                 a.DepositTypeTitle ,\r\n                 a.DepositType ,\r\n                 a.Installment ,\r\n                 a.HasDiscount ,\r\n                 a.DetailCode,\r\n				 a.Currency\r\n        FROM     a\r\n        WHERE    a.Amount &gt; 0\r\n                 AND a.DocumentDate &gt;= &#039;2026-03-21&#039;\r\n                 AND a.DocumentDate ', 0, 0, 1, 1, '2026-09-20 07:37:20', '2026-09-20 07:37:20'),
	(3568, NULL, 29, 1992, 2, 'tickets', NULL, NULL, 'با سلام و احترام\r\nپیرو صحبت با تیم فنی مقرر شد بررسی گردد.', 0, 0, 1, 1, '2026-09-20 07:45:46', '2026-09-20 07:45:46'),
	(3569, NULL, 27, 1998, 2, 'tickets', NULL, NULL, 'با سلام و احترام\r\n\r\nتراکنش با PrCode 72 بنا به درخواست آن مجموعه پیاده‌سازی شده است. در این نوع تراکنش، RRN از سمت POS ارسال می‌شود و همان RRN در سوئیچ در نظر گرفته می‌شود.\r\n\r\nپیش‌تر نیز اعلام شده بود که به‌صورت معمول RRN ارسالی از سمت POS مورد پذیرش قرار نمی‌گیرد؛ با این حال، برای این تراکنش و بنا به درخواست مطرح‌شده، این محدودیت اعمال نشده و RRN دریافتی از POS پذیرفته می‌شود.', 0, 0, 1, 1, '2026-09-20 08:36:22', '2026-09-20 08:36:22'),
	(3570, NULL, 27, 1998, 2, 'tickets', NULL, NULL, 'با سلام و احترام\r\n\r\nتراکنش با PrCode 72 بنا به درخواست آن مجموعه پیاده‌سازی شده است. در این نوع تراکنش، RRN از سمت POS ارسال می‌شود و همان RRN در سوئیچ در نظر گرفته می‌شود.\r\n\r\nپیش‌تر نیز اعلام شده بود که به‌صورت معمول RRN ارسالی از سمت POS مورد پذیرش قرار نمی‌گیرد؛ با این حال، برای این تراکنش و بنا به درخواست مطرح‌شده، این محدودیت اعمال نشده و RRN دریافتی از POS پذیرفته می‌شود.', 0, 0, 0, 1, '2026-09-20 08:36:29', '2026-09-20 08:36:29'),
	(3571, NULL, 27, 1950, 2, 'tickets', NULL, NULL, 'با سلام و احترام\r\n\r\nپیرو مذاکره انجام‌شده با جناب آقای محمدی، مقرر گردید این تیکت جهت بررسی و انجام اقدامات لازم به واحد توسعه ارجاع گردد.', 0, 0, 1, 1, '2026-09-20 08:40:44', '2026-09-20 08:40:44'),
