	(3580, NULL, 24, 1969, 2, 'tickets', NULL, NULL, 'برروی سرور 16.40\r\n\r\n  SELECT  *  FROM [B2SCommon].[dbo].[CMMTerminalCardProject] Pro WITH(NOLOCK) \r\nINNER JOIN\r\n   [B2SCommon].[dbo].CMMCardSegment cs WITH(NOLOCK)   on cs.CardProjectID = Pro.CardProjectID\r\nINNER JOIN\r\n   [B2SCommon].[dbo].[CMMCardProject] CarPro WITH(NOLOCK) ON Pro.CardProjectID = CarPro.ID\r\n  WHERE cs.SegmentCode = 29497 AND CarPro.ServiceCode = 203 --AND CarPro.IsActive = 1\r\n  AND pro.TerminalNumber IN (\r\n  SELECT terminalNo from ImportData.dbo.DisableBuySegmentCredite2\r\n  )\r\n\r\n\r\n\r\n\r\n--آپدیت برروی رکرود های اکسل\r\n\r\n\r\n  UPDATE Pro SET Pro.IsActive = 0 from\r\n  [B2SCommon].[dbo].[CMMTerminalCardProject] Pro \r\nINNER JOIN\r\n   [B2SCommon].[dbo].CMMCardSegment cs  on cs.CardProjectID = Pro.CardProjectID\r\nINNER JOIN\r\n   [B2SCommon].[dbo].[CMMCardProject] CarPro WITH(NOLOCK) ON Pro.CardProjectID = CarPro.ID\r\n  WHERE cs.SegmentCode = 29497 AND CarPro.ServiceCode = 203 --AND CarPro.IsActive = 1\r\n  AND pro.TerminalNumber IN (\r\n  SELECT terminalNo from ImportData.dbo.DisableBuySegmentCredite2\r\n  )\r\n\r\n\r\n', 0, 0, 1, 1, '2026-09-20 14:00:09', '2026-09-20 14:00:09'),
