	(3632, NULL, 24, 1839, 2, 'tickets', NULL, NULL, '\r\n\r\n\r\nSELECT\r\n    car.CardNo,\r\n    car.PersianName,\r\n    car.PersianFamily,\r\n    con.Destination AS MobileNumber,\r\n    pat.Title AS CardPattern,\r\n    MAX(txn.CreatedOn) AS Last_Txn\r\nFROM B2SCard.dbo.ISSCard AS car\r\n\r\nINNER JOIN B2SAccounting.dbo.GLAccount AS acc\r\n    ON car.MainAccountID = acc.ParentAccountID\r\n\r\nINNER JOIN B2SAccounting.dbo.GLAccountContact AS con\r\n    ON acc.ParentAccountID = con.AccountID\r\n\r\nINNER JOIN B2SCard.dbo.ISSCardPattern AS pat\r\n    ON pat.ID = car.CardPatternID\r\n\r\nINNER JOIN B2STxn.dbo.SwISSTxn AS txn\r\n    ON car.CardNo COLLATE SQL_Latin1_General_CP1_CI_AS = txn.Pan\r\n\r\nWHERE\r\n    txn.CreatedOn &gt;= &#039;2025-03-20 00:00:00&#039;\r\n    AND txn.CreatedOn &lt; &#039;2026-03-21 00:00:00&#039;\r\n    AND pat.ID IN (117, 298, 1225)\r\n\r\nGROUP BY\r\n    car.CardNo,\r\n    car.PersianName,\r\n    car.PersianFamily,\r\n    con.Destination,\r\n    pat.Title;', 0, 0, 1, 1, '2026-09-23 11:34:33', '2026-09-23 11:34:33'),
