	(193, 'عظیمی', 'تماس آقای عظیمی رفاه بابت اضافه شدن فیلد شناسه به View کشتیرانی', 100, 9, 0, NULL, NULL, NULL, NULL, '2026-05-03 08:30:00', '2026-05-03 08:30:00', 'low', '2026-05-04 07:15:12', '2026-05-04 10:38:35'),
	(195, 'تغییرات گزارش کار', 'ایجاد سیستم ثبت گزارش کار برای افراد  بیرون سیستم تیکت', 100, 1, NULL, 2, 9, 'اینتک', 'محمد علی محمدی', '2026-05-04 06:30:00', '2026-05-04 09:53:11', 'low', '2026-05-04 09:53:11', '2026-05-04 09:53:11'),
	(196, 'پیام های چت', 'جداسازی اعلان پیام های چت و تغییر ات دیتا بیس', 100, 1, NULL, 2, 16, 'اینتک', 'مریم هاشمی', '2026-05-04 05:30:00', '2026-05-04 09:54:05', 'low', '2026-05-04 09:54:05', '2026-05-04 09:54:05'),
	(197, 'روت ترمینال', 'تیکت انجام و به کلاینت اطلاع رسانی شد.\r\nتست موفقیت آمیز بود.\r\nابتدا با دستور \r\n\r\nSELECT * FROM [B2SConfig].[dbo].[CfgRouteTerminalGroup] with(nolock) where terminalNo in (\r\n\r\n)\r\nبررسی میشه که ایا این ترمینال روت دارد یا خیر و اگر دارد روت درست هست یا نه .\r\nبعد از بررسی در صورت نداشتن روت با استفاده از دستور\r\ninsert into [B2SConfig].[dbo].[CfgRouteTerminalGroup] values(&#039;*******&#039;,*);\r\nبرای ترمینال مورد نظر نسبت به کلاینت درخواست دهنده روت مناسب را وارد میکنیم.\r\n\r\n\r\n', 100, 28, NULL, 8, 31, 'پرداخت الکترونیک سامان کیش', 'امیر عابدی', '2026-05-04 06:30:00', '2026-05-04 09:30:00', 'low', '2026-05-04 10:03:51', '2026-06-13 09:41:08'),
	(198, 'خطای ۵۰۰ ترمینال های نپین', 'در حال بررسی و رفع خطا\r\nموضوع برطرف گردید\r\nمشکلی از سمت اینتک نبود و به اطلاع شرکت محترم پرداخت نوین رسید.\r\n', 100, 28, NULL, 4, 10, 'پرداخت نوین آرین', 'زهرا کمایی', '2026-05-04 05:30:00', '2026-05-04 10:06:55', 'high', '2026-05-04 10:06:55', '2026-05-17 06:18:41'),
	(199, 'درخواست تغییر اطلاعات تسهیم های شرکت شهروند بر روی پایانه ها', 'تماس بابت پیگیری درخواست اعمال تسهیم های ترمینال های شهروند\r\nارسال تصویر نامه در بله\r\nپیگیری از آقای تفضلی\r\nپاسخ به خانم تربتی فرد:\r\nبا وب سرویس درخواست را ارسال کنند', 100, 9, NULL, 9, 45, 'تجارت الکترونیک پارسیان', 'تربتی فرد', '2026-05-03 08:30:00', '2026-05-03 08:30:00', 'low', '2026-05-04 10:37:58', '2026-05-04 10:37:58'),
	(200, 'تماس کمایی راجع به تست تیکت 1218', 'تست انجام شد با خطای پوز', 100, 24, NULL, 4, 10, 'پرداخت نوین آرین', 'زهرا کمایی', '2026-05-04 08:30:00', '2026-05-04 11:29:24', 'medium', '2026-05-04 11:29:24', '2026-08-26 09:03:57'),
	(201, 'خطا در پرونده اعتباری', 'موضوع سمت تیم توسعه نیاز به ارایه پابلیش دارد.\r\nبه آقای محمدی اطلاع رسانی شد.\r\nپابلیش از سمت تیم توسعه قرار گرفت.\r\nمورد برطرف شد.', 100, 28, NULL, 4, 10, 'پرداخت نوین آرین', 'زهرا کمایی', '2026-05-04 05:30:00', '2026-05-04 13:12:06', 'medium', '2026-05-04 13:12:06', '2026-06-13 09:42:08'),
	(202, 'مانیتورینگ پردیس(سامان)', 'فایل سرت کانفیگ شد.\r\nدیتابیس ساخته شد.\r\nنیازمند ایجاد دسترسی بین سرور ها که به اطلاع اقای پهلوان رسید.\r\nدسترسی بین سرور ها انجام شد.\r\nمورد تست و به اطلاع مهندس محمدی رسید.\r\nسرویس های مورد نظر در سرور نصب شد.', 100, 28, NULL, 2, 22, 'اینتک', 'مهدی صدوقیان', '2026-05-04 05:30:00', '2026-05-04 13:13:40', 'medium', '2026-05-04 13:13:40', '2026-06-13 09:42:42'),
	(203, 'افزودن مانیتویرینگ سامان برای سایت دیزاستر', 'افزودن مانیتویرینگ سامان برای سایت دیزاستر برای سرور مربوطه', 50, 24, NULL, 0, 0, '', '', '2026-05-04 08:30:00', '2026-05-04 15:32:25', 'high', '2026-05-04 15:32:25', '2026-05-04 15:32:25'),
	(204, 'دسترسی بین سرورها', 'از سرور منیجمنت سامان به سرور پردیس\r\nو از سرور پردیس به سرور مانیتورینگ دسترسی نیاز بود که با هماهنگی آقای پهلوان ایجاد شد.\r\nتست شد و دسترسی ها با موفقیت در اختیار اینتک قرار گرفت.', 100, 28, NULL, 2, 22, 'اینتک', 'مهدی صدوقیان', '2026-05-04 05:30:00', '2026-05-05 06:30:00', 'medium', '2026-05-05 05:26:15', '2026-06-13 11:32:24'),
	(205, 'ارشیو دیتاهای سامان', 'انتقال دیتاها به سرور ارشیو (80.20) جهت بایگانی انجام شد.', 100, 28, NULL, 2, 22, 'اینتک', 'مهدی صدوقیان', '2026-04-20 05:30:00', '2026-05-05 08:30:00', 'low', '2026-05-05 05:31:03', '2026-05-05 05:31:03'),
	(206, 'مانیتورینگ', 'راه اندازی مانیتورینگ HA سپ', 100, 22, NULL, 2, 7, 'اینتک', 'بهرنگ حیدری مقدم', '2026-05-04 08:00:00', '2026-05-06 08:30:00', 'medium', '2026-05-05 05:46:33', '2026-05-10 11:04:03'),
