	(215, 'امور روزانه شرکت رفاه ', 'بررسی خطاهای هفته گدشته سوییچ\r\nبررسی ترمینال کشتیرانی\r\nکلید گذاری دستگاه کارتخوان\r\n', 100, 28, NULL, 5, 26, 'توسعه فناوری رفاه پردیس', 'محمود عظیمی', '2026-05-06 06:30:00', '2026-05-06 05:34:48', 'medium', '2026-05-06 05:34:48', '2026-05-17 06:18:53'),
	(216, 'گزارش کل تراکنش های سوییچ', 'طبق دستور آقای حیدری مقدم\r\nگزارشاتی مبنی بر تعداد تراکنش های موفق سوییچ در تمامی پی اس پی ها \r\nبه تفکیک ماهانه و روزانه \r\nو\r\n به تفکیک سوییچ کد در اختیار ایشان قرار گرفت.', 100, 28, NULL, 2, 7, 'اینتک', 'بهرنگ حیدری مقدم', '2026-05-06 05:30:00', '2026-05-06 12:30:00', 'medium', '2026-05-06 11:28:30', '2026-05-09 06:28:28'),
