	(220, 'پر شدن فضای سرور 10.0.72.112 سرور اکوئری پرداخت نوین', 'تماس از مانیتورینگ پرداخت نوین جهت آزادسازی فضای درایو C سرور اکوئر پرداخت نوین %90', 100, 24, NULL, 4, 10, 'پرداخت نوین آرین', 'زهرا کمایی', '2026-05-06 19:30:00', '2026-05-07 08:30:00', 'medium', '2026-05-09 06:58:29', '2026-05-09 06:58:29'),
	(221, 'گزارش از تعداد کل پایانه های موجود بر روی سوییچ', 'با سلام و احترام \r\nبه درخواست مهندس حیدری مقدم گزارشی مبنی بر تعداد کل پایانه ها (سامان-پارسیان-رفاه-نوین) تهیه و از طریق ایمیل در اختیار ایشان قرار گرفت.', 100, 28, NULL, 2, 7, 'اینتک', 'بهرنگ حیدری مقدم', '2026-05-09 06:30:00', '2026-05-09 07:45:00', 'low', '2026-05-09 07:45:37', '2026-05-09 07:45:37'),
	(222, 'گزارشگیری دیتابیس', 'تهیه گزارشی مبنی بر تعداد کل تراکنش های مالی مشتری ها و پیک تراکنش ها در تاریخ ۲۸ اسفند ۴۰۴', 100, 28, NULL, 2, 7, 'اینتک', 'بهرنگ حیدری مقدم', '2026-05-09 06:30:00', '2026-05-09 11:00:00', 'low', '2026-05-09 09:12:32', '2026-05-09 11:45:25'),
	(223, 'ترمینال کشتیرانی', '  تماس جهت پیگیری تراکنش های کشتیرانی برای امروز', 90, 24, NULL, 5, 26, 'توسعه فناوری رفاه پردیس', 'محمود عظیمی', '2026-05-09 08:30:00', '2026-05-09 08:30:00', 'low', '2026-05-09 09:47:08', '2026-05-09 09:47:08'),
	(224, 'آزاد ساری فضای سرور های عملیاتی ', 'تماس مانیتورینگ نوین و پیام زیر برای آزاد ساری فضای سرور های عملیاتی زیر:\r\n&quot; سلام وقت بخیر\r\nAcq p2 VMware free disk space on D 9.96%\r\n۱۰.۰.۷۱.۱۳۰\r\n\r\nAcq proc02 free disk space on C 9.9%\r\n10.0.71.113\r\n\r\nAcq proc01 free disk space on C 18%\r\n10.0.71.112\r\n\r\nAcq monitoring VMware free disk space on c 9.6%\r\n10.0.71.111\r\n\r\nAcq db3 VMware free disk space on d 7.6%\r\n10.0.72.105\r\n&quot;\r\n', 95, 24, NULL, 4, 10, 'پرداخت نوین آرین', 'زهرا کمایی', '2026-05-09 08:30:00', '2026-05-09 19:30:00', 'high', '2026-05-09 18:25:42', '2026-05-09 18:25:42'),
