	(228, 'پیگیری نامه مرتبط با وب سرویس های تسهیم برای Sep', ' ', 50, 9, NULL, 2, 9, 'اینتک', 'محمد علی محمدی', '2026-05-10 08:30:00', '2026-05-10 08:30:00', 'low', '2026-05-10 08:29:08', '2026-05-10 08:29:08'),
	(229, 'سینک نبودن دیتابیس سامان', 'طی تماس تلفنی مهندس پهلوان مشخص شد کندی در بک افیس وجود \r\nبعد از رفع کندی بک افیس مشخص شد دیتاها نیز کامل سینک نشده اند.\r\nدیتا ها سینک و بک افیس recycle شد.\r\nدیتابیس و بک افیس به حالت نرمال بازگشتند.\r\n', 100, 28, NULL, 8, 31, 'پرداخت الکترونیک سامان کیش', 'امیر عابدی', '2026-05-09 06:30:00', '2026-05-09 10:30:00', 'medium', '2026-05-10 10:56:35', '2026-05-10 10:56:35'),
	(230, 'خطای وب سرویس yecard', 'مشکل سمت وب سرویس مشتری بوده که لاگ نیز برای نوین ارسال گردید و مقرر شد با مشتری هماهنگ گردد', 100, 22, NULL, 4, 41, 'پرداخت نوین آرین', 'سوده فرمانی', '2026-05-10 10:30:00', '2026-05-10 11:11:06', 'high', '2026-05-10 11:11:06', '2026-05-25 13:48:34'),
	(231, 'قطعی سوئیچ', 'پرداخت نوین مشکل سوئیچ پذیرندگی', 100, 22, NULL, 2, 22, 'اینتک', 'مهدی صدوقیان', '2026-05-10 12:30:00', '2026-05-10 18:05:00', 'high', '2026-05-10 18:09:44', '2026-05-10 18:09:44'),
	(232, 'سینک دیتابیس', 'بعذ از تماس کارشناس محترم مانیتورینگ در خصوص عقب افتادن سینک دیتاها (۳۰ دقیقه)\r\nمورد بررسی و رفع شد.\r\nهمچنین به تیم مانیتورینگ سپ هم در خصوص رفع موضوع اطلاع رسانی شد.', 100, 28, NULL, 8, 31, 'پرداخت الکترونیک سامان کیش', 'امیر عابدی', '2026-05-10 18:30:00', '2026-05-10 19:00:00', 'low', '2026-05-11 06:37:10', '2026-05-11 06:37:10'),
	(233, 'پیگیری تیکتینگ شامان', 'طی اعلام مهندس حیدری مقدم بخه جهت\r\nنیاز کارشناس سامان کیش\r\nبرای دسترسی به سامانه تیکتینگ بررسی شد\r\nموضوع رفع و به اطلاع ایشان رسید.', 100, 28, NULL, 2, 7, 'اینتک', 'بهرنگ حیدری مقدم', '2026-05-11 08:30:00', '2026-05-10 22:30:00', 'medium', '2026-05-11 11:23:48', '2026-05-11 11:23:48'),
	(234, 'Test', 'test test', 100, 28, NULL, 2, 1, 'اینتک', 'super user', '2026-05-11 08:30:00', '2026-05-12 08:30:00', 'high', '2026-05-12 07:09:27', '2026-05-12 07:17:57'),
	(235, 'خطای کارت های ایرانخودرو', 'در زمان خرید تراکنش با خطا مواجه شده ولی مدعی میباشند که از مخزن پول کم میشود\r\nپیرو آخرین بررسی مورخ 03/12 مقرر گردید پارسیان پینگ متدی (غیر شبکه) از سرویس ایرانخودرو را بگیرد تا مشخص شود مشکل سویس ایرانخودرو از کجا و به چه دلیل می باشد.\r\nامروز 03/18 مجدد پیگیری گردید و مقرر شد محمدی با افضلی پک صحبت کند جهت پیگیری موضوع\r\n---\r\nامروز 03/26 مجدد پیگیری گردید و مقرر شد محمدی با افضلی پک صحبت کند جهت پیگیری موضوع', 50, 22, NULL, 9, 37, 'تجارت الکترونیک پارسیان', 'مریم خزلی', '2026-05-11 08:30:00', '2026-06-16 13:30:00', 'high', '2026-05-12 08:49:51', '2026-06-16 13:27:12'),
	(236, 'کانال اقتصاد نوین', 'تست و راه اندازی مجدد کانال تستس اقتصاد نوین برای تراکنش و فرم 8', 100, 22, NULL, 4, 10, 'پرداخت نوین آرین', 'زهرا کمایی', '2026-05-12 12:30:00', '2026-05-17 08:30:00', 'high', '2026-05-12 12:57:25', '2026-05-17 12:13:09'),
	(237, 'گزارشات کارت هدیه پارسیان', 'طبق اعلام نیاز شرکت محترم پارسیان مبنی بر ارایه گزارش کارت های هدیه گزارشی در این باره خدمت کارشناس محترم این شرکت ارسال شد.\r\n\r\n\r\n\r\n\r\n\r\nselect   \r\ndistinct c.CardNo,r.CreatedBy,r.CreatedOn,d.CardRequestID\r\nfrom b2scard.dbo.isscard as c\r\njoin [ImportData].[dbo].[cardhediye] as g on c.CardNo=g.CardNo\r\njoin b2scard.dbo.ISSCardRequestDetail as d on d.CardNo=c.CardNo\r\njoin b2scard.dbo.ISSCardRequest as r on r.ID=d.CardRequestID\r\n', 100, 28, NULL, 9, 52, 'تجارت الکترونیک پارسیان', 'پویا عاطفی', '2026-05-12 10:30:00', '2026-05-12 12:30:00', 'medium', '2026-05-12 13:12:00', '2026-05-12 13:12:00'),
	(238, 'اختلال در سرور ۸۰.۸۰', 'بعد از تماس مانیتورینگ سامان\r\nموضوع بررسی و به اطلاع آقای موسوی رسید.\r\nمشکل از سمت آقای موسوی برطرف گردید و سرور به حالت نرمال بازگشت.', 100, 28, NULL, 8, 31, 'پرداخت الکترونیک سامان کیش', 'امیر عابدی', '2026-05-16 18:30:00', '2026-05-16 08:30:00', 'high', '2026-05-17 06:18:03', '2026-05-17 06:18:03'),
	(239, 'Knowlage', 'بروزرسانی دیتاهای پایگاه داده داخلی', 100, 28, NULL, 2, 37, 'اینتک', 'محمد عرفان حمیدی مقدم', '2026-05-17 06:30:00', '2026-05-17 08:30:00', 'low', '2026-05-17 08:52:32', '2026-05-17 08:52:32'),
	(240, 'فارا', 'جهت تست بر روی کانال  فارا در محیط تستی نود تست', 100, 22, NULL, 4, 10, 'پرداخت نوین آرین', 'زهرا کمایی', '2026-05-17 11:30:00', '2026-05-17 12:12:35', 'medium', '2026-05-17 12:12:35', '2026-05-23 12:39:28'),
	(241, '۸۰.۸۰---۸۰.۳۵', 'تماس از تیم مانیتورینگ سامان\r\nبالا رفتن CPU سرور 80.35 تا ۸۷٪\r\nو\r\nبالا رفتن Memory 80.80 تا ۹۷ ٪\r\nکه بعد از بررسی، بهینه سازی شد . به اطلاع واحد مانیتورینگ سامان رسید.\r\n', 100, 28, NULL, 8, 31, 'پرداخت الکترونیک سامان کیش', 'امیر عابدی', '2026-05-17 02:00:00', '2026-05-17 02:45:00', 'medium', '2026-05-18 05:42:30', '2026-05-18 05:42:30'),
	(242, 'ResetPasword', 'پسورد های مرتبط با PAM سرور نوین ریست و در اختیار مهندس فتحی قرار گرفت.', 100, 28, NULL, 2, 30, 'اینتک', 'ابراهیم فتحی', '2026-05-18 07:30:00', '2026-05-18 09:30:00', 'low', '2026-05-18 09:37:55', '2026-05-18 09:37:55'),
	(243, 'امور روزانه شرکت رفاه پردیس', 'گزارشگیری ها و ارایه لاگ های مورد نظر مهندس عظیمی\r\nآموزش ابتدایی مونگو به کارشناس محترم رفاه پردیس\r\nو سایر امور روزانه رفاه انجام شد.\r\n', 100, 28, NULL, 5, 26, 'توسعه فناوری رفاه پردیس', 'محمود عظیمی', '2026-05-17 07:30:00', '2026-05-17 13:30:00', 'low', '2026-05-18 09:39:21', '2026-05-18 09:39:21'),
	(244, 'افزایش رم سرور Mongo', 'تماس مانیتورینگ جهت بررسی رم سرور Mongo', 85, 24, NULL, 8, 31, 'پرداخت الکترونیک سامان کیش', 'امیر عابدی', '2026-05-19 08:30:00', '2026-05-19 08:30:00', 'medium', '2026-05-19 12:23:55', '2026-05-19 12:23:55'),
	(245, 'جلسه توسعه و ارایه بک آفیس جدید به پارسیان', 'صبح امروز به همراه مهندس محمدی در محل شرکت تجارت الکترونیک پارسیان حضور به عمل آورده و از جلسه ویس و نت برداری شد.', 100, 28, NULL, 9, 52, 'تجارت الکترونیک پارسیان', 'پویا عاطفی', '2026-05-19 04:30:00', '2026-05-19 10:30:00', 'high', '2026-05-19 13:22:18', '2026-05-19 13:22:18'),
	(246, 'حضور در شرکت رفاه', 'امور روزانه شرکت رفاه پردیس\r\nبررسی عملکرد سوییچ\r\nبرسی پایانه رفاهی\r\nبررسی علت عدم ارسال پی ار کد در تراکنش ۲۲۰ \r\n', 100, 28, NULL, 5, 26, 'توسعه فناوری رفاه پردیس', 'محمود عظیمی', '2026-05-20 08:30:00', '2026-05-20 13:00:00', 'low', '2026-05-20 10:05:05', '2026-05-20 10:05:05'),
	(247, 'کات آف', 'تماس از واحد مانیتورینگ سامان\r\nاختلال در سوییچ به دلیل انجام نشدن کات اف و اختلال در پایانه ها\r\nپس از بررسی و تماس با مهندس صدوقیان مورد برطرف شد.\r\n', 100, 28, NULL, 8, 31, 'پرداخت الکترونیک سامان کیش', 'امیر عابدی', '2026-05-19 08:30:00', '2026-05-20 09:00:00', 'high', '2026-05-20 10:06:43', '2026-05-20 10:06:43'),
	(248, 'Mongo PNA', 'دریاو D سرور مونگو پرداخت نوین به ظرفیت ۹۶٪‌رسید که بعد از تماس واحد مانیتورینگ آزاد سازی فضا انجام شد.', 100, 28, NULL, 4, 25, 'پرداخت نوین آرین', 'میلاد حلاجی', '2026-05-22 16:30:00', '2026-05-22 17:30:00', 'medium', '2026-05-23 05:24:55', '2026-05-23 05:24:55'),
	(249, 'Mongo SEP', 'پس از تماس واحد مانیتورینگ سامان جهت اطلاع پر شدن فضای مونگو\r\nآزاد سازی فضا انجام شد.', 100, 28, NULL, 8, 31, 'پرداخت الکترونیک سامان کیش', 'امیر عابدی', '2026-05-22 18:30:00', '2026-05-22 19:30:00', 'medium', '2026-05-23 05:27:38', '2026-05-23 05:27:38'),
	(250, '142.13 سابین', 'پس از تماس واحد مانیتورینگ سامان آزاد سازی فضا انجام شد.', 100, 28, NULL, 8, 31, 'پرداخت الکترونیک سامان کیش', 'امیر عابدی', '2026-05-22 14:30:00', '2026-05-23 15:30:00', 'medium', '2026-05-23 05:28:39', '2026-05-23 05:28:39'),
	(251, 'امور روزانه شرکت رفاه پردیس', 'تنظیم کویری کارشناس فنی رفاه\r\nارایه لاگ SecureChanel به کارشناس محترم رفاه\r\nآموزش مشاهده لاگ در Navicat به کارشناس محترم رفاه\r\n', 100, 28, NULL, 5, 26, 'توسعه فناوری رفاه پردیس', 'محمود عظیمی', '2026-05-20 07:30:00', '2026-05-20 13:30:00', 'low', '2026-05-23 05:32:42', '2026-05-23 05:32:42'),
	(252, 'تمدید فایل کارت های نوین', 'مقدار سال &quot; تاریخ انقضا &quot; برای کارت های فایل های پیوست ، 3 سال اضافه گردید', 100, 27, NULL, 2, 27, 'اینتک', 'سارینا سنگی ', '2026-05-23 08:30:00', '2026-05-23 08:30:00', 'low', '2026-05-23 10:40:46', '2026-05-23 10:40:46'),
	(253, 'افزایش سرعت تیکتینگ', 'افزایش سرعت تیکتینگ در ساید کاربر و مدیران', 100, 38, NULL, 2, 1, 'اینتک', 'Superadmin', '2026-05-23 04:30:00', '2026-05-24 10:30:00', 'medium', '2026-05-24 09:49:04', '2026-05-24 09:49:04'),
	(254, 'ایجاد گردش کار جدید ', 'ایجاد گردش کار جدید  برای واحد توسعه با توجه به تغییرات چارت سازمانی', 100, 38, NULL, 2, 16, 'اینتک', 'مریم هاشمی', '2026-05-24 05:30:00', '2026-05-24 09:49:57', 'low', '2026-05-24 09:49:57', '2026-05-24 09:49:57'),
	(255, 'ایجاد چرخه تیکت', 'درخواست ایجاد چرخه تیکت در واحد فنی', 100, 38, NULL, 2, 9, 'اینتک', 'محمد علی محمدی', '2026-05-24 07:30:00', '2026-05-24 09:50:48', 'low', '2026-05-24 09:50:48', '2026-05-24 09:50:48'),
	(256, 'جستجو جدید تیکتینگ', 'سیستم جستجو در متن تیکت', 100, 38, NULL, 2, 1, 'اینتک', 'Superadmin', '2026-05-23 04:30:00', '2026-05-24 09:57:50', 'low', '2026-05-24 09:57:50', '2026-05-24 09:57:50'),
	(257, 'جستجوی انواع گروه کاربران', 'جستجوی در انواع گروه کاربران در قسمت افزودن تیکت', 100, 38, NULL, 2, 1, 'اینتک', 'Superadmin', '2026-05-24 09:30:00', '2026-05-24 09:58:57', 'low', '2026-05-24 09:58:57', '2026-05-24 09:58:57'),
	(258, 'جلسه در خصوص راهبردهای جدید با محمدی', 'جلسه برای افزایش کیفیت بخش پشتیبانی با اقای محمدی مدیر واحد توسعه ', 100, 38, NULL, 2, 38, 'اینتک', 'مهدی ایمنی', '2026-05-24 09:30:00', '2026-05-24 10:15:51', 'low', '2026-05-24 10:15:51', '2026-05-24 10:15:51'),
	(259, 'شماره تیکت', 'تغییر شماره تیکت ها بر اساس شرکت و عدد اتفاقی', 100, 38, NULL, 2, 9, 'اینتک', 'محمد علی محمدی', '2026-05-24 10:30:00', '2026-05-24 12:18:02', 'low', '2026-05-24 12:18:02', '2026-05-24 12:18:02'),
	(260, 'انتقال شارژ ایرانسل و همراه اول از مخزن بانک تجارت به مخزن سوییچ مهرانا 202605-1610', 'مقرر بود شارژ ایرانسل 10هزارتومانی به تعداد 2000 و شارژ همراه اول 10هزارتومانی به تعداد 4000 از بانک تجارت به سوییچ مهرانا انتقال یابد اما این انتقال از مخزن تجارت الکترونیک پارسیان به سوییچ مهرانا انجام شد\r\nبعد از مشورت با اقای ایمنی و اقای حیدری مقدم با اقای عاطفی تماس حاصل شد و پیرو مذاکرات انجام شده با اقای عاطفی مقرر گردید:\r\n تعداد 2000 شارژ ایرانسل 10 هزارتومانی از مخزن بانک تجارت به مخزن تجارت الکترونیک پارسیان و تعداد 4000 شارژ همراه اول 10هزارتومانی از مخزن بانک تجارت به مخزن تجارت الکترونیک پارسیان انتقال یابد\r\n\r\nو باقی مانده شارژ ایرانسل 10هزارتومانی به تعداد 437 از مخزن بانک تجارت به مخزن سوییچ مهرانا و\r\n باقی مانده شارژ همراه اول 10هزارتومانی به تعداد 890 از مخزن بانک تجارت به مخزن سوییچ مهرانا انتقال یابد', 100, 27, NULL, 2, 38, 'اینتک', 'مهدی ایمنی', '2026-05-19 08:30:00', '2026-05-25 06:41:29', 'low', '2026-05-25 06:41:29', '2026-05-25 10:39:19'),
	(261, 'جلسه معارفه', 'جلسه معارفه بود که به مدیرعامل بانک ارائه گردید و در طول روز آموزش جداول دیتابیس (ویوها) و تراکنش های مالی توضیح گردید به پرسنل واحد مانیتورینگ و دیتابیس مجموعه رفاه', 100, 22, NULL, 5, 26, 'توسعه فناوری رفاه پردیس', 'محمود عظیمی', '2026-05-24 04:30:00', '2026-05-24 12:30:00', 'low', '2026-05-25 07:11:19', '2026-05-25 07:11:19'),
	(262, 'تغییرات ای دی تیکت', 'تغییر کلی تیکت ای دی در قسمت کاربر و مدیران', 100, 38, NULL, 2, 1, 'اینتک', 'Superadmin', '2026-05-24 10:30:00', '2026-05-25 07:50:58', 'low', '2026-05-25 07:50:58', '2026-05-25 07:50:58'),
	(263, 'سرور جدید پارسیان', 'طی اعلام نیازمندی مهندس محمدی بابت سرور جدید برای بالا آوردن بک آفیس جدید\r\nطی پیگیری های مکرر از شرکت محترم پارسیان\r\nسرور جدیدی با آی پی 172.25.1.240 در دسترس ما قرار گرفت و به اطلاع مهندس محمدی رسید.\r\na.parvizi\r\ns.sangi\r\nma.mohammadi\r\nدسترسی ایجاد شد.\r\nپسورد من و سارینا As@123456789!\r\n', 100, 28, NULL, 2, 9, 'اینتک', 'محمد علی محمدی', '2026-05-24 04:30:00', '2026-05-24 06:30:00', 'medium', '2026-05-25 08:22:49', '2026-06-17 08:03:13'),
	(264, 'دسترسی های بین سرور', 'طبق نیازمندی اتصال سرور های پارسیان\r\nطی پیگیری های مکرر از آن شرکت محترم \r\nتلنت های مورد نیاز\r\n(از مبدا\r\n 175.25.1.240 \r\nبه مقصد های\r\n172.25.16.188:1433\r\n172.25.16.135:1433\r\n172.25.16.59:1433\r\n172.25.16.77:1433\r\n)\r\n باز شد.', 100, 28, NULL, 2, 9, 'اینتک', 'محمد علی محمدی', '2026-05-23 04:30:00', '2026-05-25 07:45:00', 'medium', '2026-05-25 08:26:00', '2026-05-25 08:26:00'),
	(265, 'قبوض رایتل (PNA)', 'طی تماس های تلفنی مکرر از مهندس حلاجی و خانم کمایی \r\nو اعلام موضوع خطای ترمینال نوین در پرداخت قبوض رایتل\r\nاین موضوع به صورت تلفنی و فورس پیگیری و به سر انجام رسید.\r\nمشکل از سمت خوده نوین (ارسال کد تابع اشتباه به شاپرک) بود .', 100, 28, NULL, 4, 10, 'پرداخت نوین آرین', 'زهرا کمایی', '2026-05-25 05:30:00', '2026-05-25 07:30:00', 'high', '2026-05-25 08:28:27', '2026-05-25 08:28:27'),
	(266, 'شارژهای زیر ۲۰ تومن نوین', 'طی اعلام شرکت نوین نیازمندی تغییرات برای عدم ارسال تراکنش های شارژهای کمتر از ۲۰ هزارتومن\r\nبررسی صورت گرفت و به کارشناس محترم پرداخت نوین اطلاع رسانی شد.\r\nبرای رفع این مشکل نوین باید نیازمندی خودرا به شرکت مبتکران اعلام کرده و تغییرات از سما آن شرکت محترم انجام شود.\r\nبرای این موضوع پس از پیگیری تلفنی تیکت نیز ثبت شد که در داخل تیکت نیز به صراحت موضوع کامنت شد و در مکالمات تلفنی نیز به اطلاع خانم کمایی رسید.\r\nتیکت تا زمان اعمال تغییرات مبتکران در کارتابل این جانب باقی میماند.', 100, 28, NULL, 4, 10, 'پرداخت نوین آرین', 'زهرا کمایی', '2026-05-23 04:30:00', '2026-05-25 08:45:32', 'low', '2026-05-25 08:45:32', '2026-05-25 13:23:31'),
	(267, 'پیاده سازی Qr merchant ( 405443647 )', 'توضیحات در تیکت پیاده سازی Qr merchant ( 405443647 ) بصورت محلی کامل ارائه شد.\r\nپروژه مربوط به پیاده سازی روی کارتخوان بوده که در کارتخوان (کهربا) یک qr جنریت شود و مشتری با اپلیکیشن داخل گوشی (مقرر شده تمام اپلیکیشن های دارای مجوز شاپرک) qr را اسکن کرده تا اطلاعات پذیرنده نمایش داده شود در گوشی همراه (اینکه مبلغ در qr هست یا خیر مقرر شد آقای جهانگیری اطلاع دهد) سپس مشتری تایید کرده و با کارت های ثبت شده در نرم افزار موبالی یا کیف پول خرید را انجام دهد.\r\nدر این سناریو بالعکس مسیر پوز بوده و از پوز به موبایل سپس از موبایل وب سرویس ها کال شود (سهند-دنا و...) سپس به شاپرک ارسال شده و از شاپرک به سمت گتوی نوین (اینتک) ارسال و در اکوئری انجام شده و و مجدد مسیر برگشت انجام شود و در دیتابیس نیز ثبت گردد.\r\n\r\nتغییرات فوق نیاز به پیاده سازی سمت سوئیچ می باشد.\r\nبا سپاس', 100, 22, NULL, 4, 39, 'پرداخت نوین آرین', 'مهدی جهانگیری', '2026-05-25 06:00:00', '2026-05-25 08:30:00', 'low', '2026-05-25 08:53:04', '2026-05-25 08:53:04'),
	(268, 'ارسال مستندات منوی داینامیک سوئیچ جهت پیاده سازی بروی دستگاه کارتخوان ( 405441529 )', 'با سلام\r\nپروژه مربوط به پیاده سازی از سمت پوز (هاردکد) به سوئیچ بصورت داینامیک می باشد. به این صورت که در پوز مواردی مانند بلیط مترو،شارژ موبایل، اقلام کالابرگ و... مدام نیاز به تغییرات می باشد و برای تغییرات در کارتخوان ، psp دچار حجم کاری و اختلال شده و پیرو همین موضوع خواستار پیاده سازی سمت سوئیچ می باشد.\r\nفرآیند به این صورت بوده که در سوئیچ موارد پیاده سازی گردد (دیتابیس از طریق بکافیس) تا زمانی که تراکنش 200 انجام شد تگ مورد نظر در 210 به کارتخوان ارسال شود و کارتخوان با دیدن این تگ متوجه شود که باید لاگان فورس انجام دهد و اطلاعاتی که در دیتابیس از طریق بکافیس بارگذاری شده دریافت و بروزرسانی کند.\r\nبرای سوئیچ نیز این دیتا از طریق وب سرویس مد نظر نوین شماره ترمینال ها ارسال شده تا  با ترمینال مذکور فرآیند مد نظر را  اعمال کند.\r\nپروژه مذکور نیاز به پیاده سازی سمت بکافیس و سوئیچ می باشد.\r\nبا سپاس', 100, 22, NULL, 4, 39, 'پرداخت نوین آرین', 'مهدی جهانگیری', '2026-05-25 07:30:00', '2026-05-25 09:30:00', 'low', '2026-05-25 09:43:23', '2026-05-25 09:43:23'),
	(269, 'یاده سازی تراکنش های با قابلیت های پرداخت وجوه دولتی ( شناسه بهداد ) و تسهیم آنلاین و همچنین احراز هویت مانا به صورت همزمان ( 202605-1627 )', 'پروژه به این صورت بوده که کد ملی با تراکنش ارسال شده و استعلام گرفته شود سپس بصورت مالتی شناسه های بهداد نیز ارسال شود تا در صورت نیاز تسهیم در سازمان های مختلف انجام شود.\r\nتراکنش بصورت ipg بوده و نیازمند تسهیم آنلاین و همچنین مالتی شناسه بهداد می باشد.\r\n\r\nتیکت مذکور پیشتر ارجاع شده بود که به پرداخت نوین اطلاع رسانی گردید پیاده سازی سمت ipg بوده و و پس از پیاده سازی از واحد مربوطه اطلاع رسانی گردد.\r\nدر صورت نیاز به پیاده سازی سمت اینتک نیازمند تایید آقای دارایی و همچنین پیش فاکتور می باشد.', 100, 22, NULL, 4, 10, 'پرداخت نوین آرین', 'زهرا کمایی', '2026-05-25 08:30:00', '2026-05-25 09:30:00', 'high', '2026-05-25 10:00:09', '2026-05-25 10:00:09'),
	(270, 'خطای 12 در خصوص تراکنش های قبض شرکت رایتل ( 405444227 )', 'خطا مربوط به شرکت های تابعه قبوض بوده و به آقای پرویزی نیز آموزش داده شد.\r\nبه خانم کمایی نیز اطلاع رسانی گردید و مشکل مرتفع شد.', 100, 22, NULL, 4, 10, 'پرداخت نوین آرین', 'زهرا کمایی', '2026-05-25 07:30:00', '2026-05-25 08:30:00', 'low', '2026-05-25 10:02:46', '2026-05-25 10:02:46'),
	(271, 'پروژه جدید والد فرزندی _ External Accounting _قسطی کارت_ 2 ( 202605-1548 )', 'با سلام موراد مورد نیاز در دیتابیس اینزرت گردید.\r\nدر سوئیچ نیز موارد مورد نظر ایجاد شد و دسترسی ها دریافت شد.\r\nمراحل تست swagger نیز انجام شد.\r\nنوع پشتیبانی api نیز به مشتری basic auth نیز اطلاع رسانی و تغییرات توسط مشتری ایجاد گردید.\r\nادامه مراحل کار نیز اطلاع رسانی شد و چهت خواندن لاگ به آقای افشار ارجاع گردید.', 100, 22, NULL, 4, 41, 'پرداخت نوین آرین', 'سوده فرمانی', '2026-05-18 08:30:00', '2026-05-21 08:30:00', 'low', '2026-05-25 10:19:44', '2026-05-25 10:19:44'),
	(272, 'سگمنت مانده حساب های متفاوت', 'با سلام از آقای دارایی و حیدری مقدم پیگیری گردید و تاکنون پاسخی دریافت نشده است.\r\nدر حال حاضر مانده به تفکیک سگمنت نداریم و در صورت نیاز باید از سمت آقای دارایی پیاده سازی گردد.\r\nمد نظر باشد که مشتری را انتخاب میکنن تا برای الگوی خاصی ارسال شود.\r\nمورد مذکور از آقای تفضلی نیز پیگیری گردید و نیاز به پیاده سازی توسط آقای دارایی می باشد.', 100, 22, NULL, 9, 37, 'تجارت الکترونیک پارسیان', 'مریم خزلی', '2026-05-20 08:30:00', '2026-05-25 08:30:00', 'high', '2026-05-25 10:35:19', '2026-05-25 10:35:19'),
	(273, 'پیاده سازی واریز سروشی ( 202605-1606 )', 'با سلام پیرو آخرین بررسی و مستند ارسالی طبق همان شتاب 7 بوده و  فقط نیاز به اضافه کردن هدر دارد  و خیلی تغییرات خاصی ندارد اما پیاده سازی و  اعمال تغییرات سمت آقای دارایی میباشد.', 100, 22, NULL, 4, 25, 'پرداخت نوین آرین', 'میلاد حلاجی', '2026-05-19 08:30:00', '2026-05-23 08:30:00', 'high', '2026-05-25 11:32:54', '2026-05-25 11:32:54'),
	(274, 'ابجاد رونوشت و صورت جلسه از جلسات هفتگی پارسیان', 'توضیحات شفاهی \r\nویس جلسه و خلاصه نوشته های نکات مطرح شده در جلسه در یک فایل ورد تقدیم مهندس ایمنی و مهندس محمدی جهت بررسی  گردید.\r\nرونوشت تهیه و برای مهندسان ایمنی صدوقیان حیدری مقدم و محمدی ارسال شد.\r\n', 100, 28, NULL, 2, 38, 'اینتک', 'مهدی ایمنی', '2026-05-25 08:30:00', '2026-06-02 08:30:00', 'low', '2026-05-25 12:52:48', '2026-06-02 10:25:23'),
	(275, 'پیگیری کلید عمومی نوین', 'طی مذاکره تلفنی با مهندس جهانگیری\r\nمشخص شد کلید هنوز ساخته نشده و کلید قبلیه ساخته شده که برای شاپرک ارسال شده بود با مشکل مواجه شده است.\r\nمجدد در طی هفته اینده از اقای جهانگیری پیگیری میشود.\r\n در تاریخ 405/03/12 مجدد تماس گرفتم و گفتن هنوز شاپرک کلید را تایید نکرده.\r\nمقرر شده امروز خبر بدن که شاپرک چه جوابی بهشون داده.\r\nمجدد از مهندس جهانگیری پیگیری شد و مقرر شد امروز PFX ‌را در اختیار ما قرار دهند.\r\nمجدد از مهندس جهانگیری پیگیری شد و ایشان فرمودند فردا PFX به همراه رمز فایل در اختیار اینتک قرار میگیرد.\r\nکلید در اختیار اینتک قرار گرفت و  در حال انجام جای گذاری میباشد.\r\nدر تاریخ ۱۵ تیر انجام خواهد شد.', 95, 28, NULL, 4, 39, 'پرداخت نوین آرین', 'مهدی جهانگیری', '2026-05-25 04:30:00', '2026-06-02 08:30:00', 'high', '2026-05-25 12:58:44', '2026-06-16 10:38:55'),
	(276, 'پروژه NFC,EBCOM', 'این 2 پروژه مربوط به تراکش های NFC بوده که مورد پیاده سازی سمت سوئیچ گویا انجام شده اما مستندی هنوز در اختیار این واحد جهت ارجاع به نوین ارائه نشده و مستند مربوط به سوئیچ بوده که نیازمند ارسال از سمت آقای درایی به این واحد می باشد.', 100, 22, NULL, 4, 10, 'پرداخت نوین آرین', 'زهرا کمایی', '2026-05-25 11:30:00', '2026-05-25 12:30:00', 'low', '2026-05-25 13:04:28', '2026-05-25 13:04:28'),
	(277, 'Knowlage', 'اطلاعات به دست آمده امروز در جهت تکمیل موارد پایگاه داده داخلی ثبت شد.', 100, 28, NULL, 2, 37, 'اینتک', 'محمد عرفان حمیدی مقدم', '2026-05-25 06:30:00', '2026-05-25 13:23:17', 'low', '2026-05-25 13:23:17', '2026-05-25 13:23:17'),
	(278, 'گزارش تیکت های اعلامی', 'سوییچ شارژ\r\n1251271\r\n(کارتابل اقای ایمنی)\r\nwait اقای دارایی\r\nنیاز به پیش فاکتور دارد\r\n&quot;کامنت محلی دارد&quot;\r\n\r\nتیکت 1522\r\n(کارتابل اقای ایمنی)\r\nwait مسنتد از سمت اقای دارایی است\r\n&quot;کامنت محلی دارد&quot;\r\n\r\n1627\r\nکارتابل اقای ایمنی \r\nwait اقای دارایی \r\n&quot;کامنت محلی دارد&quot;\r\n\r\n1529\r\nکارتابل اقای صدوقیان\r\nهم نیاز به پیاده سازی سوییچ دارد  هم بک افیس(مطابق کامنت محلی اقای صدوقیان)\r\n\r\n3647 \r\nکارتابل اقای ایمنی\r\nپروژه نیازمند پیاده سازی است\r\n\r\nدر همه موارد در کامنت محلی توضیحات را اقای صدوقیان نوشتند', 100, 27, NULL, 2, 38, 'اینتک', 'مهدی ایمنی', '2026-05-25 08:30:00', '2026-05-25 08:30:00', 'low', '2026-05-25 13:55:53', '2026-05-25 13:55:53'),
	(279, 'سوییچ تستی', 'بر روی یک سرور داخلی که شرکت در اختیارمون گذاشته سوییچ تستی رو داریم بالا میاریم\r\nکه تا الان دیتابیس کاملا اومده بالا\r\nسوییچ هم همذاه با یک نود اومده بالا\r\nو الان در تلاش برای بالا اوردن بک افیس هستیم تا یک ترمینال تعریف کنیم\r\nدر تاریخ 26 خرداد ماه سوییچ به طور کامل بالا امد بک افیس قسمت های اصلی تست شد و اوکی بود ', 90, 27, NULL, 2, 7, 'اینتک', 'بهرنگ حیدری مقدم', '2026-05-25 11:00:00', '2026-05-25 13:30:00', 'low', '2026-05-26 07:42:55', '2026-06-20 06:57:47'),
	(280, 'فایل شارژ در حال پردازش', 'تماس گرفت و یک فایل شارژ داشتند که در وضیعت در حال پردازش مونده بود و پیگیری تیکتی رو کرد که در این مورد زده بود در خصوص رفع ریشه ای مشکل این سرویس که از اقای محمدی پیگیری کردم', 80, 27, NULL, 4, 41, 'پرداخت نوین آرین', 'سوده فرمانی', '2026-05-25 08:30:00', '2026-05-25 08:30:00', 'low', '2026-05-26 07:46:37', '2026-05-26 07:46:37'),
	(281, 'پیگیری ارسال پوز از خانم کمایی', 'با خانم کمایی تماس گرفته شد برای پیگیری ارسال پوز برای تست سوییچ تستی', 100, 27, NULL, 2, 7, 'اینتک', 'بهرنگ حیدری مقدم', '2026-05-26 08:30:00', '2026-05-26 08:30:00', 'low', '2026-05-26 07:50:33', '2026-05-26 07:50:33'),
	(282, 'تماس با اقای بهشتی', 'اطلاع رسانی مشکل مشاهده شماره تقاضا برای اقای کیارش.... در شرکت پارسیان', 100, 27, NULL, 2, 22, 'اینتک', 'مهدی صدوقیان', '2026-05-25 08:30:00', '2026-05-25 08:30:00', 'low', '2026-05-26 07:52:13', '2026-05-26 07:52:13'),
	(283, 'تیکت 905441779', 'یوزر و پسووردی که به پارسیان دادن وقتی واردش میشن خطای 401 بهشون میده \r\nاین به این دلیل که این یوزر رول نداره و باید براش رول تعریف بشه\r\nتماس گرفیتم و ازشون سطح دسترسی یوزر برای تعریف رول پرسیدیم.', 100, 27, NULL, 2, 28, 'اینتک', 'امیرارسلان پرویزی', '2026-05-26 08:30:00', '2026-05-26 08:30:00', 'low', '2026-05-26 10:33:50', '2026-05-26 10:33:50'),
	(284, 'خطای استعلام فارا کلیه ترمینال ها برروی نود 23 (ارتباط فردا)', 'تمامی تراکش ها با خطای 84 در سمت پوز و دیتابیس و همچنین با خطای ایشوئر داون برروی لاگ اکوئری نود 23 سامان پرداخت مشاهده شد.\r\nدر سمت سامان پرداخت کد نویسی و توکن طوری توسعه یافته است که باعث اشکال در کانکتور فارا شده است. ابتدا با دستور log view FaraConnector  در نود 23 وضعیت تراکنش های فارا را چک میکنیم. سپس با دستور log view Connector آیدی کانکتور فارا را می یابیم و سپس با دست Connector build {ID fara} کانکتور مذکور را ریبیلد میکنیم. \r\nدر آخر تمامی تراکنش ها با موفقیت صورت میپذیرند.', 100, 24, NULL, 8, 31, 'پرداخت الکترونیک سامان کیش', 'امیر عابدی', '2026-05-26 05:00:00', '2026-05-26 08:30:00', 'high', '2026-05-26 11:11:52', '2026-05-26 11:11:52'),
	(285, 'خظا خوردن کلیه تراکنش های پین شارژ 50 و 100 هزار تومانی همراه اول در سامان پرداخت (بخش اول) و افت کلی تراکنش های سوویچ در ساعت 9:30 مورخ 1405/03/06', 'با سلام و احترام\r\nمورخ تاریخ 1405/03/06 در ساعت 20:00 سامان پرداخت اعلام کرد که مبتکران پس از شارژ مخزن شارژ های 50 و 100ای همراه اول، تمامی تراکنش های َشارژ آن به خطای 12 و کد داخلی 50 (شارژ درخواستی به فروش رسیده است) بر میخورد.\r\nپس از بررسی لاگ مشخص گردید که مخزن شارز در بک آفیس و دیتابیس پر گردیده است و در ساعت 23 همان روز تراکنش های شارژ به روال قبلی خود بازگشت.\r\nتماس با آقای فتحی نیز صورت گرفت که گفتند کال شدن سرویس شارژ در لاگ اکوئر از سمت ما نیست.\r\nهمچنین با آقای مجمدی و تفضلی تماس گرفته شد اما بی پاسخ.\r\nپیگیری و بررسی بین ساعات 20 و 23:59 انجام پذیرفت.\r\nهمچنین طبق تماس قبلی مانیتورینگ سامان پرداخت در ساعت 10 صبح همان روز، اعلاگ گردید که سوییپچ به میزان 2 دقیقه افت کلی داشته که از پس بررسی بنده و اعلام شرکت انفورماتیک (حدمات)، اعلام گردید تغییرات از سمت شاپرک بوده که باعث افت کلی تراکنش ها گردیده بود.', 100, 24, NULL, 8, 31, 'پرداخت الکترونیک سامان کیش', 'امیر عابدی', '2026-05-27 16:30:00', '2026-05-27 08:30:00', 'high', '2026-05-28 15:21:28', '2026-05-28 15:21:28'),
	(286, 'تماس مانیتورینگ سامان پرداخت مبنی بر بالا رفتن cpu سرور 80:35 دیتابیس سامان پرداخت', 'مورخ 1405/03/07در ساعت 1 بامداد تماس گرفته شد مبنی بر به 95 رسیدن زم سرور دیتابیس 172.31.80.35 و بررسی بنده صورت گرفت.', 95, 24, NULL, 8, 31, 'پرداخت الکترونیک سامان کیش', 'امیر عابدی', '2026-05-27 21:30:00', '2026-05-27 22:30:00', 'medium', '2026-05-28 15:27:27', '2026-05-28 15:27:27'),
	(287, 'پیگیری تیکت های نیازمند اقدام جناب مهندس دارایی', 'پیگیری تیکت های نیازمند اقدام جناب مهندس دارایی به شماره های 1251 ، 271 ، 1522 ، 1198 ، 1627 ، 1529 ، 3647', 100, 38, NULL, 2, 7, 'اینتک', 'بهرنگ حیدری مقدم', '2026-05-19 04:30:00', '2026-05-19 07:30:00', 'medium', '2026-05-30 03:27:05', '2026-05-30 03:27:05'),
	(288, 'شروع به کار سیستم جدید پیاده سازی سوئیچ شارژ', 'شروع به کار سیستم جدید پیاده سازی سوئیچ شارژ . بررسی اطلاعات و دسترسی های مورد نیاز با شرکت پرداخت نوین. خانم کمایی ، آقای جهانگیری ، آقای محب و همچنین جلسه و پیگیری از آقای حیدری مقدم .', 100, 38, NULL, 4, 39, 'پرداخت نوین آرین', 'مهدی جهانگیری', '2026-05-19 12:30:00', '2026-05-30 03:29:26', 'medium', '2026-05-30 03:29:26', '2026-06-16 03:47:55'),
	(289, 'موضوع خطای 12 روی سیستم شارژ سامان ', 'پیگیری خطای شارژ روی سیستم شارژ سامان  تماس با آقایان افشار ، محمدی ، فتحی ، توکل ( سینا توکل ) ، صدوقیان .\r\nعلت عدم ارتباطات از شرکت سامان به سرور مبتکران  . 14.60', 100, 38, NULL, 8, 31, 'پرداخت الکترونیک سامان کیش', 'امیر عابدی', '2026-05-20 17:30:00', '2026-05-30 03:30:00', 'high', '2026-05-30 03:32:14', '2026-05-30 03:32:14'),
	(290, 'حذف شارژ 5 ، 10 هزار تومانی ', 'حذف شارژ 5 ، 10 هزار تومانی  از دیتابیس سامان ( دی اکتیو ) به منظور رفع خطای اکسپشن و حذف از سیستم همراه اول و ایرانسل ', 100, 38, NULL, 2, 38, 'اینتک', 'مهدی ایمنی', '2026-05-21 18:30:00', '2026-05-21 20:00:00', 'medium', '2026-05-30 03:34:06', '2026-05-30 03:34:06'),
	(291, 'شارژهای 50.000 تومانی همراه اول سپ', 'پیرو بررسی های مجدد و توضیحات تکمیلی به آقای افشار جهت تست مشخص گردید با توجه به لاگ تراکنش و مولفه های خطا ، موضوع مربوط به تغییر آیپی پورت سرور سرویس دهنده شارژ بوده که ایجاد اختلال کرده و پس از اصلاح آیپی پ.رت مشکل برطرف گردید و در این خصوص هیچ اطلاعی به ااینتک داده نشده و همچنین سپ نیز (آقای پهلوان) در جریان نبودند.', 100, 22, NULL, 8, 31, 'پرداخت الکترونیک سامان کیش', 'امیر عابدی', '2026-05-28 06:00:00', '2026-05-28 08:30:00', 'high', '2026-05-30 04:55:02', '2026-05-30 04:55:02'),
	(292, 'شارژ 50.000 تومانی همراه اول سپ و سرویس و تسک اسکژولر سرویس ستلمنت', 'سرویس و تسک ستل ها با تغییر رمز استاپ شده و مشکل خورده و با بروزرسانی پسورد مشکل برطرف گردید.\r\nشارژها بدلیل تغییر IP,PORT سرویس دهنده بوده که مشکل برطرف شد در روز بعد.', 100, 22, NULL, 8, 31, 'پرداخت الکترونیک سامان کیش', 'امیر عابدی', '2026-05-27 18:30:00', '2026-05-27 21:00:00', 'high', '2026-05-30 04:58:56', '2026-05-30 04:58:56'),
	(293, 'بروزرسانی سرورهای ویندوزی', 'بروزرسانی سرورها و راه اندازی مجدد سرویس ها و سوئیچ و دیتابیس ها  از ساعت 23:00 مورخ 2 خرداد تا ساعت 03:00 مورخ 3 خرداد انجام گردید.', 100, 22, NULL, 4, 10, 'پرداخت نوین آرین', 'زهرا کمایی', '2026-05-23 07:30:00', '2026-05-23 23:30:00', 'medium', '2026-05-30 05:10:58', '2026-05-30 05:10:58'),
	(294, 'بالا رفتن CPU 80.35', 'بعد از تماس واحد مانیتورینگ شرکت سامان مبنی بر افزایش نرخ بهره وری CPU سرور 80.35 و بررسی\r\nسرور در حاتلت نرمال قرار گرفت.\r\nواحد درخواست دهنده : امیر عابدی', 100, 28, NULL, 0, 0, '', '', '2026-05-27 19:30:00', '2026-05-27 20:29:00', 'low', '2026-05-30 05:13:12', '2026-05-30 05:13:43'),
	(295, 'Mongo PNA', 'بعد از تماس واحد مانیتورینگ پرداخت نوین\r\n مبنی بر بالا رفتن Memory سرور 7251(Mongo) به مقدار 96٪\r\nبررسی های لازم به عمل آمده و مورد بر طرف شد.', 100, 28, NULL, 4, 10, 'پرداخت نوین آرین', 'زهرا کمایی', '2026-05-30 05:30:00', '2026-05-30 06:43:46', 'medium', '2026-05-30 06:43:46', '2026-05-30 06:43:46'),
	(296, 'View Refah Merchant Information', 'در خواست مهندس عظیمی جهت ساخت ویو در دیتابیس از اقای افشار و اقای موسوی پیگیری شد.\r\nاقای موسوی بیان کردند که امروز ویو حاظر و در اختیار شرکت رفاه پردیس قرار میگیرد.\r\nدر روز یکشنبه مورخ 405/03/10 این ویو تحویل شد.', 100, 28, NULL, 5, 26, 'توسعه فناوری رفاه پردیس', 'محمود عظیمی', '2026-05-30 04:30:00', '2026-05-30 06:55:06', 'low', '2026-05-30 06:55:06', '2026-06-01 09:00:58'),
	(297, 'پیاده سازی سوئیچ شارژ', 'پیاده سازی سوئیچ شارژ\r\nمورخ 03/09 ترمینال تستی ارائه شد و پروایدر تغییر کرد و پروایدر در دیتابیس اضافه و تغییرات ترمینال انجام گردید و مقرر شد تست گردد.\r\nپیگیری در مورخ 03/09 انجام شد و مقرر گردید  تست انجام شود\r\nپیگیری در مورخ 03/10 انجام شد و مشخص گردید تست دیروز از سمت پرداخت نوین اشتباه  بوده و خطا مربوط به کانفیگ سرویس بوده و مقرر گردید همرا اول تست شود.\r\n\r\nبا آقای ایمنی مذاکره شد و پیرو اعلام ایشان پروژه سمت اینتک انجام نمی شود و تیکت برای ایشان ارسال گردید\r\n\r\n', 100, 22, NULL, 4, 10, 'پرداخت نوین آرین', 'زهرا کمایی', '2026-05-30 05:00:00', '2026-06-13 12:30:00', 'high', '2026-05-30 07:10:03', '2026-06-13 12:24:38'),
	(298, 'بروزرسانی سرورهای بهرامی', 'با توجه به عدم بار بر روی سرورهای بهرامی مقرر گردید در ساعت اداری بروزرسانی و ریاستارت گردد تا سرویس ها و سوئیچ ها و دیتابیس و... بررسی گردد.\r\nتمامی کانال ها و سرورها بررسی گردید و خطاها رفع و کانال ها فعال گردید.', 100, 22, NULL, 4, 10, 'پرداخت نوین آرین', 'زهرا کمایی', '2026-05-30 08:00:00', '2026-05-30 10:05:00', 'low', '2026-05-30 08:22:44', '2026-05-30 10:03:44'),
	(299, 'مانیتورینگ سامان (شارژ )', 'تماس از واحد مانیتورینگ شامان مبنی بر خطا در مخازن شارژ ۱۰۰ همراه و ۲۰ ایرانسل\r\nکه بعد از پیگیری و تماس با مبتکران (خانم پرکار)\r\nدلیل این اختلال فروش حجم بالای شارژ برای خرید اینترنت بوده و مبتکران در حال آماده سازی شارژها و مخازن میباشد.', 100, 28, NULL, 8, 31, 'پرداخت الکترونیک سامان کیش', 'امیر عابدی', '2026-05-30 04:30:00', '2026-05-30 08:52:31', 'low', '2026-05-30 08:52:31', '2026-05-30 08:52:31'),
	(300, 'وایت لیست نسخه نرم افزاری کارتخوان', 'با توجه به فورس بوده پروژه و هماهنگی پیش از تیکت نسخه های مورد نظر نوین (3 نسخه) در اینترچنج اد گردید تا امکان تست نسخه میسر شود.', 100, 22, NULL, 4, 39, 'پرداخت نوین آرین', 'مهدی جهانگیری', '2026-05-30 09:30:00', '2026-05-30 11:30:00', 'medium', '2026-05-30 11:22:33', '2026-05-30 11:22:33'),
	(301, 'بروزرسانی شبای ترمینال های بانک تجارت', 'با کوئری مورد نظر تعداد 1000 تا 1000 آپدیت انجام گردید', 100, 22, NULL, 4, 10, 'پرداخت نوین آرین', 'زهرا کمایی', '2026-05-30 09:30:00', '2026-05-31 00:00:00', 'high', '2026-05-31 02:09:30', '2026-05-31 02:09:30'),
	(302, 'بروزرسانی شباهای تجارت', 'با کوئری مورد نظر تعداد 1000 تا 1000 آپدیت انجام گردید', 100, 22, NULL, 9, 37, 'تجارت الکترونیک پارسیان', 'مریم خزلی', '2026-05-30 08:30:00', '2026-05-31 01:30:00', 'high', '2026-05-31 02:10:49', '2026-05-31 02:10:49'),
	(303, 'دان تایم', 'بروزرسانی و راه اندازی مجدد تکاکی سرورهای نوین و رفاه و sw,app.db.mongo', 100, 22, NULL, 4, 39, 'پرداخت نوین آرین', 'مهدی جهانگیری', '2026-05-30 18:30:00', '2026-05-31 02:30:00', 'high', '2026-05-31 02:12:33', '2026-05-31 02:12:33'),
	(304, 'تغییر شباهای بانک تجارت', 'گرفتن فایل از شرکت نوین و پارسیان\r\nچک و اینزرت فایل ها در دیتابیس \r\nنوشتن کوئری اپدیت \r\nبک اپ گرفتن از دیتابیس پارسیان\r\nتست یکی از کارت ها برای پارسیان جهت صحت کوئری\r\nارسال همه کوئری ها برای ارسلان', 100, 27, NULL, 2, 38, 'اینتک', 'مهدی ایمنی', '2026-05-31 08:30:00', '2026-05-31 08:30:00', 'high', '2026-05-31 08:17:22', '2026-05-31 08:17:22'),
	(305, 'فارا', 'پیگیری و چک کردن فارا به جهت دیر ارسال کردن 220به آقای افشار توضیح داده شد که روال به همین صورت است و عملکرد طبیعی می باشد و در صورت نیاز باید دارایی نسخه اعمال کند بر روی سوئیچ', 100, 22, NULL, 4, 10, 'پرداخت نوین آرین', 'زهرا کمایی', '2026-05-31 08:30:00', '2026-05-31 12:30:00', 'medium', '2026-06-01 05:14:44', '2026-06-01 05:14:44'),
	(306, 'سیگنالینگ ایشوئری پرداخت نوین', 'توضیح به آقای افشار و آموزش جهت ساختن فایل سیگنالینگ', 100, 22, NULL, 4, 39, 'پرداخت نوین آرین', 'مهدی جهانگیری', '2026-06-01 05:30:00', '2026-06-01 08:30:00', 'medium', '2026-06-01 08:48:11', '2026-06-01 08:48:11'),
	(307, 'تغییر حساب مالتی اکانت', 'بررسی لاگ تراکنش تغییر حساب ترمینال 11194434  سامان کیش\r\nپیرو پیگیری مجدد مقرر گردید آقای پهلوان تست کنند و اطلاع دهند 13/03\r\nپیرو آخرین بررسی اطلاعات جدیدی از آخرین وضعیت توسط آقای پهلوان ارائه نشد. 03/18', 100, 22, NULL, 8, 31, 'پرداخت الکترونیک سامان کیش', 'امیر عابدی', '2026-06-01 08:30:00', '2026-06-08 05:30:00', 'medium', '2026-06-01 08:49:26', '2026-06-08 05:38:20'),
	(308, 'پیاده سازی سرویس شارژ جدید', 'با خانم کمایی تماس گرفته شد و رد تماس کردند\r\nبا آقای جهانگیری تماس گرفته شد پاسخگو نبودند\r\nبا آقای حلاجی تماس گرفته شد و به ایشان توضیحات ارائه شد و مقرر شد تغییرات کانفیگی سمت پرداخت نوین اعمال گردد', 100, 22, NULL, 4, 10, 'پرداخت نوین آرین', 'زهرا کمایی', '2026-06-01 06:30:00', '2026-06-01 08:51:42', 'high', '2026-06-01 08:51:42', '2026-06-01 11:17:24'),
	(309, 'تغییر شباهای بانک تجارت براساس الگوریتم استاندارد در سوئیچ پذیرندگی', 'شماره شباهای بانک تجارت با الگوریتم استاندارد برای شرکت  پرداخت نوین \r\nدر تاریخ 405/03/10 از ساعت ۱۲ بامداد شروع و ساعت 04:30 صبح به اتمام رسید.\r\n', 100, 28, NULL, 4, 39, 'پرداخت نوین آرین', 'مهدی جهانگیری', '2026-05-30 20:30:00', '2026-05-31 01:00:00', 'medium', '2026-06-01 08:55:56', '2026-06-01 08:55:56'),
	(310, 'تغییر شباهای بانک تجارت براساس الگوریتم استاندارد در سوئیچ پذیرندگی', 'شماره شباهای بانک تجارت با الگوریتم استاندارد برای شرکت تجارت الکرونیک پارسیان \r\nدر تاریخ 405/03/10 از ساعت ۱۲ بامداد شروع و ساعت 04:30 صبح به اتمام رسید.\r\n', 100, 28, NULL, 9, 45, 'تجارت الکترونیک پارسیان', 'تربتی فرد', '2026-05-30 20:30:00', '2026-05-31 01:00:00', 'medium', '2026-06-01 08:56:46', '2026-06-01 08:56:46'),
	(311, 'جلسه دوم پارسیان', 'موضوعات مطرح شده در این جلسه :\r\nصدور رونوشت\r\nتمدید رونوشت\r\nثبت درخواست کارت\r\nو سایر مطالبی که در جلسه مطرح شد در قالب صورت جلسه به شرکت ارایه خواهد شد.', 100, 28, NULL, 2, 38, 'اینتک', 'مهدی ایمنی', '2026-06-01 04:30:00', '2026-06-01 08:30:00', 'low', '2026-06-01 08:58:30', '2026-06-01 08:58:30'),
	(312, 'CPU Sep', 'تماس از واحد مانیتورینگ سامان مبنی بر بالا رفتن CPU تا حد 83% \r\nموضوع بررسی و مورد رفع شد.', 100, 28, NULL, 8, 31, 'پرداخت الکترونیک سامان کیش', 'امیر عابدی', '2026-05-29 20:30:00', '2026-05-30 09:00:00', 'low', '2026-06-01 08:59:54', '2026-06-01 08:59:54'),
	(313, 'عدم نمایش اطلاعات تماس برخی کارت ها', 'پیگیری با مهندس ایمنی و ارجاع تیکت سمت ایشان جهت تعیین و تکلیف\r\n\r\nطبق صحبت دیروز با خانم سوزانی و مشکل در فرم اصلاح مشخصات کارت قرار شد واحد توسعه مشکل را برطرف کنند.\r\n', 100, 29, NULL, 9, 52, 'تجارت الکترونیک پارسیان', 'پویا عاطفی', '2026-05-24 09:24:00', '2026-06-17 05:50:00', 'low', '2026-06-01 10:06:58', '2026-06-17 05:52:32'),
	(314, 'بروزرسانی TerminalUID', 'با پیگیری از آقای عاطفی فایل درخواستی در مسیر قرار گرفت و بعد از انتقال به دیتابیس سوییچ و join زدن با جدول AcqTerminal.\r\nTermUid پایانه ها با موفقیت به فایل درخواستی شرکت پارسیان تغییر یافت.', 100, 29, NULL, 9, 52, 'تجارت الکترونیک پارسیان', 'پویا عاطفی', '2026-05-23 06:02:00', '2026-05-31 13:10:00', 'low', '2026-06-01 10:21:50', '2026-06-01 10:21:50'),
	(315, 'افزودن الگوی جدید پروژه والد فرزندی ( 406449820 )', 'پیگیری گردید\r\nمورد مذکور مربوط به ایجاد فرم در بکافیس بوده و نیازمند پیاده سازی توسط تیم توسعه می باشد.', 100, 22, NULL, 4, 41, 'پرداخت نوین آرین', 'سوده فرمانی', '2026-06-01 08:30:00', '2026-06-01 09:30:00', 'high', '2026-06-01 10:45:13', '2026-06-01 10:45:13'),
	(316, 'عملیاتی سازی پروژه مترو بروی کانال 7070و 4080 ( 405446949 )', 'با سلام \r\nبا خانم کمایی هماهنگ شد و مقرر گردید تست و اعلام نتیجه گردد.\r\nپیرو بررسی های انجام شده امروز مورخ 03/12 مقرر گردید تغییرات مجدد سمت مترو و فاوا انجام گردد.', 50, 22, NULL, 0, 0, '', '', '2026-06-01 11:00:00', '2026-06-01 11:27:38', 'high', '2026-06-01 11:27:38', '2026-06-02 08:29:05'),
	(317, 'ایجاد دسترسی با نقش رونوشت انفرادی', 'در سرور 172.25.16.77 ابتدا باید یوزر را جستجو کنیم از طریق جدول B2SMain.sec.user و ID این جدول را برمیداریم در سرور 172.25.16.59 در جدول B2SCard.dbo.TempAccessUsers. \r\nInsert Into می کنیم.\r\n\r\nUSE [B2SCard]\r\nGO\r\nINSERT INTO [dbo].[TempAccessUsers]\r\n           ([UserID])\r\n     VALUES\r\n           (5617)\r\nGO\r\n', 100, 29, NULL, 9, 52, 'تجارت الکترونیک پارسیان', 'پویا عاطفی', '2026-06-01 08:30:00', '2026-06-01 11:28:00', 'low', '2026-06-01 11:43:32', '2026-06-01 11:43:32'),
	(318, 'اکسترنال اکانتینگ', 'پروژه مربوط به امیرپی بوده و نیاز بود بصورت فورس گروه کارت و پترن در پروژه ایجاد گردد\r\nهماهنگی انجام شده و در دیتابیس درج گردید', 100, 22, NULL, 4, 41, 'پرداخت نوین آرین', 'سوده فرمانی', '2026-06-01 12:30:00', '2026-06-01 13:30:00', 'high', '2026-06-01 13:31:41', '2026-06-01 13:31:41'),
	(319, 'کانال طلا', 'پیرو بررسی های انجام شده کانال متصل بوده و بصورت سرور می باشد و در حال لیسن کردن بوده و به آقای جهانگیری اطلاع رسانی گردید و مقرر شد با واحد شبکه نوین بررسی کنند.', 100, 22, NULL, 4, 39, 'پرداخت نوین آرین', 'مهدی جهانگیری', '2026-06-02 07:30:00', '2026-06-02 08:30:00', 'high', '2026-06-02 07:47:12', '2026-06-02 08:28:08'),
	(320, 'بالا رفتن خطاها', 'با توجه به ابزار مانیتورینگ موجود و بررسی علت بالا رفتن خطاها بعد از بررسی های به عمل آمده مشخص شد علت این مورد اختلال در بانک کشاورزی بوده و تمام تراکنش های کشاورزی برگشت خورده اند.\r\nتایم اختلال از ساعت 13:29 الی 13:49 بود.', 100, 28, NULL, 5, 26, 'توسعه فناوری رفاه پردیس', 'محمود عظیمی', '2026-06-02 08:30:00', '2026-06-02 10:22:20', 'medium', '2026-06-02 10:22:20', '2026-06-02 10:22:20'),
	(321, 'OTP LogIn Parsian', 'طبق اعلام درخواست شرکت محترم پارسیان مبنی بر نیازمندی تایید دو مرحله ای برای ورود به بک آفیس \r\nو مذاکره با خانم تربتی فرد و خانم خزلی این مورد نیاز به قبت تیکت توسعه دارد و موارد مورد نیاز به اطلاع شرکت محترم پارسیان رسید.\r\nدر حال حاظر انجام این مورد نیازمند ثبت تیکت و بررسی آن در واحد توسعه میباشد.\r\nمققر شد خانم خزلی بعد از دریافت نامه اعلام نیاز از سوی مهندس تربتی فرد\r\nجهت پیشبرد این امر تیکتی با موضوع توسعه ثبت کنند.', 100, 28, NULL, 9, 45, 'تجارت الکترونیک پارسیان', 'تربتی فرد', '2026-06-01 08:30:00', '2026-06-02 10:24:51', 'low', '2026-06-02 10:24:51', '2026-06-02 10:24:51'),
	(322, 'خطای 03 ( 806451257 )', 'کلید گذاری سپ\r\nموضوع مربوط به خطای کلید می باشد 03 که پس از بررسی لاگ مشخص گردید چنج کی یا تغییر کلید توسط کاربر ثبت نشده که پس از ثبت تراکنش دریافت کلید موفق انجام شده است', 100, 22, NULL, 8, 31, 'پرداخت الکترونیک سامان کیش', 'امیر عابدی', '2026-06-02 12:00:00', '2026-06-02 13:00:00', 'medium', '2026-06-02 12:39:55', '2026-06-02 12:59:23'),
	(323, 'نداشتن 220 ساید 2 بین 1 نوین', 'پیرو بررسی و توضیحات و آموزش به آقای افشار نمونه نشان داده شد که روال بین 1 به همین صورت می باشد و مقرر گردید ایشان به نوین توضیح دهند', 100, 22, NULL, 2, 24, 'اینتک', 'علی رضا افشار', '2026-06-02 12:00:00', '2026-06-02 13:00:00', 'medium', '2026-06-02 12:58:45', '2026-06-02 12:58:45'),
	(324, 'ایجاد دسترسی با نقش رونوشت انفرادی', '2 مورد درخواست رونوشت انفرادی برای یوزرهای ذیل ایجاد شد.\r\ns.jalalian\r\nz.abdollahkhani', 100, 29, NULL, 9, 52, 'تجارت الکترونیک پارسیان', 'پویا عاطفی', '2026-06-02 12:20:00', '2026-06-02 13:30:00', 'low', '2026-06-02 13:40:16', '2026-06-02 13:40:16'),
	(325, 'شارژ ایرانسل', 'پیرو بررسی مشخص گردید نوین در فروش شارژ ایرانسل با مبالغ بغیر از 200.000 ریال موجود نمی باشد.\r\nشارژها تست و انجام گردید', 100, 22, NULL, 2, 22, 'اینتک', 'مهدی صدوقیان', '2026-06-03 06:30:00', '2026-06-08 05:30:00', 'medium', '2026-06-03 07:16:19', '2026-06-08 05:39:20'),
	(326, 'درخصوص طرح ضميه شده در اينتك بصورت فشرده (زيپ شده) ( 906452365 )', 'موضوع درخواست:\r\nباسلام و احترام به اطلاع ميرساند در اينتك دارندگي كارت در قسمت كارت /درخواست هاي كارت / صدور كارت / زماني كه درخواست جديدي ثبت ميشود و درقسمت (فایل طرح کارت ) فايل بصورت فشرده * زيپ شده * ضميمه و ذخيره ميشود؛  \r\n\r\nپیرو بررسی های انجام شده موضوع مربوط به تیت توسعه بوده و تیکت ارجاع گردید', 100, 22, NULL, 9, 52, 'تجارت الکترونیک پارسیان', 'پویا عاطفی', '2026-06-03 07:20:00', '2026-06-03 07:40:00', 'low', '2026-06-03 07:42:59', '2026-06-06 07:09:40'),
	(327, 'تعداد کارتهای صادر شده در سایت کادونا ( 906453386 )', 'موضوع درخواست: \r\nبدینوسـیله به اسـتحضار می رسانـد، پیرو پایش هاي صورت گرفته و گزارش ها در بررسـی هاي به عمل آمده از سایت کادونا، مشخص گردید که در فرآیند تعریف و صدور کارت ها، محدودیت تعداد لحاظ نگردیده است.\r\nلازم به ذکر است که فقـدان این محـدودیت در سـطح سامانه، میتوانـد منجر به بروز مخاطرات جدي از جمله امکان سوء استفاده هاي احتمالی گردد که تداوم این وضعیت، امنیت را با چالش هاي جدي مواجه خواهد ساخت.\r\nلذا با عنایت به حساسـیت موضوع و به منظور پیشـگیري از هرگونه آسـیب احتمالی، خواهشـمند است دستور فرمایید در اسرع وقت نسبت به بررسی دقیق وضعیت موجود و اعمال محدودیت هاي لازم در سایت، اقدامات مقتضی صورت پذیرد.\r\nنمونه کارت :  6221062030820096\r\n\r\nدرخواست دهنده: ناهید روح اله زاده\r\nنامه : 6761\r\n\r\nموضوع بررسی شد و مشخص شد psp درخواست دارد تا مشتری نتواند از طریق سایت (هر شخص حقیقی) بیشتر از 5 کارت نهایت با سقف 15.000.000 تومان (کل مبلغ) یا یک کارت با مبلغ بیشتر از 15.000.000 تومان خرید یا سفارش داشته باشد.\r\n\r\nپیگیری انجام گردید و باید سمت وب سرویس تیم توسعه اصلاح گردد.\r\nبا آقای بهشتی نیز هماهنگ گردید.', 100, 22, NULL, 9, 52, 'تجارت الکترونیک پارسیان', 'پویا عاطفی', '2026-06-03 07:30:00', '2026-06-03 08:00:00', 'low', '2026-06-03 08:05:02', '2026-06-03 08:05:02'),
	(328, 'عدم نمایش شماره تقاضا', 'طبق صحبت با مهندس ایمنی یوزر و پسوورد از کاربر گرفته شد و تحویل ایشان گردید.\r\n\r\nاز آقای یوسفی پیگیری شد و همچنان نمی تواند این شماره تقاضا را مشاهده کند.\r\nمقرر شد تیم توسعه این مشکل را برطرف کنند.', 100, 29, NULL, 9, 52, 'تجارت الکترونیک پارسیان', 'پویا عاطفی', '2026-06-03 08:15:00', '2026-06-17 05:56:00', 'low', '2026-06-03 08:28:49', '2026-08-25 12:09:30'),
	(329, 'فارا تستی', 'توضیحات مربوطه به آقای اغشار جهت نوع تراکنش و چک کردن مولفه های مورد نیاز داده شد.\r\nنمونه نیز از روی لاگ به ایشان نشان  داده و آموزش داده شد.\r\n220 ساید 1 سمت فارا میزد که به خانم کمایی توضیح داده شد', 100, 22, NULL, 4, 10, 'پرداخت نوین آرین', 'زهرا کمایی', '2026-06-03 07:30:00', '2026-06-03 09:00:00', 'low', '2026-06-03 08:31:28', '2026-06-03 09:03:00'),
	(330, 'یوزر رایمون PNA', 'در خصوص عدم توانایی لاگ این به تمامی سرورهای رفاهی از طریق سامانه پم پرداخت نوین\r\nبا کارشناس امنیت نوین (مهندس میرنور) تماس حاصل شد .\r\nبعد از پیگیری مشخص شد که پسورد یوزر m.mohammadi منقضی شده و پسورد جدید صادر شد.\r\nپسورد جدید در اختیار مهندس فتحی برای بررسی تراکنش های فارا قرار گرفت.\r\nبعد از پیگیری از اقای فتحی مشخص شد مشکل فایل های فارا برطرف شده است.\r\n', 100, 28, NULL, 2, 30, 'اینتک', 'ابراهیم فتحی', '2026-06-03 04:30:00', '2026-06-03 09:46:45', 'low', '2026-06-03 09:46:45', '2026-06-13 06:48:52'),
	(331, ' تعداد کارتهای صادر شده در سایت کادونا', 'با آقای عاطفی صحبت و پیگیری شد و نمونه کارتی که داده اند اشتباه است و این تیکت مربوط نمی شود.\r\nمنتظر نمونه صحیح هستم .\r\n\r\nهمچنان منتظر اعلام نمونه کارت صحیح برای پیگیری و چک کردن موضوع هستم.', 50, 29, NULL, 9, 52, 'تجارت الکترونیک پارسیان', 'پویا عاطفی', '2026-06-03 07:55:00', '2026-06-03 10:54:48', 'low', '2026-06-03 10:54:48', '2026-06-14 08:01:39'),
	(332, 'پیگیری کد شعبه', 'بررسی در دیتابیس جهت ویو رفاه برای دیتای کد شعب\r\nمقرر گردید وب سرویس جهت ثبت در دیتابیس ایجاد گردد\r\nابتدا از سامانه جام جم (یاوری) سپس توسط اینتک در دیتابیس در جدول مورد نظر ثبت گردد.\r\nتوضیحات به آقای عظیمی توسط افشار ارائه گردید.', 100, 22, NULL, 5, 26, 'توسعه فناوری رفاه پردیس', 'محمود عظیمی', '2026-06-06 07:30:00', '2026-06-08 09:30:00', 'low', '2026-06-06 07:36:11', '2026-06-08 09:35:28'),
	(333, 'تغییر شبای بانک تجارت', 'پیرو تماس خانم هاشمی و خانم کمایی تعذلذی از شباهای بانک تجارت آپدیت نشده و مجدد لیست ارسال شد برای آپدیت\r\nپیرو بررسی فایل ها لیست ناقص بوده و مقرر گردید لیست جدید توسط خانم کمایی ارسال شود.\r\nبا خانم کمایی هناهنگ گردید و مشخص شد تمامی شباها در همان شب آپدیت شده و مقرر گردید پرداخت نوین با شاپرک دبل چک کنند.\r\nموضوع توسط خانم سنگی به خانم کمایی اطلاع رسانی گردید.\r\n', 100, 22, NULL, 4, 10, 'پرداخت نوین آرین', 'زهرا کمایی', '2026-06-06 08:45:00', '2026-06-08 09:30:00', 'high', '2026-06-06 09:03:02', '2026-06-08 09:36:57'),
	(334, 'ارسال مبلغ کمتر از 2000 تومان برای شاپرک', 'در تراکنش فارا با مبلغ کمتر از 2000 تومان ارسال می شود و باعث بالا رفتن خطای psp شده\r\nبه آقای ایمنی جهت اعلام به آقای دارایی برای جلوگیری از تراکنش با مبلغ زیر 2000 تومان پس از استعلام فارا اعلام گردید', 100, 22, NULL, 8, 31, 'پرداخت الکترونیک سامان کیش', 'امیر عابدی', '2026-06-06 07:30:00', '2026-06-08 05:30:00', 'medium', '2026-06-06 09:32:00', '2026-06-08 05:33:49'),
	(335, 'سرویس نامشخص بر روی نود اکوئری 23 سپ', 'موضوع بررسی گردید سرویسی در نود 23 وجود دارد برای کال کردن پین شارژها که  از نود 23 نود 24 تستی با آیپی 172.31.7.30 کال می شود و شارژ 10 تومانی انجام میشود اما شارژ 50 تومانی خطا میدهد و سپ پیگیر سرویس و مورد می باشد.\r\nپیرو بررسی مجدد درخواستی از سپ در این خصوص ثبت نگردید', 100, 22, NULL, 8, 31, 'پرداخت الکترونیک سامان کیش', 'امیر عابدی', '2026-06-06 09:30:00', '2026-06-08 09:30:00', 'medium', '2026-06-06 11:08:26', '2026-06-08 09:32:55'),
	(336, 'گزارش تعداد تراکنش موفق گروه کارت تنخواه - قبضینو ( 406455525 )', 'باسلام و احترام\r\nخواهشمند است گزارش تعداد تراکنش های موفق گروه کارت &quot;تنخواه - قبضینو &quot;  برای مهرماه  تا پایان اسفند ماه 1404 با در نظر گرفتن فیلد ServerDateTime به عنوان زمان گزارش،   ارسال گردد.\r\nباسپاس\r\n\r\nبا توجه به درخواست مشتری پیرو  نوع فیلتر کوئری ایجاد و تراکنش گرفته شد و ارسال گردید.\r\nبا توجه به تغییرات مد نظز گزارش تهیه و پیوست تیکت گردید\r\nپیرو آخرین بررسی تیکت به واحد توسعه ارجاع گردید.\r\nپیرو آخرین بررسی مشخص گردید کوئری های پشت بکافیس و وب سرویس مشتری مشکل دارد و گزارش تراکنش ها اشتباه بوده است.\r\nوب سرویس توسط تیم توسعه رفع گردید و مقرر شد بکافیس نیز اصلاح گردد.', 100, 22, NULL, 4, 25, 'پرداخت نوین آرین', 'میلاد حلاجی', '2026-06-06 11:30:00', '2026-06-08 09:30:00', 'high', '2026-06-06 11:56:46', '2026-06-08 12:53:08'),
	(337, 'وب سرویس ریفاند', 'رفاه پردیس نیاز به پیاده سازی وب سرویس ریفاند دارد که لازمه اینکار پیاده سازی ریفاند در سوئیچ می باشد.\r\nدر صورتی که پیاده سازی شده در سوئیچ، ادامه فرآیند جهت پیاده سازی وب سرویس به تیم توسعه ارجاع گردد.', 100, 22, NULL, 5, 26, 'توسعه فناوری رفاه پردیس', 'محمود عظیمی', '2026-06-06 11:50:00', '2026-06-06 12:30:00', 'high', '2026-06-06 12:13:10', '2026-06-06 12:13:10'),
	(338, 'رفع باگ فرم گروه کارت ', 'از آقای عاطفی پیگیری کردم قرار شد نمونه تحوبل بده که هنوز نفرستاده .\r\nاز خانم تربتی پیگیری کردم و گفتند نمونه نداریم از روی سورس مشکل بررسی شود.\r\nقرار شد که خانم تربتی و جناب عاطفی گروه کارت و نمونه کارتی که تخصیص داده شده و در سوییچ اعمال نشده را ارسال کنند.\r\n\r\nبا آقای عاطفی صحبت و پیگیری کردم و اعلام کردند هر دوشنبه پارسیان اکسل می دهد برای تخصیص کارت.\r\n\r\n\r\n//////////////// \r\nگزارش کامل !', 50, 29, NULL, 9, 52, 'تجارت الکترونیک پارسیان', 'پویا عاطفی', '2026-06-06 10:30:00', '2026-06-17 07:07:00', 'low', '2026-06-06 12:33:28', '2026-06-17 07:07:15'),
	(339, 'گزارش اختلال سرویس فارا در تاریخ 16 خرداد', 'بعد از بررسی و پیگیری از اقای تفضلی مشخص شد دلیل اختلال سوییچ ربطی به منقضی شدن توکن ندارد و دلیل اصلی به دلیل اختلال در سوییچ و بالا رفتن ریورس ها دارد 2 کد خطای 57 و 58 با تعداد بالا در گزارشات مشاهده شد که کد خطای 57 به دلیل اختلال مانا بوده است \r\nو  الان اقای تفضلی براشون توضیح داده اینارو  قرار شده نوین به ما بگه که قانع شدن یا هنوز نیاز به گزارش دارن\r\nدر تاریخ 03/18 کمایی در بله پیام داد و گفت فارا اوکیه(قانع شدن)', 100, 27, NULL, 2, 38, 'اینتک', 'مهدی ایمنی', '2026-06-07 08:30:00', '2026-06-07 08:30:00', 'medium', '2026-06-07 07:22:01', '2026-06-08 11:05:53'),
	(340, 'پیگیری خطای تراکنش های فارای نوین', 'بررسی خطای فارا\r\nپیرو بررسی های انجام شده تراکنش فارا خطای 58 که مربوط به قابلیت های ترمینال است گرفته در صورتیکه ترمینال در ساعات قبل و بعد اختلال درست کار کرده و مشکل از فارا یا سوئیچ بوده است.\r\nتوضیحات به خانم سنگی ارائه گردید و مقرر شد گزارش تهیه و برای آقای ایمنی ارسال گردد', 100, 22, NULL, 4, 39, 'پرداخت نوین آرین', 'مهدی جهانگیری', '2026-06-06 19:30:00', '2026-06-08 05:30:00', 'high', '2026-06-07 10:43:05', '2026-06-08 05:36:08'),
	(341, 'کلید شاپرک', 'انقضا کلید عمومی شرکت پرداخت نوین آرین 051 ( 202605-1592 )\r\nموضوع مربوط به تغییر کلید شاپرک و همچنین جایگزینی کلید صدرا می باشد.\r\nپیرو بررسی و مذاکره با آقای جهانگیری کلید صدرا تحویل شده و مقرر گردید برای اینتک ارسال گردد و پس از بررسی و هماهننگی دان تایم ثبت گردد و کلید صدرا با کلید پاپلیک شاپرک جایگزین گردد.\r\nهمچین مقرر گردید در زمان دان تایم tls 1.3 بر روی کانال شاپرک بین 1 اجرا گردد و در صورت درست بودن چند روز تست شود سپس برای بین 1 نیز همین روال انجام شود.\r\nپیرو آخرین بررسی و مذاکرات مقرر شد pfx از نوین برای اینتک ارسال شود و در صورت نیاز فایل کلید سرت نیز ارسال گردد و بر روی سوئیچ بارگزاری گردد در زمان دان تایم و tls 1.3 نیز فعال گردد.\r\n\r\nدر ادامه فرآیند مذکور تیکت جدید با مشخصات فایل گواهی صدرا ( 406459026 ) ثبت گردید و مقرر شد رمز توسط آقای جهانگیری ارسال گردد.\r\n\r\nتیکت انقضا کلید عمومی شرکت پرداخت نوین آرین 051 ( 202605-1592 ) مربوط به همین تیکت بوده و در  راستای تیکت فایل گواهی صدرا ( 406459026 )\r\n می باشد و تیکت 1592  بسته می شود.\r\nپیرو مذاکره مجدد با آقای جهانگیری فایل های ارسالی در تیکت خانم کمایی (سرتیفیکیت ها) اشتباه بوده و مقرر گردید فایل pfx برای بنده ارسال گردد.\r\n\r\nمجدد از آقای جهانگیری پیگیری گردید و مقرر شد فایل ارسال شود.', 100, 22, NULL, 4, 39, 'پرداخت نوین آرین', 'مهدی جهانگیری', '2026-06-08 06:30:00', '2026-06-13 12:30:00', 'low', '2026-06-08 07:43:08', '2026-07-12 11:58:58'),
	(342, 'لاگ تراکنش 230 موفق', 'نیاز به نمونه لاگ تراکنش 230 بود که به خانم سنگی آموزش داده شد و برای ایشان نمونه ارسال گردید', 100, 22, NULL, 4, 10, 'پرداخت نوین آرین', 'زهرا کمایی', '2026-06-08 07:30:00', '2026-06-08 07:50:00', 'low', '2026-06-08 07:52:05', '2026-06-08 07:52:05'),
	(343, 'تماس مانیتورینگ سامان پرداخت مبنی بر پر شدن سرور مونگو 29.45', 'با سلام پیرو تماس مانیتورینگ سامان (آقای پرهیری) مورخ 05/03/07 ساعت 12:30 بامداد، فضای سرور 172.31.29.45 به 90% رسیده بود که توسط بنده فضای آن سرور آزاد گردید.', 100, 24, NULL, 8, 31, 'پرداخت الکترونیک سامان کیش', 'امیر عابدی', '2026-06-07 08:30:00', '2026-06-07 08:30:00', 'medium', '2026-06-08 09:59:08', '2026-06-08 09:59:08'),
	(344, 'هشدار پایانه', 'موضوع مربوط به کشف تقلب دارد که شرح کار و جدول و روش پر شدن به آقای افشار جهت ارائه و بررسی با مشتری توضیح داده شد.', 100, 22, NULL, 5, 26, 'توسعه فناوری رفاه پردیس', 'محمود عظیمی', '2026-06-08 11:30:00', '2026-06-08 12:15:00', 'medium', '2026-06-08 12:15:47', '2026-06-08 12:15:47'),
	(345, 'اصلاح کف مبلغ ترمینال ها ( 406458755 )', 'اصلاح کف مبلغ ترمینال ها ( 406458755 )\r\n\r\nاین موضوع مربوط به سامانه جام جم بوده و باید بر روی api تغییر گردد.\r\nترمینال های مذکور نیز باید در دیتابیس اکوئری در دینتابیس b2smain جدول ترمینال و مرچنت فیلد مربوط به کف و سقف بوده که آپدیت شود.\r\nبه خانم سنگی  جهت تغییرات اطلاع رسانی گردید.', 100, 22, NULL, 4, 10, 'پرداخت نوین آرین', 'زهرا کمایی', '2026-06-09 05:30:00', '2026-06-09 05:45:00', 'medium', '2026-06-09 05:45:00', '2026-06-09 05:45:00'),
	(346, 'وضعیت بحرانی سرور 80.35 ', 'وضعیت بحرانی سرور 80.35 ( 806459358 )\r\nبا توجه به اینکه در تایم 00:00 الی 01:00 بامداد سرور 172.31.80.35 با افزایش cpu مواجه می شود و تقریبا هر شب این اتفاق تکرار می شود و این مورد به صورت تلفنی به همکاران اینتک اطلاع داده شده ولی رفع نگردیده لطفا در سامانه تیکت اینتک این مورد را اعلام فرمایید\r\n----------\r\nپیرو مذاکره با آقای موسوی احتمالا بخاطر تعدادی کوئری می باشد که از سمت خود سپ در آن تایم اجرا می گردد.\r\nلذا مقرر گردید ایشان پروسسور و جاب ها و کوئری های تایم مذکور را بررسی کرده و اعلام نمایند.\r\n\r\nبا سعید موسوی صحبت کردم روی 80.35 مانیتورینگ و کوئری باز کرده تا زمانی که خطا میخوره لاگ ثبت بشه و بررسی کنیم مشکل از چیه و کجاس\r\n\r\nبا سعید مجدد مذاکره شد و درگیر قطعی بانک ها بود و مقرر شد سرویسی که برای چک کردن باز گذاشته بعدا چک کنه و خبر بده 1405/03/23\r\n----\r\nبا سلام و احترام\r\nپیرو بررسی های انجام شده در حدود 1 هفته مورد خاصی وجود ندارد.\r\nدر صورت بروز اختلال لطفا تصویری از مانیتورینگ یا گراف ارسال گردد.\r\nبا سپاس\r\n', 100, 22, NULL, 8, 31, 'پرداخت الکترونیک سامان کیش', 'امیر عابدی', '2026-06-09 05:40:00', '2026-06-16 07:41:00', 'high', '2026-06-09 06:09:43', '2026-06-16 07:42:05'),
	(347, 'از دسترس خارج شدن دیتابیس گزارش گیری رفاه پردیس', 'با سلام و احترام \r\nپیرو تماس آقای عظیمی در تاریخ 05/03/19 در ساعت 07:30 صبح ازتباط دیتابیس شرکت رفاه قطع گردیده بود و خطای زیر برای ایشان نمایش داده میشد:\r\nDatabase &#039;B2STxn&#039; cannot be opened due to inaccessible files or insufficient memory or disk space.  See the SQL\r\n Server errorlog for details.\r\nپیرو بررسی با آقای موسوی، مشکل از Always on High دیتابیس 187.12 بوده که متوقف شده بود. در ساعت 9:15 این اختلال برطرف گردید.\r\n\r\n\r\nسپاس از شما', 100, 24, NULL, 5, 26, 'توسعه فناوری رفاه پردیس', 'محمود عظیمی', '2026-06-09 03:30:00', '2026-06-09 05:30:00', 'high', '2026-06-09 06:51:08', '2026-06-09 07:55:10'),
	(348, 'پروژه ی کارت _ عدم وجود تراکنش ( 406459519 )', 'پروژه ی کارت _ عدم وجود تراکنش ( 406459519 )\r\nتراکنش با مبلغ 104,488,000 و شماره مرجع 347885245068 با کارت 6274-1244-9134-2535 در تاریخ 18 خرداد اعمال شده است ولی بر روی بک آفیس نمایش داده نمی شود.\r\nلاگ وب سرویس پروژه ی کارت به پیوست ارسال می گردد.\r\n---------------\r\nبا سلام پیرو بررسی و مذاکرات قبلی در بکافیس ایشوئری فقط تراکنش های موفق نمایش داده می شود و مقرر گردیده بود psp اعلام کند تا در صورت نیاز تراکنش های ناموفق نیز نمایش داده شود.\r\nهمچنین تراکنش مذکور در زمان انجام تراکنش وب سرویس ی کارت را کال کرده اما پاسخی دریافت نشده و سرویس تایم اوت شده و پاسخ 96 ثبت شده است.\r\n\r\nپیرو مذاکره با خانم فرمانی و توضیحات لاگ تراکنش، مقرر گردید در صورت نیاز درخواست توسعه ثبت گردد تا تراکنش های ناموفق نیز امکان دریافت گزارش در بکافیس با اعمال فیلتر میسر گردد.\r\n\r\nتیکت بسته شد\r\n\r\n\r\n-----------------\r\nلاگ کجا دیدی چه دستوراتی استفاده کردی \r\n', 100, 22, NULL, 4, 25, 'پرداخت نوین آرین', 'میلاد حلاجی', '2026-06-09 08:30:00', '2026-06-09 10:50:00', 'high', '2026-06-09 09:15:38', '2026-06-22 08:51:25'),
	(349, 'جلسه سوم پارسیان', 'جلسه سوم تجارت الکترونیک پارسیان به صورت حضوری در محیط مشتری برگزار شد.\r\nصورت جلسه در حال آماده سازی و ارسال برای مهندسان ایمنی و محمدی میباشد.\r\nصورت جلسه به صورت پیش نویس آماده شده است\r\nجلسه بعدی که مقرر بود در تاریخ 25-03-1405 برگزار شود در حال حاظر به حالت تعلیق درآمده است.\r\nهنوز برای جلسه حضوری بعدی زمانی مقرر نشده است.', 100, 28, NULL, 9, 37, 'تجارت الکترونیک پارسیان', 'مریم خزلی', '2026-06-08 08:30:00', '2026-06-10 06:25:44', 'medium', '2026-06-10 06:25:44', '2026-06-22 13:05:18'),
	(350, 'خطای قطعی 1 دقیقه ای نوین', 'پیرو بررسی های انجام شده تراکنش از ابزار پذیرش به سوئیچ اکوئری رسیده و اکوئر شده و به شاپرک فوروارد گردیده است اما شاپرک دیر پاسخ داده و بدلیل تایم اوت شده تراکنش توسط اکوئر خطای 91 ارسال شده است.\r\nدر ادامه شاپرک با تاخیر پاسخ داده و جواب موفق برگردانده اما با توجه به دیر پاسخ دادن و پس از تایم اوت تراکنش مردود گردیده است.\r\nکلیات خطا\r\n\r\nResponseReceivedTooLateException (-2) (68) که از شاپرک گرفتیم\r\n\r\nیعنی پاسخ از مقصد برگشته، اما دیرتر از زمان مجاز رسیده.\r\n\r\nتفاوت با خطای قبلی:\r\n\r\nکد 91: اصلاً پاسخی نگرفتید / Issuer inoperative\r\nکد 68: پاسخ رسید، ولی بعد از Timeout؛ دیگر برای تراکنش معتبر نیست\r\n\r\nپس احتمالاً سناریو این بوده:\r\n\r\nتراکنش ارسال شده.\r\nسیستم بین ۳۰ یا ۳۷ ثانیه منتظر مانده.\r\nTimeout/Rollback یا پاسخ 91 ساخته شده.\r\nبعداً پاسخ اصلی از مقصد رسیده.\r\nچون دیر رسیده، سیستم آن را با 68 / Response received too late رد کرده.\r\nتوضیحات به آقای جهانگیری نیز ارائه شد.\r\nایشان نیز قبول کردند.\r\n\r\n\r\n-------------------------\r\n\r\nعملیات باید قید شود', 100, 22, NULL, 4, 39, 'پرداخت نوین آرین', 'مهدی جهانگیری', '2026-06-10 04:30:00', '2026-06-10 09:15:00', 'high', '2026-06-10 08:16:40', '2026-06-22 08:50:02'),
	(351, 'خطای تراکنش 50 هزارتومانی شارژ ایرانسل همراه اول', 'با سلام بررسی گردید \r\n2 مخزن شارژ وجود دارد \r\nیک مخزن مربوط به ارتباط فردا و دیگری مربوط به سامان پرداخت\r\nسامان پرداخت دارای 120.000 شارژ 50 تومانی\r\nارتباط فردا دارای 10 عدد شارژ 50 تومانی ایرانسل\r\n\r\nتوضیحات به پرویزی ارائه شد و مقرر گردید به پهلوان صحبت کنه\r\nتماس با پهلوان گرفته شد و ریجکت کرد پرویزیو\r\nمجدد چک شد و ی شماره ترمینال به ما دادن که بررسی کردم تراکنش خطای اکسترنال 9000 از شاپرک گرفته\r\nترمینال 14942845 مرجع 862189141671\r\nپیرو لاگ های پیوست خطا از شاپرک برگشته\r\n14-شماره کارت ارسالی نامعتبر است (وجود ندارد)\r\n\r\n\r\n====\r\nگزارش ناقص است \r\n', 100, 22, NULL, 8, 31, 'پرداخت الکترونیک سامان کیش', 'امیر عابدی', '2026-06-10 07:45:00', '2026-06-10 12:00:00', 'high', '2026-06-10 08:21:27', '2026-06-22 08:49:23'),
	(352, 'شارژهای ۵۰ تومنی ایرانسل', 'طبق اعلام سامان پرداخت شارژهای ۵۰ تومنی ایرانسل با خظا مواجه میشوندو\r\nبعد از بررسی مشخص شد سامان دارای ۲ مخزن شارژ میباشد، یکی مخزن سامان و یکی مخزن ارتباط فردا\r\nمخزن سامان دارای ۱۰کا شارژ بوده و مخزن ارتباط فردا فقط ۱۰ عدد شارژ موجود دارد.\r\nسامان باید بررسی کند که این مخزن از مجا پر میشود و چرا در حال حاظر خالی است.\r\n\r\n\r\n============\r\n\r\nنحوه دستورات ادرس  و.....', 100, 28, NULL, 8, 31, 'پرداخت الکترونیک سامان کیش', 'امیر عابدی', '2026-06-10 04:30:00', '2026-06-10 09:32:38', 'medium', '2026-06-10 09:32:38', '2026-06-22 08:48:59'),
	(353, 'بررسی علت قطعی در پرداخت نوین', 'در ساعت ۱۲:۰۹ ظهر تا ساعت ۱۲:۱۲ دقیقه ظهر تعداد خطاهای سوییچ بالا رفته بود که با استفاده از کوییری\r\n\r\n\r\n\r\nSELECT\r\n    responsecode,\r\n    COUNT(*) AS ErrorCount\r\nFROM b2stxn.dbo.swtxn WITH (NOLOCK)\r\nWHERE localdatetime &amp;amp;amp;gt;= &amp;amp;amp;#039;2026-06-09 12:09:00&amp;amp;amp;#039;\r\n  AND localdatetime &amp;amp;amp;lt;  &amp;amp;amp;#039;2026-06-09 12:12:00&amp;amp;amp;#039;\r\n  AND responsecode  0\r\nGROUP BY responsecode\r\nORDER BY ErrorCount DESC;\r\n\r\n\r\nselect top 100 * from b2stxn.dbo.swtxn WITH (NOLOCK)\r\nwhere responsecode in (91,2,25)\r\nand localdatetime &amp;amp;amp;gt;= &amp;amp;amp;#039;2026-06-09 12:09:00&amp;amp;amp;#039;\r\nAND localdatetime &amp;amp;amp;lt;  &amp;amp;amp;#039;2026-06-09 12:12:00&amp;amp;amp;#039;\r\n\r\n\r\n10.0.72.101:6985\r\n\r\nنمونه تراکنش های مردود شده یافت شد.\r\nبعد از بررسی به عمل آمده مشخص شد سوییچ به هنگام ارسال تراکنش برای Uplink_gateway_20 تایم اوت داده است، چون ارسال برای اپلینک 20012.0743Ms زمان برده است. به همین علت خطای ۹۱-۴ داده است.\r\nبه نظر میرسد مشکل از سمت بانک(شاپرک) بوده است.\r\n\r\n\r\n\r\n', 100, 28, NULL, 4, 39, 'پرداخت نوین آرین', 'مهدی جهانگیری', '2026-06-09 19:30:00', '2026-06-10 09:41:09', 'high', '2026-06-10 09:41:09', '2026-06-29 09:18:34'),
	(354, 'تغییر شماره همراه', 'طبق درخواست آقای محمدی \r\nبررسی شود که در کدام یک از فیلد های بک افیس امکان تغییر شماره موبایل وجود دارد\r\nو با شماره کارت نمونه بررسی شود که کدام منو به صورت درست کار میکند.\r\nشماره کارت نمونه طی مذاکره تلفنی از مهندس خزلی دریافت شدو به شرح زیر است\r\n6221064807147414\r\nبعد از بررسی و تست نمونه کارت خانم خزلی مشخص شد هر دو منوی بک افیس به درستی در حال کار بوده و مشکلی در سامانه ما وجود ندارد.', 100, 28, NULL, 2, 9, 'اینتک', 'محمد علی محمدی', '2026-06-10 08:30:00', '2026-06-13 16:47:00', 'high', '2026-06-10 11:00:51', '2026-06-13 04:47:33'),
	(355, 'مانیتورینگ سامان (CPU)', 'تماس از مانیتورینگ سامان بابت بالا رفتن CPU سرور 172.31.29.43\r\nکه به مقدار ۱۶٪  رسیده بود و بعد از مانیتور کردن این عدد به کمتر از ۷٪ رسید.\r\nبرای مانیتور کردن باید ابتدا وارد ولیکس سامان به آی پی 172.31.50.128 و سپس وارد سرور 29.43 شویم و از طریق task manager مقدار استفاده سیستم از سی پی یو را بررسی میکنیم\r\n', 100, 28, NULL, 8, 31, 'پرداخت الکترونیک سامان کیش', 'امیر عابدی', '2026-06-11 04:04:00', '2026-06-13 04:45:44', 'medium', '2026-06-13 04:45:44', '2026-06-22 12:45:07'),
	(356, 'شارژهای ۵۰ تومنی ارتباط فردا', 'طبق گزارش آقای ایمنی شارژهای ۵۰ تومنی ایرانسل سامان که از ارتباط فردا تهیه میشود با خطای ۱۲ مبلغ نامعتبر مواجه میشود.\r\nبعد از بررسی لاگک نمونه مشخص شد تراکنش اصلی با مبلغ ۵۰۰۰۰ به سوییچ میرسد\r\nاما بعد در مرحله درخواست شارژ پوز در فیلد ۴۸ دیتای (۹)را ارسال میکند که سوییچ طبق این دیتا به سراغ PriceID 9 رفته که مربوط به شارژ ۱۰۰۰ تومنی میباشد.\r\nبه اطلاع مهندس ایمنی رسید و مقرر شد از اقای پهلوان لاگ شارژ50 تومن و 10 تومنی ارتباط فردا گرفته شود پ با آن شرکت محترم بررسی شود که چرا در فیلد ۴۸ عدد ۹ ارسال میشود.\r\nاز اقای پهلوان پیگیری شد برای ارسال لاگ و ایشان فرمودند که هنوز ارتباط فردا برایشان لاگی ارسال نکرده است.\r\nپیگیری مجدد انجام خواهد شد.\r\nمقرر شد ترتیبی اتخاذ شود تا امکان ادیت و آپدیت شارژپرایس برای آن شرکت محترم فراهم شود.\r\nفردا به همراه مهندس ایمنی بررسی شود.\r\nبرای چک کردن رپر که آیا API درستی را کال میکند و چه پاسخی میگیرد ابتدا وارد سرور 7.30 سامان شده و از طریق IIS اقدام به برداشتن جیسون ورودی وب سرویس میکنیم.\r\nدر حال حاظر در حال نصب PostMan برای تست هستیم.\r\nمقرر شد پابلیش برای شارژهای ۵۰ تومنی قرار بگیرد اما به دلیل قطع بودن تمام سرویس هاس ارتباط فردا ، تا وصل شدن مجدد سرویس ها این تسک به تعویق افتاد.\r\nطبق آخرین پیگیری آقاقی افشار با مهندس پهلوان (بعد از پابلیش )تست های موفق انجام داده و مورد برطرف شده است.', 100, 28, NULL, 8, 31, 'پرداخت الکترونیک سامان کیش', 'امیر عابدی', '2026-06-10 04:30:00', '2026-06-13 04:52:47', 'medium', '2026-06-13 04:52:47', '2026-06-20 08:13:54'),
	(357, ' Qr merchant', 'تست Qr merchant با شرکت خدمات ( 406462256 )\r\n\r\nموضوع مربوط به تست نسخه پوز با ورژن 10.4.44 می باشد جهت راه اندازی qr و کلید گذاری کارتخوان\r\nنسخه ابتدا در وایت لیست اینزرت شده سپس عملیات کلید گذاری آغاز می شود.\r\n----\r\nنسخه اد گردید و مقرر شد تست گردد\r\nتست انجام شد اما با خطا مواجه گردید  مقرر شد مجدد نسخه از سمت پرداخت نوین (خانم کمایی) بررسی گردد\r\n\r\nکانال و کانکتور مشخص نبود پس از تماس با خانم کمایی مشخص گردید\r\nدر تیکت چند آیپی پورت وجود داشت\r\n\r\nبا خانم کمایی مذاکره شد مجدد مشخص شد pfx و کلید کامل نیست مجدد هماهنگ گردید با پسوند درست و رمز نیز ارسال شد\r\n\r\nپیرو انجام عملیات و وجود مشکل مقرر گردید مجدد خانم کمایی کلیدها را بررسی کنند و اطلاع دهند\r\n\r\npfx و رمز اعمال شد همچنان کانال بالا نیامده\r\n\r\nبا خانم کمایی مذاکره شد و آموزش کلید ها به ایشان داده شد و مقرر گردید پیگیری کنند برای کلیدها از خدمات و اطلاع رسانی کنند به اینتک\r\nکانکشن بیلد شد اما به رمز pfx خطا داده و به خانم کمایی اطلاع رسانی گردید\r\nرمز جدید pfx  توسط خانم کمایی ارسال گردید\r\nکانال بیلد شد و از خدمات دان است و مقرر گردید فردا خانم کمایی پیگیری کنند\r\n-----\r\nخطای 19 گرفته که مربوط به بالا نبودن کانال سمت خدمات می باشد و به خانم کمایی اطلاع رسانی گردید\r\n-----\r\nمجدد بررسی شد و نگوشیت بین کانال تستی با خدمات برقرار نمیشه به خانم کمایی اطلاع رسانی شد\r\nپیرو بررسی و مذاکرات با سیمیلیتور تراکنش انجام شد و همان خطای 19 مواجه گردید و مقرر شد با خدمات مذاکره گردد\r\nمقرر گردید زیرساخت نوین کاستومر ca مربوط به این کلیدو روی سرور نود ۱۰۸ نصب کنن\r\n---\r\nامروز 03/26 از صبح درگیر کانال خدمات جهت تست کهربا qr بودم و همچنان مشکل برطرف نشده لذا با عباس تفضلی هم صحبت کرد و تست ها مجدد انجام شد همچنان وصل نشده و در نهایت به مهدی گفتم که با آقای دارایی هماهنگ کند جهت راهنمایی\r\nاز chatgpt نیز کمکی بر نیامد\r\n\r\nپیرو آخرین بررسی و مذاکره با آقای دارایی مشکل از کلیدها بوده و به خانم کمایی اطلاع رسانی گردید.\r\n\r\n', 80, 22, NULL, 4, 10, 'پرداخت نوین آرین', 'زهرا کمایی', '2026-06-13 05:30:00', '2026-06-16 13:30:00', 'high', '2026-06-13 05:53:20', '2026-06-16 13:28:23'),
	(358, 'OTP پارسیان', 'طبق اعلام نیاز مهندس تربتی فرد\r\nجهت ورود به بک \r\nآفیس لازم است تایید دو مرحله ای صورت بگیرد (از طریق اس ام اس)\r\nبه همین منظور تیکتی در این مورد ثبت شده است به شماره &amp;amp;amp;amp;#039;&amp;amp;amp;amp;#039; در سامانه تیکتینگ ما ثبت شده است (482711CR)\r\nاین قابلیت باید برای پذیرندگی و صادرکنندگی فعال شود.\r\nهمچنین قابلیتی لحاظ شود تا در صورت نیاز، تایید دو مرحله ای غیر فعال شود.(تکی و گروهی)\r\nدر حال حاظر در انتظار تیم توسعه برای ارايه پیش فاکتور و نفر ساعت متناسب هستیم.\r\nپیگیری از مهندس محمدی انجام شد.\r\nجلسات پارسیان به حالت تعویق درآمده است و ممکن است انجام این موضوع زمانبرتر از حالت عادی باشد.\r\nاز مهندس محمدی پیگیری شد ایشان فرمودند مراحل در حال پیش روی بوده و ویت پاسخگویی مشتری بر روی تیکت هستند.\r\nتیکت به حالت نیازمند اقدام درآمده است .\r\nبرای پیگیری انجام اقدام از سمت مشتری با خانم خزلی تماس حاصل شد و ایشان فرمودند تیکت را بررسی و پاسخ خواهند داد.\r\nپاسخ خانم خزلی در تیکت ثبت شد و تیکت مجدد به مهندس محمدی ارجاع داده شد.\r\nدر انتظار ارسال نفر ساعت از اقای محمدی برای شرکت پارسیان هستیم.', 70, 28, NULL, 9, 45, 'تجارت الکترونیک پارسیان', 'تربتی فرد', '2026-06-08 16:30:00', '2026-06-13 08:31:41', 'high', '2026-06-13 08:31:41', '2026-06-22 08:00:59'),
	(359, 'افق تراکنش های نوین', 'با همکاری مهندس افشار بعد از بررسی مانیتورینگ و دیتابیس\r\nمشخص شد تراکنش های بانک های (ملی-صادرات-آینده-مهر اقتصاد)\r\nبا خطای ۸۴ (عدم دریافت پاسخ از سوی صادرکننده کارت) مواجه شده اند.\r\nاین خطا مربوط به صادرکنندگی بوده و نیاز به انجام کاری در واحد پشتیبانی اینتک نیست.\r\nمراتب به استحضار مهندس ایمنی رسید.\r\nدر حال مانیتور کردن تراکنش ها تا برگشت به وضعیت نرمال هستیم.\r\nهمچنین تصویر ابزار مانیتورینگ در پیوست قرار گرفت.\r\nآدرس ماینتورینگ جهت مشاهده خطا ها : http://10.0.71.111:8085/lastTxn/\r\nخطای خارجی ۹۰۰۳ (مقصد نها یی در وضعیت پاسخگویی نمیباشد) نیز به عنوان خطای خارجی مشاهده شد.\r\nاین اختلالات به صورت گترده در بانک ها بوده و هنوز به صورت کامل تراکنش ها برنگشته اند.\r\nاختلالات باک های صادرات-ملی و ... رفع شدند.', 100, 28, NULL, 2, 38, 'اینتک', 'مهدی ایمنی', '2026-06-13 07:20:00', '2026-06-13 08:36:50', 'high', '2026-06-13 08:36:50', '2026-06-15 12:13:19'),
	(360, 'افت تراکنش تراکنش های پرداخت نوین', 'با سلام و احترام\r\nپیرو بررسی های صورت گرفته، اختلال از ساعت 10:50 شروع گردیده است و پس از بررسی لاگ سوییچ و بخش Incident در آدرس https://10.0.35.52:7215/gridview/179/ مشخص گردید که بانک های صادرات و مهر ایران و ملی قادر به پاسخگویی نبوده و از دسترس خارج شده بودند. و همچنین تراکنش ها دارای ریسپانس کد 84 بودند.\r\nپیرو تماس با آقای زارع مانیتورینگ نوین به ایشان اطلاع رسانی گردید.', 90, 24, NULL, 2, 38, 'اینتک', 'مهدی ایمنی', '2026-06-13 06:30:00', '2026-06-13 08:30:00', 'high', '2026-06-13 08:39:54', '2026-06-13 08:39:54'),
	(361, 'آموزش اضافه کردن فیلدسلکت به خانم سنگی در سوئیچ تستی', 'آموزش ایجاد فیلدسلکت در کنسول سوئیچ به خانم سنگی', 100, 22, NULL, 2, 27, 'اینتک', 'سارینا سنگی ', '2026-06-13 08:40:00', '2026-06-13 08:45:00', 'low', '2026-06-13 08:49:33', '2026-06-13 08:49:33'),
	(362, 'قاسم ایران', 'تیکتی با عنوان درخواست قاسم ایران از طرف مهندس ایمنی به اینجانب تخصیص داده شد جهت بررسی\r\nنتیجه بررسی در کامنت تیکت با شماره 406463957 قرار گرفت.\r\nتوضیحات به شرح زیر میباشد:\r\nفیلد ورود شناسه مشتری روی POS اضافه شود.\r\nشناسه همراه تراکنش به سوئیچ ارسال شود.\r\nسوئیچ شناسه را اعتبارسنجی کند.\r\nدر صورت تأیید، تراکنش ادامه پیدا کند.\r\nدر صورت عدم تأیید، تراکنش Fail شود.\r\nشناسه مشتری روی رسید چاپ شود.\r\n\r\nتیکت تقدیم حضور مهندس ایمنی شد', 100, 28, NULL, 2, 38, 'اینتک', 'مهدی ایمنی', '2026-06-13 11:30:00', '2026-06-13 13:11:16', 'low', '2026-06-13 13:11:16', '2026-06-13 13:13:00'),
	(363, 'ایجاد دسترسی در سامانه جدید اینتک', 'دسترسی از طریق بکافیس به کابرهای اعلام شده داده شد.\r\n\r\nامنیت/کاربران/ایجاد کاربر جدید/ایجاد نقش جدید/تخصیص نقش', 100, 29, NULL, 9, 52, 'تجارت الکترونیک پارسیان', 'پویا عاطفی', '2026-06-14 05:20:00', '2026-06-14 06:45:00', 'low', '2026-06-14 06:54:19', '2026-06-14 06:54:30'),
	(364, 'ایجاد دسترسی با نقش رونوشت انفرادی', 'دسترسی به نقش رونوشت انفرادی برای یوزر h.sarvabadi ایجاد گردید.\r\n\r\nاز سرور 172.25.16.77  \r\nدیتابیس B2smain\r\nجدول sec.user\r\n یوزر را جستجو میکنیم و ID این جدول را در سرور 172.25.16.59 طبق دستور زیر اجرا مکنیم.\r\n\r\nUSE [B2SCard]\r\nGO\r\n\r\nINSERT INTO [dbo].[TempAccessUsers]\r\n           ([UserID])\r\n     VALUES\r\n           (5628)\r\nGO\r\n', 100, 29, NULL, 9, 52, 'تجارت الکترونیک پارسیان', 'پویا عاطفی', '2026-06-14 06:00:00', '2026-06-14 07:15:00', 'low', '2026-06-14 07:19:01', '2026-06-14 07:19:01'),
	(365, 'ایجاد دسترسی با نقش رونوشت انفرادی', 'دسترسی به نقش رونوشت انفرادی برای یوزر r.mohammadi ایجاد گردید.\r\n\r\nاز سرور 172.25.16.77  \r\nدیتابیس B2smain\r\nجدول sec.user\r\n یوزر را جستجو میکنیم و ID این جدول را در سرور 172.25.16.59 طبق دستور زیر اجرا مکنیم.\r\n\r\nUSE [B2SCard]\r\nGO\r\n\r\nINSERT INTO [dbo].[TempAccessUsers]\r\n           ([UserID])\r\n     VALUES\r\n           (5628)\r\nGO\r\n', 100, 29, NULL, 9, 52, 'تجارت الکترونیک پارسیان', 'پویا عاطفی', '2026-06-14 06:00:00', '2026-06-14 07:20:00', 'low', '2026-06-14 07:20:40', '2026-06-14 07:20:40'),
	(366, 'پروژه مترو', 'از دیروز مورخ 03/23 مترو با خطای عدم دسترسی به ماژول بود و موضوع برطرف نشد\r\nسوئیچ به مود تستی رفت باز هم اوکی نشد\r\nمجدد تست شد و پیرو بررسی مشخص شد خطا مربوط به ماژول بوده و به آقای دارایی اطلاع رسانی شد نسخه گذاشته و مشکل برطرف گردید\r\n---------\r\nنسخه انجام شده و خطا برطرف گردید 03/24\r\n-------------\r\nامروز 03/25 مجدد چک شد خطای عدم وجود شارژ میدهد کد 12\r\nمقرر شد مهدی از آقای دارایی پیگیری کند بابت پر نشدن شارژ\r\nجاب درست شد و شارژها پر شد و مشکل برطرف گردید', 100, 22, NULL, 4, 10, 'پرداخت نوین آرین', 'زهرا کمایی', '2026-06-15 10:30:00', '2026-06-15 13:00:00', 'high', '2026-06-14 08:03:50', '2026-06-15 12:57:38'),
	(367, 'اختلال و قطعی کامل سوئیچ پرداخت نوین', 'شبکه سپ دارای اختلال بود\r\nبا سینا توکل صحبت کردم گفت مشکل از شبکه است\r\nبا مهدی صحبت کردم و بهش اطلاع دادم\r\nبه سعید زنگ زدم جواب نداد\r\nرو سوئیچ چک کردم قطع بود\r\nوصل شد خیلی کند بود تایم اوت میشد کانکشنم\r\nمجدد با سینا صحبت کردم اختلال داشت\r\nاز 40.000 تا تراکنش اومده رو 10.000\r\nآقای دارایی هم تاکید کرد حواسمون به سپ باشه\r\nگویا اتک خورده\r\nالان هم همچنان 20.000 تا در دقیقه داره ساعت 13:20\r\nقطعی و اختلال دیروز حدود 14:00 رفع گردید اما تراکنش های دارای مغایرت به آقای افشار اعلام شد که در حال بررسی و پیگیری بودند', 100, 22, NULL, 8, 31, 'پرداخت الکترونیک سامان کیش', 'امیر عابدی', '2026-06-14 08:15:00', '2026-06-15 08:30:00', 'high', '2026-06-14 09:50:30', '2026-06-15 08:51:44'),
	(368, 'قطعی شبکه اینتک', 'لینک داخل شرکت (پتیاک) مجدد از ساعت 13:30 قطع شده و به سپ و پک دسترسی قطع شده است.\r\nدیر.وز حدود 16:00 وصل شد', 100, 22, NULL, 2, 35, 'اینتک', 'محمدرضا مقدم', '2026-06-14 10:00:00', '2026-06-15 08:30:00', 'low', '2026-06-14 10:54:29', '2026-06-15 08:50:17'),
	(370, 'پر شدن فضای سرور مونگو 72.51 نوین', 'پیرو تماس آقای احمدی (مانیتورینگ) با بنده مورخ 1405/03/25 ساعت 9:30 شب، پر شدن فضای سرور مونگو 72.51 نوین اطلاع رسانی گردید و فضای سرور آزاد گردید. ', 100, 24, NULL, 2, 38, 'اینتک', 'مهدی ایمنی', '2026-06-14 08:30:00', '2026-06-14 08:30:00', 'high', '2026-06-16 06:06:24', '2026-06-16 06:06:24'),
	(371, 'ایجاد ناتم کاربری بهشتی', 'طبق برنامه ONCall بودن برای همه کارشناسان پشتیبانی\r\nنیاز بود برای اقای مهدی بهشتی نام کاربری و پسورد برای دسترسی به سرورهای نوین و سامان ایجاد گردد.\r\nبه همین منظور با مهندس کمایی (نوین)\r\nو\r\nمهندس رستگار (سامان)\r\nتماس حاصل شد و درخواست به آن شرکت محترم ارسال شد.\r\nنام کاربری سامان برای اقای بهشتی برابر با itk_beheshti و پسورد در اختیار شخص ایشان قرار گرفت.\r\nهمچنین نام کاربری برای نوین m.beheshti و m-beheshti در انتظار ایجاد از سمت خانم کمایی بوده و به محض ایجاد، در اختیار اقای بهشتی قرار خواهد گرفت.\r\nیوزر های نوینی هنوز آماده نشده مجدد با خانم کمایی پیگیری شد ایشان فرمودند در مراحل انجام ایجاد نام کاربری میباشند و فعلا ویت تیم امنیت خودشان برای تایید کاربر هستند.', 85, 28, NULL, 2, 29, 'اینتک', 'مهدی بهشتی', '2026-06-16 04:30:00', '2026-06-16 08:05:49', 'medium', '2026-06-16 08:05:49', '2026-06-20 08:12:08'),
	(372, 'اپدیت سقف تراکنش های ترمینال های سامان', 'WHILE 1 = 1\r\nBEGIN\r\n    UPDATE TOP (500) t2\r\n    SET t2.MaxTransactionAmmount = 4000000001\r\n    FROM B2SMain.dbo.AcqCardAcceptor AS t2\r\n    WHERE t2.MaxTransactionAmmount = 2000000001;\r\n\r\n    IF @@ROWCOUNT = 0\r\n        BREAK;\r\n\r\n    WAITFOR DELAY &#039;00:00:03&#039;;\r\nEND;\r\n\r\nحدود 41 هزار ترمینال سامان به مبلغ سقف تراکنش 400 میلیون اپدیت شد', 100, 27, NULL, 8, 31, 'پرداخت الکترونیک سامان کیش', 'امیر عابدی', '2026-06-16 08:30:00', '2026-06-16 08:30:00', 'low', '2026-06-16 08:57:23', '2026-06-16 08:57:23'),
	(373, 'تغییر مسیر لاگ 172.31.29.46 سرور مونگوی ( 806467616 )', 'آموزش های لازم برای کانفیگ و تغییر مسیر و استاپ کردن مونگو به آقای افشار داده شد.\r\nنمونه فایل نیز ارسال گردید.\r\nبرای اینکار نیازی به دان تایم نمیباشد و فقط سرویس استاپ و مجدد ریاستارت میشود و باید بعدش چک کرد که لاگ ها صفش خالی و درست ثبت گردد\r\n\r\n------------------\r\nآموزش اینجا قرار بدهید ', 100, 22, NULL, 2, 24, 'اینتک', 'علی رضا افشار', '2026-06-16 11:30:00', '2026-06-16 12:30:00', 'medium', '2026-06-16 12:12:44', '2026-06-22 08:41:12'),
	(374, 'تعریف IIN جدید شتاب میر ( 806467465 )', 'روش تعریف iin جدید و جدول مربوطه به آقای افشار آموزش داده شد و اینگه چطور در سوئیچ اضافه کند و سپس چه دستوری برای اعمال انجام دهد آموزش داده شد. \r\n\r\n-------------\r\nآموزش اینجا قرار داده شود ', 100, 22, NULL, 2, 24, 'اینتک', 'علی رضا افشار', '2026-06-16 11:30:00', '2026-06-16 12:30:00', 'medium', '2026-06-16 12:14:53', '2026-06-22 08:40:48'),
	(375, 'خطای 12 ترمینال 15572229 ( 806468215 )', 'تیکت مربوط به تغییر اکانت بوده که بررسی و رفع گردید.\r\nبا مسئول مربوطه مذاکره شد و توضیحات ارائه گردید.\r\nهمچنین مورد مذکور تست شد و عملیات موفق انجام گردید.\r\n\r\n--------------\r\n\r\nشماره تیکت \r\nعملیات انجام شده \r\nبا چه شخصی صحبت شد \r\nنحوه تست ', 100, 22, NULL, 8, 31, 'پرداخت الکترونیک سامان کیش', 'امیر عابدی', '2026-06-17 05:30:00', '2026-06-17 07:00:00', 'low', '2026-06-17 07:06:12', '2026-06-22 08:40:20'),
	(376, 'سرور', 'با پیگیری از مهندس ایمنی و مهندس تفضلی و مهندس صدوقیان ریست سرور 172.25.2.173 Prilive بکافیس آریانا  در حال انجام است.\r\n\r\nریست سرور 172.25.2.173 انجام شد.', 100, 29, NULL, 0, 0, '', '', '2026-06-17 08:15:00', '2026-06-17 08:30:00', 'low', '2026-06-17 08:33:03', '2026-06-21 06:29:21'),
	(377, 'خطای internal error 500 ( 406469017 )', 'موضوع مربوط به خطای 500 اینترنال سرویس بوده لاگ چک شد و برای محمدی ارسال شد.\r\nمقرر گردید بررسی و اعلام نتیجه کنند', 100, 22, NULL, 4, 10, 'پرداخت نوین آرین', 'زهرا کمایی', '2026-06-17 08:15:00', '2026-06-17 08:40:42', 'high', '2026-06-17 08:40:42', '2026-07-12 11:59:16'),
	(378, 'درخواست پورت جدید ', 'طبق صحبت با آقای محمدی و درخواست ایشان برای باز شدن پورت 443 برای سرور جدید بکافیس iss (172.25.1.240) تیکت در سیمفا ثبت شد.\r\n\r\nتیکت با موفقیت از سمت پارسیان انجام شد منتظر تایید آقای محمدی هستم.\r\n', 88, 29, NULL, 0, 0, '', '', '2026-06-17 07:57:00', '2026-06-17 08:58:46', 'low', '2026-06-17 08:58:46', '2026-06-21 06:28:16'),
	(379, 'خطا در تراکنش تسهیم', 'طی بررسی و چک کردن سرور 172.25.16.41 شبای IR210180000000142148792691 در ویوو (B2SMain.dbo.VwSettlement-Abbas) پشت ترمینال اضافه نشده است و تیکت به مدیر مربوطه ارجاع شد.\r\n\r\n', 100, 29, NULL, 9, 52, 'تجارت الکترونیک پارسیان', 'پویا عاطفی', '2026-06-17 05:50:00', '2026-06-17 07:00:00', 'low', '2026-06-17 09:33:24', '2026-06-17 09:33:24'),
	(380, 'تغییر رمز کارت', 'فایل پیوست شده را که شامل شماره کارت است را در سرور 172.25.16.59 و دیتابیس importdara میریزیم و fh جدول IssCard و جدول IssCardSecurity جوین میزنیم.\r\nID جدول IssCard برابر است با CardID جدول IssCardSecurity.\r\n\r\n===================================\r\n\r\nselect * from ISSCardSecurity s\r\nwhere s.cardid in (\r\nselect c.id from B2SCard.dbo.ISSCard c\r\nwhere c.cardno in (select i.cardno from ImportData.dbo.CardNo2025 i))\r\n\r\n====================================================\r\n\r\nupdate s\r\nset\r\ns.PrimaryPin = &amp;#039;IrN0fiX0aNA=&amp;#039;\r\n,s.SecPin    = &amp;#039;IrN0fiX0aNA=&amp;#039;\r\nfrom\r\nISSCardSecurity s\r\nwhere s.cardid in (\r\nselect c.id from B2SCard.dbo.ISSCard c\r\nwhere c.cardno in (select i.cardno from ImportData.dbo. i))\r\n\r\n\r\n\r\n\r\n--------------------------\r\nادرس سرور ها ای پی و... ', 100, 29, NULL, 9, 52, 'تجارت الکترونیک پارسیان', 'پویا عاطفی', '2026-06-17 07:30:00', '2026-06-17 09:00:00', 'low', '2026-06-17 10:47:09', '2026-06-22 08:37:49'),
	(381, 'حذف IIN نا متعارف ( 806469598 )', 'تیکت مربوط به مورد خاصی در IIN بوده که پس از بررسی در سوئیچ به درخواست مشتری حذف گردید.\r\n\r\n-----------------\r\nشماره تیکت \r\nعملیات انجام شده \r\nمسیر سرور کد .... ', 100, 22, NULL, 8, 31, 'پرداخت الکترونیک سامان کیش', 'امیر عابدی', '2026-06-17 10:30:00', '2026-06-17 11:30:00', 'medium', '2026-06-17 11:23:54', '2026-06-22 08:37:13'),
	(382, 'سرور مونگو سپ', 'سپ بدون هماهنگی با اینتک دیسک مونگو را پاک کرده و تمامی لاگ ها در حال ویت بودند\r\nدر صورت متوجه نشدن این موضوع سوئیچ قطع می گردید\r\nپیرو بررسی مشخص گردید دیسک بدون هماهنگی از سرور گرفته شده و پس از پیگیری مجدد برگردانده شد و سرور ریاستارت شده و مجدد سرویس راه اندازی کردم و مونگو به حالت لیسن درآمد و لاگ تمامی سرورها که در سوئیچ غیرفعال کرده بودم مجدد فعال کردم و صف مونگو خالی شد.\r\nبه اطلاع آقایان دارایی، ایمنی و پهلوان رسید', 100, 22, NULL, 2, 22, 'اینتک', 'مهدی صدوقیان', '2026-06-17 11:30:00', '2026-06-17 12:30:00', 'high', '2026-06-17 11:57:27', '2026-06-17 12:25:44'),
	(383, 'خطای استعلام فارا کلیه ترمینال ها برروی نود 23 سامان پرداخت', 'با سلام و احترام\r\nمورخ 05/03/28 ساعت 17:15، پیرو تماس مانیتورینگ سامان اعلام گردید تمامی تراکنش های فارا با خطای 84 و اینترنال 2 مواجه میشوند. پس از بررس مشخص گردید توکن ارسالی برای api استعلام فارا دچار مشکل شده و خطای UnAthorized در جواب JSON ارسالی داده میشود. حتی پس از زدن چندباره دستور Connector build [FaraConnectorID] برروی سوییچ مشکل حل نگردید. پس از پیگیری آقای ایمنی با آقای توکل در نهایت ساعت 20:39 مشخص گردید از طرف سامان پرداخت کاربر DeActive گردیده بود و توکن رفرش نمیشد.\r\nدستورات log view faraConnector برروی سرور های زی:\r\n Acquirer [2]            [172.31.29.42]\r\nAcquirer [3]            [172.31.29.43]\r\n------ \r\n', 100, 24, NULL, 8, 31, 'پرداخت الکترونیک سامان کیش', 'امیر عابدی', '2026-06-18 13:30:00', '2026-06-18 17:30:00', 'high', '2026-06-20 06:41:06', '2026-08-08 11:21:02'),
	(384, 'اعلام کندی بک افیس', 'طبق اعلام اختلال در سرویس های بک آفیس و کندی آن از شرکت سامان پرداخت(شیفت اقای بهشتی بود و به اطلاع ایشان و منهدس ایمنی رسید)\r\nمورد بررسی و از طریق ReStart  IIS سرور بک افیس مورد برطرف و به اطلاع سامان رسید.', 100, 28, NULL, 8, 31, 'پرداخت الکترونیک سامان کیش', 'امیر عابدی', '2026-06-18 13:30:00', '2026-06-18 15:00:00', 'medium', '2026-06-20 08:04:19', '2026-06-20 08:09:56'),
	(385, 'اعلام اختلال در تراکنش های فارا', 'بعد از تماس واحد مانیتورینگ سامان(شیفت آنکال اقای افشار بود سید جهت پیگیری اطلاع داده شد)\r\nمبنی بر افت کامل تراکنش های فارا\r\nبعد از بررسی های به عمل آمده \r\nمشخص شد مشکل به دلیل اکسپایر شدن توکن فارا سمت سامان بوده و به اطلاع سامان و فارا رسید.', 100, 28, NULL, 8, 31, 'پرداخت الکترونیک سامان کیش', 'امیر عابدی', '2026-06-19 13:45:00', '2026-06-19 15:00:00', 'high', '2026-06-20 08:10:20', '2026-06-20 08:10:20'),
	(386, 'ریبوت شدن سرور 172.31.80.20', 'با سلام و احترام\r\nپیرو تماس آقای علینژاد در تاریخ 05/03/28 ساعت 12:30 بامداد مانیتورینگ سامان پرداخت، ریبوت شدن سرور 172.31.80.20 اطلاع رسانی گردید.', 100, 24, NULL, 8, 31, 'پرداخت الکترونیک سامان کیش', 'امیر عابدی', '2026-06-17 21:30:00', '2026-06-18 08:30:00', 'low', '2026-06-20 08:22:26', '2026-06-20 08:22:26'),
	(387, 'خظا خوردن دوباره کلیه تراکنش های پین شارژ 50 و 100 هزار تومانی همراه اول در سامان پرداخت (بخش اول) و افت کلی تراکنش های سوویچ در ساعت 9:30 مورخ 1405/03/06', 'با سلام و احترام\r\nمورخ تاریخ 1405/03/30در ساعت 12:00 ظهر سامان پرداخت اعلام کرد که مبتکران پس از شارژ مخزن شارژ های 50 و 100ای همراه اول، تمامی تراکنش های شارژ آن به خطای 12 و کد داخلی 50 (شارژ درخواستی به فروش رسیده است) بر میخورد.\r\nپس از بررسی لاگ مشخص گردید که ارتباط با وب سرویس شارژ مبتکران برقرار شده و پیام &quot;محصول موردنظر یافت نشد&quot; برای شارژ های 50 و 100 تومانی دریافت میشود.\r\nمراتب به آقای پهلوان اطلاع رسانی گردید.\r\n', 100, 24, NULL, 8, 31, 'پرداخت الکترونیک سامان کیش', 'امیر عابدی', '2026-06-20 08:30:00', '2026-06-20 08:30:00', 'high', '2026-06-20 09:55:27', '2026-06-20 09:55:27'),
	(388, 'اپدیست سقف تراکنش ترمینال های نوین', 'WHILE (1 = 1)\r\nBEGIN\r\n    UPDATE TOP (500) a\r\n    SET a.MaxTransactionAmmount = 4000000000\r\n	from B2SMain.dbo.AcqCardAcceptor a \r\njoin B2SMain.dbo.AcqTerminal t on t.MerchantID = a.ID\r\njoin ImportData.dbo.[termnum_maxtrans] m on m.terminalnum=t.terminalinumber\r\n    WHERE a.MaxTransactionAmmount = 2000000000\r\n\r\n    IF @@ROWCOUNT = 0\r\n        BREAK;\r\n\r\nWAITFOR DELAY &#039;00:00:03&#039;;\r\n\r\nend\r\n\r\nتمامی سقف تراکنش های ترمینال هایی که در فایل پیوست تیکت ارسال کرده بودند که تعدادش حدودا 177 هزارتا بود اپدیت شد', 100, 27, NULL, 4, 10, 'پرداخت نوین آرین', 'زهرا کمایی', '2026-06-21 08:30:00', '2026-06-21 08:30:00', 'low', '2026-06-21 12:00:37', '2026-06-21 12:00:37'),
	(389, 'Server Down 29.144', 'طی تماس واحد مانیتورینگ سامان\r\nمبنی بر خوابیدن سرور 29.144 \r\nبعد از بررسی های صورت گرفته(با مهندس صدوقیان) مشخص شد که این سرور مدتیست که جمع آوری شده است.\r\nموضوع به اطلاع شرکت سامان پرداخت نیز رسید.', 100, 28, NULL, 8, 31, 'پرداخت الکترونیک سامان کیش', 'امیر عابدی', '2026-06-21 12:00:00', '2026-06-21 13:30:45', 'low', '2026-06-21 13:30:45', '2026-06-21 13:30:45'),
	(390, ' فعال سازی ترمینال های نوین', 'پیرو تماس خانم کمایی مبنی بر فعال سازی ترمینال های لیست پیوست (تیکت فورس 406472096 ) که شامل ترمینال های رفاه و نوین بودند، در دیتابیس فرآیند فعال سازی در جدول AcqTerminal انجام گردید. سپس در shell سوییچ پرداخت نوین، دستور shadow reload 1 و همچنین clearcche برروی نود های اکوئر زده شد و به خانم کمایی جهت نتست و هماهنگی اطلاع رسانی گردید.\r\n', 100, 24, NULL, 4, 10, 'پرداخت نوین آرین', 'زهرا کمایی', '2026-06-21 08:30:00', '2026-06-21 10:30:00', 'medium', '2026-06-21 15:52:55', '2026-06-21 15:52:55'),
	(391, 'گزارش تسهیم', 'در سرور 172.25.16.41 \r\nدیتابیس b2smain \r\nVwSettlement-Abbas\r\nترمینال های فایل پیوستی که شرکت پارسیان داده بود را جستجو کردم و گزارش را تحویل پویا عاطفی دادم.', 100, 29, NULL, 9, 52, 'تجارت الکترونیک پارسیان', 'پویا عاطفی', '2026-06-21 11:25:00', '2026-06-22 06:30:00', 'low', '2026-06-22 06:37:59', '2026-06-22 06:37:59'),
	(392, 'درخواست گزارش', 'از سرور 172.25.16.77\r\nدیتابیس B2SCard\r\nجدول TxnType  \r\n 6 = TxnTypeIdentifier  \r\n\r\n===============================\r\n\r\nSELECT  * FROM dbo.ISSCard \r\nJOIN dbo.ISSCardCapabilityDetail ON ISSCardCapabilityDetail.CardID = ISSCard.ID \r\nWHERE TxnType =6', 100, 29, NULL, 9, 52, 'تجارت الکترونیک پارسیان', 'پویا عاطفی', '2026-06-21 06:15:00', '2026-06-22 06:45:00', 'low', '2026-06-22 06:58:00', '2026-06-22 06:58:00'),
	(393, 'درحال فعالسازی صدور کارت', 'فایل صدور کارت در بک افیس ایشوئر نوین در حال پردازش میمونه \r\nاول بک افیس با شناسه صدوری که به ما دادن چک میکنیم \r\nدر این موقیعت state در حال فعالسازی مونده بود حالا توی دیتابیس باید بریم status و isactive چک کنیم \r\nselect \r\nr.*, \r\nd.cardno,\r\n c.isactive ,\r\nd.*,\r\nr.Status,\r\nd.Status,\r\nc.Status\r\nfrom ISSCardRequest r\r\njoin ISSCardRequestDetail d on r.id = d.CardRequestID\r\njoin isscard c on c.cardno = d.CardNo\r\nwhere r.id = 2074\r\nبا این کوئری چک میکنیم که status جدول ISSCardRequest چی هست\r\nباید 4 باشه \r\nباید isactive جدول isscard هم نگاه کنیم که چنده\r\nselect top 10 * from B2SCustomer.dbo.IndividualCustomers where Id = 280448\r\n\r\nselect top 100 * from ISSCard where \r\nCardPatternID = 10116\r\nCardGroupID = 287 order by id desc\r\n\r\nبعد اگر isactive کارت ها فالس بود باید true کنیم\r\nselect top 10 * ,r.status\r\nfrom ISSCardRequest r \r\nwhere id= 2238\r\n\r\nupdate ISSCardRequest set Status=4 where id=2074\r\nبعد هم status باید اپدیت کنیم', 100, 27, NULL, 4, 41, 'پرداخت نوین آرین', 'سوده فرمانی', '2026-06-21 08:30:00', '2026-06-21 08:30:00', 'medium', '2026-06-22 07:19:25', '2026-06-22 07:19:25'),
	(394, 'اختلال در تراکنش های تاریخ 31 خرداد ماه نوین', 'با سلام و احترام\r\n\r\nدر خصوص اختلال متناوب مشاهده‌شده در نمودار تراکنش‌های سوئیچ در تاریخ ۳۱ خرداد ۱۴۰۵، بررسی‌های فنی انجام‌شده بر روی لاگ‌ها و زیرساخت ارتباطی نشان می‌دهد که اختلال ناشی از بروز مشکل در برقراری ارتباطات شبکه‌ای با پایگاه داده بوده است. خطاهای ثبت‌شده حاکی از عدم امکان ایجاد ارتباط جدید با SQL Server در برخی بازه‌ها بوده که منجر به اختلال مقطعی در پردازش و ثبت تراکنش‌ها شده است.\r\n\r\nعلت بروز مشکل\r\nبررسی‌های انجام‌شده نشان می‌دهد این وضعیت پس از اعمال تغییرات در تنظیمات فایروال و زیرساخت شبکه رخ داده است. در نتیجه این تغییرات، بخشی از ارتباطات پس از قطع شدن به‌صورت کامل آزاد نشده و برای مدتی در وضعیت انتظار (TIME_WAIT) باقی می‌مانند. این موضوع باعث کاهش ظرفیت ایجاد ارتباطات جدید و بروز اختلال متناوب در دسترسی به سرویس پایگاه داده شده است.\r\n\r\nاقدامات انجام‌شده\r\nبه‌منظور کاهش اثرات اختلال و حفظ پایداری سرویس، تنظیمات مربوط به زمان انقضای ارتباطات در سطح سیستم‌عامل بازبینی و اصلاح شد تا ارتباطات بلااستفاده در مدت زمان کوتاه‌تری آزاد شده و امکان برقراری ارتباطات جدید فراهم گردد.\r\n\r\nراهکار رفع مشکل\r\nاقدام انجام‌شده به‌عنوان یک راهکار موقت جهت کاهش اثرات اختلال عمل می‌کند و ماهیت اصلی مشکل را برطرف نمی‌کند. رفع ریشه‌ای موضوع مستلزم بازبینی و اصلاح تنظیمات فایروال و تجهیزات شبکه، به‌ویژه مدیریت Sessionها و نحوه آزادسازی ارتباطات TCP پس از قطع ارتباط است.\r\n\r\nاقدامات پیشگیرانه آتی\r\n\r\nبازبینی تنظیمات فایروال و Session Timeoutهای شبکه.\r\nپایش مستمر وضعیت ارتباطات TCP و تعداد Connectionهای باقی‌مانده در وضعیت TIME_WAIT.\r\nانجام تست‌های پایداری پس از هرگونه تغییر در تجهیزات یا سیاست‌های امنیتی شبکه.\r\nتعریف فرآیند کنترل تغییرات (Change Management) جهت ارزیابی اثر تغییرات شبکه بر سرویس‌های عملیاتی پیش از اعمال در محیط تولید.\r\n\r\nامید است با اجرای اقدامات فوق، از بروز موارد مشابه در آینده جلوگیری شود.\r\n\r\n\r\n-------\r\n\r\nآدرس و دستوراتی که برای چک کردن سمت ما صورت گرفته ', 100, 28, NULL, 2, 38, 'اینتک', 'مهدی ایمنی', '2026-06-21 08:30:00', '2026-06-22 08:00:11', 'low', '2026-06-22 08:00:11', '2026-06-22 08:48:25'),
	(395, 'پروژه قاسم ایران', 'پیرو مذاکره با خانم کمایی و آقای جهانگیری مشخص شد یک شرکتی وجود دارد که دارای یکسری شناسه است (کاربران) که قرار است تراکنش انجام شده ابتدا اعتبارسنجی داشته باشد و برای اعتبار سنجی این شناسه استفاده می شود که شناسه در کارتخوان وارد شود و قبل تر از طریق جدولی در دیتابیس وجود داشته باشد تا بعد از اعتبار سنجی شناسه از طریق سوئیچ ادامه فرآیند میسر گردد.', 55, 22, NULL, 4, 10, 'پرداخت نوین آرین', 'زهرا کمایی', '2026-06-22 08:10:00', '2026-06-22 09:30:00', 'low', '2026-06-22 09:32:17', '2026-06-22 09:32:17'),
	(396, 'پروژه USSD', 'پروژه مربوط به شرکت رایتل می باشد که نیاز به ussd دارد \r\nپیرو مذاکره با آقای جهانگیری مقرر شد از کانال 8000 استفاده شود\r\nپیش نیاز توضیحات آقای جهانگیری و همچنین تست و راه اندازه سمت پرداخت نوین جهت تست تراکنش می باشد.', 50, 22, NULL, 4, 10, 'پرداخت نوین آرین', 'زهرا کمایی', '2026-06-22 07:30:00', '2026-06-22 11:21:01', 'medium', '2026-06-22 11:21:01', '2026-06-22 11:21:01'),
	(397, 'نامحدود کردن سقف تراکنش 15 ترمینال نوین', 'سرکار خانم کمایی تماس گرفتند و اعلام نمودند که لیستی شامل ۱۵ ترمینال ارسال شده است و درخواست داشتند سقف تراکنش این ترمینال‌ها به‌صورت نامحدود تنظیم گردد.\r\n\r\nدر این خصوص با جناب آقای ایمنی و جناب آقای حیدری‌مقدم مشورت شد و مقرر گردید پیش از اعمال تغییرات، بررسی شود که ترمینال‌های مذکور در شاپرک به‌عنوان ترمینال کلوزلوپ ثبت نشده باشند.\r\n\r\nمتعاقباً با سرکار خانم کمایی تماس گرفته شد و ضمن تشریح موضوع، در خصوص محل بررسی تأییدیه شاپرک ترمینال‌ها استعلام انجام شد. مقرر گردید ایشان موضوع را روز شنبه بررسی نموده و پس از اعلام نتیجه، اقدامات لازم انجام شود.\r\n\r\n\r\nبعد از کامنت خانم کمایی که فرمودند ترمینال ها شاپرکی هستند ترمینال ها اپدیت شد\r\n4/6', 100, 27, NULL, 4, 10, 'پرداخت نوین آرین', 'زهرا کمایی', '2026-06-23 08:30:00', '2026-06-23 08:30:00', 'medium', '2026-06-23 06:55:29', '2026-06-27 07:13:07'),
	(398, 'تماس مانیتورینگ سامان پرداخت مبنی down شدن سرور 129.144', 'پیرو تماس مانیتورینگ سامان پرداخت مورخ 05/04/01 ساعت7:00 صبح، اعلام گردید که سرور 129.144 در مانیتورینگ دیده نمیشود. سرور مذکور قبلا جمع آوری شده است و مراتب به مانیتورینگ اطلاع رسانی گردید.', 100, 24, NULL, 8, 31, 'پرداخت الکترونیک سامان کیش', 'امیر عابدی', '2026-06-22 03:30:00', '2026-06-22 04:30:00', 'low', '2026-06-23 07:26:21', '2026-06-23 07:26:21'),
	(399, 'برورزرسانی user &amp; pass فارا سپ', 'تغییرات بر روی یوزر و پسورد کانال فارا سپ انجام گردید\r\nکانکشن ها ریبیلد شد\r\nکانکشن متصل شده و تراکنش موفق انجام شد\r\nتغییر توکن با توجه به بالا بودن حجم تراکنش فارا مشخص نبود', 100, 22, NULL, 8, 31, 'پرداخت الکترونیک سامان کیش', 'امیر عابدی', '2026-06-23 04:00:00', '2026-06-23 05:30:00', 'high', '2026-06-23 07:31:23', '2026-06-23 07:31:23'),
	(400, 'بروزرسانی user &amp; pass فارا نوین', 'تغییرات بر روی یوزر و پسورد کانال فارا نوین انجام گردید\r\nکانکشن ها ریبیلد شد\r\nکانکشن متصل شده و تراکنش موفق انجام شد\r\nتغییر توکن با توجه به بالا بودن حجم تراکنش فارا مشخص نبود', 100, 22, NULL, 4, 39, 'پرداخت نوین آرین', 'مهدی جهانگیری', '2026-06-23 05:20:00', '2026-06-23 06:20:00', 'high', '2026-06-23 07:32:43', '2026-06-23 07:32:43'),
	(401, 'رفع آسیب پذیری mongo', 'ورژن MongoDB بررسی شد و مشخص گردید نسخه نصب‌شده 4.0.4 می‌باشد که در لیست نسخه‌های منسوخ‌شده قرار دارد.\r\n\r\nموضوع با جناب آقای تفضلی مطرح گردید و طبق اعلام ایشان، لازم است این مورد یک‌بار در زمان Downtime انجام شود. همچنین مقرر گردید ورژن موردنظر از سمت این واحد اعلام شود تا بر روی سرور نصب و اعمال گردد.\r\n\r\nIP نیز بررسی شد و مشخص گردید پابلیک نمی‌باشد.\r\n\r\n\r\nنسخه **5.0.6** بر روی سرور ایران‌کیش قرار داده شد. طبق اعلام جناب آقای تفضلی، نسخه‌ای که قرار است بر روی سپ اعمال شود، ابتدا باید برای مدتی بر روی سرور تستی اجرا و بررسی گردد.\r\n\r\nبر همین اساس، مقرر شد در صورت عدم مشاهده مشکل و تأیید عملکرد نسخه پس از چند روز بر روی سرور ایران‌کیش، همین نسخه بر روی سامان نیز اعمال گردد.\r\n\r\nموضوع با جناب آقای ایمنی نیز مطرح شد و مورد تأیید ایشان قرار گرفت.', 50, 27, NULL, 8, 31, 'پرداخت الکترونیک سامان کیش', 'امیر عابدی', '2026-06-23 08:30:00', '2026-06-28 08:30:00', 'low', '2026-06-23 08:24:19', '2026-06-28 07:16:00'),
	(402, 'ترمینال سامان', 'جناب آقای مجیبیان تماس گرفتند و اعلام نمودند ترمینالی که از سمت ایشان در دیتابیس خودشان ثبت می‌شود، در دیتابیس اینتک اعمال و مشاهده نمی‌گردد. موضوع  در حال بررسی است.', 45, 27, NULL, 0, 0, '', '', '2026-06-23 08:30:00', '2026-06-23 08:30:00', 'low', '2026-06-23 08:26:59', '2026-06-23 08:26:59'),
	(403, 'بروزرسانی فایلهای ویزیو اکوئری و ایشوئری نوین', 'موارد بررسی شد و مپ ها بروزرسانی گردید', 100, 22, NULL, 2, 38, 'اینتک', 'مهدی ایمنی', '2026-06-23 08:15:00', '2026-06-23 09:00:00', 'low', '2026-06-23 08:51:55', '2026-06-23 08:51:55'),
	(404, 'MongoDb97%', 'تماس از واحد مانیتورینگ سامان (آقای میرزایی) در ساعت ۰۷:45\r\nمبنی بر پر شدن حافظه ۲۹.۴۵ و رسیدن به آستانه ۹۷٪\r\nدر همین راستا بعد از ریموت شدن به سرور ۲۹.۴۵ و بررسی حافظه سرور\r\nاقدام به خالی کردن فضا از طریق میانبر MongoCleaner به عمل آمد.', 100, 28, NULL, 8, 31, 'پرداخت الکترونیک سامان کیش', 'امیر عابدی', '2026-06-27 04:00:00', '2026-06-27 05:23:56', 'high', '2026-06-27 05:23:56', '2026-06-27 05:23:56'),
	(405, 'راه اندازی ایران کیش', 'نصب پیش نیازهای سوئیچ (فیچرها)\r\nبالا آوردن سرویس های ویندوزی سوئیچ\r\nراه اندازی نسخه اولیه سوئیچ\r\nدسترسی بین سرورها\r\nراه اندازی مونگو و سرویس های مربوطه\r\nتست ارتباط بین سوئیچ و دیتابیس و مونگو\r\nساخت کانکشن استرینگ ها', 100, 22, NULL, 2, 38, 'اینتک', 'مهدی ایمنی', '2026-06-24 09:30:00', '2026-06-25 13:30:00', 'medium', '2026-06-27 06:41:41', '2026-06-27 06:41:41'),
	(406, 'پیگیری تراکنش های فارا با مبالغ کمتر از مبلغ کف تراکنش', 'تراکنش پس از برگشت از فارا با مبلغ کمتر از 2000 برای شاپرک ارسال می شود و با خطا مواجه می شود که باید جلوی این تراکنش گرفته شود.', 51, 22, NULL, 8, 31, 'پرداخت الکترونیک سامان کیش', 'امیر عابدی', '2026-06-27 07:30:00', '2026-06-27 10:30:00', 'medium', '2026-06-27 10:18:23', '2026-06-27 10:18:23'),
	(407, 'تیکت شماره 4966 مربوط به شارژ ارزش افزوده', 'پیرو بررسی های انجام شده این تیکت اشتباه بوده و برای شارژهای پین امکان پذیر نمی باشد زیرا زمانی که کاربر در حال خرید شارژ پین می باشد مالیات و ارزش افزوده اعمال می شود اما در شارژ تاپاپ امکان پذیر می باشد و نیازمند نسخه از سمت آقای دارایی می باشد.\r\nبه آقای پرویزی و خانم سنگی نیز آموزش داده شد و به اطلاع آقای ایمنی نیز رسید و در گروه به آقای دارایی اطلاع رسانی گردید.', 100, 22, NULL, 8, 31, 'پرداخت الکترونیک سامان کیش', 'امیر عابدی', '2026-06-27 09:30:00', '2026-06-27 11:30:00', 'medium', '2026-06-27 11:41:11', '2026-06-27 11:41:11'),
	(408, 'ثبت نشدن ترمینال در دیتابیس', 'با سلام و احترام\r\n\r\nجناب آقای مجیبیان از شرکت سامان تماس گرفتند و اعلام نمودند ترمینالی را ثبت کرده‌اند که اطلاعات آن در دیتابیس سامان درج می‌شود، اما در دیتابیس اینتک اعمال و مشاهده نمی‌گردد.\r\n\r\nدر این خصوص، درخواست شد لاگ JSON ورودی ارسال گردد و همچنین اعلام فرمایند هنگام ثبت ترمینال با چه خطا یا پیغامی مواجه می‌شوند تا بررسی لازم انجام شود.', 30, 27, NULL, 8, 31, 'پرداخت الکترونیک سامان کیش', 'امیر عابدی', '2026-06-16 08:30:00', '2026-06-27 11:46:20', 'low', '2026-06-27 11:46:20', '2026-06-27 11:46:20'),
	(409, 'پیگیری تراکنش فارا زیر 2000 ریال', 'با سلام و احترام\r\n\r\nموضوع با جناب آقای پهلوان بررسی شد و مشخص گردید همچنان تراکنش‌های فارا با مبالغ کمتر از ۲۰۰۰ ریال به سمت شاپرک ارسال می‌شوند، در حالی که این تراکنش‌ها نباید به شاپرک ارسال شوند.\r\n\r\nدر این خصوص، نیاز به اعمال اصلاحات از طریق نسخه جدید می‌باشد که توسط جناب آقای دارایی باید ارائه گردد. پیگیری‌های لازم نیز انجام شده است، لیکن تاکنون نسخه مربوطه ارائه نشده است.\r\n\r\n(تاریخ شروع تیکت یادم نیست)', 60, 27, NULL, 8, 31, 'پرداخت الکترونیک سامان کیش', 'امیر عابدی', '2026-06-27 08:30:00', '2026-06-27 12:28:25', 'low', '2026-06-27 12:28:25', '2026-06-27 12:28:25'),
	(410, 'درخصوص طرح ضميه شده در اينتك بصورت فشرده (زيپ شده) ( 906452365 )', 'با سلام و احترام\r\n\r\nدر قسمت کارت-درخواست کارت-جدید   وقتی یه فایلی رو اپلود میکردن و درخواست ثبت میکردن بعدش که شماره تقاضا رو سرچ میکردن اون فایل اپلود شده رو که دانلود میکردن نمیتونستن بازش کنن\r\nپیرو مذاکره تلفنی با سرکار خانم سوزانی و انجام تست مورد مطرح‌شده با شماره تقاضای مذکور، مشکلی مشاهده نگردید و فایل دانلودشده به‌صورت RAR دریافت و بدون مشکل باز شد.\r\n\r\nموضوع مطرح‌شده به نرم‌افزارهای نصب‌شده بر روی سیستم کاربر و تنظیمات پیش‌فرض سیستم جهت دانلود و باز کردن فایل‌ها مربوط می‌باشد. در صورت نیاز، می‌توانید فایل را از طریق گزینه Open with با نرم‌افزار موردنظر باز نمایید.', 100, 27, NULL, 9, 52, 'تجارت الکترونیک پارسیان', 'پویا عاطفی', '2026-06-27 08:30:00', '2026-06-27 08:30:00', 'low', '2026-06-27 12:31:00', '2026-06-27 12:31:00'),
	(411, ' عدم نمایش شماره تقاضا 478662 ( 905445216 )', 'با سلام و احترام\r\nموضوع بررسی شد. با استفاده از نام کاربری و رمز عبور کاربری که مشکل را گزارش کرده بود وارد سامانه شدم و تست انجام شد. در بررسی انجام‌شده، مشاهده گردید که شماره تقاضای مذکور واقعاً برای این کاربر قابل مشاهده نمی‌باشد.\r\n\r\nبا جناب آقای محمدی بررسی شد تا علت مشکل مشخص گردد و مقرر شد تیکت برای ایشان ارسال شود؛ زیرا اعلام نمودند ممکن است رفع مشکل نیازمند پابلیش نسخه جدید باشد و باید بررسی کنن که موضوع دیتابیسی حل میشود یا خیر', 100, 27, NULL, 9, 52, 'تجارت الکترونیک پارسیان', 'پویا عاطفی', '2026-06-27 08:30:00', '2026-06-27 08:30:00', 'low', '2026-06-27 12:37:30', '2026-06-27 12:39:17'),
	(412, 'فرم 8 و 13 پارسیان', 'در تاریخ 30 خرداد 1405 ساعت 1:37 بامداد مانیتورینگ پارسیان تماس گرفت و اعلام کردند فایل فرم 8 و 13 در بکافیس ایجاد شده ولی در مسیر FTP پوشه ای برای قرار دادن فایل تاریخ 29 خرداد 1405 ایجاد نشده است.\r\nبا پیگیری از رییس مانیتورینگ (مهندس صنوبر) اعلام کردند مشکل از سمت کاسپین بوده است به دلیل اختلال در دسترسی یوزرها.', 100, 29, NULL, 2, 29, 'اینتک', 'مهدی بهشتی', '2026-06-19 22:00:00', '2026-06-20 00:30:00', 'low', '2026-06-28 06:20:54', '2026-06-28 06:20:54'),
	(413, 'پیگیری اختلال در histpry مانیتورینگ', 'برخی از صفحات مانیتورینگ که مربوط به history میشدند مانند src و static و failed txn by date با مشکل مواجه شده بودند که تیم توسعه پابلیش گذاشتند و مشکل برطرف شد.', 100, 27, NULL, 4, 10, 'پرداخت نوین آرین', 'زهرا کمایی', '2026-06-28 08:30:00', '2026-06-28 08:30:00', 'low', '2026-06-28 12:59:35', '2026-06-28 12:59:35'),
	(414, 'تعریف کارت در گروه کارت', '\r\nدر بکافیس پذیرندگی/اطلاعات پایه/گروه کارت\r\nعنوان گروه کارت را جستجو می کنیم و بعد روی گروه کارت کلیک می کنیم و از گزینه عملیات تخصیص کارت را انتخاب می کنیم اگر کارت اعلامی وجود نداشت با استفاده از گزینه جدید شماره کارت را اضافه می کنیم.\r\n\r\nبرای ساختن گروه کارت گزینه جدید را میزنیم و نام گروه کارتی که اعلام کرده اند را وارد می کنیم.', 100, 29, NULL, 9, 52, 'تجارت الکترونیک پارسیان', 'پویا عاطفی', '2026-06-28 10:30:00', '2026-06-28 12:58:00', 'low', '2026-06-28 13:11:05', '2026-06-28 13:11:05'),
	(415, 'سقف تراکنش ترمینال های رفاه', 'سقف تراکنش برای تمامی اصناف به جز صنف انرژی و حمل و نقل با کدتکمیلی : ۹۸۰۵۰۰۰۱ و کد صنف : ۹۸۰۵ از 2,000,000,000 به 4,000,000,000 ریال افزایش یافت.\r\n\r\n  WHILE (1 = 1)\r\nBEGIN\r\n    UPDATE TOP (500) a\r\n    SET a.MaxTransactionAmmount = 4000000000 \r\n	from B2SMain.dbo.AcqCardAcceptor a \r\n    WHERE a.MaxTransactionAmmount = 2000000000 and a.MCC != 9805\r\n\r\n    IF @@ROWCOUNT = 0\r\n        BREAK;\r\n\r\nWAITFOR DELAY &#039;00:00:03&#039;;\r\n\r\nend', 100, 27, NULL, 5, 26, 'توسعه فناوری رفاه پردیس', 'محمود عظیمی', '2026-06-28 08:30:00', '2026-06-28 08:30:00', 'low', '2026-06-28 13:24:41', '2026-06-28 13:24:41'),
	(416, 'تغییر وضعیت تقاضا 673564', '\r\nتغییر وضعیت شماره تقاضا 673564 از در انتظار فعالسازی(14) به انتظار چاپ رمز(15)\r\n\r\n=======================================\r\n\r\nupdate B2SCard.dbo.ISSCardRequest\r\n  set Status = 15\r\n  where ID = 673564\r\n\r\n========================================\r\nطبق صحبت با خانم ملاحسینی قرار شد تیکت درخواست تغییر را ثبت کنند.\r\n', 100, 29, NULL, 9, 52, 'تجارت الکترونیک پارسیان', 'پویا عاطفی', '2026-06-29 06:00:00', '2026-06-29 06:24:00', 'low', '2026-06-29 06:28:20', '2026-06-29 06:28:20'),
	(417, 'دان تایم راه اندازی tls 1.3 و نماد سدرا', 'بر روی بین 1 نوین (سیپا)\r\nکلید و pfx در سرور جانمایی شد و کانال ها بروز رسانی گردید و کانکتور ها ریبیلد و کانال شاپرک بروزرسانی و متصل گردید.\r\ntls 1.3 نیز اعمال شد و ssl نیز بالا آمده و متصل گردید.\r\nتست انجام شد و حدود نیم ساعت مانیتور گردید.\r\nهمین عملیات برای بین 2 نیز انجام گردید.', 100, 22, NULL, 4, 10, 'پرداخت نوین آرین', 'زهرا کمایی', '2026-06-28 09:30:00', '2026-06-28 13:50:00', 'high', '2026-06-29 08:16:41', '2026-06-29 08:19:21'),
	(418, 'ممیزی داخلی پرداخت نوین', 'تمامی موارد سوئیچ بررسی گردید و نیازمندی ها توسط آقای افشار یاداشت شد و مقرر شد بررسی گردد.\r\nنمونه لاگ ها و موارد مورد نظر مشاهده گردید.\r\nدیتابیس نیز با آقای افشار ممیزی گردید', 100, 22, NULL, 4, 39, 'پرداخت نوین آرین', 'مهدی جهانگیری', '2026-06-28 09:30:00', '2026-06-28 13:50:00', 'low', '2026-06-29 08:27:56', '2026-06-29 08:27:56'),
	(419, 'آزادسازی فضای مونگو نوین', 'ظرفیت  فضای ذخیره سازی سرورهای مونگو شرکت پرداخت نوین به حد اخطار رسید و با استفاده از سرویس مونگو کلینر لاگ ها از تاریخ 03-26-2026 تا تاریخ 17-06-2026 از سرور حدف شدند.', 100, 28, NULL, 4, 10, 'پرداخت نوین آرین', 'زهرا کمایی', '2026-06-29 07:30:00', '2026-06-29 09:09:15', 'high', '2026-06-29 09:09:15', '2026-06-29 09:09:15'),
	(420, 'آزادسازی فضای سرور مانیتورینگ سابین', 'فضای ذخیره سازی لاگ در سرور 142.13 سابین به حد اخطار رسیده\r\nو بعد از بررسی فایل های لاگ\r\nتعدادی از آنها به جهت آزادسازی فضا از روی فضای دیسک حذف شدند.', 100, 28, NULL, 7, 49, 'سابین تجارت آریا', 'سعید تاج', '2026-06-29 07:30:00', '2026-06-29 09:13:19', 'high', '2026-06-29 09:13:19', '2026-06-29 09:13:19'),
	(421, 'اختلال 4 دقیقه ای نوین', 'با سلام و احترام\r\n\r\nطبق بررسی‌های انجام‌شده، هیچ‌گونه خطایی بر روی سوییچ مشاهده نگردید و تراکنش‌ها پیش از رسیدن به سوییچ با خطا مواجه می‌شدند.\r\n\r\nبر این اساس، مشخص گردید اختلال به‌وجودآمده ناشی از مشکل شبکه‌ای سمت شرکت پرداخت نوین بوده است.\r\n\r\nاین اختلال از ساعت 20:23 الی 20:27 بوده است.\r\n', 100, 27, NULL, 2, 38, 'اینتک', 'مهدی ایمنی', '2026-06-29 08:30:00', '2026-06-29 08:30:00', 'high', '2026-06-29 10:37:58', '2026-06-29 10:37:58'),
	(422, 'اختلال سوییچ سامان', 'با سلام و احترام\r\n\r\nبا توجه به بررسی‌های به‌عمل‌آمده، برخلاف اعلام شرکت سامان، تعداد تراکنش‌های 420 در ساید 2 بالا نبوده و عمده آن‌ها در ساید 1 مشاهده شده است (حدود 85 هزار تراکنش). بررسی‌ها نشان می‌دهد که به نظر می‌رسد برخی پایانه‌ها (POS) در وضعیت Loop قرار گرفته و به‌صورت مکرر تراکنش‌های 420 ارسال کرده‌اند.\r\n\r\nبا این وجود، با توجه به اینکه شب گذشته شرکت سامان دارای Downtime بوده و تغییراتی بر روی سامانه‌های خود اعمال کرده است، به احتمال زیاد اختلال ایجادشده ناشی از همان تغییرات بوده است.', 95, 27, NULL, 2, 38, 'اینتک', 'مهدی ایمنی', '2026-06-29 08:30:00', '2026-06-29 08:30:00', 'high', '2026-06-29 11:33:32', '2026-06-29 11:33:32'),
	(423, ' واریزی - تراکنش - مانده کارت به تفکیک هر کارت _ تا پایان 31 تیر ( 406478420 )', 'پیرو مذاکره با اقای فتحی و اقای محمدی این تیکت نیازمند توسعه بر روی بک آفیس میباشد (فرم جدید) و مقرر شد به واحد توسعه ارجاع شود.\r\n\r\nاین گزارش انجام شد و تحویل داده شد \r\nیک sp در b2scard وجود دارد با اسم \r\nEXEC [dbo].[Report_Deposit_Transaction_Balance_ByCard_AllCards]\r\n    @fromDate = &#039;2019-01-01&#039;,\r\n    @toDate   = &#039;2026-07-22&#039;;\r\n\r\nاینو باید اجرا کنید', 100, 27, NULL, 4, 41, 'پرداخت نوین آرین', 'سوده فرمانی', '2026-06-30 08:30:00', '2026-06-30 08:30:00', 'low', '2026-06-30 06:48:52', '2026-08-01 12:50:30'),
	(424, 'کانال توسن ', 'پیرو تماس آقای جهانگیری، ایشان پیگیر دسترسی اعمال روت توسط نوین هستند که مقرر شد تیکت ارسال شود و از سمت مدیران اینتک بررسی گردد', 100, 22, NULL, 4, 39, 'پرداخت نوین آرین', 'مهدی جهانگیری', '2026-07-09 06:30:00', '2026-07-07 08:25:00', 'low', '2026-07-08 06:52:17', '2026-07-08 06:56:00'),
	(425, 'مشکل NFC', 'پیرو تماس آقای عظیمی، ایشان اعلام فرمودند که در بکافیس بر روی گزینه فعال کردن nfc زده می شود هیچ تغییری اعمال نمی شود که طی بررسی مشخص گردید که همینطور است و مقرر گردید تیکت ثبت گردد.', 100, 22, NULL, 5, 26, 'توسعه فناوری رفاه پردیس', 'محمود عظیمی', '2026-07-07 05:30:00', '2026-07-07 06:30:00', 'low', '2026-07-08 06:54:53', '2026-07-08 06:54:53'),
	(426, ' سرور مونگو 29.45 سپ', 'پیرو تماس سپ برای پر شدن سرور مونگو\r\nدیسک های مورد نظر بررسی و تخلیه گردید\r\n\r\n\r\n-------------------- \r\nچطوری  ؟ توضیحات آدرس نحوه .... ', 100, 22, NULL, 8, 31, 'پرداخت الکترونیک سامان کیش', 'امیر عابدی', '2026-07-07 08:30:00', '2026-07-07 09:30:00', 'medium', '2026-07-08 06:59:06', '2026-07-26 09:02:38'),
	(427, 'پروتکل و کانفیگ های لازم جهت اتصال کلوزلوپ برای سایر بانک ( 407483045 )', 'با آقای جهانگیری صحبت کردم اطلاعات کامل سوئیچ دادم\r\nقرار شد با بانک ها صحبت کنه و خبر بده\r\n\r\n	شتاب 7 iso 8583 87\r\n	شتاب 7 iso 8583 97\r\n	.net 4.8\r\n	دستور \r\n	Compatibility\r\n\r\nهر وقت نتیجه گرفتی گزارش بزن', 55, 22, NULL, 4, 39, 'پرداخت نوین آرین', 'مهدی جهانگیری', '2026-07-08 08:20:00', '2026-07-08 08:33:21', 'low', '2026-07-08 08:33:21', '2026-07-15 13:12:05'),
	(428, 'روت ترمینال ارتباط فردا', 'ترمینال درخواستی ابتدا insert شد در سرور 80.30 \r\nبه GroupID = 5 \r\nو در نودهای 5.6.7.10.11 آپدیت شد.\r\n\r\n\r\nکامند ؟\r\n\r\n=======================\r\n\r\nupdate [B2SConfig].[dbo].[CfgRouteTerminalGroup] set GroupID = 5\r\n  where terminalNo in (15613437)\r\n\r\n\r\n\r\n  select * from [B2SConfig].[dbo].[CfgRouteTerminalGroup] \r\n  where terminalNo in (15613437)\r\n\r\n\r\n\r\n  insert into [B2SConfig].[dbo].[CfgRouteTerminalGroup] values (15613437,5)', 100, 29, NULL, 8, 31, 'پرداخت الکترونیک سامان کیش', 'امیر عابدی', '2026-07-12 07:46:00', '2026-07-12 09:25:00', 'low', '2026-07-12 11:25:02', '2026-07-18 09:07:18'),
	(429, 'تغییر مسیر لاگ 172.31.29.46 سرور مونگوی ( 806467616 )', 'مراحل اجرای کار\r\n\r\n1. بررسی وضعیت فعلی سرویس\r\n\r\n* بررسی وضعیت سرویس MongoDB و اطمینان از عملکرد عادی آن.\r\n* شناسایی فایل پیکربندی سرویس (mongod.conf یا معادل آن).\r\n* بررسی مسیر فعلی ذخیره‌سازی فایل‌های لاگ و میزان فضای اشغال‌شده.\r\n* بررسی فضای آزاد در درایو G و اطمینان از کافی بودن ظرفیت جهت نگهداری لاگ‌ها.\r\n\r\n 2. آماده‌سازی مسیر جدید\r\n\r\n* ایجاد پوشه مقصد در درایو G  (در صورت عدم وجود).\r\n\r\n 3. تهیه نسخه پشتیبان\r\n\r\n* تهیه نسخه پشتیبان از فایل پیکربندی MongoDB پیش از اعمال تغییرات.\r\n* در صورت نیاز، تهیه نسخه پشتیبان از فایل‌های لاگ موجود جهت نگهداری سوابق.\r\n* ثبت تنظیمات فعلی جهت امکان بازگشت (Rollback) در صورت بروز مشکل.\r\n\r\n4. اعمال تغییرات روی سوییچ\r\nشل سوییچ نودهایی که محل ذخیره ساریشون سرور 29.46 هستند رو باز میکنیم و دستور Mongo Disable رو میرنیم.\r\n\r\n4. اعمال تغییرات\r\n\r\n* ویرایش فایل پیکربندی MongoDB و تغییر مقدار پارامتر **systemLog.path** از مسیر موجود در درایو H به مسیر جدید در درایو G.\r\n* بررسی سایر پارامترهای مرتبط با ثبت لاگ (مانند Log Rotation) و اطمینان از عدم ایجاد مغایرت در تنظیمات.\r\n\r\n 5. انتقال اطلاعات (در صورت نیاز)\r\n\r\n* انتقال فایل‌های لاگ قبلی به مسیر جدید در صورت نیاز به حفظ سوابق.\r\n* کنترل صحت انتقال فایل‌ها و اطمینان از کامل بودن اطلاعات منتقل‌شده.\r\n\r\n6. راه‌اندازی مجدد سرویس\r\n\r\n* توقف کنترل‌شده سرویس MongoDB.\r\n* اعمال تنظیمات جدید.\r\n* راه‌اندازی مجدد سرویس و بررسی وضعیت Start شدن بدون خطا.\r\nشل سوییچ نودهایی که محل ذخیره ساریشون سرور 29.46 هستند رو باز میکنیم و دستور Mongo Enable رو میرنیم.\r\n\r\n7. تست و صحت‌سنجی\r\n\r\n* بررسی ایجاد فایل‌های لاگ جدید در مسیر تعیین‌شده در درایو G.\r\n* کنترل Event Viewer و لاگ‌های سرویس جهت اطمینان از عدم وجود خطا یا هشدار.\r\n* بررسی عملکرد دیتابیس و انجام تست‌های اولیه جهت اطمینان از در دسترس بودن سرویس.\r\n* پایش عملکرد سرویس برای مدت زمان مشخص پس از اعمال تغییرات.\r\n\r\n\r\nپس از اجرای مراحل فوق، مسیر پیش‌فرض ذخیره‌سازی فایل‌های لاگ سرور MongoDB با موفقیت از **درایو H** به **درایو G** منتقل خواهد شد. همچنین سرویس MongoDB بدون اختلال به فعالیت خود ادامه داده و تمامی لاگ‌های جدید در مسیر جدید ثبت خواهند شد. صحت عملکرد سرویس، دسترسی به فایل‌های لاگ و ثبت رویدادها نیز پس از انجام تست‌های نهایی تأیید خواهد شد.\r\n', 100, 24, NULL, 8, 31, 'پرداخت الکترونیک سامان کیش', 'امیر عابدی', '2026-07-02 08:30:00', '2026-07-07 08:30:00', 'high', '2026-07-14 07:18:29', '2026-07-14 07:18:29'),
	(430, 'روت تراکنشهای سوئیچ سیپا به اینتک ', 'از سرور 10.0.72.100\r\nدیتابیس b2sconfig\r\nجدول CfgRoute\r\nای دی های مورد نظر که در سوییچ توسن (268و269و270و271و272و273) می باشند را از priority -10  به 10 آپدیت می کنیم و با این تغییر تراکنش های سیپایی به سمت سوییچ اینتک می آیند. \r\nطبق دستور زیر\r\n---------------------------------------------\r\n\r\n update [B2SConfig].[dbo].[CfgRoute]\r\n  set Priority = 10\r\n  where ID in (268,269,270,271,272,273)', 100, 29, NULL, 4, 10, 'پرداخت نوین آرین', 'زهرا کمایی', '2026-07-09 20:30:00', '2026-07-10 01:30:00', 'low', '2026-07-15 12:29:19', '2026-07-15 12:29:19'),
	(431, 'خالی کردن دیسک mongologer D (172.25.1.162)', 'پاک کردن دیتاهای اضافی و خالی کردن دیسک D از طریق mongocleaenr\r\nاپلیکیشن mongocleaenr را باز می کنیم\r\nدر قسمت connetion\r\nhost : آپی سرور مورد نظر را وارد میکنیم و test connetion را کلیک می کنیم و بعد در قسمت filter \r\nftom date , to date تاریخ را وارد میکنیم و در نهایت دکمه clean را می زنیم و دیتاها پاک میشود.', 100, 29, NULL, 9, 42, 'تجارت الکترونیک پارسیان', 'عباس تفضلی', '2026-07-18 08:05:00', '2026-07-18 08:10:00', 'low', '2026-07-18 08:49:58', '2026-07-18 08:49:58'),
	(432, 'پر شدن دیسک های نوین', 'از مانیتورینگ تماس گرفتند و اعلام کردند دیسک سرورهای ذیل پر شده است.\r\n\r\nACQ proc 01 دیسک (C) 93% \r\nوارد سرور مورد نظر می شویم \r\nDisk : C / پوشه Intek / پوشه DUMP دیتاهای اضافه پاک می شود.\r\n\r\n-----------\r\nACQ DB 1,2,3 دیسک (D) 87%\r\nبه آقای مهندس موسوی اطلاع داده شد و گفتند که امروز درست می کنند.', 100, 29, NULL, 4, 39, 'پرداخت نوین آرین', 'مهدی جهانگیری', '2026-07-18 06:30:00', '2026-07-18 20:20:00', 'low', '2026-07-18 09:23:38', '2026-07-18 09:23:38'),
	(433, 'درخواست گزارش - اطلاعات درخواستی در خصوص شماره کارت مبداء تراکنش بررسی اعتبار کارت و حساب ( 907489221 )', 'در جداول زیر، طبق کوئری گرارش انجام داده و نتیجه را در قالب فایل Excel برای مشتری ارسال میکنیم. (در دیتابیس اکوئری)\r\n\r\n   --Corect\r\n   SELECT\r\n    B2STxn.dbo.FromBase64(ISNULL(ca.PanHash, N&amp;amp;#039;MDA=&amp;amp;#039;)) AS pan,\r\n    gp.Title\r\nFROM [B2SMain].[dbo].[AcqCardGroup] gp WITH (NOLOCK)\r\nINNER JOIN [B2SMain].[dbo].[AcqCard] ca WITH (NOLOCK)\r\n    ON ca.CardGroupId = gp.ID\r\n\r\n---------------------------\r\n Ip Database : 172.25.16.41,6985', 100, 24, NULL, 9, 52, 'تجارت الکترونیک پارسیان', 'پویا عاطفی', '2026-07-13 08:30:00', '2026-07-18 08:30:00', 'medium', '2026-07-18 10:43:54', '2026-08-08 11:23:03'),
	(434, 'پر شدن دیسک های سپ', 'برروی سرور 172.31.29.25\r\nدیسک : D\r\nپوشه explog\r\nپوشه Node25\r\nپوشه ای که فضای زیادی گرفته را پیدا کرده و پاک می کنیم.\r\n\r\nاین مورد license بود که دیتای اضافی پاک شد.', 100, 29, NULL, 8, 31, 'پرداخت الکترونیک سامان کیش', 'امیر عابدی', '2026-07-19 09:00:00', '2026-07-19 09:20:00', 'low', '2026-07-20 08:49:24', '2026-07-20 08:49:24'),
	(435, 'اختلال در مانیتورینگ', 'از  پرداخت نوین تماس گرفتند که 10.0.71.111:8080 قطع شده و بالا نمیاد که بعد از 10 دقیقه تماس گرفتم با قسمت مانیتورینگ که گفتند درست شده.\r\n\r\nمن و خانم سنگی چک کردیم برای ما باز نمیشه مانیتورینگ پورت 8080\r\n\r\nنکته : در حالی که مانیتورینگ جدید دادیم شرکت پرداخت نوین همچنان از مانیتورینگ قدیم استفاده میکنند.', 100, 29, NULL, 4, 39, 'پرداخت نوین آرین', 'مهدی جهانگیری', '2026-07-18 18:52:00', '2026-07-18 19:03:00', 'low', '2026-07-20 11:49:59', '2026-07-20 11:49:59'),
	(436, 'کانال فارا بررای بهرامی نوین', 'به جهت تست تراکنش های کالابرگ بر روی سایت پشتیبان(بهرامی)\r\nنیاز است تا کانال ها - کانکتورها -و روت ها یمتناسب با تراکنش بر روی نودهای سایت بهرامی ایجاد شود.\r\nبا است=فاده از دستورات \r\ncfgchannel add\r\ncfgconnector add\r\ncfgrouting add\r\nاقدام به ایجاد کانال و کانکتور و روت مورد نیاز میکنیم \r\nسپس با استفاده از دستور cfgapplicaton add\r\nاقدام به افزودن تنظیمات اپلیکشن میکنیم.\r\nنکته برای این مورد بعد از اتمام ست کردن تنظیمات نیاز است تا با استفاده از دستور \r\ncfgapplication MakeGlobal این تنظیمات را از حالت لوکال خارج کنیم\r\nنکته بعدی در مورد روت ها که حتما باید بعد از ایجاد روت \r\nبا استفاده از دستورROUT اقدام به اعمال روت ها روی سوییچ نمایید\r\nتوجه داشته باشید برای هر نود باید روت جداگانه تعریف شود\r\nبعد از ساختن کانکتور حتما با استفاده از دستور cfgconnector Builde اقدام به بیلد ردن کانکتور نمایید.\r\n\r\n\r\n----------------\r\nبه این میگن گزارش احسنت بر شما ', 100, 28, NULL, 4, 39, 'پرداخت نوین آرین', 'مهدی جهانگیری', '2026-07-19 06:30:00', '2026-07-21 08:20:27', 'high', '2026-07-21 08:20:27', '2026-07-26 08:50:19'),
	(437, 'خطا در رونوشت کارت مددجویان زندان رضوی 1', 'در بکافیس منوی کارت/کارت شماره کارت را جستجو میکنیم و در باکس پایین قسمت دلیل انسداد را نشان می دهد.\r\nکه برای این کارت دلیل انسداد آزادی درج شده بود.\r\n\r\nکارتی که به دلیل آزادی مددجو مسدود شده باشد دیگر قابلیت رونوشت ندارد.', 100, 29, NULL, 9, 52, 'تجارت الکترونیک پارسیان', 'پویا عاطفی', '2026-07-22 09:55:00', '2026-07-22 10:55:00', 'low', '2026-07-22 11:04:16', '2026-07-22 11:04:16'),
	(438, 'افزایش سقف تراکنش از 200 به 400 میلیون', '\r\nابتدا با دستور زیر ID ترمینال ها را در دیتابیس b2sMain و جدول AcqTerminal پیدا میکنیم\r\n\r\nSELECT  ID\r\n  FROM [B2SMain].[dbo].[AcqTerminal] with(nolock)\r\n  where MaxTransactionAmount = 2000000000 and IsHot = 0\r\n=======================================================\r\n\r\nو بعد با دستور زیر MaxTransactionAmount را آپدیت می کنیم.\r\n\r\n  update [B2SMain].[dbo].[AcqTerminal] with(rowlock)\r\n  set MaxTransactionAmount = 4000000000\r\n  where id in(\r\n  SELECT  ID\r\n  FROM [B2SMain].[dbo].[AcqTerminal] with(nolock)\r\n  where MaxTransactionAmount = 2000000000 and IsHot = 0\r\n======================================================= \r\nو اگر تعداد ترمینال ها زیاد بود برای فشار کمتر به سوییچ از دستور زیر استفاده می کنیم\r\n\r\ndeclare @MinID as bigint = 0\r\ndeclare @MaxID as bigint = 0\r\n\r\nselect @MinID=min(id) , @MaxID=max(id) from AcqTerminal\r\n\r\n  while @MinID &lt; = @MaxID\r\n  begin\r\n  update [B2SMain].[dbo].[AcqTerminal] with(rowlock)\r\n  set MaxTransactionAmount = 4000000000\r\n  where id in(\r\n  SELECT  ID\r\n  FROM [B2SMain].[dbo].[AcqTerminal] with(nolock)\r\n  where MaxTransactionAmount = 2000000000 and IsHot = 0\r\n  and   ID &gt;= @MinID and ID ', 100, 29, NULL, 9, 52, 'تجارت الکترونیک پارسیان', 'پویا عاطفی', '2026-08-01 06:20:00', '2026-08-01 07:25:00', 'low', '2026-08-01 07:34:21', '2026-08-01 07:34:21'),
	(439, 'گزارش سود رسوب', 'برای گزارش سود رسوب (172.25.16.135) تاریخ ابتدا و تاریخ انتهای و همچنین مقدار درصد سود که میخواهند را باید در کوئری زیر مقدار دهی کنیم و اگر گروه کارت خاصی مدنظر بود , شناسه گروه کارت را در قسمت CardGroup این دستور اضافه می کنیم و در دیتابیس Importdata ذخیره میکنیم.\r\n\r\n=======================================\r\n\r\nUSE [ISSReport]\r\nGO\r\n\r\ndeclare\r\n    @FromDate DATE ,\r\n    @ToDate DATE ,\r\n    @PercentDividend DECIMAL(10, 3)  \r\n\r\n	SET @FromDate = &#039;2025-03-21&#039;\r\n    SET @ToDate   = &#039;2026-02-19&#039;\r\n    SET @PercentDividend = 24\r\n\r\n\r\n     \r\n\r\n        INSERT INTO ImportData.dbo.Saeidi_Rosoob (CardNo ,\r\n                            CardGroupID ,\r\n                            AccountId)\r\n                    SELECT c.CardNo ,\r\n                           c.CardGroupID ,\r\n                           a.ID AS AccountID\r\n                    FROM   B2SCard.dbo.ISSCard c WITH ( NOLOCK, FORCESEEK )\r\n                           INNER JOIN b2scard.dbo.isscardgroup g ON g.ID = c.CardGroupID\r\n                           INNER JOIN B2SAccounting.dbo.GLAccount a WITH ( NOLOCK ) ON a.ID = c.MainAccountID\r\n                    WHERE c.State = 1 AND c.IsVirtual IS NULL\r\n                    UNION ALL\r\n                    SELECT c.CardNo ,\r\n                           c.CardGroupID ,\r\n                           a.id AS AccountID\r\n                    FROM   B2SCard.dbo.ISSCard c WITH ( NOLOCK, FORCESEEK )\r\n                           INNER JOIN B2SCard.dbo.ISSCardGroup g ON g.ID = c.CardGroupID\r\n                           INNER JOIN B2SAccounting.dbo.GLAccount a WITH ( NOLOCK ) ON a.ParentAccountID = c.MainAccountID\r\n                           INNER JOIN b2scard.dbo.Segment s ON s.HeadingID = a.AccountHeadingID AND s.IsVirtual = 0\r\n                    WHERE  c.State = 1 AND c.IsVirtual IS NULL\r\n\r\n        UPDATE t\r\n        SET    t.Deposit = dm.Deposit\r\n        FROM   ImportData.dbo.Saeidi_Rosoob t\r\n               INNER JOIN (   SELECT   [AccountId] ,\r\n                                       SUM([Amount]) AS Deposit\r\n                              FROM     rep.DepositMoneyTest dm WITH ( NOLOCK, FORCESEEK )\r\n                              WHERE    dm.BusinessDate &gt;= @FromDate\r\n                                       AND dm.BusinessDate &lt; @ToDate\r\n                              GROUP BY dm.AccountId ) dm ON t.AccountID = dm.AccountID;\r\n\r\n        IF ( @@ROWCOUNT ', 100, 29, NULL, 9, 52, 'تجارت الکترونیک پارسیان', 'پویا عاطفی', '2026-07-28 06:30:00', '2026-08-01 11:05:00', 'low', '2026-08-01 11:31:40', '2026-08-01 11:31:40'),
	(440, 'استعلام مانا کارت', '1. از سرور 172.25.16.77\r\n2. دیتابیس b2sCard\r\n3. جدول iisCard \r\nکارت یا کارت هایی که اعلام میکنند استعلام مانا نگرفته اند را پیدا میکنیم اگر 0 = IsMana بود کارت استعلام مانا ندارد و  دیتای درست برای کارت تعریف نشده و خطا می خورد.\r\nبرای اینکه ببینیم چه خطایی برای استعلام مانا گرفته است از جدول ISSManaInquiryErrors استفاده می کنیم.\r\nو بعد از دیدن خطا و پیدا شدن مشکل به کاربر مربوطه اطلاع میدهیم خطاها را ویرایش کند و اطلاع دهد بعد از ویرایش , از سرور 172.25.16.59 InquiryDateMana و ManaInquiryOnline را NULL میکنیم تا وب سرویس مجدد برای استعلام این کارت ها را بردارد.\r\n\r\n==========================================\r\nQuery نمایش خطا\r\n\r\nSELECT TOP (1000) [Id]\r\n      ,[CardNo]\r\n      ,[ErrorMessage]\r\n      ,[CreatedOn]\r\n      ,[Data]\r\n  FROM [B2SCard].[dbo].[ISSManaInquiryErrors]\r\n  where\r\n==========================================\r\nQuery آپدیت\r\n\r\n  UPDATE [B2SCard].[dbo].[ISSCard]\r\nSET\r\n    InquiryDateMana = NULL,\r\n    ManaInquiryOnline = NULL\r\nWHERE', 100, 29, NULL, 9, 52, 'تجارت الکترونیک پارسیان', 'پویا عاطفی', '2026-08-02 07:03:00', '2026-08-02 09:03:00', 'low', '2026-08-02 09:24:29', '2026-08-02 09:24:29'),
	(441, 'خطا ی 22 - E22 يکي از شباهاي قبلي پذيرنده در تسهيم استفاده شده و قابل حذف نيست (تیکت sdsjd; 408506095 )', '### رفع خطای E22 پس از فراخوانی سرویس `Change_IBAN`\r\n\r\nبر اساس اعلام مشتری، پس از فراخوانی سرویس `Change_IBAN` اینتک در سامانه جام‌جام، ترمینال‌های موجود در فایل پیوست با خطای **E22** مواجه می‌شوند.\r\n\r\nعلت بروز این خطا این است که کاربر قصد حذف شبایی را دارد که حداقل یک ترمینال در سیستم به آن متصل است. قرار بود این مشکل از سمت آقای یاوری برطرف شود، اما تاکنون اصلاحی انجام نشده است. در حال حاضر، نوین درخواست کرده است که این مورد به‌صورت دستی انجام شود.\r\n\r\n### مراحل انجام کار\r\n\r\nابتدا، با توجه به اطلاعات موجود در فایل پیوست، دستورات زیر را اجرا کرده و شبای موردنظر را در جدول مربوطه درج (Insert) کنید.\r\n\r\n&gt; **نکته:** قبل از اجرای دستور `INSERT`، مقدار فیلد `ExtenalId` باید از طریق `Sequence` مربوطه استخراج شود و در دستور `INSERT` قرار گیرد.\r\n\r\n```sql\r\nUSE B2SMain;\r\nGO\r\n\r\n-- یافتن اطلاعات ترمینال و Merchant\r\nSELECT at.Id, at.SettlementAccountID, *\r\nFROM AcqTerminal at\r\nWHERE at.TerminalINumber = 30185003;\r\n\r\n-- بررسی اطلاعات حساب در جدول AcqCardAcceptorBankAccounts\r\nSELECT IBAN, Id, IsActive, CreatedOn, *\r\nFROM AcqCardAcceptorBankAccounts\r\nWHERE PartyID = 307878;\r\n\r\n-- دریافت مقدار جدید از Sequence\r\nDECLARE @result BIGINT;\r\nSET @result = NEXT VALUE FOR BankAccountSequence;\r\nPRINT @result;\r\n\r\n-- درج شبا\r\nINSERT INTO B2SMain.dbo.AcqCardAcceptorBankAccounts\r\n(\r\n    PartyID,\r\n    ExtenalId,\r\n    IsActive,\r\n    IBAN,\r\n    CreatedOn,\r\n    MerchantId\r\n)\r\nVALUES\r\n(\r\n    307878,\r\n    [مقدار به‌دست‌آمده از Sequence],\r\n    1,\r\n    &#039;IR510640176498914467096001&#039;,\r\n    GETDATE(),\r\n    2914114\r\n);\r\n```\r\n', 100, 24, NULL, 4, 10, 'پرداخت نوین آرین', 'زهرا کمایی', '2026-08-05 04:30:00', '2026-08-05 08:30:00', 'medium', '2026-08-05 11:15:41', '2026-08-05 11:15:41'),
	(442, 'سوییج اوت پارسیان', 'ابتدا وارد ولیکس پارسیان می شویم (172.25.1.185)\r\nسپس وارد سرور 172.25.16.41 می شویم در SQL اول جاب های سرور (172.25.16.39) Arch_Txn , Arch_Txndata را disable میکنیم.\r\nبه سرور 172.25.16.40 کانکت می شویم و دیتابیس b2sTxn را باز می کنیم و 3 جدول swTxn , swTxnData , swTxnLog کلیک راست storage و بعد manage partition و sw out partition را انتخاب و \r\nتعداد روزهایی (جداول) که باید انتقال دهیم را انتخاب میکنیم.\r\nTxnLog را بر روی همان سرور(172.25.16.40) پاک میکنیم با این روش که کلیک روی Table پوشه زرد سپس F7 را می زنیم و فایل هایی که آوردیم را DELETE می کنیم.\r\nبرای انتقال جداول باید به سرور (172.25.16.159) لاگین کرده و SQL را باز می کنیم کلیک راست روی دیتابیس B2sTxn و Tasks و Export Data را انتحاب میکنیم و\r\n از سرور 16.159 Txn به 16.41 Arch انتقال انجام میشود.\r\nبعد از اتمام انتقال Txn , TxnData جداول از روی سرور 16.40 پاک می شود و \r\nروی دیتابیس B2sTxn کلیک راست می کنیم و  از قسمت properties و بعد Files تعداد جداولی که خارج کردیم Remove می کنیم و در بالا سمت چپ Script را می زنیم و کوئری پاک کردن جداول انتقال داده شده باز می شود و کوئری را اجرا می کنیم.\r\nو در آخر جاب های سرور 16.39 را Enable می کنیم.\r\n', 100, 29, NULL, 9, 42, 'تجارت الکترونیک پارسیان', 'عباس تفضلی', '2026-08-03 05:30:00', '2026-08-03 12:30:00', 'low', '2026-08-05 11:46:02', '2026-08-05 11:46:02'),
	(443, 'فزایش مبلغ شارژ ایرانسل 10%', 'با سلام\r\nباتوجه به پیگیری و بررسی های صورت گرفته و تماس تلفنی با اقای پهلوان تمامی مبالغ شارز ایرانسل، 10% افزایش پیدا کرده اند.\r\nبرای اینکار اقای دارایی نسخه جدیدی اعمال کردند بر روی سوییچ', 100, 27, NULL, 8, 31, 'پرداخت الکترونیک سامان کیش', 'امیر عابدی', '2026-08-08 08:30:00', '2026-08-08 08:30:00', 'low', '2026-08-08 06:13:07', '2026-08-08 06:13:07'),
	(444, 'روت ترمینال ارتباط فردا', 'از سرور 80.30 و اگر تعداد ترمینال ها زیاد بود از سرور 80.80 (Read) استفاده می کنیم البته بهتر است که سرور Read استفاده شود.\r\nابتدا این دستور را اجرا می کنیم :\r\n\r\nSELECT [TerminalNo],[GroupID]\r\n FROM [B2SConfig].[dbo].[CfgRouteTerminalGroup] with(nolock) where terminalNo in (&#039;terminalNo&#039;) \r\n========================================================================\r\nاگر شماره ترمینال وجود نداشت دستور زیر را اجرا می کنیم : \r\n\r\ninsert into [B2SConfig].[dbo].[CfgRouteTerminalGroup] values (terminalNo,5)\r\n========================================================================\r\nو اگر ترمینال وجود داشت و  GroupID عدد دیگری بود از دستور زیر استفاده می کنیم : \r\n\r\nupdate [B2SConfig].[dbo].[CfgRouteTerminalGroup] set GroupID = 5\r\n  where terminalNo in (&#039;terminalNo&#039;)\r\n========================================================================\r\nدر آخر وارد shel سوییچ میشویم و برای روت ارتباط فردا نود های 5 و 6 و 7 و 10 و 11 را route  می کنیم.\r\n\r\n\r\nتوضیحات:\r\nGroupID \r\nارتباط فردا = 5 \r\nانیاک = 17\r\n\r\n', 100, 29, NULL, 8, 31, 'پرداخت الکترونیک سامان کیش', 'امیر عابدی', '2026-08-16 06:30:00', '2026-08-16 06:45:00', 'low', '2026-08-16 07:54:03', '2026-08-16 07:54:03'),
	(445, 'غیرفعالسازی پایانه بر روی سوییچ', 'شماره مرجع در دیتابیس سوییج (172.25.16.41) بررسی شد, تراکنش و شماره مرجع در دیتابیس موجود نبود. \r\nتراکنش بر روی سوییچ مهرانا بوده است. \r\n\r\n\r\n=======================================\r\n\r\nSELECT * FROM [B2STxn].[dbo].[SwTxn]\r\n  where RRN = &#039;813690328058&#039;', 100, 29, NULL, 9, 52, 'تجارت الکترونیک پارسیان', 'پویا عاطفی', '2026-08-23 05:45:00', '2026-08-23 06:47:00', 'low', '2026-08-23 06:52:31', '2026-08-23 06:52:31'),
	(446, 'پر شدن فضای سرور مونگو 72.51 نوین', 'با سلام مبنی بر تماس مانیتورینگ نوین، سرور 72.51 با استفاده از MongoCleaner در سامانه رایمون خالی گردید.', 100, 24, NULL, 4, 10, 'پرداخت نوین آرین', 'زهرا کمایی', '2026-08-20 08:30:00', '2026-08-20 11:30:00', 'low', '2026-08-23 09:03:29', '2026-08-23 09:03:29'),
	(447, 'حذف شبا', 'از سرور 172.25.16.41 \r\nدیتابیس b2smain\r\nویوو [VwSettlement-Abbas1].[dbo]\r\nشماره شباهای اعلامی را پیدا میکنیم اگر IsActive برابر 1 بود شماره شبا فعال است و با دستور update از سرور 172.25.16.40 غیرفعال می کنیم طبق دستور زیر:\r\n\r\n==========================================\r\n\r\nupdate [B2SMain].[dbo].[VwSettlement-Abbas1]\r\n  set IsActive = 0\r\n  where IBAN in (&#039;&#039;)\r\n\r\n=========================================\r\n\r\nupdate [B2SMain].[dbo].[VwAcqMerchantSettlementItems]\r\nset IsActive = 0\r\n  where IBAN in (&#039;&#039;)', 100, 29, NULL, 9, 52, 'تجارت الکترونیک پارسیان', 'پویا عاطفی', '2026-08-24 05:15:00', '2026-08-24 06:20:00', 'low', '2026-08-24 06:35:11', '2026-08-25 08:04:59'),
	(448, 'فیلد 53 جدید برای کانال 10010 (تیکت 408515739 )', 'ابتدا باید روی یکی از نودهای Shell Switch، دستور cfgChannelKey را اجرا کنیم تا کلیدها و ایندکس‌های تعریف‌شده برای یک کانال مشخص نمایش داده شوند. برای مثال، در اینجا اطلاعات کانال Secure Channel با شناسه 10010 بررسی می‌شود.\r\n\r\nسپس باید با استفاده از اپلیکیشن یا وب‌سایت مربوطه، یک کلید ۳۲ کاراکتری ایجاد کنیم. پس از آن، با توجه به ایندکس‌های تعریف‌شده روی کانال موردنظر، دستور CFGChannel key add را اجرا کرده و مشخصات لازم را براساس کانال، آخرین ایندکس موجود و کلیدی که در مرحله قبل ساخته‌ایم، ثبت می‌کنیم.\r\n\r\nدر ادامه، دستور [ZMKENTRY ایندکس جدید] Switch key را اجرا می‌کنیم. پس از اجرای این دستور، دو مقدار KVC و شناسه ۳۲ رقمی نمایش داده می‌شوند. این دو مقدار باید در محلی امن ذخیره شده و سپس برای مشتری ارسال شوند.\r\n\r\n\r\n---------------------------------------------------------------------\r\n\r\n\r\n\r\n# گزارش بررسی کاربرد و ساختار Bit 53 در ISO8583 و سوییچ پرداخت\r\n\r\n## 1. مقدمه\r\n\r\nاین گزارش نتیجه بررسی انجام‌شده درباره **Field 53 یا Bit 53 پیام ISO8583** و نحوه استفاده از آن در سوییچ پرداخت است.\r\n\r\nهدف اصلی بررسی، پاسخ به این موارد بوده است:\r\n\r\n* Bit 53 چه کاربردی دارد؟\r\n* چه نوع اطلاعاتی در این فیلد قرار می‌گیرد؟\r\n* ساختار آن چگونه است؟\r\n* سوییچ فعلی Bit 53 را چگونه پردازش می‌کند؟\r\n* ارتباط Bit 53 با PIN Block و کلیدهای رمزنگاری چیست؟\r\n* در زمان عیب‌یابی چه مواردی باید کنترل شوند؟\r\n\r\n---\r\n\r\n## 2. تعریف Bit 53\r\n\r\nدر ISO8583، فیلد 53 با عنوان زیر شناخته می‌شود:\r\n\r\n**Security Related Control Information**\r\n\r\nاین فیلد برای نگهداری **اطلاعات کنترلی مرتبط با عملیات امنیتی و رمزنگاری** استفاده می‌شود.\r\n\r\nبنابراین Bit 53 اصولاً محل نگهداری خود PIN نیست. همچنین نباید آن را با MAC اشتباه گرفت.\r\n\r\nبه‌صورت مفهومی:\r\n\r\n```text\r\nBit 52  → PIN Block\r\nBit 53  → Security Control Information\r\nBit 64/128 → MAC\r\n```\r\n\r\nBit 53 می‌تواند اطلاعاتی را در اختیار سیستم دریافت‌کننده قرار دهد که مشخص کند عملیات امنیتی با چه پارامتر یا مجموعه کلیدی انجام شود.\r\n\r\nجزئیات دقیق ساختار این فیلد به پروتکل و توافق دو طرف ارتباط وابسته است.\r\n\r\n---\r\n\r\n## 3. ساختار عمومی Bit 53\r\n\r\nدر تعاریف رایج ISO8583، Bit 53 به‌عنوان یک فیلد امنیتی با ساختار عددی تعریف می‌شود و معمولاً با مشخصه‌ای مانند زیر دیده می‌شود:\r\n\r\n```text\r\nDE53\r\nSecurity Related Control Information\r\nn16\r\n```\r\n\r\nیعنی در سطح ISO با یک فیلد کنترلی امنیتی مواجه هستیم.\r\n\r\nبا این حال، ISO8583 به تنهایی الزام نمی‌کند که مثلاً:\r\n\r\n```text\r\nDigit 1-2 = PIN Key Index\r\nDigit 3-4 = MAC Key Index\r\nDigit 5-6 = Algorithm\r\n...\r\n```\r\n\r\nباشد.\r\n\r\nمعنی دقیق Positionها وابسته به پروتکل شبکه و Implementation است.\r\n\r\nبنابراین ساختار Bit 53 یک شبکه دیگر را نمی‌توان بدون مستندات به شتاب، شاپرک یا سوییچ فعلی تعمیم داد.\r\n\r\n---\r\n\r\n## 4. رفتار Bit 53 در سوییچ فعلی\r\n\r\nمهم‌ترین نتیجه بررسی سورس سوییچ این است که سیستم از Bit 53 برای استخراج **Key Index** استفاده می‌کند.\r\n\r\nدر کد مربوط به پردازش امنیتی، منطق زیر وجود دارد:\r\n\r\n```csharp\r\nISOUtil.hexString(\r\n    message.PayLoad.GetByteValue(53)\r\n).Substring(6, 2)\r\n```\r\n\r\nروند پردازش به این شکل است:\r\n\r\n1. مقدار Field 53 از پیام گرفته می‌شود.\r\n2. مقدار آن به صورت Byte دریافت می‌شود.\r\n3. داده به Hex String تبدیل می‌شود.\r\n4. از Position شماره 6 به طول 2 کاراکتر خوانده می‌شود.\r\n5. مقدار استخراج‌شده به‌عنوان `keyIndex` استفاده می‌شود.\r\n\r\nدر نتیجه از دید Implementation فعلی، **Byte چهارم داده‌ای که کد بررسی می‌کند اهمیت مستقیم دارد**.\r\n\r\n---\r\n\r\n## 5. نمونه استخراج Key Index\r\n\r\nفرض کنیم داده مورد بررسی به این صورت باشد:\r\n\r\n```text\r\n00 00 00 03\r\n```\r\n\r\nنمایش Hex آن برابر است با:\r\n\r\n```text\r\n00000003\r\n```\r\n\r\nتقسیم‌بندی:\r\n\r\n```text\r\nByte       1       2       3       4\r\n         +-------+-------+-------+-------+\r\nValue    |  00   |  00   |  00   |  03   |\r\n         +-------+-------+-------+-------+\r\nHex Pos    0-1     2-3     4-5     6-7\r\n                                  ↑\r\n                              Key Index\r\n```\r\n\r\nکد زیر:\r\n\r\n```csharp\r\n&quot;00000003&quot;.Substring(6, 2)\r\n```\r\n\r\nمقدار زیر را برمی‌گرداند:\r\n\r\n```text\r\n03\r\n```\r\n\r\nدر نتیجه:\r\n\r\n```text\r\nKeyIndex = 3\r\n```\r\n\r\nبنابراین در این مثال، سوییچ باید کلید مرتبط با **Index شماره 3** را برای ادامه عملیات امنیتی پیدا کند.\r\n\r\n---\r\n\r\n## 6. استفاده از Key Index\r\n\r\nپس از استخراج Key Index، سوییچ از منطق انتخاب کلید Channel استفاده می‌کند.\r\n\r\nبه‌صورت مفهومی فراخوانی مشابه زیر انجام می‌شود:\r\n\r\n```csharp\r\nSharedUtils.GetKeyByIndex(\r\n    channelId,\r\n    keyIndex,\r\n    1\r\n);\r\n```\r\n\r\nدر نتیجه سه پارامتر مهم وجود دارد:\r\n\r\n```text\r\nChannel ID\r\n    +\r\nKey Index\r\n    +\r\nKey Usage\r\n    ↓\r\nCryptographic Key\r\n```\r\n\r\nیعنی صرفاً داشتن `KeyIndex = 3` کافی نیست.\r\n\r\nسوییچ باید بداند این Index مربوط به **کدام Channel** و **کدام Key Usage** است.\r\n\r\n---\r\n\r\n## 7. ارتباط Bit 53 با PIN\r\n\r\nدر مسیر بررسی‌شده، Bit 53 خودش PIN Block را حمل نمی‌کند.\r\n\r\nنقش آن کمک به تعیین کلیدی است که برای پردازش اطلاعات امنیتی استفاده می‌شود.\r\n\r\nدر سناریوی مورد بررسی سوییچ:\r\n\r\n```text\r\nBit 53\r\n   ↓\r\nExtract KeyIndex\r\n   ↓\r\nFind Channel Key\r\n   ↓\r\nGet PPK\r\n   ↓\r\nDecrypt encrypted PIN data\r\n   ↓\r\nOpen PIN Block\r\n   ↓\r\nObtain PIN information\r\n```\r\n\r\nبنابراین اگر مثلاً:\r\n\r\n```text\r\nBit 53 = ...03\r\n```\r\n\r\nباشد، مفهوم عملی آن در این مسیر این است که سوییچ باید به دنبال Key Index شماره 3 در تنظیمات کلیدهای Channel مربوطه برود.\r\n\r\n---\r\n\r\n## 8. ارتباط با Bit 48 در Implementation فعلی\r\n\r\nیکی از نکات مهم این سوییچ این است که در برخی Processing Codeهای خاص، اطلاعات PIN رمز‌شده از **Bit 48** دریافت می‌شود.\r\n\r\nدر این حالت جریان به‌صورت زیر است:\r\n\r\n```text\r\nBit 53\r\n   │\r\n   └── Key Index\r\n          │\r\n          ↓\r\n     Channel Key\r\n          │\r\n          ↓\r\n        PPK\r\n          │\r\n          ↓\r\nBit 48 → Encrypted PIN Data\r\n          │\r\n          ↓\r\n       Decrypt\r\n          │\r\n          ↓\r\n      PIN Block\r\n```\r\n\r\nبنابراین در این سناریو:\r\n\r\n```text\r\nBit 48 = داده رمز‌شده\r\nBit 53 = اطلاعات لازم برای انتخاب کلید\r\n```\r\n\r\nاین رفتار مربوط به Implementation فعلی سوییچ است و نباید به همه پیام‌های ISO8583 تعمیم داده شود.\r\n\r\n---\r\n\r\n## 9. وضعیت نبودن Bit 53\r\n\r\nیکی دیگر از رفتارهای مهم مشاهده‌شده این است که اگر Bit 53 در پیام موجود نباشد، سیستم الزاماً متوقف نمی‌شود.\r\n\r\nدر این حالت Key Index می‌تواند براساس Trace Number و تعداد کلیدهای Channel محاسبه شود.\r\n\r\nمنطق آن به شکل زیر است:\r\n\r\n```csharp\r\nkeyIndex = TraceNo % CurrentChannel.KeyCount + 1;\r\n```\r\n\r\nبرای مثال اگر:\r\n\r\n```text\r\nTraceNo = 125\r\nKeyCount = 4\r\n```\r\n\r\nداشته باشیم:\r\n\r\n```text\r\n125 % 4 = 1\r\n```\r\n\r\nسپس:\r\n\r\n```text\r\n1 + 1 = 2\r\n```\r\n\r\nپس:\r\n\r\n```text\r\nKeyIndex = 2\r\n```\r\n\r\nدر نتیجه دو مسیر برای تعیین Key Index وجود دارد:\r\n\r\n```text\r\n               Key Index\r\n                  ▲\r\n                  │\r\n        ┌─────────┴─────────┐\r\n        │                   │\r\n   Bit 53 Exists       Bit 53 Missing\r\n        │                   │\r\nExtract from DE53      Calculate from\r\n                      TraceNo/KeyCount\r\n```\r\n\r\n---\r\n\r\n## 10. تفاوت Bit 52، Bit 53 و MAC\r\n\r\nبرای جلوگیری از اشتباه در تحلیل لاگ‌ها، تفاوت این فیلدها مهم است.\r\n\r\n### Bit 52\r\n\r\nمعمولاً برای **PIN Data / PIN Block** استفاده می‌شود.\r\n\r\n```text\r\nDE52 → PIN Block\r\n```\r\n\r\n### Bit 53\r\n\r\nبرای **Security Related Control Information** است.\r\n\r\nدر Implementation مورد بررسی، یکی از کاربردهای عملی آن استخراج **Key Index** است.\r\n\r\n```text\r\nDE53 → Security Control → Key Index\r\n```\r\n\r\n### Bit 64 یا Bit 128\r\n\r\nمعمولاً برای MAC استفاده می‌شوند.\r\n\r\n```text\r\nDE64 / DE128 → MAC\r\n```\r\n\r\nبنابراین:\r\n\r\n```text\r\nPIN Block ≠ Key Index ≠ MAC\r\n```\r\n\r\nهر کدام نقش مستقلی در امنیت پیام دارند.\r\n\r\n---\r\n\r\n## 11. معنی سایر قسمت‌های Bit 53\r\n\r\nاز سورس بررسی‌شده فقط بخشی که برای استخراج Key Index استفاده می‌شود با قطعیت مشخص است.\r\n\r\nبرای مثال اگر مقدار داده مورد بررسی این باشد:\r\n\r\n```text\r\n00 00 00 03\r\n```\r\n\r\nمی‌دانیم:\r\n\r\n```text\r\n03 → Key Index\r\n```\r\n\r\nاما از کد موجود نمی‌توان با قطعیت نتیجه گرفت:\r\n\r\n```text\r\nByte 1 = ?\r\nByte 2 = ?\r\nByte 3 = ?\r\n```\r\n\r\nزیرا Validator مورد بررسی این قسمت‌ها را Parse نمی‌کند.\r\n\r\nبنابراین نسبت دادن معنی‌هایی مانند:\r\n\r\n```text\r\nByte 1 = Algorithm\r\nByte 2 = PIN Format\r\nByte 3 = MAC Type\r\n```\r\n\r\nبدون داشتن Specification مربوط به Interface شاپرک/شتاب قابل استناد نیست.\r\n\r\n---\r\n\r\n## 12. نکات مهم عیب‌یابی\r\n\r\nاگر تراکنشی به دلیل PIN یا عملیات رمزنگاری با خطا مواجه شود، Bit 53 یکی از نقاط مهم بررسی است.\r\n\r\nموارد زیر باید کنترل شوند:\r\n\r\n1. آیا Bit 53 در پیام وجود دارد؟\r\n\r\n2. مقدار Raw/Hex بیت 53 چیست؟\r\n\r\n3. Key Index استخراج‌شده از آن چه مقداری است؟\r\n\r\n4. آیا این Key Index برای Channel مبدأ تعریف شده است؟\r\n\r\n5. آیا Key Usage مورد انتظار صحیح است؟\r\n\r\n6. آیا کلید متناظر با Index موردنظر در تنظیمات Channel Keys وجود دارد؟\r\n\r\n7. آیا طرف ارسال‌کننده و سوییچ روی نحوه Encoding بیت 53 توافق دارند؟\r\n\r\n8. آیا داده PIN با همان کلیدی رمز شده که سوییچ براساس Bit 53 انتخاب می‌کند؟\r\n\r\n9. در صورت نبود Bit 53، Key Index محاسبه‌شده از Trace Number چه مقداری شده است؟\r\n\r\n---\r\n\r\n## 13. نمونه سناریوی عیب‌یابی\r\n\r\nفرض کنیم در یک تراکنش داریم:\r\n\r\n```text\r\nMTI      = 0200\r\nBit 11   = 123456\r\nBit 53   = 00000003\r\n```\r\n\r\nاز Bit 53 نتیجه می‌گیریم:\r\n\r\n```text\r\nKeyIndex = 3\r\n```\r\n\r\nدر ادامه انتظار داریم سوییچ کلیدی با مشخصات منطقی زیر پیدا کند:\r\n\r\n```text\r\nChannel = Source Channel\r\nIndex   = 3\r\nUsage   = Expected PPK Usage\r\n```\r\n\r\nاگر کلید وجود نداشته باشد یا کلید اشتباهی تعریف شده باشد، عملیات Decrypt اطلاعات PIN می‌تواند شکست بخورد.\r\n\r\nبنابراین در چنین شرایطی فقط بررسی خود PIN Block کافی نیست؛ باید مسیر زیر کامل بررسی شود:\r\n\r\n```text\r\nBit53\r\n  ↓\r\nKeyIndex\r\n  ↓\r\nCfgChannelKeys / Channel Key Configuration\r\n  ↓\r\nActual Key ID\r\n  ↓\r\nDecrypt\r\n  ↓\r\nPIN Block\r\n```\r\n\r\n---\r\n\r\n## 14. جمع‌بندی\r\n\r\nBit 53 در ISO8583 یک فیلد مرتبط با **کنترل عملیات امنیتی** است و نباید آن را خود PIN Block یا MAC در نظر گرفت.\r\n\r\nدر سوییچ مورد بررسی، کاربرد مهم و اثبات‌شده Bit 53، **استخراج Key Index برای انتخاب کلید رمزنگاری Channel** است.\r\n\r\nبه‌صورت خلاصه:\r\n\r\n```text\r\nBit 53\r\n   ↓\r\nSecurity Related Control Information\r\n   ↓\r\nExtract Key Index\r\n   ↓\r\nFind Key for Source Channel\r\n   ↓\r\nUse PPK\r\n   ↓\r\nDecrypt PIN-related Data\r\n```\r\n\r\nاز سورس موجود مشخص است که سوییچ بخشی از Field 53 را برای استخراج `KeyIndex` می‌خواند. همچنین اگر Field 53 وجود نداشته باشد، امکان محاسبه Key Index بر مبنای Trace Number و تعداد کلیدهای Channel وجود دارد.\r\n\r\nبا این حال، **معنی دقیق تمام Positionها یا Byteهای Bit 53 در پروتکل شاپرک/شتاب از سورس‌های فعلی قابل اثبات نیست**. برای تعیین دقیق ساختار کامل این فیلد، باید Specification رسمی Interface مربوط به شتاب/شاپرک بررسی شود.\r\n\r\n### نتیجه عملی برای پشتیبانی\r\n\r\nهنگام مشاهده مشکل PIN/Encryption، مسیر بررسی پیشنهادی به این صورت است:\r\n\r\n```text\r\nDE53\r\n ↓\r\nKeyIndex\r\n ↓\r\nSource Channel\r\n ↓\r\nChannel Key Configuration\r\n ↓\r\nPPK / Key ID\r\n ↓\r\nEncrypted PIN Data\r\n ↓\r\nDecrypt\r\n ↓\r\nPIN Block\r\n```\r\n\r\nدر نتیجه Bit 53 را می‌توان در این سوییچ به‌عنوان یکی از نقاط کلیدی ارتباط بین **پیام ISO8583 و Key Management سوییچ** در نظر گرفت.\r\n', 100, 24, NULL, 4, 10, 'پرداخت نوین آرین', 'زهرا کمایی', '2026-08-23 08:30:00', '2026-08-24 08:30:00', 'high', '2026-08-25 07:30:36', '2026-08-25 07:30:36'),
	(449, 'تغییر وضعیت تقاضا ', 'از سرور 172.25.16.77\r\nدیتابیس B2scard\r\nجدول isscardrequest\r\nشماره تقاضا (ID) را پیدا می کنیم :\r\n\r\n  SELECT *\r\n  FROM [B2SCard].[dbo].[ISSCardRequest]\r\n  where ID = \r\n ==========================================\r\nو از سرور 172.25.16.59 status را به وضعیتی که درخواست کرده اند تغییر می دهیم :\r\n\r\nupdate [B2SCard].[dbo].[ISSCardRequest]\r\n  set Status = \r\n  where id =', 100, 29, NULL, 9, 52, 'تجارت الکترونیک پارسیان', 'پویا عاطفی', '2026-08-25 11:45:00', '2026-08-25 12:05:00', 'low', '2026-08-25 12:46:29', '2026-08-25 12:46:29'),
	(450, 'استعلام مانا کارت', '1. از سرور 172.25.16.77\r\n2. دیتابیس b2sCard\r\n3. جدول iisCard \r\nکارت یا کارت هایی که اعلام میکنند استعلام مانا نگرفته اند را پیدا میکنیم اگر 0 = IsMana بود کارت استعلام مانا ندارد و  دیتای درست برای کارت تعریف نشده و خطا می خورد.\r\nبرای اینکه ببینیم چه خطایی برای استعلام مانا گرفته است از جدول ISSManaInquiryErrors استفاده می کنیم.\r\nو بعد از دیدن خطا و پیدا شدن مشکل به کاربر مربوطه اطلاع میدهیم خطاها را ویرایش کند و اطلاع دهد بعد از ویرایش , از سرور 172.25.16.59 InquiryDateMana و ManaInquiryOnline را NULL میکنیم تا وب سرویس مجدد برای استعلام این کارت ها را بردارد.\r\n\r\n==========================================\r\nQuery نمایش خطا\r\n\r\nSELECT TOP (1000) [Id]\r\n      ,[CardNo]\r\n      ,[ErrorMessage]\r\n      ,[CreatedOn]\r\n      ,[Data]\r\n  FROM [B2SCard].[dbo].[ISSManaInquiryErrors]\r\n  where\r\n==========================================\r\nQuery آپدیت\r\n\r\n  UPDATE [B2SCard].[dbo].[ISSCard]\r\nSET\r\n    InquiryDateMana = NULL,\r\n    ManaInquiryOnline = NULL\r\nWHERE', 100, 29, NULL, 9, 52, 'تجارت الکترونیک پارسیان', 'پویا عاطفی', '2026-08-31 08:30:00', '2026-08-31 11:46:00', 'low', '2026-08-31 11:49:37', '2026-08-31 11:49:37'),
	(451, 'سوییج اوت پارسیان', 'ابتدا وارد ولیکس پارسیان می شویم (172.25.1.185)\r\nسپس وارد سرور 172.25.16.41 می شویم در SQL اول جاب های سرور (172.25.16.39) Arch_Txn , Arch_Txndata را disable میکنیم.\r\nبه سرور 172.25.16.40 کانکت می شویم و دیتابیس b2sTxn را باز می کنیم و 3 جدول swTxn , swTxnData , swTxnLog کلیک راست storage و بعد manage partition و sw out partition را انتخاب و \r\nتعداد روزهایی (جداول) که باید انتقال دهیم را انتخاب میکنیم.\r\nTxnLog را بر روی همان سرور(172.25.16.40) پاک میکنیم با این روش که کلیک روی Table پوشه زرد سپس F7 را می زنیم و فایل هایی که آوردیم را DELETE می کنیم.\r\nبرای انتقال جداول باید به سرور (172.25.16.159) لاگین کرده و SQL را باز می کنیم کلیک راست روی دیتابیس B2sTxn و Tasks و Export Data را انتحاب میکنیم و\r\n از سرور 16.159 Txn به 16.41 Arch انتقال انجام میشود.\r\nبعد از اتمام انتقال Txn , TxnData جداول از روی سرور 16.40 پاک می شود و \r\nروی دیتابیس B2sTxn کلیک راست می کنیم و  از قسمت properties و بعد Files تعداد جداولی که خارج کردیم Remove می کنیم و در بالا سمت چپ Script را می زنیم و کوئری پاک کردن جداول انتقال داده شده باز می شود و کوئری را اجرا می کنیم.\r\nو در آخر جاب های سرور 16.39 را Enable می کنیم.\r\n', 100, 29, NULL, 9, 42, 'تجارت الکترونیک پارسیان', 'عباس تفضلی', '2026-09-01 05:30:00', '2026-09-01 10:30:00', 'low', '2026-09-01 10:34:41', '2026-09-01 10:34:41'),
	(452, 'خطای کلید رمز کارتخوان ', 'از سرور 172.25.16.41\r\nدیتابیس B2sTxn\r\nجدول SwTxn\r\nدستور زیر را اجرا می کنیم :\r\n\r\nSELECT ResponseCode,InternalReasonCode,*\r\n  FROM [B2STxn].[dbo].[SwTxn]\r\n  WHERE PTerminalNo in (45084124,45092299,45092300)\r\n  AND ResponseCode = 55\r\n  AND InternalReasonCode = 2\r\n  AND BusinessDate &gt;= &#039;2026-03-21&#039;\r\n  AND BusinessDate &lt; &#039;2026-09-20&#039;;\r\n\r\nجهت اطلاع دیتا از اول سال موجود نمی باشد و به دلیل سوییچ اوت به سرور آرشیو معمولا 3 هفته دیتا موجود می باشد.\r\nبدلیل کند بودن سرور آرشیو و نداشتن ایندکس در جداول امکان گرفتن گزارش وجود ندارد.', 100, 29, NULL, 9, 52, 'تجارت الکترونیک پارسیان', 'پویا عاطفی', '2026-09-19 11:10:00', '2026-09-20 06:55:00', 'low', '2026-09-20 07:06:10', '2026-09-20 07:06:10'),
	(453, 'مستند RKI و مستندات رفاه', 'مستند RKI کامل ترجمه شد ، اصلاحات انجام شد.\r\n4 مستند رفاه بروز شد .', 100, 40, NULL, 2, 38, 'اینتک', 'مهدی ایمنی', '2026-09-21 17:10:00', '2026-09-21 11:20:00', 'medium', '2026-09-22 07:37:42', '2026-09-22 13:27:53'),
	(454, 'ساخت مستند مانیتورینگ و اصلاح مستند رفاه و اتمام RKI', 'مستند مانیتورینگ رفاه ساخته شد .\r\nمستندات رفاه تا حد امکان تصحیح شد.\r\nمستند RKI فهرست درست شد و اصلاحات انجام شد.\r\n', 100, 40, NULL, 2, 38, 'اینتک', 'مهدی ایمنی', '2026-09-22 08:30:00', '2026-09-22 08:30:00', 'medium', '2026-09-22 13:39:42', '2026-09-22 13:39:42');
