	(7, 1, 13, 'سیستم پیام رسان داخلی', 'درود خدمت همکاران عزیز . از قسمت پیام ها می توانید به همکاران داخل شرکت از این پس پیام ارسال کنید .\nباتشکر', 0, 0, 0, '2024-06-29 09:43:38', '2024-06-29 09:43:38'),
	(8, 1, 14, 'سیستم پیام رسان داخلی', 'درود خدمت همکاران عزیز . از قسمت پیام ها می توانید به همکاران داخل شرکت از این پس پیام ارسال کنید .\nباتشکر', 0, 1, 1, '2024-06-29 09:43:38', '2024-10-16 09:29:22'),
	(9, 1, 16, 'سیستم پیام رسان داخلی', 'درود خدمت همکاران عزیز . از قسمت پیام ها می توانید به همکاران داخل شرکت از این پس پیام ارسال کنید .\nباتشکر', 0, 1, 1, '2024-06-29 09:43:38', '2024-10-12 08:39:46'),
	(10, 1, 24, 'سیستم پیام رسان داخلی', 'درود خدمت همکاران عزیز . از قسمت پیام ها می توانید به همکاران داخل شرکت از این پس پیام ارسال کنید .\nباتشکر', 0, 0, 1, '2024-06-29 09:43:38', '2024-12-04 07:24:23'),
	(13, 1, 22, 'درخواست ها', 'با سلام موارد در خواستی انجام شد .', 1, 1, 1, '2024-10-08 10:56:27', '2024-10-12 09:39:43'),
	(15, 28, 9, 'سریال شارژ', '47243000030101860', 1, 1, 1, '2024-10-16 08:56:46', '2024-11-04 10:47:58'),
	(16, 27, 9, 'تیکت 392', 'با درود\nشارژ 100 هزار تومانی همراه اول در تاریخ 7/6/1403 به شماره سریال شارژ 40246000820002996 فروخته شده . مورخ 12/8/1403 همین شماره سریال مجدد برای شماره آقای خالدی 09140855895 به شماره پیگیری تراکنش 271815 و مرجع  845285878359 اختصاص داده شده که رکورد تکراری به کاربر اعلام شده ،  خواهشمند است بررسی فرمایید سریال شارژ 40246000820002996 در چه تاریخ و یا تاریخ هایی از سمت مبتکران به سپ فروخته شده است \n خواهشمند است بررسی و نتیجه را به مشترک اعلام فرمایید .\n', 0, 1, 1, '2024-11-04 10:45:31', '2024-11-04 10:45:43'),
	(17, 22, 7, 'بکافیس', 'اینجا هم فقط پیام چیزی برای ثبت تسک یا تیکت نداره\n', 0, 0, 0, '2026-04-20 07:12:37', '2026-04-20 07:12:37'),
