	(1, 'پیاده سازی چند حسابی', 'با سلام \r\nلطفا زمانبندی پیاده سازی را اعلام فرمایید', '202310-1', 1, 10, 'condition_pendency', 'medium', NULL, '2023-10-08 12:40:05', '2024-10-30 07:47:46', NULL, NULL, NULL),
	(2, 'رفع خطای 03 ', 'با سلام\r\nلطفا زمانبندی رفع خطا را اعلام فرمائید', '202310-2', 1, 10, 'Condition_regect', 'low', NULL, '2023-10-08 12:41:12', '2025-01-27 07:26:57', NULL, NULL, NULL),
	(3, 'پیاده سازی پروژه نفت', 'با سلام\r\nلطفا زمانبندی پیاده سازی را اعلام فرمائید', '202310-3', 1, 10, 'condition_pendency', 'low', NULL, '2023-10-08 12:42:34', '2024-10-30 07:47:46', NULL, NULL, NULL),
	(4, 'پیاده سازی سوب پول', 'با سلام\r\nلطفا زمانبندی پیاده سای را اعلام فرمایید', '202310-4', 1, 10, 'Condition_regect', 'low', NULL, '2023-10-08 12:45:38', '2025-01-27 07:27:24', NULL, NULL, NULL),
	(5, 'گزارش وضعیت موارد صورتجلسه مورخ 06-04-1402', 'لطفا گزارشی از آخرین وضعیت انجام تسک ها اعلام فرمایید و برای مواردی که انجام نشده زمانبندی اعلام فرمایید.', '202310-5', 1, 10, 'Condition_final_done', 'low', NULL, '2023-10-08 12:48:20', '2025-04-23 08:30:39', NULL, NULL, NULL),
	(6, 'پیاده سازی وافینو (باشگاه مشتریان)', 'با سلام\r\nبا توجه به اینکه مستندات مربوطه ارسال شده است لطفا زمانبندی پیاده سازی را اعلام فرمایید ', '202310-6', 1, 10, 'Condition_regect', 'low', NULL, '2023-10-08 12:50:35', '2025-01-27 07:49:28', NULL, NULL, NULL),
	(7, 'پیاده سازی قبض توانیر', 'با سلام با توجه به اینکه مستندات مربوطه ارسال شده است لطفا زمانبندی پیاده سازی را اعلام فرمایید ', '202310-7', 1, 10, 'Condition_archive', 'low', NULL, '2023-10-08 12:51:15', '2024-11-19 06:48:37', NULL, NULL, NULL),
	(8, 'رفع نواقص مستندات سوئیچ ', 'با سلام\r\nلطفا زمانبندی جهت رفع نواقص را اعلام فرمایید.', '202310-8', 1, 10, 'condition_pendency', 'low', NULL, '2023-10-08 13:15:07', '2024-10-30 07:47:46', NULL, NULL, NULL),
	(9, 'API-ADD Card', 'با سلام \r\nلطفا زمانبندی جهت انجام را ارسال فرمایید.', '202310-9', 1, 10, 'Condition_regect', 'low', NULL, '2023-10-08 13:23:53', '2025-01-27 07:54:03', NULL, NULL, NULL),
	(10, 'َAPI-ADD Terminal', 'با سلام \r\nلطفا زمانبندی جهت انجام را ارسال فرمایید.', '202310-10', 1, 10, 'Condition_final_done', 'low', NULL, '2023-10-08 13:24:15', '2025-02-25 13:31:58', NULL, NULL, NULL),
	(11, 'API- ADD تسهیم ', 'با سلام \r\nلطفا زمانبندی جهت انجام را ارسال فرمایید.', '202310-11', 1, 10, 'Condition_regect', 'low', NULL, '2023-10-08 13:24:58', '2025-01-27 07:55:07', NULL, NULL, NULL),
	(12, 'ریورس USSD همراه اول', 'USSD همراه اول اگر verify نشد پس از 15 دقیقه ریورس شود.', '202310-12', 1, 10, 'Condition_regect', 'low', NULL, '2023-10-08 13:28:32', '2025-01-27 07:55:45', NULL, NULL, NULL),
	(13, 'API همراه اول- صدور کارت و شارژ و غیره', 'با سلام\r\nلطفا زمانبندی انجام را اعلام فرمائید.', '202310-13', 1, 10, 'Condition_regect', 'low', NULL, '2023-10-08 13:30:57', '2025-01-27 07:56:18', NULL, NULL, NULL),
	(14, 'پذیرندگی SMS', 'با سلام\r\nلطفا زمانبندی انجام را اعلام فرمایید.', '202310-14', 1, 10, 'Condition_regect', 'low', NULL, '2023-10-08 13:33:44', '2025-01-27 07:58:41', NULL, NULL, NULL),
	(15, 'مغایرت گیری مبتکران', 'با سلام\r\nلطفا زمانبندی رفع مشکل را اعلام فرمایید.', '202310-15', 1, 10, 'Condition_regect', 'low', NULL, '2023-10-08 13:35:34', '2025-01-27 07:58:52', NULL, NULL, NULL),
	(16, 'گزارش‌های زی کارت', 'با سلام \r\nلطفا زمانبندی جهت پیاه سازی را اعلام فرمائید.', '202310-16', 1, 10, 'Condition_regect', 'low', NULL, '2023-10-08 13:37:14', '2025-01-27 07:59:02', NULL, NULL, NULL),
	(17, 'checkstatus charge', 'با سلام\r\nلطفا زمانبندی انجام را اعلام فرمائید.', '202310-17', 1, 10, 'Condition_regect', 'low', NULL, '2023-10-08 13:38:17', '2025-01-27 07:59:13', NULL, NULL, NULL),
	(18, 'آستانه خرید پین', 'با سلام \r\nلطفا زمانبندی پیاده سازی را اعلام فرمایید.', '202310-18', 1, 10, 'Condition_regect', 'low', NULL, '2023-10-08 13:41:38', '2025-01-27 07:59:24', NULL, NULL, NULL),
	(19, 'تست شبای مبتکران 7002', 'با سلام \r\nلطفا زمانبندی انجام را اعلام فرمائید.', '202310-19', 1, 10, 'Condition_regect', 'low', NULL, '2023-10-08 13:42:41', '2025-01-27 07:59:35', NULL, NULL, NULL),
	(20, 'رفع خطای تغییر حساب ترمینال هایی  سوئیچ سیپا بروی سوئیچ اینتک', 'با سلام \r\nنیاز به رفع خطای تغییر حساب ترمینال هایی  سوئیچ سیپا بروی سوئیچ اینتک می باشد.\r\nفایل به آقای محمدی از طریق واتس آپ ارسال شده است.', '202310-20', 1, 10, 'Condition_regect', 'low', NULL, '2023-10-11 06:18:57', '2025-01-27 07:59:44', NULL, NULL, NULL),
	(21, 'تغییر روال تسهیم ', 'با سلام\r\nامکان تعریف تسهیم بصورت ثابت و همچنین امکان تخصیص تسهیم به چند ترمینال وجود داشته باشد.', '202310-21', 1, 10, 'condition_acepted_test_auto', 'low', NULL, '2023-10-11 10:12:02', '2025-04-05 07:28:57', NULL, NULL, NULL),
	(22, 'ایجاد پنل محدود کردن نسخه بروی back office', 'با سلام\r\nامکان غیر فعال کردن و عدم دریافت Log on نسخه بروی back office  ایجاد گردد.', '202310-22', 1, 10, 'Condition_final_done', 'low', NULL, '2023-10-11 10:14:17', '2025-04-23 08:30:59', NULL, NULL, NULL),
	(23, 'سند برگشت کارت هدیه به صندوق', '1- تعیین تکلیف کارت و حساب های اشغال شده\r\n2- رفع مغایرت ایجاد شده در خصوص برگشت مبالغ واریزی به مخزن مالی\r\n', '202310-23', 1, 10, 'Condition_regect', 'low', NULL, '2023-10-11 13:23:56', '2025-01-27 07:59:52', NULL, NULL, NULL),
	(24, 'تغییر کلید کانال 7030 و غیر فعال کردن SSL', 'تغییر کلید کانال 7030 و غیر فعال کردن SSL', '202310-24', 1, 10, 'Condition_final_done', 'low', NULL, '2023-10-14 12:01:46', '2026-02-21 11:59:16', NULL, NULL, NULL),
	(25, 'درخواست امکان ابطال گروهی کارت ها و ثبت سند برگشتی', 'باسلام\r\nبه اطلاع می‌رساند درخواست ابطال گروهی 29 عدد کارت هدیه، در مرحله آخر با موفقیت ثبت نگردید( با انتخاب دکمه ثبت هیچ پیغامی مبنی بر موفق بودن عملیات نمایش داده نشد). \r\n با توجه به نیازمندی ابطال گروهی کارت (همانند نمونه مذکور)  خواهشمند  است امکان ابطال گروهی کارت ها و ثبت سند برگشتی فراهم گردد.\r\n \r\n', '202310-25', 1, 10, 'Condition_final_done', 'low', NULL, '2023-10-14 13:01:30', '2026-02-21 11:59:25', NULL, NULL, NULL),
	(26, 'وب سرویس های سوئیچ دارندگی', 'لطفا مستندات وب سرویس های سوئیچ دارندگی جهت انجام امور مرتبط با کارت (شارژ، صدور، رونوشت و ...) را ارسال نمایید.', '202310-26', 1, 10, 'condition_pendency', 'low', NULL, '2023-10-15 11:05:19', '2024-10-30 07:47:46', NULL, NULL, NULL),
	(27, 'گزارش گیری سامانه صدور کارت', 'خواهشمند است در خصوص موارد ذیل اقدامات مقتضی را مبذول فرمایید:\r\n1. در گزارش شارژ کارت، خروجی گزارش نمایش داده نمی‌شود(پیغام خطایی نمایش داده نمی‌شود)\r\n2. ایجاد گزارش موجودی کل کارت های یک گروه مشتری\r\n3. ایجاد گزارش موجودی کارت های یک گروه مشتری به تفکیک شماره کارت\r\n4. در گزارش تراکنش کارت، فیلتر بر اساس گروه مشتری اضافه گردد.\r\n5. در گزارش تراکنش کارت، در قسمت نوع تراکنش، &quot; شارژ کارت &quot;  اضافه گردد\r\n6.   در گزارش تراکنش کارت، موفق یا ناموفق بودن تراکنش نمایش داده شود\r\n7. در گزارش تراکنش کارت، نام پذیرنده به طور صحیح نمایش داده نمی‌شود.\r\n8. در گزارش تراکنش کارت، با انتخاب شماره کارت گزارش نمایش  داده شده در بک آفیس صحیح می‌باشد ولی در فایل خروجی کلیه کارت ها نمایش داده شده و فیلتر کارت اعمال نمی‌گردد.\r\n9. در گزارش تراکنش کارت، تاریخ تراکنش ها در بک آفیس بصورت شمسی نمایش  داده شده ولی در فایل خروجی تاریخ میلادی نمایش داده می‌شود. در فایل خروجی هم تاریخ شمسی نمایش داده شود.\r\n', '202310-27', 1, 10, 'Condition_final_done', 'low', NULL, '2023-10-15 11:46:32', '2026-02-21 12:00:03', NULL, NULL, NULL),
	(28, 'نمایش وضعیت اشتباه در منو درخواست صدور کارت', ' \r\nباسلام و احترام\r\n \r\nبه اطلاع می‌رساند در منو  درخواست صدور کارت، علی رغم &quot; فعال بودن &quot;  کارت های صادر شده( به عنوان نمونه کارت های صادر شده در تاریخ 24 مهر فعال هستند ولی وضعیت آن‌ها در صفحه درخواست ) ، وضعیت به اشتباه &quot; در انتظار فعالسازی &quot; نمایش داده می‌شود. \r\n', '202310-28', 1, 10, 'Condition_final_done', 'low', NULL, '2023-10-16 08:52:20', '2026-02-21 12:00:11', NULL, NULL, NULL),
	(29, 'مستندات کارت', 'با سلام\r\nمستند کارت جهت افزودن فیچرهای کارت بروی اپلیکیشن سان مورد نیاز می باشد.', '202310-29', 1, 10, 'Condition_final_done', 'low', NULL, '2023-10-17 06:05:55', '2026-02-21 12:00:23', NULL, NULL, NULL),
	(32, 'کد خطا 57 برای 1- کارت هدیه', 'با سلام\r\nبر روی 10 عدد کارت هدیه، تراکنش های  موجودی و خرید با کد خطا 57 مواجه می‌گردید. ', '202310-32', 1, 10, 'Condition_final_done', 'low', NULL, '2023-10-18 04:46:08', '2026-02-21 12:00:29', NULL, NULL, NULL),
	(33, 'عدم اعمال فیلتر تاریخ در گزارش تراکنش کارت', 'در گزارش تراکنش کارت فیلتر تاریخ اعمال نمی‌گردد.', '202310-33', 1, 10, 'Condition_final_done', 'low', NULL, '2023-10-18 04:49:38', '2026-02-21 12:00:36', NULL, NULL, NULL),
	(34, 'عدم نمایش صحیح موجودی کارت', 'موجودی کارت  6274129810000003 صحیح نمایش داده نمی شد.', '202310-34', 1, 10, 'Condition_final_done', 'low', NULL, '2023-10-18 07:59:48', '2026-02-21 12:00:41', NULL, NULL, NULL),
	(35, ' فیلد 54 بروی پورت 4090- افزودن مانده واقعی', ' فیلد 54 بروی پورت 4090- افزودن مانده واقعی', '202310-35', 1, 10, 'Condition_final_done', 'low', NULL, '2023-10-21 10:01:28', '2026-02-21 12:00:46', NULL, NULL, NULL),
	(36, 'عدم امکان غیرفعال سازی کارت', 'در منو عملیات گروهی کارت زیر منو غیر فعال سازی کارت، ثبت درخواست از طریق پنل و بارگذاری فایل امکان پذیر نبود.', '202310-36', 1, 10, 'Condition_final_done', 'low', NULL, '2023-10-22 12:13:13', '2026-02-21 12:00:52', NULL, NULL, NULL),
	(37, 'تخصیص شماره حساب جدید به سوئیچ کارت', 'باسلام و احترام \r\nبنا به درخواست واحد مالی مبنی بر اختصاص شماره حساب 2-165000-850-176 شعبه سرو غربی کد 176 به سوئیچ کارت،\r\nاقدامات مقتضی را مبذول فرمایید.\r\n', '202310-37', 1, 10, 'Condition_final_done', 'low', NULL, '2023-10-24 07:43:20', '2026-02-21 12:01:02', NULL, NULL, NULL),
	(38, 'شماره کارت تکراری زی کارت', 'با صدور کارت با الگوی زی کارت، به ازا هر شخص دو عدد کارت با شماره یکسان ایجاد می‌گردد. (تصویر این مورد برای خانم فلاح زاده ارسال گردیده است)\r\nطبق فرمایش خانم فلاح زاده صدور کارت با الگو زی کارت تا زمان رفع مشکل می‌بایست متوقف گردد.\r\nبا توجه به فوریت صدور دو عدد زی کارتی که در تاریخ 01-08-1402 تعریف شده است، خواهشمند است جهت رفع این مشکل راهکار ارائه بفرمایید.\r\n', '202310-38', 1, 10, 'Condition_final_done', 'low', NULL, '2023-10-24 07:50:11', '2026-02-21 12:01:15', NULL, NULL, NULL),
	(39, 'عدم نمایش پیغام صحیح در منو تمدید/رونوشت کارت', 'در منو &quot; تمدید/رونوشت کارت &quot;  با فعال سازی شناسه درخواست 130 (بن کارت پرسنل پرداخت نوین) پیغام کارت هدیه با موفقیت صادر شد نمایش داده شد در صورتی که کارت های مذکور بن کارت می‌باشند.', '202310-39', 1, 10, 'Condition_final_done', 'low', NULL, '2023-10-24 07:53:23', '2026-02-21 12:01:24', NULL, NULL, NULL),
	(40, 'درخواست های بک آفیس صادرکنندگی', 'خواهشمند است در خصوص موارد ذیل اقدامات مقتضی را مبذول فرمایید:\r\n1.	گزارشی مبنی بر نمایش تاریخچه کارت (زمان مسدود شدن، زمان صدور المثنی، زمان صدور رمز المثنی، و ....) ایجاد گردد.\r\n2.	پس از بارگذاری فایل صدور کارت در صورت اینکه کد ملی موجود در فایل جدید در سیستم کارت فعال و یا کارت مسدود د اشته باشد پیغامی نمایش داده شود و بسته به انتخاب کاربر امکان  صدور کارت جدید برای شخص مذکور فراهم گردد. \r\n3.	در فایل چاپ کارت مقابل هر شماره کارت مبلغ هم نمایش داده شود.\r\n', '202310-40', 1, 10, 'Condition_final_done', 'low', NULL, '2023-10-28 09:05:10', '2026-02-21 12:01:33', NULL, NULL, NULL),
	(41, 'درخواست view لیتر از دیتابیس سوییچ پذیرندگی', 'View ای از دیتابیس سوییچ پذیرندگی با فیلدهای زیر ایجاد گردد.\r\n1.	TerminalId\r\n2.	MerchantId\r\n3.	TransactionDate\r\n4.	Iban\r\n5.	TotalAmount\r\n6.	TashimAmount\r\n7.	Rrn\r\n8.	ProcessType\r\n9.	StoreName\r\n10.	Status\r\n11.	Status_Description\r\n12.	ShenaseKharid\r\n13.	ResponseCode\r\n', '202310-41', 1, 10, 'Condition_final_done', 'low', NULL, '2023-10-28 09:07:48', '2026-02-21 12:01:42', NULL, NULL, NULL),
	(42, 'پیاده سازی موارد مرتبط با شیوه نامه صدور کارت برداشت ریالی اشخاص حقوقی', 'با سلام\r\nاحتراما پیرو ابلاغ &quot;شیوه نامه صدور کارت برداشت ریالی اشخاص حقوقی&quot; توسط بانک مرکزی به تمامی بانک ها و موسسات اعتباری اعلام شده است که حداکثر سقف تراکنش (خرید، انتقال وجه و پرداخت قبض)\r\nکارت‌های برداشت ریالی اشخاص حقوقی معادل سه برابر سقف‌ های متناظر در کارت های عادی مربوط به اشخاص حقیقی می باشد. \r\nهمچنین آستانه تراکنش های روزانه این دسته از کارتها نیز معادل سه برابر آستانه های مقرر در مورد اشخاص حقیقی می باشد. بر این اساس ضروری است شرکت ها نسبت به مستثنی نمودن کد محصول مربوط به\r\nاین گروه از کارت ها (کد محصول 88  در گروه محصولات Debit) از سقف های متعارف روی سوئیچ خود اقدامات لازم را به قید فوریت انجام دهند. \r\nلذا خواهشمند است در خصوص پیاده سازی مورد مذکور اقدامات لازم را مبذول فرمایید. \r\nفایل های مرتبط ایمیل شده است', '202310-42', 1, 10, 'Condition_final_done', 'low', NULL, '2023-10-28 11:18:41', '2026-02-21 12:02:09', NULL, NULL, NULL),
	(43, 'view دیتابیس از مقدار مخازن پین', 'با سلام\r\nخواهشمند است view دیتابیس از مقدار مخازن پین را ایجاد نمایید.', '202310-43', 1, 10, 'Condition_final_done', 'low', NULL, '2023-10-29 06:46:09', '2026-02-21 12:02:19', NULL, NULL, NULL),
	(44, 'درخواست لیست کاربران با شماره موبایل  9999999999', ' با سلام \r\nلیست کاربرانی که شماره موبایل شان در سوییچ صادرکنندگی 9999999999 ثبت گردیده است، ارائه گردد.', '202310-44', 1, 10, 'Condition_final_done', 'low', NULL, '2023-10-29 10:52:57', '2026-02-21 12:02:28', NULL, NULL, NULL),
