	(740, 'درخواست اجرای Job برای نام کاربری قبضینو', 'باسلام و احترام\r\nخواهشمند است صندوق تخصیص داده شده به نام کاربری ghabzino ، هر شب تا سقف مبلغ 2 میلیارد تومان ( مبلغ شارژ صندوق به گونه ای باشد که موجودی صندوق هر شب 2 میلیارد باشد) ،شارژ گردد.\r\nباسپاس', '202503-740', 1, 25, 'Condition_do_action', 'high', NULL, '2025-03-08 10:10:11', '2025-03-08 12:27:08', NULL, NULL, NULL),
	(741, 'روت ترمینال های تستی پروژه جانبازان', ' با سلام و  احترام\r\nخواهمشند است ترمینال های لیست ضمیمه بروی کانال تستی روت شود\r\n\r\nبا تشکر\r\n', '202503-741', 3, 10, 'Condition_final_done', 'medium', NULL, '2025-03-08 10:16:59', '2025-04-23 08:18:53', NULL, NULL, NULL),
	(742, 'تغییر د سوئیچ ترمینال 11544190 از 3 به 7', 'با سلام و احترام\r\nخواهشمند است کد سوئیچ ترمینال 11544190 از 3 به 7 تغییر یابد\r\nبا تشکر', '202503-742', 3, 10, 'Condition_final_done', 'medium', NULL, '2025-03-08 11:42:54', '2025-03-10 08:07:05', NULL, NULL, NULL),
	(743, 'دسترسی ', 'لطفا دسترسی انتقال به  خرید اینترنتی شارژ و ..... برای دسترسی ایجاد قابلیت ایجاد   گردد .\r\nجهت هماهنگی 09351003290', '202503-743', 3, 34, 'Condition_final_done', 'medium', NULL, '2025-03-08 12:06:22', '2025-04-23 08:18:46', NULL, NULL, NULL),
	(744, 'دسترسی جانبازان', 'با سلام و احترام\r\nخواهشمند است برای نام کاربری janbazan دسترسی های ذیل به گونه ای اعمال گردد که تنها نام کاربری مذکور قادر به مشاهده کارت های گروه &quot; مجازی_ کارت خرید فروشگاه جانبازان &quot; باشد:\r\nشایان ذکر است برای نام کاربری مذکور نقش &quot; janbazan &quot; ایجاد شده است.\r\n1. جستجوی کارت\r\n2.صدور رمز اول\r\n3.گزارش تراکنش کارت\r\nباسپاس', '202503-744', 1, 25, 'Condition_final_done', 'high', NULL, '2025-03-09 06:43:49', '2025-04-23 08:18:37', NULL, NULL, NULL),
	(745, 'لید مک لاگان برای کلیدگذاری نسخه RKI', 'با سلام\r\nخواهشمند است کلید مک لاگان برای کلیدگذاری نسخه RKI رفاه را ایمیل فرمایید \r\n\r\nبا تشکر\r\n', '202503-745', 3, 10, 'Condition_final_done', 'high', NULL, '2025-03-09 07:57:41', '2026-02-21 11:54:05', NULL, NULL, NULL),
	(746, 'عدم  امکان ویرایش نقش در بک افیس جدید', 'با سلام\r\nدر بک افیس در بخش امنیت امکان ویرایش نقش وجود ندارد\r\n', '202503-746', 3, 10, 'condition_in_progress', 'high', NULL, '2025-03-09 08:57:42', '2025-03-18 05:39:09', NULL, NULL, NULL),
	(747, 'افزودن مارکت جانبازان', 'باسلام و احترام\r\nخواهشمند است به کارت های صادر شده در درخواست صدور کارت با شناسه 721 ، مارکت &quot; فروشگاه جانبازان &quot; تخصیص داده شود.\r\nباسپاس', '202503-747', 1, 25, 'Condition_final_done', 'high', NULL, '2025-03-09 09:39:14', '2026-02-21 11:53:52', NULL, NULL, NULL),
	(748, 'عدم اعمال مارکت', 'باسلام و احترام\r\nپیرو پیاده سازی مارکت بر روی بک آفیس صادرکنندگی، مقرر شده بود کارت های تعریف شده بر روی مارکت مورد نظر تنها بر روی پایانه های تعریف شده مارکت قابلیت انجام تراکنش  داشته باشند و بر روی سایر ترمینال ها تراکنش صورت نگیرد.\r\nبر روی پایانه غیر مارکت تراکنش &quot; موجودی &quot; نیز اعمال نگردد.\r\nباسپاس', '202503-748', 1, 25, 'Condition_final_done', 'high', NULL, '2025-03-09 12:03:22', '2026-02-21 11:53:38', NULL, NULL, NULL),
	(749, 'کلید جدید برای کانال رفاه', 'با سلام و احترام\r\nخواهشمند است کلید جدید ضمیمه شده بروی کانال رفاه ست شود و فیلد 53 نیز ارسال گردد.\r\n', '202503-749', 3, 10, 'Condition_final_done', 'high', NULL, '2025-03-09 12:55:06', '2025-04-23 08:16:58', NULL, NULL, NULL),
	(750, 'نیازمندی پروژه کارت‌های مجازی', 'باسلام و احترام\r\nخواهمشند است موارد ذیل پیاده سازی گردد:\r\n 1. یک currency مجازی ( 999 ) ایجاد گردد. \r\n2. ایجاد صندوق مجازی با حساب مجازی \r\n3. شارژ صندوق مجازی تنها توسط واحد مالی پرداخت نوین با currency مجازی صورت گیرد\r\n 4. شارژ کارت ها توسط نام کاربری janbazan امکان پذیر باشد\r\n 5. دشارژ کارت ها توسط نام کاربری janbazan امکان پذیر باشد. در فاز اولیه انجام برگشت از واریز امکان پذیر گردد. در فاز دوم برداشت مبلغ باقیمانده در کارت، امکان پذیر گردد.\r\n 6. این پروژه تنها بر روی گروه کارت &quot; مجازی_ کارت خرید فروشگاه جانبازان &quot; اجرا می‌گردد. \r\n7. رنج سریال های کارت های مجازی 627412449950000 تا 627412449999999 می‌باشد\r\n8.در صورت ناموفق بودن تراکنش ( کسر مبلغ از کارت مجازی)، مبلغ سند برگشت به حساب کارت برگردد(مبلغ به حساب صندوق مجازی برگشت زده نشود)\r\n9.کلیه پیامک هایی که برای سایر بن کارت ها ارسال می‌گردد. برای کارت های مجازی نیز ارسال گردد. عنوان &quot; سگمنت مجازی &quot; در متن پیامک قرار داده شود.\r\n10. کلیه گزارشات به جز گزارش رسوب برای کارت های مجازی نیز ایجاد گردد.\r\nباسپاس', '202503-750', 1, 25, 'condition_in_progress', 'high', NULL, '2025-03-09 13:59:02', '2025-03-10 09:35:01', NULL, NULL, NULL),
	(751, 'درخواست شماره حساب و موجودی کارت', 'باسلام و احترام\r\nخواهشمند  است شماره حساب کارت های فایل پیوست به همراه موجودی آن ها ارسال گردد.\r\nباسپاس', '202503-751', 1, 25, 'Condition_final_done', 'high', NULL, '2025-03-09 14:06:59', '2026-02-21 11:53:25', NULL, NULL, NULL),
	(752, 'امکان تعریف شبا تکراری در صورتی که مشتری و ترمینال فعالی نداشته باشد', '\r\nبا سلام و احترام\r\n\r\nطبق مذاکرات صورت گرفته با اینتک وقتی که یک شماره شبا مشتری و ترمینال فعال نداشته باشد امکان تعریف همان شماره شبا برای کد مشتری جدید بلا اشکال است در حالی که طبق فرموده خانم شریفی برای تعریف مجدد شماره شباهای &#039;IR770150000001624800139608&#039;, &#039;IR810190000000216892458008&#039; با وجود غیرفعال بودن مشتری و ترمینال خطای شماره شبا تکراری میباشد دریافت میگردد.\r\n\r\nلطفا از پشتیبانی اینتک درخواست کنید این مورد را بررسی کنند. \r\n\r\nضمنا بنده ایمیلی به همین مضمون و به همراه شماره شباها برای جناب محمدی ارسال کرده ام.', '202503-752', 1, 31, 'Condition_final_done', 'high', 0, '2025-03-10 04:53:09', '2026-02-22 13:19:52', NULL, NULL, NULL),
	(753, 'پکیجر کانال 7050 مشابه کانال تستی', 'با سلام\r\nخواهشمند است پکیجر کانال 7050 مشابه کانال تستی (نود 101) شود.\r\nبا تشکر', '202503-753', 3, 10, 'Condition_final_done', 'medium', NULL, '2025-03-10 12:08:18', '2025-04-23 08:16:13', NULL, NULL, NULL),
	(754, 'غیر فعال کردن ترمینال ها', 'با سلام و احترام\r\nخواهشمند است ترمینالهای لیست ضمیمه در اسرع وقت غیر فعال گردد\r\nبا تشکر', '202503-754', 3, 10, 'Condition_final_done', 'high', NULL, '2025-03-11 08:04:53', '2025-04-23 08:15:29', NULL, NULL, NULL),
	(755, 'مغایرت در اطلاعات هویتی و پیگیری قضائی', 'با سلام، به اسـتحضار می رسانـد، با توجه به دریافت گزارشاز سامانه اینتک دارندگی بمنظور پاسـخگویی به دسـتورات مقام محترم قضایی، شاهـدیک باگ در سیسـتم مذکور می باشـیم؛ ازطرفی با توجه به بررسـی بعمل آمده مشـخص شدکه با یک شـماره\r\nکـارت، شـماره موبایـل هـاي متفـاوتی که ارتباطی با دارنـده نـدارد نمایش داده می شود، مع الوصف درصورتیکه این باگ درمـدت کوتـاهی مرتفـع نشـود شاهـد ارائه اطلاعـات اشـتباه به مراجع قضـایی درخواست کننـده خواهیم بودکه می توانـد تبعـات جبران ناپذیري ازجمله حقوقی وکیفري براي شـرکت در پی داشـته باشد. لذا مستدعی است دستور فرمائیدبا قیدفوریت نسبت به رفع مشـکل مزبور اقدام شایسته بعمل آید. مع هذا یک نمونه ازگزارش خروجی دریافتی تراکنش جهت بررسی حضورتان ارسال می گردد.خاطر نشان می سازد این مورد بارها برای شرکت اینتک تیکت شده است مانند تیکت 202412-526 . با تشکر.\r\n', '202503-755', 8, 36, 'Condition_final_done', 'high', NULL, '2025-03-11 11:54:29', '2025-04-23 08:15:22', NULL, NULL, NULL),
	(756, 'عدم برداشت بیش از 100 هزار', 'با سلام و احترام\r\nاین دو شماره کارت امکان برداشت بیش از 100 هزار تومان را ندارد.\r\n5057853100681595\r\n5057853100659955\r\nجهت هماهنگی با اقای غربی به شماره 09351003290 تماس حاصل فرمایید.\r\nبا سپاس', '202503-756', 3, 34, 'condition_acepted_test_auto', 'medium', NULL, '2025-03-11 12:02:25', '2026-10-07 16:08:21', NULL, NULL, NULL),
	(757, 'دریافت خطای 500 در فراخوانی وب سرویس TMS', 'با درود\r\nلاگ ضمیمه می باشد ، برای جناب آقای محمدی ارسال گردد\r\nhttp://172.31.14.60/NewApiServices/api/TmsTerminal\r\nبا تشکر', '202503-757', 1, 31, 'Condition_final_done', 'low', NULL, '2025-03-11 13:41:16', '2026-02-22 13:19:48', NULL, NULL, NULL),
	(758, 'سرور های سخت افزاری LOM  - سایت پشتیبان', 'با سلام و احترام\r\n\r\nدر خصوص راه اندازی سرور های سایت پشتیبان در محل دیتا سنتر پردیس ، خواهشمند است دستور فرمایید LOM سرور های سخت افزاری در خصوص راه اندازی سرویس های پردازنده ، فورواردر و پایگاه داده برای اینجانب ارسال گردد./\r\n\r\nبا تشکر\r\n', '202503-758', 1, 31, 'Condition_regect', 'low', NULL, '2025-03-11 13:48:43', '2025-05-03 08:41:59', NULL, NULL, NULL),
	(759, 'عدم بروزرسانی فیلد منقضی کارت', 'باسلام و احترام\r\nبه اطلاع می رساند برای کارت هایی که تاریخ انقضا آن ها Expire شده است، مقدار فیلد &quot; منقضی  &quot; خیر می باشد.\r\nخواهشمند است مقدار فیلد &quot; منقضی  &quot;  اصلاح گردد.\r\nباسپاس', '202503-759', 1, 25, 'Condition_final_done', 'low', NULL, '2025-03-12 08:06:53', '2026-02-21 11:53:19', NULL, NULL, NULL),
	(760, 'لیست پایانه های جانبازان', 'باسلام و احترام\r\nخواهشمند است کارت های مارکت فروشگاه جانبازان،  تنها برای روی پایانه های فایل پیوست امکان انجام تراکنش &quot; موجودی  &quot; را داشته باشند.\r\nباسپاس', '202503-760', 1, 25, 'condition_acepted_test_auto', 'high', NULL, '2025-03-12 10:37:19', '2026-05-10 14:58:14', NULL, NULL, NULL),
	(761, 'مشکل در دریافت پیکربندی ترمینال 70000910', 'با سلام و احترام،\r\n\r\nبه استحضار می‌رساند ترمینال با شماره 70000910 با مشکل دریافت پیکربندی مواجه شده است. شایان ذکر است که رمز OTP چندین بار وارد شده و حتی سریال جدید نیز به این ترمینال تخصیص داده شده، اما مشکل همچنان پابرجاست.\r\n\r\nخواهشمند است دستور فرمایید موضوع در اسرع وقت بررسی و نتیجه اقدامات انجام‌شده به این واحد اعلام گردد.\r\n\r\nبا سپاس فراوان،\r\nمحمد علی غریبی', '202503-761', 3, 26, 'Condition_final_done', 'high', NULL, '2025-03-12 12:37:26', '2025-04-23 08:35:05', NULL, NULL, NULL),
	(762, 'خطای 2 پایانه 14824917', 'با سلام و احترام\r\nپایانه 14824917 دارای خطای 2 میباشد.\r\nبا سپاس', '202503-762', 3, 34, 'Condition_final_done', 'medium', NULL, '2025-03-15 06:34:52', '2025-04-23 08:15:09', NULL, NULL, NULL),
	(763, 'پیغام خطا در فرمت فایل در زمان بارگذاری فایل صدور', 'باسلام و احترام\r\nدر زمان بارگذاری فایل صدور ، پیغام خطا در فرمت فایل نمایش داده میشود.\r\nفایل به پیوست ارسال می‌گردد.\r\nباسپاس', '202503-763', 1, 25, 'Condition_final_done', 'high', NULL, '2025-03-15 07:00:04', '2026-02-21 11:53:03', NULL, NULL, NULL),
	(764, 'خطای 2 پایانه 14803798', 'با سلام و احترام\r\nپایانه 14803798 دارای خطای 2 میباشد\r\nبا سپاس', '202503-764', 3, 34, 'Condition_final_done', 'medium', NULL, '2025-03-15 07:24:57', '2025-04-23 08:15:03', NULL, NULL, NULL),
	(765, 'ایجاد رمز یکسان-SR405871', 'با سلام خواهشمند است دستور فرمایید شماره تقاضاهای که در ذیل اعلام می شود رمز اول و رمز دوم به 1606 تغییر یابد. باتشکر\r\n606281 و 606285 و 606287 و 606289', '202503-765', 8, 36, 'Condition_final_done', 'high', NULL, '2025-03-15 07:27:24', '2025-04-23 08:32:52', NULL, NULL, NULL),
	(766, 'گزارش کارت های صادر شده شارژ نشده', 'باسلام و احترام\r\nخواهشمند است گزارش شماره کارت هایی که صادر شده اند ولی شارژی برای آن ها صورت نگرفته است، را ارسال بفرمایید.\r\nباسپاس', '202503-766', 1, 25, 'Condition_final_done', 'high', NULL, '2025-03-15 09:32:00', '2026-02-21 11:52:58', NULL, NULL, NULL),
	(767, 'افزودن قبضینو به ماژول شارژ', 'باسلام و احترام\r\nخواهشمند است برای فیلد ChargeModule متد CustomerChargeCard ، مقدار &quot; قبضینو &quot;  اضافه گردد.\r\nباسپاس', '202503-767', 1, 25, 'Condition_final_done', 'high', NULL, '2025-03-15 10:03:04', '2026-02-21 11:52:50', NULL, NULL, NULL),
	(768, 'گزارش خطاهای سوییچ 1403/12/20', 'با سلام و احترام\r\nگزارش خطاهای سوییچ جهت جلوگیری از بروز مجدد خطا ها و ارائه گزارش ارسال می گردد.\r\n\r\nبا سپاس\r\n', '202503-768', 3, 10, 'Condition_final_done', 'medium', NULL, '2025-03-16 06:22:50', '2026-02-21 11:52:41', NULL, NULL, NULL),
	(769, 'حذف شبای تکراری که سوئیچ برای شاپرک ارسال می کند', 'ا سلام و احترام\r\nبرای تعدادی از ترمینال ها که دارای چندحسابی(مولتی) می باشند تراکنش ها دارای خطا 03 (6205-کدشبای ارسالی برای این پذیرنده فروشگاهی تعریف نشده است)می دهد ضمنا پشت ترمینال سرویس پرداخت(دارای مدل تسویه )فعال میباشد و شبای چندحسابی در تراکنش چندمرتبه نمایش می دهد که خطا به پیوست میباشد\r\nخواهشمند است بررسی نمایید. لازم به توضیح است برای ترمینال های پیوست شده شبای IR100190000000218740218009 دابل برای پیذیرنده تکرار شده است که احتملا دلیل بروز خطا می باشد\r\n\r\nخواهشمند است شبای تکراری را برای ترمینال ها حذف نمایید\r\nترمینال نمونه:\r\n14634086 \r\n14634087 \r\n14756082 \r\n14756083 \r\n14756086', '202503-769', 1, 31, 'Condition_final_done', 'high', NULL, '2025-03-16 06:42:52', '2026-02-22 13:19:43', NULL, NULL, NULL),
	(770, 'مشکل سرویس مدل تسهیم و تخفیف - SaveSettlement ', 'با سلام و احترام\r\nطبق مستند آن شرکت محترم، سرویس SaveSettlement ، برای درج/ویرایش مدل تسهیم و تخفیف مورد استفاده قرار می گیرد. ولی در هنگام ارسال درخواست ویرایش (غیر فعال شدن) شماره شباها (مطابق تصویر پیوست) خطای &quot;شماره شبا از قبل در تسهیم تعریف شده است&quot; مشاهده می‌گردد.\r\nبه نظر می‌رسد این سرویس برای ویرایش شباهای از قبل تعریف شده دچار مشکل می‌گردد.\r\nخواهشمند است اقدام فوری در این خصوص مبذول فرمایید.', '202503-770', 1, 43, 'Condition_final_done', 'medium', NULL, '2025-03-16 08:30:37', '2026-02-22 13:51:58', NULL, NULL, NULL),
	(771, 'فعال سازی ترمینال ها', 'با سلام و احترام\r\nخواهشمند است ترمینالهای ضمیمه در اسرع وقت فعال گردد.\r\nبا تشکر', '202503-771', 3, 10, 'Condition_final_done', 'high', NULL, '2025-03-16 08:52:49', '2025-04-23 08:14:59', NULL, NULL, NULL),
	(772, 'درخواست گزارش پتروشیمی گچساران', 'باسلام و احترام \r\nخواهشمند است اطلاعات گروه مشتری پتروشیمی گچساران شامل:  کد ملی ، شماره کارت، نام و نام خانوادگی و شماره موبایل ارسال گردد.\r\nباسپاس', '202503-772', 1, 25, 'Condition_final_done', 'high', NULL, '2025-03-17 08:46:24', '2025-04-23 08:14:48', NULL, NULL, NULL),
	(773, 'خطای 96 برخی از ترمینالها', 'با سلام\r\nترمینال های زیر بعد از پیکربندی خطای 96 دریافت می کند.\r\nتراکنش بروی پورت 4050 انجام میشود.\r\n30035426\r\n30580734', '202503-773', 3, 10, 'Condition_final_done', 'high', NULL, '2025-03-17 10:27:19', '2025-04-23 08:14:11', NULL, NULL, NULL),
	(774, 'عدم امکان ویرایش اطلاعات کاربر (در بخش  امنیت - کاربران) در بک آفیس جدید', 'با سلام \r\nدر بک افیس  امکان ویرایش اطلاعات کاربر در بخش  امنیت - کاربران وجود ندارد\r\n', '202503-774', 3, 10, 'Condition_final_done', 'medium', NULL, '2025-03-17 11:20:49', '2025-04-05 11:55:45', NULL, NULL, NULL),
	(775, 'اصلح و نمایش صحیح نام فروشگاه در گزارش تراکنش دارنده کارت ', 'با سلام، با عنایت به فایل های پیوست برای نمونه  شماره پایانه 83257067 در &quot;گزارش تراکنش کارت&quot; نام فروشگاه درست نمایش داده می شود در حالی برای همین پایانه در &quot;گزارش تراکنش دارنده کارت&quot; نام فروشگاه از چپ به راست نمایش داده شده است. لذا خواهشمند است برای اصلاح  &quot;گزارش تراکنش دارنده کارت&quot; در منوی گزارشات مالی اقدامات لازم را مبذول نمایید. با سپاس ', '202503-775', 8, 36, 'Condition_final_done', 'high', NULL, '2025-03-25 11:29:38', '2026-02-22 13:52:19', NULL, NULL, NULL),
	(776, 'خطای 58 داخلی در تراکنش موجودی و پیکربندی تغییر حساب ترمینال 14706032', 'با درود\r\nترمینال 14706032 با اینکه پیکربندی را موفق دریافت کرده است اما با اینکه تیک موجود را در مجوز ترمینال دارد با خطای 58 در موجودی و خطای 03 دالخی در تغییر حساب مواجه می شود\r\nلاگ وب سرویس تعریف ترمینال ضمیمه است که در هنگام ویرایش سمت اینتک با اینکه شبای ارسال تعریف شده است اما پاسخ شبا متعلق به اینت پذیرنده نمی باشد ارائه شده است', '202503-776', 3, 31, 'Condition_final_done', 'medium', NULL, '2025-03-26 08:38:17', '2026-02-22 13:19:31', NULL, NULL, NULL),
	(777, 'افزودن امکان جستجوی پایانه بر اساس کد ملی', 'با سلام\r\nخواهشمند است امکان جستجوی پایانه بر اساس کد ملی در بک آفیس جدید ایجاد گردد.\r\nبا تشکر', '202504-777', 3, 10, 'condition_in_progress', 'low', NULL, '2025-04-05 09:22:10', '2025-04-20 13:08:18', NULL, NULL, NULL),
	(778, 'عدم امکان ویرایش نقش در بخش سطح دسترسی', 'با سلام \r\nدر بخش امنیت- نقش ها\r\n امکان ویرایش نقش در بخش سطح دسترسی وجود ندارد  و تغییرات اعمال نمیگردد.', '202504-778', 3, 10, 'Condition_final_done', 'low', NULL, '2025-04-05 09:24:50', '2026-02-21 11:52:30', NULL, NULL, NULL),
	(779, 'عدم امکان فعال یا غیر فعالسازی ترمینال', 'با سلام\r\nامکان فعال یا غیر فعالسازی ترمینال وجود ندارد.\r\nچه با کلیک راست و استفاده از گزینه فعال/غیر فعال\r\nچه با استفاده از گزینه ویرایش (مشاهده پیغام شماره شبا یافت نشد)', '202504-779', 3, 10, 'Condition_final_done', 'medium', NULL, '2025-04-05 09:35:03', '2025-04-23 08:14:04', NULL, NULL, NULL),
	(780, 'ایجاد مغایرت تراکنش ها بعد از رخداد 14 فروردین برای پایگاه داده (موارد به شکل مثال ذکر شده است)', 'با درود\r\nبرای تعدادی از تراکنش ها مطاق با اعلام دارنده کارت، با اینکه تراکنش دارای رسید ناموفق هستند و تراکنش برگشت سمت مرکز نیز موجود است، تراکنش به عنوان تراکنش موفق در فرم 9 شرکت اینتک در (SP)  SP B2STxn.dbo.GenerateSuccessTxn_Sep وجود دارد\r\nفلگ وضعیت برگشت تراکنش نیز تنظیم نشده است کد مرجع : 849574719072 تاریخ 2025-04-03 11:57:19\r\n\r\nبرای برخی دیگر از تراکنش ها با اینکه تراکنش برگشت سمت مرکز وجود دارد تکرار شده است و پاسخ سوئیچ 09 بوده است ، اما به اشتباه تراکنش تسویه ساید 2 توسط سوئیچ برای شاپرک ارسال شده است\r\nمثال : 849574306042 تاریخ 2025-04-03 11:42:21\r\n\r\nبرای هر 2 مثال بالا به جای آنکه پول به حساب دارنده کارت برگشت شود، پول به حساب پذیرنده واریز شده است\r\n\r\nدر خصوص مثال اول تراکنش نمی بایست در SP تراکنش های موفق اعلام می شده است، تراکنش های موفق اعلامی در فرم 9 درج شده و برای واریز به حساب پذیرنده به شاپرک اعلام می شود\r\nدر خصوص مثال دوم، تراکنش دارای تراکنش برگشت بوده است و ارسال تسویه ساید 2 توسط جاب سوئیچ اشتباه بوده است\r\n\r\nلطفا مساعدت فرمایید', '202504-780', 3, 31, 'Condition_final_done', 'high', NULL, '2025-04-05 09:51:37', '2026-02-22 13:19:26', NULL, NULL, NULL),
	(781, 'عدم حذف رمز دوم', 'باسلام و احترام\r\nدر منو درخواست صدور کارت، در صورت که گزینه &quot; حذف رمز دوم از فایل چاپ کارت &quot; انتخاب گردد بر روی فایل چاپ رمز همچنان رمز دوم نمایش داده میشود.\r\nباسپاس', '202504-781', 1, 25, 'Condition_final_done', 'high', NULL, '2025-04-05 09:57:53', '2025-05-18 08:06:53', NULL, NULL, NULL),
	(782, 'عدم اعمال تغییر حساب بروی سوئیچ اینتک', 'با سلام \r\nترمینال ۱۱۷۶۶۸۶۷ در سامانه  تغییرحساب اعمال شده است ولی در سوییچ اینتک همچنان جهت انجام تراکنش ها، حساب قبلی معیار قرار میگیرد و دستگاه خطای ۰۳ می دهد .\r\n\r\n', '202504-782', 3, 10, 'Condition_final_done', 'high', NULL, '2025-04-05 09:58:46', '2026-02-21 11:51:26', NULL, NULL, NULL),
	(783, 'غیرفعال سازی ترمینال های ارسالی 04-01-16', 'با سلام و احترام\r\nخواهشمند است پایانه های لیست ارسالی در اسرع وقت غیر فعال گردد.\r\nبا تشکر\r\n', '202504-783', 3, 10, 'Condition_final_done', 'medium', NULL, '2025-04-05 10:54:48', '2025-04-23 08:12:51', NULL, NULL, NULL),
	(784, 'تغییر کلید شرکت پرداخت نوین دوشنبه 18/01/1404 از ساعت  6:30 صبح', 'باسلام و احترام\r\n      باتوجه به اعلام شرکت شاپرک باستحضار میرساند، تغییر کلید شرکت پرداخت نوین دوشنبه 18/01/1404 از ساعت  6:30 صبح انجام خواهد شد، لذا خواهشمند است اقدامات لازم در این خصوص صورت گیرد. \r\nرمز فایل از خانم کمایی دریافت گردد.\r\nباتشکر\r\n', '202504-784', 3, 10, 'Condition_final_done', 'high', NULL, '2025-04-05 11:15:58', '2026-02-21 11:51:08', NULL, NULL, NULL),
	(785, 'چاپ رمز یک بار مصرف', 'با سلام و احترام، \r\nخواهشمند است نسبت به ایجاد رمز یکسان برای تقاضاهای 606743 - 606848 مساعدت فرمایید.\r\nرمز اول تمامی کارت ها: 2318\r\nرمز دوم تمامی کارت ها: 23180\r\nبا تشکر\r\n', '202504-785', 8, 36, 'condition_acepted_test_auto', 'high', NULL, '2025-04-06 07:48:59', '2026-10-07 16:08:21', NULL, NULL, NULL),
	(786, 'تغییر پورت دیتابیس دارندگی', 'باسلام و احترام\r\nطبق اعلام شاپرک پورت دیتابیس دارندگی می بایست تغییر یابد. (نباید پورت پیش فرض استفاده شود)\r\nدر حال حاضر پورت پیش فرض به دیتابیس دارندگی تخصیص داده شده است.\r\nباسپاس', '202504-786', 1, 25, 'condition_acepted_test_auto', 'low', NULL, '2025-04-06 08:39:41', '2026-03-25 08:43:38', NULL, NULL, NULL),
	(787, 'افزایش زمان پاسخ گویی در فراخوانی وب سرویس های پلاگین توسط سوئیچ ند 30', 'با درود\r\nسرویس پرداخت ها توسط سوئیچ اینتک از روز نود 30 فراخوانی می گردد، بیشترین زمان انتظار جهت دریافت پاسخ از جانب سوئیچ از آنجایی که از طریق لاگ مشخص است 1 دقیقه است، این موضوع در شرایطی است که برای اکثر حداکثر زمان در انتظار بیشتر از 1 دقیقه زمان نیاز است،\r\nدستور فرمایید زمان مربوطه بیشتر از 1 دقیقه باشد \r\n\r\n[SepPluginWrapper] Validate INewServicePayment...\r\nThe request channel timed out attempting to send after 00:01:00. Increase the timeout value passed to the call to Request or increase the SendTimeout value on the Binding. The time allotted to this operation may have been a portion of a longer timeout.\r\n\r\nبیشتر در این زمینه مشکلی نبوده است و با اتفاق روز 14 فروردین این مورد ها رخ داده است\r\n\r\n', '202504-787', 3, 31, 'Condition_final_done', 'high', NULL, '2025-04-07 08:24:15', '2026-02-22 13:19:21', NULL, NULL, NULL),
	(788, 'اختلال سوئیچ تاریخ 14 فروردین', 'با سلام و احترام\r\nبدلیل اختلال سوئیچ در تاریخ 14 فروردین ، برخی از تراکنش ها مغایرتی شده اند که موجب نارضایتی (پذیرنده و دارنده کارت) و عدم امکان پاسخگویی همکاران مرکز تماس(بدلیل نبود قانون تراکنشی) شده است.\r\nلطفا دستورات مقتضی جهت بررسی و تعیین وضعیت تراکنش ها و  عدم تکرار این مورد را صادر فرمایید.\r\n \r\nنمونه برخی از تراکنش ها:\r\nمورد 1:\r\nتراکنش ناموفق بوده و دستگاه رسید ناموفق چاپ کرده است اما تاریخ 17 ام به حساب پذیرنده واریز شده است.(مغایرت در تراکنش)\r\nشماره مرجع : 849574719072\r\n \r\n \r\nمورد 2 :\r\nتراکنش موفق و دستگاه رسید موفق چاپ کرده است اما زمان واریز نامشخص و تاکنون واریز نشده است.(220 سمت 1 خطادار)\r\nشماره مرجع : 849574983798\r\n \r\n \r\nمورد 3 :\r\nتراکنش ناموفق و دستگاه رسید ناموفق چاپ کرده است اما سوئیچ برای تراکنشی که 420 دارد ، 220 تولید و به حساب پذیرنده واریز شده است.\r\nشماره مرجع: 849574306042\r\n \r\n \r\nمورد 4 :\r\nتراکنش ناموفق می باشد و وضعیت تراکنش نامعلوم می باشد و امکان پاسخگویی صحیح وجود ندارد.\r\nمرجع: 849574936374\r\n \r\n', '202504-788', 3, 31, 'Condition_final_done', 'high', NULL, '2025-04-07 08:48:28', '2026-02-22 13:19:16', NULL, NULL, NULL),
	(789, 'کدملی تکراری ', 'باسلام و احترام\r\nخواهشمند است در صورتی که در فایل صدور کارت کدملی وجود داشته باشد که از قبل برای آن کارتی (با گروه کارت مذکور در فایل صدور کارت) تعریف شده باشد.\r\nدر زمان صدور مجدد کارت با کد ملی تکراری بر روی گروه تکراری پیغام خطا نمایش داده شده و صدور مجدد کارت امکان پذیر نباشد.\r\nباسپاس', '202504-789', 1, 25, 'Condition_final_done', 'high', NULL, '2025-04-08 06:44:16', '2026-02-21 11:51:01', NULL, NULL, NULL),
	(790, 'تغییر سوئیچ کد ', 'با سلام\r\nخواهمند است سوئیچ کد ترمینال 06119360 از 3 به 7 تغییر کند.\r\nبا تشکر ', '202504-790', 3, 10, 'Condition_final_done', 'high', NULL, '2025-04-08 07:03:15', '2026-02-21 11:50:57', NULL, NULL, NULL),
	(791, 'عدم نمایش تراکنش در سرویس ternover ', 'با سلام واحترام \r\nطبق مکالمه با جناب آقای محمدی در این خصوص ، و پیگیری ایشان ، مشخص شد که این سرویس گردش تراکنش های روز قبل را نمایش می دهد  و به دلیل پیگیری تلفنی این تیکت ثبت شده است \r\nخواهشمند است در صورت امکان بررسی شود که آیا امکان این می باشد که این سرویس تراکنش های روز جاری را نشان دهد ، در صورت امکان و در صورت نیاز سازمان تیکت توسعه آن ثبت خواهد شد. \r\nبا احترام مجدد ', '202504-791', 1, 35, 'condition_in_progress', 'low', NULL, '2025-04-08 07:43:53', '2025-04-13 11:43:57', NULL, NULL, NULL),
	(792, 'درخواست افزایش تعداد رکورهای خروجی اکسل', 'باسلام و احترام\r\nخواهشمند است بر روی خروجی گزارشات ذیل تعداد رکوردهای خروجی به یک میلیون رکورد افزایش داده شود :\r\nگزارش تراکنش کارت \r\nگزارش شارژ کارت \r\nگزارش سرجمع صدور کارت \r\nگزارش سود ناشی از رسوب', '202504-792', 1, 25, 'Condition_final_done', 'high', NULL, '2025-04-08 07:58:17', '2026-02-21 11:50:52', NULL, NULL, NULL),
	(793, 'گزارش فعالیت های کارت', 'باسلام و احترام\r\nبر روی گزارش فعالیت های کارت، خروجی صحیح نمایش داده نمی شود.\r\nنمونه کارت جهت بررسی \r\n6274124491500546\r\nباسپاس', '202504-793', 1, 25, 'condition_acepted_test_auto', 'high', NULL, '2025-04-08 08:59:00', '2026-05-24 11:22:03', NULL, NULL, NULL),
	(794, 'داکیومنت راهنمای کاربری بک افیس جدید', 'با سلام\r\n\r\nداکیومنت راهنمای کاربری بک افیس جدید را ارسال فرمایید.\r\nبا تشکر', '202504-794', 3, 10, 'Condition_final_done', 'low', NULL, '2025-04-08 09:01:55', '2026-02-21 09:10:25', NULL, NULL, NULL),
	(795, 'امکان حذف یوزر ', 'با سلام\r\nامکان حذف یوزر، برای کاربران ، برای یوزر ادمین وجود داشته باشد.', '202504-795', 3, 10, 'Condition_regect', 'low', NULL, '2025-04-08 10:55:27', '2025-04-23 07:56:20', NULL, NULL, NULL),
	(796, 'افزودن گروه کارت ', 'باسلام و احترام\r\nخواهشمند است در فایل چاپ کارت &quot; خرید &quot;  گروه کارت  نیز اضافه گردد.\r\nخواهشمند این ویژگی تنها برای نوع کارت خرید اعمال گردد.\r\nباسپاس', '202504-796', 1, 25, 'Condition_final_done', 'low', NULL, '2025-04-09 07:17:29', '2026-02-21 11:50:42', NULL, NULL, NULL),
