	(798, 'گزارش تجمیعی', 'باسلام و احترام\r\nخواهشمند است گزارشی مطابق فرمت فایل پیوست ایجاد گردد.\r\nباسپاس', '202504-798', 1, 25, 'condition_in_progress', 'high', NULL, '2025-04-09 10:11:36', '2025-04-09 10:44:11', NULL, NULL, NULL),
	(799, 'تغییر شبا و کد پرونده شارژ تاپ آپ شاتل (فقط شاتل)', 'با درود\r\nدستور فرمایید شبا و کد پرونده فروش شارژ آنی شاتل بر روی دستگاه های سپ 1 بر روی سوئیچ اینتک به شبای جدید به روز رسانی گردد\r\n\r\nشبای قدیم: IR070700001000124572725015\r\n\r\nشبای جدید: IR820700001000124572725023\r\nکد پرونده: 8128\r\n\r\nلازم به توضیح است مقدار اپراتور برای شارژ شاتل بر روی سوئیچ اینتک 5 می باشد\r\n&quot;MNPOperator&quot;:5\r\n', '202504-799', 3, 31, 'Condition_final_done', 'high', NULL, '2025-04-09 10:50:32', '2025-04-23 08:12:34', NULL, NULL, NULL),
	(800, 'تغییر کلید', 'خواهشمند است تغییر کلید بین 2 در تاریخ 21 فروردین ساعت 6 تا 7 صبح با هماهنگی شرکت خدمات انجام شود.\r\nبا سپاس', '202504-800', 3, 10, 'Condition_final_done', 'high', NULL, '2025-04-09 16:13:09', '2026-02-21 11:50:25', NULL, NULL, NULL),
	(801, 'تغییر حساب فعال پذیرنده بدون انجام تراکنش تغییر حساب  توسط پذیرنده', 'با درود\r\nمطابق با تراکنش های ضمیمه ترمینال به شماره 12849299 پیشتر مشغول انجام تراکنش بر روی شبای IR600180000000177001296576  بوده است، اما به طور ناگهانی در تاریخ 2025-04-09 08:59:04 شبای فعال پذیرنده به حساب IR850560085480609548403001 تغییر کرده است، این نکته قابل ذکر است که هیچ تراکنش تغییر حساب 700 در زمان فوق انجام نشده است و این امر باعث گمراهی پذیرنده شده است\r\nدر آخر پذیرنده با راهنمایی پشتیبان اقدام به انجام تراکنش تغییر حساب می نمایید 700 2025-04-10 11:24:38 و 700 2025-04-10 11:25:06 تا مجدد تراکنش های پذیرنده به حساب پیشین بازگشت داده شود IR600180000000177001296576\r\nبه چه علت تغییر شبای برای پذیرنده بدون انجام تغییر حساب انجام شده است؟؟\r\n\r\nخواهشمند است اعلام فرمایید\r\nبا تشکر', '202504-801', 3, 31, 'Condition_final_done', 'high', NULL, '2025-04-10 09:25:29', '2026-02-22 13:19:10', NULL, NULL, NULL),
