	(806, 'خطای 58', 'با سلام\r\nتعدادی از ترمینال ها خطای 58 دریافت میکنند\r\nخواهشمند است در اسرع وقت بررسی شود\r\n30519938\r\n12177460\r\n12082693', '202504-806', 3, 10, 'Condition_final_done', 'high', NULL, '2025-04-13 09:12:23', '2025-04-23 08:12:23', NULL, NULL, NULL),
	(807, 'دریافت خطای 03 در هنگام دریافت پیکربندی برای ترمینال 10531940', 'با درود\r\nدریافت خطای 03 در هنگام دریافت پیکربندی برای ترمینال 10531940 - خطای داخلی در هنگام دریافت پیکربندی\r\n\r\n3-1-شماره ترمینال در جدول ترمینال ها پیدا نشد', '202504-807', 3, 31, 'Condition_final_done', 'medium', NULL, '2025-04-13 11:01:20', '2026-02-22 13:18:51', NULL, NULL, NULL),
	(808, 'خطا مولتی اکانت در تسویه تراکنش شبا با حساب اصلی - ترمینال 31204462', 'با درود\r\nترمینال به شماره 31204462 در حال انجام تراکنش بوده است با شبای IR140150004619701530114916 ، طی درخواست از جانب پذیرنده درخواست تغییر حساب با تراکنش 700 به شبای IR470560611828006258301901  تغییر می کند، روال انجام تراکنش طی شده است اما بدون تراکنش تغییر حساب از سوی پذیرنده در تاریخ 2025-04-08 15:22:43.653 شبای پذیرنده به IR140150004619701530114916 تغییر پیدا کرده است.\r\nدلیل چیست؟', '202504-808', 3, 31, 'Condition_final_done', 'high', NULL, '2025-04-13 12:44:00', '2026-02-22 13:18:47', NULL, NULL, NULL),
	(809, 'پیاده سازی شارژ آنی دلخواه شارژ مرکزی توسط سوئیچ سپ 1', 'با درود\r\nخواهشمند است مطابق سند ضمیمه و کالکشن پست من نسبت به پیاده سازی درخواست شارژ آنی دلخواه مطابق با روال پیشین اقدام فرمایید\r\n\r\nتنها تفاوت در فرآیند موجود تغییر متد ها می باشد\r\n\r\nشناسه کاربری و رمز عبور پیشین قابل استفاده هستند\r\nبا تشکر', '202504-809', 5, 31, 'condition_acepted_test_auto', 'medium', NULL, '2025-04-14 05:45:59', '2026-03-14 08:31:21', NULL, NULL, NULL),
	(810, 'عدم صحت زمان تراکنش در پیامک ', 'باسلام و احترام\r\nساعت انجام تراکنش در متن پیامک ارسالی صحیح نمی باشد. (در متن پیامک زمان سرور نمایش داده میشود)\r\nباسپاس', '202504-810', 1, 25, 'Condition_final_done', 'high', NULL, '2025-04-14 09:47:01', '2025-05-27 09:50:56', NULL, NULL, NULL),
	(811, 'ارائه یوزر و پس جدید برای وب سرویس SyncSwitchWorker', 'با درود\r\nدستور فرمایید  نسبت به اخذ نام کاربری و رمز عبور جدید جهت استفاده در ویندوز سرویس بروزرسانی سوئیچ اینتک \r\nSyncSwitchWorker\r\nاقدامات لازم صورت گیرد\r\nلازم به ذکر است در حال حاضر ویندوز سرویس با نام کاربری \r\nSepDeveloper\r\nکار میکند که می بایست یک یوزر جدید به جهت استفاه سیستم در نظر گرفته شود\r\n\r\nخدمت جناب محمدی ارائه شود\r\n\r\nبا تشکر\r\n', '202504-811', 1, 31, 'Condition_regect', 'low', NULL, '2025-04-14 10:17:29', '2025-07-30 06:55:40', NULL, NULL, NULL),
	(812, 'عدم امکان  چاپ کارت ', 'باسلام و احترام\r\nبه اطلاع می رساند بر روی شناسه 775 درخواست صدور کارت ، چاپ شماره کارت 6274124491338582 امکان پذیر نمی باشد.\r\nباسپاس', '202504-812', 1, 25, 'condition_acepted_test_auto', 'high', NULL, '2025-04-14 11:10:29', '2026-05-10 14:58:14', NULL, NULL, NULL),
	(813, 'اطلاعات گروه  شرکت رایزکو ', 'باسلام و احترام\r\nخواهشمند است کلیه اطلاعات گروه مشتری های شرکت رایزکو به همراه کد ملی و شماره موبایل را ارسال بفرمایید.\r\nباسپاس', '202504-813', 1, 25, 'Condition_final_done', 'high', NULL, '2025-04-15 06:37:20', '2026-02-21 08:51:42', NULL, NULL, NULL),
	(814, 'فروش شارژ پین تکراری', 'با سلام و احترام\r\nبا توجه به شکایت مشتریان مبنی بر فروش پین شارژ تکراری لطفا وضعیت شارژهای زیر را بررسی نمایید:\r\nسریال شارژ:\r\n98256000150002465  \r\nمراجع :\r\n848146648042\r\n849910910648\r\n\r\nسریال شارژ :\r\n29256000210002130\r\nمراجع : \r\n849915599205\r\n848583620461\r\n\r\nسریال شارژ:\r\n18255000210007743\r\nمراجع :\r\n849912807101\r\n848178334761\r\n\r\nسریال شارژ : \r\n18255000170003443\r\nمراجع :\r\n849909927722\r\n848026281871\r\n', '202504-814', 3, 31, 'Condition_final_done', 'medium', NULL, '2025-04-15 13:14:35', '2026-02-22 13:18:07', NULL, NULL, NULL),
	(815, 'صدور المثنی کارت هدیه', 'باسلام و احترام\r\nخواهشمند است صدور المثنی کارت هدیه با موارد ذیل پیاده سازی گردد :\r\n1. CVV2 هم تغییر یابد\r\n2.تاریخ انقضا کارت هم بروزرسانی گردد\r\nباسپاس', '202504-815', 1, 25, 'Condition_final_done', 'high', NULL, '2025-04-16 07:35:43', '2026-02-21 08:51:59', NULL, NULL, NULL),
	(816, 'خطای 96', 'باسلام و احترام\r\nخواهشمند است علت خطای 96 شماره کارت ذیل را اعلام بفرمایید.\r\nشماره کارت\r\n6274123330942125\r\nتاریخ \r\n1404-01-25\r\nباسپاس', '202504-816', 1, 25, 'Condition_final_done', 'high', NULL, '2025-04-16 08:00:14', '2025-04-23 08:12:19', NULL, NULL, NULL),
	(817, 'عدم ارائه فیلد 48 با فرمت خاص در تراکنش پیکربندی سوخت', 'با درود\r\nمطابق با نیازمندی سپ ، تراکنش سوخت در قالب تراکنش های پیکربندی سری 700 با فیلد 48 مشخص سمت ترمینال ارسال می گردد\r\nاما متاسفانه فیلد 48 ارائه شده به PG اینتک برای ترمینال ارسال نمی گردد، لاگ ضمیمه می باشد\r\n\r\nمساعدت فرمایید', '202504-817', 3, 31, 'Condition_final_done', 'medium', NULL, '2025-04-19 06:24:34', '2026-02-22 13:17:55', NULL, NULL, NULL),
	(818, 'امکان فعال سازی چندین تسهیم برای ترمینال در سوئیچ سپ 1', 'با سلام و احترام\r\nدرخواست تغییر نرم افزار مطابق با سند پیوست\r\nبا تشکر', '202504-818', 2, 31, 'Condition_need_action', 'low', NULL, '2025-04-19 06:37:32', '2025-07-30 06:57:37', NULL, NULL, NULL),
	(819, 'نمایش کلیه صندوق ها در نام کاربری صندوق جانبازان', 'باسلام و احترام\r\nبه اطلاع می رساند زمانی که با نام کاربری janbazanSandogh بر روی بک آفیس صادرکنندگی لاگ این می کنیم، اطلاعات کلیه صندوق ها به همراه موجودی آن ها نمایش داده میشود.\r\nخواهشمند است تنها صندوق مربوط به جانبازان نمایش داده شود.\r\nباسپاس', '202504-819', 1, 25, 'Condition_final_done', 'high', NULL, '2025-04-19 07:15:11', '2026-02-21 08:52:05', NULL, NULL, NULL),
	(820, 'پلین بودن شماره کارت در لاگ ACQUIRER تر اکنش فارا در هنگام استعلام مانا در هنگام خطا', 'با درود\r\n--------------------------------------------------------------------------------\r\n [PrepareMessage] NationalCodeCollaborator\r\n [NationalCodeCollaborator]  [GetNationalCode] for Card  [585983-**-3125]\r\n{&quot;SourcePAN&quot;: &quot;5859831811933125&quot;}\r\n [NationalCodeCollaborator]  [GetNationalCode] Http Result: StatusCode: 400, ReasonPhrase: &#039;Bad Request&#039;, Version: 1.1, Content: System.Net.Http.StreamContent, Headers:\r\n{\r\n  Transfer-Encoding: chunked\r\n  Date: Sat, 19 Apr 2025 07:18:30 GMT\r\n  Server: Microsoft-IIS/10.0\r\n  X-Powered-By: ASP.NET\r\n  Content-Type: application/json; charset=utf-8\r\n}\r\n [NationalCodeCollaborator]  [GetNationalCode] No National Code Found!\r\nException of type &#039;B2S.Core.MessageBroker.Exceptions.NotPermittedToCardHolderException&#039; was thrown. (200) (57)\r\n [HandleExceptionBase] IsSent =  [False] tp =  [B2S.Dynamic.Acquirer.RefahiAuthorizationTP] TxnType =  [9]\r\n [HandleExceptionBase] Building Invalid Message (57)\r\n [BuildInvalidMessage] MTI:  [0110]\r\n [SaveOnException] Saving...\r\n [Save] Data Service  [ISOMessageData]\r\n [SaveOnException] COMMIT\r\n [DDC]  [Save] New Audit  [1]  [SwTxn]\r\n    [RECORD] (TxnType, AggRRN, DestFunctionCode, ResponseCode, InternalReasonCode, ExternalReasonCode, RespTime, )\r\n [ISOMessageData]  [Persist] Txn Id: 128193980891\r\n [BTS] #ROLLBACK...\r\n [TCMP]  [Transaction] Next State is  [ROLLINGBACK]\r\n [TCMP]  [Transaction] ALLROLLEDBACK (ROLLINGBACK) =&gt; {ROLLBACK}', '202504-820', 3, 31, 'Condition_regect', 'high', NULL, '2025-04-19 07:26:54', '2025-04-30 11:49:14', NULL, NULL, NULL),
	(821, 'تغییر پیامک نوع کارت های خرید با شارژ مجازی', 'باسلام و احترام\r\nخواهشمند است  در متن کلیه پیامک های نوع کارت &quot;   خرید با شارژ مجازی &quot; ، عنوان سگمنت اصلی به سگمنت مجازی تغییر یابد.\r\nباسپاس', '202504-821', 1, 25, 'Condition_regect', 'high', NULL, '2025-04-19 07:33:36', '2026-05-25 11:37:34', NULL, NULL, NULL),
	(822, 'عدم اعمال تغییر حساب - ترمینال ترمینال نمونه 13938365', 'با سلام و احترام\r\nدر فرآیند مولتی اکانت برای حساب های اعتباری زمانیکه حساب پیش فرض را از اعتباری به حساب اصلی تغییر می دهیم در سوییچ سپ به درستی انجام شده و در گزارش همگام سازی هم موفق میباشد ولی در سوییچ اینتک حساب پیش فرض تغییر نمیکند و همان اعتباری باقی میماند خواهشمند است بررسی نمایید.\r\nترمینال نمونه 13938365\r\nشبای اعتباری IR680560215072304438832001\r\nشبای اصلی IR690560922180604438832001\r\nبا تشکر', '202504-822', 3, 31, 'Condition_final_done', 'low', NULL, '2025-04-19 08:13:19', '2026-02-22 13:17:49', NULL, NULL, NULL),
	(823, 'ثبت درخواست شارژ با نام کاربری جانبازان', 'باسلام و احترام\r\nخواهشمند است امکان ثبت درخواست شارژ با نام کاربری janbazan بر روی بک آفیس صادرکنندگی پیاده سازی گردد.\r\nباسپاس', '202504-823', 1, 25, 'Condition_final_done', 'low', NULL, '2025-04-19 09:41:57', '2026-02-21 08:52:12', NULL, NULL, NULL),
	(824, 'محدودسازی درخواست شارژهای قبضینو', 'باسلام و احترام\r\nخواهشمند است برای نام کاربری ghabzino تنها امکان شارژ کارت های گروه کارت &quot; تنخواه-قبضینو &quot; را داشته باشد.\r\nباسپاس', '202504-824', 1, 25, 'Condition_final_done', 'low', NULL, '2025-04-19 09:51:57', '2026-02-21 08:52:20', NULL, NULL, NULL),
	(825, 'مشکل عدم امکان استفاده از رمز پویا پس از دریافت کد پاسخ ۵۹', 'در صورت دریافت کد پاسخ ۵۹، پس از نمایش پیغام “بدلیل عدم تطابق اقلام تراکنش با مشخصات رمز پویا یا ورود رمز اشتباه، از انجام تراکنش جلوگیری شد” با توجه به اینکه ممکن است کاربر از کارت دیگری جهت پرداخت استفاده نماید لازم است امکان درخواست رمز پویا مجدد فراهم گردد.', '202504-825', 3, 26, 'Condition_final_done', 'low', NULL, '2025-04-19 10:32:37', '2026-05-12 07:32:08', NULL, NULL, NULL),
	(826, 'عدم ارجاع به callback پذیرنده هنگام عملیات انصراف', 'در صورت فشردن دکمه انصراف در درگاه پرداخت، وضعیت تراکنش باید به آدرس callback پذیرنده ارسال گردد.', '202504-826', 3, 26, 'Condition_final_done', 'low', NULL, '2025-04-19 11:57:58', '2026-02-22 14:05:44', NULL, NULL, NULL),
	(827, 'درخواست API شارژ صندوق', 'باسلام و احترام\r\nخواهشمند است API شارژ صندوق پیاده سازی گردد.\r\nباسپاس', '202504-827', 1, 25, 'Condition_final_done', 'high', NULL, '2025-04-19 12:02:11', '2026-02-21 08:53:58', NULL, NULL, NULL),
	(828, 'Decrypt نمودن فایل های درخواستی ', 'با سلام، به اسـتحضار میرساندشـرکت &quot;پارسیان کیش&quot; بعنوان پیمانکـارصـدور در سـال جـاري به مجموعه تاپ اضافه شـده است که متاسـفانه بدلیل عدم دسترسـی به Decrypt کردن فایلهاي صـدور ثبت شـده در اینتک امکان صدورکارتها براي آنها میسر نمی باشد.\r\nخواهشـمنداست برای ایجاد امکان مذکور و ارسال فایل های  Decrypt  شده شماره تقاضاهای   605869 , 610932 دستورات لازم مبذول فرمایید.  باتشکر', '202504-828', 8, 36, 'Condition_final_done', 'high', NULL, '2025-04-20 05:59:00', '2026-02-22 13:52:24', NULL, NULL, NULL),
	(829, 'اعمال تغییرات تراکنش های فارا', 'باسلام و احترام\r\nبا توجه به تغییرات اعمال شده بر روی تراکنش های فارا ( ارسال تراکنش به ریز ) خواهشمند است نسبت به اعمال تغیرات بر روی سوییچ اقدامات مقتضی اعمال گردد.\r\nتغییرات مطابق با فایل پیوست اعمال گردد.\r\nباسپاس', '202504-829', 3, 25, 'Condition_final_done', 'high', NULL, '2025-04-20 12:02:13', '2026-02-21 08:58:36', NULL, NULL, NULL),
	(830, 'مشکل نام کاربری janbazanSandogh', 'باسلام و احترام\r\nبه اطلاع می رساند نام کاربری  janbazanSandogh  در منو شارژ کارت ( جهت تایید درخواست های شارژ ) کلیه درخواست های شارژ ثبت شده را مشاهده می کند.\r\nمقرر شده بود این نام کاربری تنها درخواست های مربوط به گروه کارت جانبازان را مشاهده نماید.\r\nباسپاس', '202504-830', 1, 25, 'Condition_final_done', 'high', NULL, '2025-04-21 06:01:10', '2026-02-21 08:54:51', NULL, NULL, NULL),
	(831, 'خطای 2 پایانه  14834799', 'با سلام و احترام\r\nپایانه 14834799 در پیکر بندی خطای 2 میدهد\r\nبا سپاس', '202504-831', 3, 34, 'Condition_final_done', 'medium', NULL, '2025-04-21 08:22:45', '2025-04-23 08:12:11', NULL, NULL, NULL),
	(832, 'رفع مشکل گزارش - عدم نمایش کامل تایتل تیکت در گزارش اکسل', 'با سلام در گزارش اکسلی که از تسکها ایجاد میشود تایتل تسک ها نیمه تمام نمایش داده میشود\r\nو برای 500 تسک باز کردن تک تک تسکها و کپی پیست کردن تایتل آنها کار بسیار سختی است .\r\nخواهشمند است این مورد اصلاح شود.', '202504-832', 3, 10, 'Condition_final_done', 'high', NULL, '2025-04-21 09:02:24', '2026-02-21 08:49:01', NULL, NULL, NULL),
	(833, 'مشاهده صندوق Ghabzino ', 'باسلام و احترام\r\nبه اطلاع می رساند زمانی که با نام کاربری Ghabzino بر روی بک آفیس صادرکنندگی لاگ این می کنیم، اطلاعات کلیه صندوق ها به همراه موجودی آن ها نمایش داده میشود.\r\nخواهشمند است تنها صندوق مربوط به قبضینو نمایش داده شود.\r\nباسپاس', '202504-833', 1, 25, 'Condition_final_done', 'high', NULL, '2025-04-21 11:39:38', '2025-04-23 08:11:40', NULL, NULL, NULL),
	(834, 'دریافت پیکربندی متوالی بعد از هر بار انجام تراکنش', 'با درود\r\nدو ترمینال به شماره های 13161382 و 14848148 بعد از انجام تراکنش پیکربندی دریافت می کنند.\r\nدلیل این امر به این خاطر است که در پاسخ تراکنش مالی در فیلد 61 حساب مشخص شده به ترمینال داده می شود\r\n  },\r\n  &quot;TermID&quot;: &quot;13161382&quot;,\r\n  &quot;PayLoad&quot;: &quot;# BEGIN [InteliNac_5001] Send\r\nH[NACInterchange] (5) 6072250050\r\nMessage Len: 233\r\nHeader  Len: 5\r\nH=&gt;6000507225\r\nBIT0=&gt;0210\r\nBIT2=&gt;[610433-**-5329]\r\nBIT3=&gt;000000\r\nBIT4=&gt;000000750000\r\nBIT5=&gt;000000750000\r\nBIT6=&gt;000000750000\r\nBIT7=&gt;0421145316\r\nBIT10=&gt;00000001\r\nBIT11=&gt;000347\r\nBIT12=&gt;145316\r\nBIT13=&gt;0421\r\nBIT15=&gt;0701\r\nBIT17=&gt;0701\r\nBIT32=&gt;581672041\r\nBIT33=&gt;581672041\r\nBIT37=&gt;850126938118\r\nBIT38=&gt;826574\r\nBIT39=&gt;00\r\nBIT41=&gt;13161382\r\nBIT42=&gt;000000013996701\r\nBIT46=&gt;250421145316\r\nBIT48=&gt; \r\nBIT49=&gt;364\r\nBIT51=&gt;364\r\nBIT60=&gt;ملت\r\nBIT61=&gt;8222026718211\r\nBIT100=&gt;581672000\r\nBIT121=&gt;0073146808B1068101018201006908B106810100820102\r\nBIT128=&gt;C35BA736CF95F75C\r\nاما به این دلیل که ترمینال حساب مربوطه که مقدار شماره فیلد 61 می باشد را پیشتر در تراکنش پیکربندی دریافت نکرده است (علی رغم ارسال پیکربندی از سوی سوئیچ سپ به سوئیچ اینتک) دائما پوز می رود به مد دریافت پیکربندی و ریستارت می شود و دوباره\r\n\r\nمقدار حساب در تراکنش پیکربندی فیلد 60 به سوئیچ اینتک ارائه شده است\r\n\r\n2025-04-21 14:55:31\r\n![CDATA[[sep1-2074-10010(SEPPOSCHANNEL)/172.31.20.74-&gt;172.31.19.17]]\r\n[send]	\r\n[send]	\r\n  \r\n  \r\n  \r\n  \r\n  \r\n  \r\n  \r\n  \r\n  \r\n  \r\n  \r\n  \r\n  \r\n  \r\n  \r\n  \r\n  \r\n  \r\n  \r\n  \r\n\r\nتراکنش پیکربندی که سوئیچ اینتک برای ترمینال فرستاده است فاقد فیلد 60 است\r\n\r\n },\r\n  &quot;TermID&quot;: &quot;13161382&quot;,\r\n  &quot;PayLoad&quot;: &quot;# BEGIN [InteliNac_5001] Send\r\nH[NACInterchange] (5) 606A9A0050\r\nMessage Len: 358\r\nHeader  Len: 5\r\nH=&gt;606A9A0050\r\nBIT0=&gt;0710\r\nBIT3=&gt;100013\r\nBIT7=&gt;0421144834\r\nBIT11=&gt;003738\r\nBIT12=&gt;144834\r\nBIT13=&gt;0421\r\nBIT32=&gt;581672041\r\nBIT38=&gt;502054\r\nBIT39=&gt;00\r\nBIT41=&gt;13161382\r\n\r\n# END [InteliNac_5001] Send\r\n&quot;,\r\n  &quot;logTime&quot;: {\r\n    &quot;$date&quot;: {\r\n      &quot;$numberLong&quot;: &quot;1745234320918&quot;\r\n    }', '202504-834', 3, 31, 'Condition_regect', 'high', NULL, '2025-04-21 11:47:04', '2025-04-30 11:50:55', NULL, NULL, NULL),
	(835, 'گزارش کارت های هدیه منقضی ', 'باسلام و احترام\r\nخواهشمند است گزارش کارت های هدیه ای که منقضی شده اند و تاریخ صدور آن ها از ابتدای ایجاد بک آفیس صادرکنندگی تا پایان دی ماه 1403 می باشد ارسال گردد.\r\nگزارش شامل فیلدهای ذیل باشد:\r\n1. شماره کارت\r\n2. گروه کارت\r\n3. موجودی کارت\r\nباسپاس', '202504-835', 1, 25, 'Condition_final_done', 'high', NULL, '2025-04-22 11:12:06', '2025-05-18 08:07:00', NULL, NULL, NULL),
	(836, 'گزارش سرجمع شارژ به تفکیک گروه کارت', 'باسلام و احترام\r\nخواهشمند است گزارشی همانند &quot; گزارش سرجمع تراکنش به تفکیک گروه کارت &quot; برای تراکنش های شارژ کارت ایجاد گردد.\r\nتراکنش های شارژ کارت شامل :\r\n1. شارژ از طریق بک آفیس\r\n2.شارژ از طریق وب سرویس ( سایت پرداخت نوین / اپلیکیشن سان )\r\n3.تراکنش های انتقال به کارت\r\n\r\nباسپاس', '202504-836', 1, 25, 'Condition_final_done', 'high', NULL, '2025-04-22 12:24:52', '2026-02-21 08:57:38', NULL, NULL, NULL),
	(837, 'ایجاد رمز یکسان شماره کارت', 'با سلام و احترام\r\nخواهشمند است نسبت به صدور رمز یکسان برای کارت‌های تقاضا 611911 اقدام فرمایید.\r\nرمز اول: 2318\r\nرمز دوم: 23180\r\nبا تشکر', '202504-837', 8, 36, 'Condition_final_done', 'high', NULL, '2025-04-23 07:49:26', '2025-07-19 09:06:16', NULL, NULL, NULL),
	(838, 'ارائه مستندات تولید ونحوه  استفاده کلیدهای صدور کارت  ', 'با سلام و احترام، با عنایت به مذاکرات انجام شده لطفا نسبت به ارائه مستندات مربوط به ایجاد و استفاده از کلیدهای امنیتی صدور کارت و مکانیزم Encrypt  و  Decrypt فایل های مربوط به آن توسط کاربران (پیمانکاران صدور و چاپ کارت)  در بکافیس دارندگی اقدامات لازم را مبذول نمایید. در ضمن دسترسی منوی ارائه کلیدهای امنیتی در بکافیس را از دسترس کاربران خارج نمایید. ', '202504-838', 8, 36, 'Condition_final_done', 'high', NULL, '2025-04-23 08:26:37', '2025-07-19 09:06:11', NULL, NULL, NULL),
	(839, 'اعمال محدودیت در منو شارژ کارت جانبازان', 'باسلام و احترام\r\nخواهشمند است در منو شارژ کارت نام کاربری جانبازان:\r\n1. در قسمت نوع کارت ، تنها خرید با شارژ مجازی نمایش داده شود\r\n2. در قسمت سگمنت ، تنها سگمنت مجازی  نمایش داده شود\r\nباسپاس', '202504-839', 1, 25, 'Condition_final_done', 'medium', NULL, '2025-04-23 12:06:18', '2026-02-21 08:57:23', NULL, NULL, NULL),
	(840, 'گزارش نام کاربری جانبازان', 'باسلام و احترام\r\nبر روی گزارش تراکنش کارت نام کاربری جانبازان تنها نوع کارت خرید با شارژ مجازی نمایش داده شود.\r\nباسپاس', '202504-840', 1, 25, 'Condition_final_done', 'medium', NULL, '2025-04-23 12:09:32', '2026-02-21 08:57:12', NULL, NULL, NULL),
	(841, 'جستجوی کارت نام کاربری جانبازان', 'باسلام و احترام\r\nدر منوی جستجوی کارت نام کاربری جانبازان تنهای کاربران گروه جانبازان نمایش داده شود در حال حاضر جستجوی کلیه کاربران بک آفیس صادرکنندگی امکان پذیر می باشد.\r\nباسپاس', '202504-841', 1, 25, 'Condition_final_done', 'medium', NULL, '2025-04-23 12:11:58', '2026-02-21 08:57:06', NULL, NULL, NULL),
	(842, 'اعمال تخفیف پایانه های فولاد ', 'با سلام\r\nخواهشمند است تخفیف بروی پایانه های فایل ضمیمه اعمال گردد.\r\n', '202504-842', 3, 10, 'Condition_final_done', 'medium', NULL, '2025-04-26 05:44:38', '2025-05-27 09:50:29', NULL, NULL, NULL),
	(843, 'جستجو بر اساس شماره مرجع تراکنش', 'باسلام و احترام\r\nخواهشمند است بر روی صفحه فایل پیوست ( نمایش حساب اصلی نمایش حساب های مرتبط ) امکان جستجو بر اساس شماره مرجع  تراکنش پیاده سازی گردد.\r\nباسپاس\r\n', '202504-843', 1, 25, 'Condition_final_done', 'high', NULL, '2025-04-26 09:03:35', '2025-05-27 09:49:57', NULL, NULL, NULL),
	(844, 'عدم تمدیدکارت در بکافیس دارندگی ', 'با سلام و احترام\r\nبنـا به نارضـایتی بعضـی مشتریـان مبنی بر تمدیـد نشـدن کارتهـا ،گزارشـی که از سیسـتم بـابت کارتهاي منقضـی اخذ می شودکارتهایی که تمدیدشده اندنیز نمایش داده می شودو همین امر باعث شده که بعضی شماره کارتها دو سه بار تمدید\r\nشوند. با توجه باحائز اهمیت بودن این موضوع خواهشـمنداست پیگیری و بررسی های لازم صورت گیرد. باتشکر', '202504-844', 8, 36, 'Condition_need_action', 'high', NULL, '2025-04-26 09:55:53', '2025-04-27 06:06:32', NULL, NULL, NULL),
	(845, 'اطلاعات فیلد 48 بروی دیتابیس', 'با سلام\r\nخواهشمند است فیلدهای دیتابیس که شامل اطلاعات فیلد 48 (همه تگ ) میباشد را اعلام فرمایید.\r\nاطلاعات فیلد 48 را در کدام دیتابیس و در کدام جدول و در کدام فیلد میتوانیم مشاهده کنیم', '202504-845', 3, 10, 'Condition_final_done', 'high', NULL, '2025-04-26 10:52:36', '2025-05-27 09:49:44', NULL, NULL, NULL),
	(846, 'به روز رسانی سرور 172.31.29.44 به نسخه ویندوز 2022', 'با درود\r\nمقرر است ارتباط کانال با شاپرک به جاب گواهی قدیمی SSlV3 به گواهی TLS 1.3 Enamad صدرا تغییر پیدا کند ، مطابق با تست موفق بر روی بین سوم سوئیچ سپ ، یکی از نیازمندی های مربوطه وجود سیستم عامل ویندوز از نسخه 2022 به بعد می باشد\r\n\r\nنسخه سرور فیزیکی 172.31.29.44 نود 4 فورواردر سپ 1 نسخه 2016 بوده و ارسال پروتکل TLS برای شاپرک برای این نسخه از ویندوز قابل ارسال نیست\r\n\r\nلذا دستور فرمایید راهکار آن شرکت محترم در خصوص به روز رسانی سرور فوق اعلام شود\r\n\r\nبا تشکر', '202504-846', 1, 31, 'Condition_regect', 'high', NULL, '2025-04-26 11:18:25', '2025-07-09 08:35:33', NULL, NULL, NULL),
	(847, 'افزایش تعداد رکوردهای خروجی اکسل جستجوی پیشرفته', 'باسلام و احترام\r\nخواهشمند است بر روی خروجی اکسل جستجوی پیشرفته  تعداد رکوردهای خروجی به یک میلیون رکورد افزایش داده شود.\r\nباسپاس', '202504-847', 1, 25, 'Condition_final_done', 'high', NULL, '2025-04-27 08:12:46', '2026-02-21 08:57:01', NULL, NULL, NULL),
	(848, 'درخواست گزارش کارت های هدیه_ گزارش بانک', 'باسلام و احترام\r\nخواهشمند است گزارش کارت های هدیه با کلیه خروجی های منوی جستجوی پیشرفته ارسال گردد.\r\nباسپاس', '202504-848', 1, 25, 'Condition_final_done', 'high', NULL, '2025-04-27 08:17:55', '2025-05-18 08:07:07', NULL, NULL, NULL),
	(849, 'گزارش شارژ صندوق', 'باسلام و احترام\r\nخواهشمند است گزارشی جهت مشاهده شارژهای صندوق پیاده سازی گردد.\r\nباسپاس', '202504-849', 1, 25, 'Condition_final_done', 'high', NULL, '2025-04-27 08:29:48', '2026-02-21 08:56:54', NULL, NULL, NULL),
	(850, 'ارسال تراکنش برگشت برای تراکنش شارژ آنی غیر موفق برای شاپرک', 'با درود\r\nدر خصوص تراکنش های شارژ آنی که پردازنده آنها نود 23 می باشد، در صورتی که سمت سامانه شارژ مرکزی با خطای مواجه شود، تراکنش کد خطای 93 و کد علت داخلی 10000 مواجه می شود و تراکنش مالی سمت شاپرک ارسال نمی شود\r\n\r\nاما تراکنش برگشت سمت شاپرک از نود 25 ارسال می شود و خطای 12 مواجه می شود\r\nبرخی از مثال ها با کد مرجع زیر مشخص هستند\r\n\r\n  --850117521456 93 420=12\r\n  --850137344403 93 420=12\r\n  --850105479271 93 420=12\r\n  --850077973608 93 420=12', '202504-850', 3, 31, 'Condition_final_done', 'low', NULL, '2025-04-27 10:49:58', '2026-02-22 13:16:06', NULL, NULL, NULL),
	(851, 'شماره ترمینال هایی که بر روی سوئیچ اینتک مدیریت می شوند', 'خواهشمند است لیست شماره سریال ترمینال هایی که مدیریت تراکنش آنها روی سوئیچ اینتک صورت می پذیرد را از روی دیتابیس اینتک را ارسال بفرمائید این گزارش روی سامانه تاپیار وجود دارد اما به دلیل صحت سنجی از روی دیتابیس اینتک این اطلاعات را نیاز داریم به درخواست سرکار خانم ملیکا هاشمی این تیکت ثبت شده است .', '202504-851', 8, 35, 'Condition_regect', 'medium', NULL, '2025-04-27 12:43:41', '2025-04-28 11:30:06', NULL, NULL, NULL),
	(852, 'عدم نمایش دیتای مناسب در جدول AcqVirtualTxn', 'با سلام و احترام؛\r\nبدین‌وسیله به استحضار می‌رساند با توجه به عدم نمایش IP مناسب در دیتابیس B2SPG، جدول AcqVirtualTxn، موجودیت CustomerAddress و IPAddress خواهشمند است دستور فرمایید تا مساعدت لازم در این زمینه انجام گیرد\r\n', '202504-852', 4, 26, 'Condition_final_done', 'low', NULL, '2025-04-28 07:53:17', '2026-05-12 07:32:27', NULL, NULL, NULL),
	(853, 'حذف کارفرمای نیک پی با ID به شماره 96', 'با درود\r\nدستور فرمایید حذف کارفرمای نیک پی با ID به شماره 96 بر روی بک آفیس اینتک انجام شود یا غیر فعال گردد', '202504-853', 1, 31, 'Condition_final_done', 'low', NULL, '2025-04-29 07:10:13', '2026-02-22 13:17:15', NULL, NULL, NULL),
	(854, 'خطای تغییر حساب', 'با سلام\r\nترمینال 11544393\r\nتغییر حساب انجام داده است \r\nاماروی سوییچ اینتک حساب قبلی را چک میکند و بنابراین خطای 03 مشاهده میشود \r\nدر صورتیکه باید حساب جدید چک شود\r\nاین ترمینال شامل تسهیم هم هست\r\nحساب قدیم:\r\nIR190640176470000985253001\r\nحساب جدید:\r\nIR660640176400700985253001\r\n', '202504-854', 3, 10, 'Condition_final_done', 'high', NULL, '2025-04-29 10:09:27', '2025-05-27 09:49:37', NULL, NULL, NULL),
	(855, 'پیگیری خطای کد 58 در تراکنش‌های کهربا', 'با سلام و احترام،\r\n\r\nبدین وسیله به استحضار می‌رسانم که در طی انجام تراکنش‌های کهربا از طریق برخی ترمینال‌ها، با خطای کد 58 مواجه شده‌ایم. این خطا فقط در مورد تعدادی از ترمینال‌ها رخ می‌دهد و مستلزم بررسی دقیق‌تری است.\r\n\r\nخطای کد 58 معمولاً به معنای عدم مجوز انجام تراکنش از سمت ترمینال یا شبکه مربوطه است. این موضوع باعث اختلال در فرآیند تراکنش‌های کهربا شده و تأثیر منفی بر خدمات ارائه‌شده به مشتریان دارد.\r\n\r\nلذا خواهشمند است دلایل این خطا بررسی شود و در صورت وجود مشکلی در تنظیمات ترمینال‌ها یا مجوزهای مربوطه، اقدامات لازم جهت رفع آن انجام گیرد. همچنین، در صورت نیاز به هرگونه اطلاعات تکمیلی از سمت ما، لطفاً مراتب را اعلام فرمایید.\r\n\r\nبدین وسیله از همکاری و رسیدگی شما صمیمانه تشکر و قدردانی می‌نمایم. ', '202504-855', 3, 26, 'Condition_final_done', 'high', NULL, '2025-04-29 10:33:18', '2026-02-22 14:05:49', NULL, NULL, NULL),
	(856, 'ایجاد کانال جدید جهت RKI', ' با سلام \r\nخواهشمند است علاوه بر کانال موجود RKI، کانال جدیدی جهت RKI ایجاد گردد.\r\nبا سپاس\r\n', '202504-856', 11, 10, 'condition_acepted_test_auto', 'medium', NULL, '2025-04-29 11:02:11', '2026-08-15 05:09:28', NULL, NULL, NULL),
	(857, 'عدم امکان تخصیص گروه کارت به یک ترمینال', 'با سلام\r\nبروی بک افس جدید امکان تخصیص گروه کارت به یک ترمینال وجود ندارد و خطا مشاهده میشود.', '202504-857', 3, 10, 'Condition_final_done', 'medium', NULL, '2025-04-29 11:39:42', '2026-02-21 08:56:48', NULL, NULL, NULL),
	(858, 'تخصیص شماره شبای عمومی به ترمینال (شبای عمومی ستاره اول کیش)', '\r\nبا سلام \r\nخواهشمند است شماره شبا به ترمینال تخصیص یابد\r\n\r\n1- ترمینال: 30553032\r\nهمراه اول\r\nشبا       IR790700001000127576840006\r\n----------------------------------------------------------\r\n\r\n2- ترمینال: 31100582\r\nایرانسل\r\nشبا   IR950700001000127576840009 \r\n\r\n', '202504-858', 1, 10, 'Condition_final_done', 'high', NULL, '2025-04-29 12:25:38', '2025-05-18 08:07:14', NULL, NULL, NULL),
	(859, 'درخواست فعال‌سازی قابلیت NFC برای ترمینال‌های با پیش‌شماره 7000', 'با سلام و احترام،\r\n\r\nبدین وسیله به استحضار می‌رسانم که به منظور افزایش کیفیت خدمات و تسهیل فرآیند پرداخت‌های الکترونیکی، تقاضای فعال‌سازی قابلیت NFC برای تمام ترمینال‌هایی که با پیش‌شماره 7000 شروع می‌شوند، داریم.\r\n\r\nلذا خواهشمند است اقدامات لازم جهت فعال‌سازی این قابلیت برای ترمینال‌های مذکور انجام شود.\r\nبا سپاس', '202504-859', 3, 26, 'condition_acepted_test_auto', 'high', NULL, '2025-04-29 13:23:21', '2025-05-20 12:14:18', NULL, NULL, NULL),
	(860, 'مشکل چند حسابی pcpos', 'با سلام و احترام\r\nبرای مواردی از ترمینال های دارای چند حسابی (Multi Account) pc pos زمانیکه در سوییچ در قسمت ویرایش ترمینال امکان چندحسابی در سوییچ سپ در حالت false قرار می گیرد این امکان در اینتک تیک فعال می باشد خواهشمند است بررسی نمایید:\r\n\r\nترمینال نمونه : 14861455\r\nحساب اصلی: IR270180000000177018841560\r\nحساب پیش فرض: IR210130100000000057485355\r\n\r\nترمینال نمونه : 14881764\r\nحساب اصلی: IR610560930180002594914001\r\nحساب پیش فرض: IR970560930104004374206001\r\n', '202504-860', 1, 31, 'Condition_final_done', 'low', NULL, '2025-04-30 04:59:50', '2026-02-22 13:17:10', NULL, NULL, NULL),
	(861, 'دسترسی به سامانه تیکتینگ', 'با سلام و احترام\r\nنظر به ارسال نامه پیوست در تاریخ 1403/12/22 به استحضار میرساند تا کنون هیچگونه پاسخی از سوی آن شرکت محترم داده نشده است لذا خواهشمند است اقدامات لازم در این خصوص را مبذول فرمایید.\r\nبا سپاس', '202504-861', 1, 34, 'Condition_pending', 'medium', NULL, '2025-04-30 08:18:19', '2025-05-04 09:24:28', NULL, NULL, NULL),
	(862, 'خطای 34 برای کارت های تمدید در سیستم', 'باسلام\r\nاحتراما به استحضار میرساند کارتهایی که توسط شعبه درخواست صدور رونوشت داشتند ومنقضی بودند در سیستم تاپیار درخواست تمدید ثبت گردید لیکن تاریخ کارت تمدیدی در سیستم با تاریخ ثبت شده بر روی جسم کارت مغایرت داشته ودر سیستم خطای تقلبی بودن کارت دیده می شود ودارنده امکان استفاده از کارت را ندارند بعنوان مثال برای کارت 6221064008939189 در سیستم با شماره تقاضا608771 تمدید ثبت شده است تاریخ انقضا کارت در سیستم 1405/02  و تاریخ انقضا بر روی کارت 1409/02 می باشد و دارنده امکان استفاده از کارت را ندارند .لذا خواهشمنداست در این خصوص اقدام مقتضی انجام پذیرد.باتشکر', '202504-862', 8, 36, 'Condition_final_done', 'high', NULL, '2025-04-30 11:08:55', '2025-09-09 10:28:31', NULL, NULL, NULL),
	(863, 'اعمال تغییر در منوی کارت-گروه کارت ', 'با سلام و احترام،\r\nخواهشمند در منو &quot;کارت&quot; و قسمت &quot;گروه کارت&quot; موارد ذیل را در فیلترهای ورودی و همچنین خروجی اضافه فرمایید:\r\n1.	تاریخ ثبت\r\n2.	نام نمایندگی\r\nشایان ذکر می‌باشد در حال حاضر در زمان ثبت گروه جدید؛ نام نمایندگی قابل ثبت هست اما طبق تصویر نه در خورجی اکسل و نه در اینتک نمایش داده نمی‌شود.\r\nبا تشکر\r\n', '202504-863', 2, 36, 'Condition_final_done', 'low', NULL, '2025-04-30 11:22:55', '2025-07-19 09:06:09', NULL, NULL, NULL),
	(864, 'حذف CVV2', '\r\nباسلام و احترام\r\nدر منو درخواست صدور کارت، در صورت که گزینه &quot; حذف رمز دوم از فایل چاپ کارت &quot; انتخاب گردد بر روی فایل چاپ رمز همچنان فیلد CVV2 نمایش داده میشود.\r\nخواهشمند است در صورت که گزینه &quot; حذف رمز دوم از فایل چاپ کارت &quot; انتخاب گردد فیلد CVV2 حذف گردد.\r\nباسپاس', '202505-864', 1, 25, 'Condition_final_done', 'medium', NULL, '2025-05-03 07:12:22', '2026-02-21 08:56:31', NULL, NULL, NULL),
	(865, 'سپ - پروژه انتقال دیتاسنتر شرکت پرداحت الکترونیک سامان کیش', 'با سلام و احترام\r\nمطابق با پروژه انتقال دیتاسنتر شرکت پرداخت الکترونیک سامان کیش و با در نظر گرفتن نصب کلیه سرور های سوئیچ سپ 1 از جمله ، پایگاه داده ، سرور های جانبی پرداخت سوئیچ مانند SSL Gateway و .... روی محیط جدید\r\nدستور فرمایید زمان تقریبی نصب و راه اندازی کلیه سرور ها به تفکیک را در حالت Fresh Instalation  به منظور آماده سازی گانت چارت پروژه ارسال بفرمایید\r\nبا تشکر\r\n', '202505-865', 3, 31, 'Condition_regect', 'medium', NULL, '2025-05-03 09:22:12', '2025-07-09 08:37:04', NULL, NULL, NULL),
	(866, 'خطای 03 در تراکنش پیکربندی سری 700 ترمینال 10794668', 'با درود\r\nخطای 03 در تراکنش پیکربندی سری 700 ترمینال 10794668\r\n3-1-شماره ترمینال در جدول ترمینال ها پیدا نشد\r\nخواهشمند است رفع بفرمایید\r\nبا تشکر', '202505-866', 3, 31, 'Condition_regect', 'low', NULL, '2025-05-03 13:23:58', '2025-05-06 05:45:56', NULL, NULL, NULL),
	(867, 'خطای ترمینال 31078392 - 58-6-حساب در جدول شماره حساب ها برای ترمینال یافت نشد', 'با درود\r\nخطای ترمینال 31078392 - 58-6-حساب در جدول شماره حساب ها برای ترمینال یافت نشد', '202505-867', 3, 31, 'Condition_final_done', 'high', NULL, '2025-05-04 05:49:58', '2025-12-30 06:19:48', NULL, NULL, NULL),
	(868, 'عدم نمایش رسید Confirm پس از انصراف از عملیات درگاه پرداخت', 'با سلام و احترام؛\r\nبدین‌وسیله به استحضار می‌رساند با توجه به نیاز به نمایش اطلاعات انصرافی تراکنش در قالب یک رسید در صفحه‌ی وب، پس از انجام عملیات انصراف، خواهشمند است دستور فرمایید تا مساعدت لازم در این زمینه انجام گیرد.', '202505-868', 1, 26, 'Condition_final_done', 'low', NULL, '2025-05-04 07:25:26', '2026-05-12 07:32:41', NULL, NULL, NULL),
	(869, 'فعال و غیرفعال سازی NFC', 'با سلام و احترام؛\r\nبدین‌وسیله به استحضار می‌رساند با توجه به نیاز به امکان فعال/غیرفعال سازی NFC توسط کاربر در سامانه BackOffice خواهشمند است دستور فرمایید تا مساعدت لازم در این زمینه انجام گیرد.', '202505-869', 7, 26, 'condition_acepted_test_auto', 'high', NULL, '2025-05-04 07:31:27', '2025-06-08 04:36:47', NULL, NULL, NULL),
	(870, 'عملیاتی سازی فارا، کهربا و میرشتاب ', 'با سلام و احترام\r\nخواهشمند است \r\nفارا\r\nکهربا \r\nمیرشتاب \r\nبروی کانال لایو عملیاتی گردد\r\nمهم ***قبل از انجام نهایی با آقای محب و آقای حلاجی هماهنگی نهایی صورت پذیرد ***', '202505-870', 3, 10, 'condition_acepted_test_auto', 'medium', NULL, '2025-05-04 08:11:14', '2025-06-24 08:04:51', NULL, NULL, NULL),
	(871, 'غیر فعال شدن کارت', 'با سلام و احترام\r\nکارت شماره 5057854100023630  مسدود گردیده و برای رفع انسداد می خواهیم اقدام کنیم اعلام می کند کارت غیرفعال است و گزینه ای مبنی بر فعال شدن ندارد .لطفا در اسرع زمان ممکن فعال کنید .\r\nپیشا پیش از همکاری شما کمال تشکر را دارم \r\n09351003290\r\n', '202505-871', 3, 34, 'condition_acepted_test_auto', 'medium', NULL, '2025-05-04 09:25:06', '2026-10-07 16:08:21', NULL, NULL, NULL),
	(872, 'تخصیص Iban شارژ بروی کانال تستی', 'با سلام و احترام\r\nخواهشمند است IBAN زیر برای کانال تستی 40800 جهت تسویه شارژ در نظر گرفته شود \r\nIR470550014381805562337002\r\nپس از تست موفق   هماهنگی جهت تخصیص IBAN  به کانال عملیاتی انجام خواهد شد.', '202505-872', 3, 10, 'Condition_regect', 'medium', NULL, '2025-05-04 11:24:54', '2025-05-05 05:05:43', NULL, NULL, NULL),
	(873, 'تست تراکنش شارژ  - BIN2', 'با سلام\r\nخواهشمند است تست تراکنش شارژ  BIN2 با این شبا صورت پذیرد:\r\n\r\nIR470550014381805562337002\r\n\r\nبا تشکر', '202505-873', 3, 10, 'Condition_final_done', 'medium', NULL, '2025-05-04 13:01:14', '2026-02-21 08:55:40', NULL, NULL, NULL),
	(874, 'منو جستجوی کارت نام کاربری جانبازان', 'باسلام و احترام\r\nخواهشمند است در منو جستجوی کارت نام کاربری جانبازان تغییرات ذیل اعمال گردد:\r\n1. منو انتخاب مشتری حذف گردد\r\n2. در خروجی تنها  کارت‌های,  گروه &quot; مجازی - کارت خرید فروشگاه جانبازان &quot; نمایش داده شود.( در حال حاضر در صورت وارد کردن شماره کارت سایر گروه کارت ها ، اطلاعات کامل مشتری نمایش داده میشود)\r\nباسپاس', '202505-874', 1, 25, 'Condition_final_done', 'high', NULL, '2025-05-05 08:07:37', '2026-02-21 08:55:30', NULL, NULL, NULL),
	(875, 'خطای 96 در اطلاعات دریافت اطلاعات TMS در ارسال وب سرویس', 'با درود\r\nلاگ نمونه ضمیمه است\r\n', '202505-875', 3, 31, 'Condition_regect', 'low', NULL, '2025-05-05 10:04:21', '2025-05-05 10:51:11', NULL, NULL, NULL),
	(876, 'اضافه کردن نام پیمانکار جدید صدور کارت در اینتک', 'با سلام و احترام. خواهشمند است  نسبت به اضافه کردن نام پیمانکار جدید صدور کارت در نرم افزار اینتک مساعدت فرمایید.\r\nنام پیمانکار جدید: داتیس آریانا تیم\r\nنام مخفف: داتکو\r\nبا تشکر', '202505-876', 8, 36, 'Condition_final_done', 'low', NULL, '2025-05-05 12:21:07', '2025-07-19 09:06:05', NULL, NULL, NULL),
	(877, 'متد موجودی صندوق نام کاربری قبضینو', 'باسلام و احترام\r\nخواهمشند است متدی جهت مشاهده موجودی صندوق  قبضینو پیاده سازی گردد.\r\nباسپاس', '202505-877', 1, 25, 'Condition_final_done', 'high', NULL, '2025-05-05 15:34:28', '2025-05-18 08:07:35', NULL, NULL, NULL),
	(878, 'به روز رسانی Bin جدید شتاب میر', 'با درود\r\nبه روز رسانی Bin های اعطایی شتاب میر', '202505-878', 3, 31, 'Condition_final_done', 'high', NULL, '2025-05-06 05:28:04', '2026-02-22 13:16:49', NULL, NULL, NULL),
	(879, 'خطای 58 داخلی در تراکنش خرید ترمینال 10488349', 'با درود\r\nخطای 58 داخلی در تراکنش خرید ترمینال 10488349\r\n58-6-حساب در جدول شماره حساب ها برای ترمینال یافت نشد، خواهشمند است رفع بفرمایید\r\nبا تشکر', '202505-879', 3, 31, 'Condition_final_done', 'low', NULL, '2025-05-06 06:39:01', '2025-12-30 06:26:24', NULL, NULL, NULL),
	(880, 'نمایش مدل دستگاه در Warehouse  پرداخت نوین', 'خواهشمند است با توجه به پیاده سازی ارسال مدل دستگاه از سوی دستگاه پوز به سوئیح (در بیت 48 تگ شماره 4) \r\nترتیبی اتخاذ فرمایید که هنگام واکشی اطلاعات از دیتابیس سوئیچ به Warehouse  پرداخت نوین مدل دستگاه قابل نمایش باشد.\r\nنمونه تگ 48 ضمیمه تیکت شده است\r\n', '202505-880', 3, 10, 'Condition_final_done', 'medium', NULL, '2025-05-06 06:50:14', '2026-02-21 11:49:44', NULL, NULL, NULL),
	(881, 'افزودن شارژ از طریق برگشت از واریز', 'باسلام و احترام\r\nپیرو درخواست واحد مالی پرداخت نوین خواهشمند است در صورتی که ابتدا دشارژ کارت/گروهی کارت صورت گرفت و  مبلغ به صندوق واریز گردید. (سپس برای شارژ بعدی که از این مبالغ برگشت از واریز استفاده شد.) شارژ کارت های جدید با عنوان &quot; شارژ از طریق برگشت از واریز &quot; (و یا عنوان مشابه) قابل تفکیک از سایر شارژ های صورت گرفته باشد.\r\nباسپاس', '202505-881', 1, 25, 'Condition_regect', 'high', NULL, '2025-05-06 08:56:35', '2025-05-17 13:50:15', NULL, NULL, NULL),
	(882, 'عملیات گروهی رفع انسداد', 'باسلام و احترام \r\nپس از بارگذاری فایل در منو عملیات گروهی رفع انسداد، پیغام خطا نمایش داده شده ولی عملیات رفع انسداد صورت گرفته است.\r\nشناسه های به خطا خورده به پیوست ارسال می‌گردد.\r\nباسپاس', '202505-882', 1, 25, 'Condition_final_done', 'medium', NULL, '2025-05-06 10:26:13', '2026-02-21 11:49:29', NULL, NULL, NULL),
	(883, 'درخواست اصلاح نوع سند_ قبضینو', 'باسلام و احترام\r\nخواهشمند است بر روی گزارش گردش حساب (به عنوان نمونه شماره حساب 13407216 ) ، نوع سندهای برداشتی اصلاح گردد.\r\nدر حال حاضر نوع سند کلیه سندها ،  &quot; واریز &quot;   نمایش داده میشود.\r\nباسپاس', '202505-883', 1, 25, 'condition_in_progress', 'high', NULL, '2025-05-06 12:51:17', '2025-05-06 13:31:07', NULL, NULL, NULL),
	(884, 'مشکل ثبت سگمنت پیش فرض گروهی', 'با سلام و احترام \r\nبه استحضار می رساند کلیه ثبت ها از تاریخ 1403/02/08 در منو زیر اعمال نشده است\r\n عملیات گروهی&gt; سگمنت پیشفرض گروهی\r\n اندیکاتورها: 32951 - 3873 - 52126 - 47029 - 14926 - 52126\r\n با تشکر\r\n', '202505-884', 8, 36, 'Condition_final_done', 'high', NULL, '2025-05-07 07:36:26', '2025-07-19 09:06:02', NULL, NULL, NULL),
	(885, 'جستجوی پیشرفته کارت', 'باسلام و احترام\r\nدر منوی جستجوی پیشرفته کارت ، فیلد &quot; نام نمایندگی &quot; حذف شده است.\r\nخواهشمند است فیلد &quot; نام نمایندگی &quot; در منوی جستجوی پیشرفته کارت نمایش داده شود.\r\nباسپاس', '202505-885', 1, 25, 'Condition_final_done', 'medium', NULL, '2025-05-07 10:36:44', '2025-05-18 08:07:44', NULL, NULL, NULL),
	(886, 'عدم نمایش کلیه نام های کاربری ', 'باسلام و احترام\r\n در منو تعریف صندوق کلیه نام های کاربری نمایش  داده نمی شود.\r\nباسپاس', '202505-886', 1, 25, 'Condition_final_done', 'high', NULL, '2025-05-07 13:16:27', '2025-05-18 08:07:53', NULL, NULL, NULL),
	(887, 'درخواست تغییر عنوان صندوق', 'باسلام و احترام\r\nخواهشمند است عنوان صندوق های فایل پیوست تغییر یابد.\r\nباسپاس', '202505-887', 1, 25, 'Condition_final_done', 'medium', NULL, '2025-05-10 08:42:55', '2025-05-18 08:07:59', NULL, NULL, NULL),
	(888, 'مشکل تفکیک تراکنش های میرشتاب از سایر تراکنش ها در سوئیچ اینتک', 'باسلام و احترام\r\nپیرو راه اندازی تراکنش های میرشتاب در سوئیچ اینتک و الزام شاپرک مبنی بر ایجاد فرم 9 جداگانه برای تراکنش های فوق، به استحضار می رساند امکان تفکیک تراکنش های میرشتاب از سایر تراکنش ها در سوئیچ اینتک وجود ندارد.\r\nبدین منظور برای رفع مشکل و ارسال صحیح تراکنش ها در فرم 9 های جداگانه، خواهشمند است جهت اضافه نمودن فیلد جدید در SP شرکت اینتک دستورات لازم را مبذول فرمائید.\r\nEXEC B2STxn.dbo.GenerateSuccessTxn_Sep\r\nباتشکر\r\n', '202505-888', 4, 31, 'Condition_final_done', 'high', NULL, '2025-05-10 09:37:54', '2026-02-22 13:16:45', NULL, NULL, NULL),
	(889, 'خطای 03 در تراکنش پیکربندی 700 ترمینال 10524078', 'با درود\r\nخواهشمند است مشکل ترمینال 10524078 را در خصوص دریافت خطای 03 در هنگام تراگنش پیکربندی رفع نمایید\r\n\r\n', '202505-889', 3, 31, 'Condition_final_done', 'high', NULL, '2025-05-10 10:07:52', '2025-12-30 06:26:16', NULL, NULL, NULL),
	(890, 'فرمت تاریخ میلادی در خروجی اکسل گزارش تراکنش کارت', 'باسلام و احترام\r\nدر خروجی اکسل گزارش تراکنش کارت فرمت تاریخ میلادی می باشد.\r\nاین فرمت در گرید بصورت صحیح نمایش داده میشود.\r\nباسپاس', '202505-890', 1, 25, 'Condition_final_done', 'high', NULL, '2025-05-10 14:49:08', '2025-05-18 08:08:06', NULL, NULL, NULL),
	(891, 'خطای 2 بر روی پیکر بندی', 'با سلام و احترام\r\nپایانه 14508799 در پیکر بندی خطای 2 میدهد\r\nبا سپاس', '202505-891', 3, 34, 'Condition_final_done', 'medium', NULL, '2025-05-11 08:31:51', '2025-12-30 06:19:17', NULL, NULL, NULL),
	(892, 'انتقال پایانه های رفاه - فاز دوم', 'با سلام\r\nخواهشمند است انتقال پایانه های منصوبه بازاریابی شده وسط دفاتر و شرکت های پرداخت نوین به سوییچ شرکت رفاه صورت پذیرد.\r\nبا تشکر', '202505-892', 3, 10, 'Condition_final_done', 'high', NULL, '2025-05-11 12:22:05', '2026-02-21 11:48:53', NULL, NULL, NULL),
	(893, 'پیامک', 'باسلام و احترام\r\nخواهشمند است موارد ذیل اعمال گردد:\r\n1. برای کلیه تراکنش های کمتر از 50 هزار تومان ، برای دارنده کارت پیامک ارسال نگردد.\r\n2.برای ورود رمز اشتباه پیامک ارسال نگردد.\r\n3.برای تغییر رمز اول پیامک ارسال نگردد.\r\n4. لیستی از  انواع متن های ارسالی پیامک ارسال گردد.\r\nباسپاس', '202505-893', 1, 25, 'Condition_final_done', 'high', NULL, '2025-05-11 14:28:02', '2025-05-18 08:08:14', NULL, NULL, NULL),
	(894, 'افزودن کانفیگ پیامک بر روی بک آفیس صادرکنندگی ', 'باسلام و احترام\r\nخواهشمند است کانفیگ پیامک های صادرکنندگی بر روی بک آفیس نام کاربری admin پیاده سازی گردد.\r\nباسپاس', '202505-894', 1, 25, 'condition_in_progress', 'high', NULL, '2025-05-11 15:01:03', '2025-05-12 09:14:49', NULL, NULL, NULL),
	(895, 'ذخیره اقلام ارسالی برای رمز پویا', 'با سلام و احترام\r\n\r\nبدین‌وسیله به استحضار می‌رساند، اطلاعات مربوط به اقلام ارسالی موردنیاز رمز پویا می‌بایست در قالب یک View در دیتابیس ذخیره گردد لذا خواهشمند است دستور فرمایید تا مساعدت لازم در این زمینه انجام گیرد.\r\n\r\nبا تشکر', '202505-895', 4, 26, 'Condition_regect', 'medium', NULL, '2025-05-12 06:08:25', '2025-12-14 05:54:34', NULL, NULL, NULL),
	(896, 'ارائه فایل decrypt شماره تقاضای 614917', 'با شلام و احترام، خواهشمند است برای ارائه فایل decrypt شماره تقاضای 614917 جهت ارسال به شرکت پیمانکار صدور کارت اقدامات و دستورات لازم را مبذول نمایید با سپاس ', '202505-896', 8, 36, 'Condition_final_done', 'high', NULL, '2025-05-12 06:46:38', '2025-07-19 09:05:48', NULL, NULL, NULL),
	(897, 'موارد درخواستی در خصوص کارت اعتباری مولتی سگمنت (در این خصوص توضیحات لازم توسط آقای تفضلی به آقای محمدی ارائه شده و هماهنگی لازم بعمل آمده است)', 'باسلام و احترام،خواهشمند است در خصوص ارائه وب سرویس ساخت گروه کارت و اضافه نمودن کارت به گروه کارت در سوییچ پذیرندگی اقدامات لازم صورت پذیرد.\r\n\r\n(درخواست طی نامه وارده 11254 1404/02/16 شماره فرستنده 36984 چکیده صورت جلسه بررسی ابهامات کارت مولتی سگمنت مورخ 14040131)\r\n', '202505-897', 9, NULL, 'Condition_official_bill', 'low', NULL, '2025-05-12 07:36:41', '2025-08-05 09:18:24', 16, 9, 'CR416226'),
	(898, 'درخواست توسعه ماژول پروژه اتصال تاپ کارت به کیف پول اعتباری تاپ', 'بند 2 نامه:ایجاد قابلیت تخصیص کد سگمنت خاص به گروهی از کد خدمت ها.در بک آفیس پذیرندگی اینتک /منوی کارت چند منظوره /زیر منوی پروژه ها (در حال حاضر امکان تخصیص سگمنت فقط به یک کد خدمت وجود دارد.)\r\nبند 3 نامه:ایجاد قابلیت تخصیص گروهی پایانه ها به گروهی از کد خدمت ها .در بک آفیس پذیرندگی اینتک /منوی کارت چند منظوره /تخصیص پایانه گروهی(در حال حاضر امکان تخصیص گروه پایانه به یک کد خدمت وجود دارد.فقط یک پروژه قابل انتخاب است و نیازمندی این است چند پروژه انتخاب شده و برگزاری را بزنیم)', '202505-898', 9, NULL, 'Condition_regect', 'low', NULL, '2025-05-12 07:37:31', '2025-11-10 10:34:50', 16, 9, 'CR416272'),
	(899, 'عدم نمایش تراکنش', 'با سلام و احترام \r\nبه استحضار می رساند شماره کارت 5057854100165324 در تاریخ 111/02/1404 تراکنش 60.000.000 ریال  داشته بصورت موفق اما در تراکنش ها نمایش داده نمی شود.\r\nو این امر در خصوص خدمات رسانی و اطلاعات حساب دچار بحران می نماید\r\n', '202505-899', 3, 34, 'condition_acepted_test_auto', 'medium', NULL, '2025-05-12 08:49:12', '2026-10-07 16:08:21', NULL, NULL, NULL),
	(900, 'پیاده سازی متد شارژ صندوق  قبضینو ', 'باسلام و احترام\r\nخواهمشند است متدی جهت شارژ صندوق  قبضینو پیاده سازی گردد.\r\nباسپاس', '202505-900', 1, 25, 'Condition_final_done', 'high', NULL, '2025-05-12 09:22:04', '2025-05-18 08:08:21', NULL, NULL, NULL),
	(901, 'تست پروژه گواهی نماد (سدرا) در تاریخ یکشنبه 1404/02/28', 'با سلام و احترام\r\nباستحضار میرساند پیرو پیاده سازی پروژه گواهی نماد ( سدرا) زمان تست و آزمون بر روی INN برای شرکت پرداخت نوین در تاریخ یکشنبه 1404/02/28 با شرکت خدمات انجام خواهد شد.\r\nخواهشمند است  اقدامات لازم در این خصوص را به عمل را بعمل آورید.\r\n باتشکر \r\n', '202505-901', 3, 10, 'Condition_regect', 'high', NULL, '2025-05-13 04:26:52', '2025-05-18 11:19:13', NULL, NULL, NULL),
	(902, 'خطای 2 پایانه 14915565', 'با سلام و احترام\r\nپایانه 14915565 در پیکربندی خطای 2 میدهد', '202505-902', 3, 34, 'Condition_final_done', 'medium', NULL, '2025-05-13 06:27:02', '2025-12-30 06:19:13', NULL, NULL, NULL),
	(903, 'عدم بروز بودن اطلاعات تراکنش', 'با سلام و احترام \r\nبه استحضار می رساند تاریخ تراکنش 11/02/1404 می باشد اما در سامانه که چک می کنیم یک روز عقب تر را نششان می دهد 140/02/10 لطفا در اسرع زمان ممکن بررسی نمایید .\r\nبا کمال ادب و احترام ', '202505-903', 8, 46, 'Condition_final_done', 'medium', NULL, '2025-05-13 06:47:04', '2025-12-30 06:23:49', NULL, NULL, NULL),
	(904, 'عدم تراکنش روی برخی از کارتخوان ها و اعلام مشکل دارنده کارت مجاز به این تراکنش نیست ', 'روی برخی از کارتخوان ها پاسخ نمی دهد در صورتیکه سمت سوئیچ هیچ پاسخی نمی آید برخی از تراکنش ها پاسخ با تاریخ مغایرت دارد . ', '202505-904', 3, 46, 'Condition_regect', 'medium', NULL, '2025-05-13 07:21:45', '2025-05-17 12:02:05', NULL, NULL, NULL),
	(905, 'کد خطا 14', 'باسلام و احترام\r\nبر روی شماره کارت 6274124491521930 ( کلیه تراکنش ها ) کد خطا 14 رخ می دهد.\r\nخواهشمند است علت کد خطا 14 اعلام گردد.\r\nباسپاس', '202505-905', 3, 25, 'Condition_final_done', 'high', NULL, '2025-05-14 13:41:54', '2026-02-21 09:08:16', NULL, NULL, NULL),
	(906, 'پورت جدید جهت تست  bin 1 با سوئیچ تستی شاپرک', 'با سلام\r\nخواهشمند است جهت ارتباط با  با سوئیچ تستی خدمات پورت جدیدی جهت( تست BIN1) ایجاد نمائید.\r\nبا سپاس', '202505-906', 3, 10, 'Condition_regect', 'medium', NULL, '2025-05-18 13:58:50', '2025-05-19 08:15:31', NULL, NULL, NULL),
	(907, 'عدم افزایش موجودی کارت پس از واریز ', 'با سلام، طبق فایل های  پیوست شامل گزارشات بکاقیس و سایر موارد 4 عدد کارت شرکت عل بابا پس از واریز وجه به موجودی اضافه نشده است. لطفا در اسرع وقت پیگیری نمایید با سپاس ', '202505-907', 8, 36, 'Condition_final_done', 'high', NULL, '2025-05-19 06:03:56', '2025-07-19 09:05:44', NULL, NULL, NULL),
	(908, 'غیر فعال سازی ترمینال ها', 'با سلام\r\nخواهمند است ترمینال های لیست پیوست غیرفعال گردد.', '202505-908', 3, 10, 'Condition_final_done', 'high', NULL, '2025-05-19 09:05:09', '2026-02-21 11:47:41', NULL, NULL, NULL),
	(909, 'خطای 2 پایانه 13322726', 'با سلام و احترام\r\nپایانه 13322726 دارای خطای 2 میباشد.لازم به ذکر است چندین مرتبه تعویض پایانه زده شد اما همچنان خطای 2 میدهد\r\nبا سپاس', '202505-909', 3, 34, 'Condition_final_done', 'medium', NULL, '2025-05-19 10:20:18', '2025-12-30 06:18:54', NULL, NULL, NULL),
	(910, 'اعلام بروز خطا در تراکنش شماره مرجع 200027376299 و درخواست بررسی', 'با سلام و احترام،\r\nبدین‌وسیله به اطلاع می‌رساند یک تراکنش با شماره مرجع (RRN) 200027376299 با خطای &quot;Internal Server Error - 500&quot; مواجه شده است.\r\n\r\nبر اساس پیگیری‌های به‌عمل‌آمده، پذیرنده مربوطه از سایت وردپرس برای ثبت و پردازش سفارشات خود استفاده می‌نماید و پیام خطای مذکور در بخش لیست سفارش‌های وردپرس این پذیرنده نمایش داده شده است.\r\n\r\nخواهشمند است ضمن بررسی موضوع، در صورت وجود هرگونه اشکال در مسیر پردازش تراکنش، اقدامات لازم جهت رفع آن را در اسرع وقت به‌عمل آورده و نتیجه را اعلام فرمایید.\r\n\r\nبا تشکر و احترام', '202505-910', 7, 26, 'Condition_final_done', 'high', NULL, '2025-05-19 10:31:30', '2026-04-05 06:43:41', NULL, NULL, NULL),
	(911, 'ارسال تسویه تراکنش های فارا در بازه زمانی 1 دقیقه', 'با سلام و احترام\r\nطبق مذاکره انجام شده با شرکت فارا و اجبار این شرکت مبنی بر ارسال  تسویه تراکنش ها در بازه زمانی 1 دقیقه خواهشمند است اقدامات لازم  جهت اعمال تغییرات در زمان Cut-off  روز مالی  1404-02-28، را مبذول فرمایید.\r\nبا تشکر\r\n', '202505-911', 3, 10, 'Condition_final_done', 'high', NULL, '2025-05-19 11:03:24', '2026-02-21 11:47:29', NULL, NULL, NULL),
	(912, 'کد خطا 57', 'باسلام و احترام\r\nتراکنش های صورت گرفته با شماره کارت     6274124491313304 ، کد خطا 57 دریافت می نمایند.\r\nخواهشمند است علت خطا را بررسی و اعلام بفرمایید.\r\nباسپاس', '202505-912', 1, 25, 'Condition_final_done', 'high', NULL, '2025-05-20 06:15:26', '2026-02-21 09:08:25', NULL, NULL, NULL),
	(913, 'نمایش کدملی تکراری در فایل صدور ', 'باسلام و احترام\r\nدر فایل صدور در صورتی که کدملی تکراری وجود داشته باشد، \r\nبه تعداد کد ملی های تکراری کارت صادر می‌گردد.\r\nباسپاس', '202505-913', 1, 25, 'Condition_final_done', 'high', NULL, '2025-05-20 07:14:44', '2026-02-21 11:47:02', NULL, NULL, NULL),
	(914, 'خطای 58 ترمینال رفاهی', 'با سلام \r\nترمینال های رفاهی خطای 58 دریافت میکنند\r\nخواهشمند است بررسی فرمایید.\r\nنمونه\r\n30255357', '202505-914', 3, 10, 'Condition_final_done', 'high', NULL, '2025-05-20 07:39:16', '2026-02-21 09:08:32', NULL, NULL, NULL),
	(915, ' بروز رسانی سیستم های عامل نسخه ویندوز در تاریخ   1404-03-02', 'با سلام و احترام\r\n     به استحضار می رساند در بامداد جمعه 2 خرداد بروز رسانی سیستم های عامل نسخه ویندوز انجام می گردد. خواهشمن است ضمن معرفی نماینده فنی شرکت اینتک، تمامی مالکین سرویس ها نسبت به صحت سرویس دهی پس از ریست شدن سرور ها اقدام فرمایند.\r\nبا سپاس\r\n', '202505-915', 1, 10, 'Condition_final_done', 'high', NULL, '2025-05-20 07:47:56', '2026-02-21 11:48:08', NULL, NULL, NULL),
	(916, 'گزارش اختلال های پیش آمده در روزهای 29-02-1404 و 30-02-1404 بروی سوئیچ', 'با سلام و احترام\r\nبا توجه به اختلال های پیش آمده در روزهای 29-02-1404 و 30-02-1404 بروی سوئیچ، خواهشمند است گزارش کالمی از دلایل اختلال اعلام فرمایید.\r\nبا سپاس', '202505-916', 1, 10, 'Condition_regect', 'high', NULL, '2025-05-20 08:11:37', '2025-10-05 08:11:41', NULL, NULL, NULL),
	(917, 'SMS Issuer', 'باسلام و احترام\r\nخواهشمند است :\r\n1. پیامک های سوییچ صادرکنندگی با نام کاربری ذیل ارسال گردد.\r\nنام کاربری\r\nIntek_issuer\r\nرمز عبور \r\nIntek_issuer@2025\r\n\r\n2.پیامک رونوشت کارت &quot; ارسال نگردد &quot;\r\n\r\nباسپاس', '202505-917', 1, 25, 'Condition_final_done', 'high', NULL, '2025-05-20 10:04:38', '2026-02-21 11:46:43', NULL, NULL, NULL),
	(918, 'تغییر شماره شبا ', 'با سلام\r\nخواهشمند است برای ترمینال 30681482 شماره شبای جدید در دیتا بیس رفاه ثبت گردد.\r\n\r\nIR200600461301008890140001', '202505-918', 3, 10, 'Condition_final_done', 'high', NULL, '2025-05-20 12:32:59', '2026-02-21 11:46:28', NULL, NULL, NULL),
	(919, 'خطای 3 پایانه 14634920', 'با سلام و احترام\r\nپایانه 14634920 دارای خطای 3 میباشد\r\nبا سپاس', '202505-919', 3, 49, 'Condition_final_done', 'medium', NULL, '2025-05-21 07:59:38', '2025-12-30 06:18:49', NULL, NULL, NULL),
	(920, 'درخواست بررسی شارژ برای برخی ترمینال‌ها', 'با سلام و احترام\r\n\r\nاحتراماً، به استحضار می‌رساند بر اساس بررسی‌های انجام‌شده، در برخی تراکنش‌های مربوط به سرویس شارژ (PPrCode = 22) با مقادیر = ResponseCode 12 و InternalReasonCode = 11، خطاهایی مشاهده شده که حاکی از وجود اختلال احتمالی در سرویس مذکور برای برخی ترمینال‌ها می‌باشد.\r\nبا تشکر\r\n\r\nشماره کارت        شماره ترمینال\r\n200028075493      70012614\r\n200028075407      70023967\r\n200028075205      70023967\r\n200028075133      70036261\r\n200028075047      70036261\r\n200028074980      70020006', '202505-920', 3, 26, 'Condition_final_done', 'high', NULL, '2025-05-21 08:46:20', '2026-04-05 06:43:34', NULL, NULL, NULL),
	(921, 'اضافه کردن نام پیمانکار جدید صدور کارت در اینتک', 'با سلام و احترام. خواهشمند است مطابق با دستور مدیر عامل محترم  نسبت به اضافه کردن نام پیمانکار جدید صدور کارت در نرم افزار اینتک مساعدت فرمایید. \r\nنام پیمانکار جدید: زرین کارت صنعتی\r\nبا تشکر\r\n', '202505-921', 8, 36, 'Condition_final_done', 'high', NULL, '2025-05-21 12:06:47', '2025-07-19 09:05:42', NULL, NULL, NULL),
	(922, 'اعلام بروز خطا در تراکنش شماره مرجع 200028598442 و درخواست بررسی', 'با سلام و احترام،\r\nبدین‌وسیله به اطلاع می‌رساند یک تراکنش با شماره مرجع (RRN) 200028598442 با خطای &quot; عملیات ناموفق و کد پاسخ درگاه E22-1 &quot; مواجه شده است.\r\n\r\nبر اساس پیگیری‌های به‌عمل‌آمده، پذیرنده مربوطه از سایت وردپرس برای ثبت و پردازش سفارشات خود استفاده می‌نماید و پیام خطای مذکور در بخش لیست سفارش‌های وردپرس این پذیرنده نمایش داده شده است.\r\n\r\nخواهشمند است ضمن بررسی موضوع، در صورت وجود هرگونه اشکال در مسیر پردازش تراکنش، اقدامات لازم جهت رفع آن را در اسرع وقت به‌عمل آورده و نتیجه را اعلام فرمایید.\r\n\r\nبا تشکر و احترام', '202505-922', 7, 26, 'Condition_final_done', 'high', NULL, '2025-05-24 05:34:23', '2026-05-12 07:32:57', NULL, NULL, NULL),
	(923, 'حذف یوزر ادمین و ایجاد یوزرهای جدید', 'با سلام و احترام\r\nخواهشمند است تمامی یوزرهای ادمین بک افیس جدید حذف گردد\r\nو برای افرادلیست پیوست یوزر ایجاد گردد\r\nبا تشکر\r\n\r\n', '202505-923', 1, 10, 'Condition_final_done', 'high', NULL, '2025-05-24 05:56:00', '2026-02-21 11:46:17', NULL, NULL, NULL),
	(924, 'نمایش علت خطا بر روی بک آفیس', 'باسلام و احترام\r\nخواهشمند است بر روی بک آفیس در منو گزارش تراکنش ها،  علت خطا نمایش داده شود.\r\nباسپاس', '202505-924', 1, 25, 'Condition_final_done', 'high', NULL, '2025-05-24 06:42:27', '2026-02-21 09:08:44', NULL, NULL, NULL),
	(925, 'کد 57', 'باسلام و احترام\r\nتراکنش های صورت گرفته با شماره کارت     6274124491555797 ، کد خطا 57 دریافت می نمایند.\r\nشایان ذکر است شماره کارت مذکور قبلا دارای تراکنش موفق بوده است.\r\nخواهشمند است علت خطا را بررسی و اعلام بفرمایید.\r\nباسپاس', '202505-925', 1, 25, 'Condition_final_done', 'high', NULL, '2025-05-24 07:13:38', '2026-02-21 11:46:09', NULL, NULL, NULL),
	(926, 'یوزر نیم و پسورد برای خانم کمایی جهت استفاده از  Mongo\\ Shell ', 'با سلام\r\nخواهشمند است یوزر نیم و پسورد برای خانم کمایی جهت استفاده از  Mongo\\ Shell ایجاد گردد.\r\nبا تشکر', '202505-926', 3, 10, 'Condition_final_done', 'medium', NULL, '2025-05-24 14:17:42', '2026-02-21 11:46:04', NULL, NULL, NULL),
	(927, 'تغییر کلید تغییر کلید عمومی  سامانه ارزش افزوده  شاپرک مربوط به جمع آوری  تسهیم  وجوه دولتی در ساعت 6 صبح  روز دوشنبه مورخ 05/03/1404', 'با سلام و احترام،\r\n با عنایت به نامه ارسال شده از سوی شرکت شاپرک در خصوص  تغییر کلید عمومی  سامانه ارزش افزوده  شاپرک مربوط به جمع آوری  تسهیم  وجوه دولتی ، خواهشمند است  اقدامات  لازم در این خصوص صورت پذیرد. \r\nلازم به ذکر است کلید مذکور در ساعت 6 صبح  روز دوشنبه مورخ 05/03/1404  تغییر خواهد یافت .\r\nفایل های مورد نیاز ایمیل خواهد شد. \r\nباتشکر \r\n', '202505-927', 3, 10, 'Condition_regect', 'high', NULL, '2025-05-24 14:34:28', '2025-05-27 11:06:45', NULL, NULL, NULL),
	(928, 'دسترسی به تعریف سگمنت ', 'سلام روز بخیر\r\n1- ما میخواهیم روی سگمنت تعاریفی انجام بدیم قبلا این دسترسی باز بوده \r\n2- روی دسترسی که می رویم پیام می دهد دسترسی محدود شده است \r\n3-با دسترسی ادمین بررسی و چک نموده ایم \r\n4-سطح دسترسی بررسی شده است \r\n5- برای بررسی با شماره 09351003290 لطفا تماس بگیرید \r\n6- در صورت نامفهموم بودن نیز لطفا تماس حاصل فرمایید ', '202505-928', 4, 46, 'condition_acepted_test_auto', 'medium', NULL, '2025-05-25 04:29:10', '2026-10-07 16:08:21', NULL, NULL, NULL),
	(929, 'دریافت Status در قالب Form Data هنگام عملیات انصراف', 'با سلام و احترام؛\r\n\r\nبدین‌وسیله به اطلاع می‌رساند به منظور دریافت اطلاعات عملیات انصراف در درگاه پرداخت اینترنتی، خواهشمند است دستور فرمایید فیلد جدیدی با عنوان &quot;status&quot; در قالب Form Data افزوده شود.\r\nبا تشکر', '202505-929', 7, 26, 'condition_acepted_test_auto', 'high', NULL, '2025-05-25 12:40:11', '2026-05-12 12:00:31', NULL, NULL, NULL),
	(930, 'افزودن اطلاعات به مانیتورینگ جدید- Intek Monitoring', 'با سلام\r\nخواهشمند است دیتای نودهای 101و 108 و 3و 10و 25  \r\nبه Intek Monitoring  (10.0.71.111:8085) بخش Stats اضافه گردد.\r\nبا تشکر', '202505-930', 3, 10, 'Condition_final_done', 'medium', NULL, '2025-05-25 12:44:02', '2026-02-21 11:45:59', NULL, NULL, NULL),
	(931, ' عدم بروز بودن اطلاعات تراکنش ( 202505-903 ) مورد  تایید نمی باشد و اعلام نموده', 'با سلام و احترام \r\nتوضح اصلا قانع کننده نیست اگر اطلاعات کارتخوان هم بفرض اشتباه باشد نباید اطلاعات کارت روز قبل را نشان دهد1- آیا سامانه  با زمان کارتخوان شبکه شتاب کار می کند؟ 2- رسید ارسالی برای روز قبل است ؟ (حداقل تصویر رسید کارتخوان را یکبار باز کنید نگاه کنید ) لطفا بررسی مناسب صورت پذیرد و جواب در حد معقول ارسال گردد .تاریخ تراکنش به لحظه باید باشد و بر پایه اطلاعات دیتا بیس. . . . . .\r\n(پاسخ شما :چون زمان کارتخوان اشتباه بوده تراکنش در اینتک در روز گذشته ثبت شده)این امر مغایر با عملکرد شتاب است و اطلاعات ارسالی از دیتا بیس ارسال می شود و همخوانی دارد حتی در خودپرداز اطلاعات مشتری توسط EPP رمزگزاری میشود و ارسال میشود و اطلاعات ارسالی از سوئیچ بانک  ارسال و دریافت می گردد.', '202505-931', 8, 46, 'condition_acepted_test_auto', 'medium', NULL, '2025-05-26 07:31:41', '2026-10-07 16:08:21', NULL, NULL, NULL),
	(932, 'خطای 3 پایانه 13207650', 'با سلام\r\nپایانه 13207650 دارای خطای 3 میباشد\r\nبا سپاس', '202505-932', 3, 49, 'Condition_final_done', 'medium', NULL, '2025-05-26 08:21:13', '2025-12-30 06:18:45', NULL, NULL, NULL),
	(933, 'تمدید تاریخ انقضا کارت هدیه', 'باسلام و احترام\r\nخواهشمند است تاریخ انقضا کارت های هدیه فایل پیوست به مدت&quot;  یک سال &quot; تمدید گردد.\r\nباسپاس', '202505-933', 1, 25, 'Condition_final_done', 'high', NULL, '2025-05-26 12:22:17', '2026-02-21 11:45:51', NULL, NULL, NULL),
	(934, 'گزارش بانک اقتصاد نوین_ اولویت بالا', 'باسلام و احترام\r\nخواهشمند است گزارش درخواستی بانک اقتصاد نوین ارسال گردد.\r\nباسپاس', '202505-934', 1, 25, 'condition_in_progress', 'high', NULL, '2025-05-26 13:49:44', '2025-05-27 07:11:18', NULL, NULL, NULL),
	(935, 'پیاده سازی گزارش مانده کارت ', 'باسلام و احترام\r\nبا توجه به نامه ارسالی بانک اقتصاد نوین ( فایل پیوست )، خواهشمند است گزارش  &quot; مانده کارت در پایان هر ماه به تفکیک شماره کارت &quot;  بر روی بک آفیس پیاده سازی گردد.\r\n باسپاس', '202505-935', 1, 25, 'condition_in_progress', 'high', NULL, '2025-05-26 14:01:00', '2025-05-27 07:09:27', NULL, NULL, NULL),
	(936, 'متد استعلام اطلاعات کارت', 'باسلام و احترام\r\nپیرو  پیاده سازی سرویس شارژ بن کارت، خواهشمند است متد استعلام اطلاعات کارت به گونه ای پیاده سازی گردد که شماره کارت پارامتر ورودی  و نام دارنده کارت به همراه شماره کارت به عنوان پارامتر خروجی نمایش داده شود.\r\nباسپاس', '202505-936', 1, 25, 'Condition_final_done', 'high', NULL, '2025-05-27 06:33:33', '2026-02-21 11:47:52', NULL, NULL, NULL),
	(937, ' داخلی 4577 - 04 1404/02/14 -درخواست دسترسی سرویس های پروژه کارت مجازی', 'جهت پیاده سازی کارت مجازی شهروند نیاز به پیاده سازی سرویس های زیر می باشد:\r\nسرویس کارت: امکان رونوشت کارت\r\nسرویس مارکت کردن ترمینال و گروه پذیرندگی (اضافه /حذف ترمینال جدید در گروه پذیرندگی)\r\nامکان گزارش گیری : گزارش تراکنش کارت های مجازی روی مارکت ذکر شده بر اساس شناسه ملی پایانه ', '202505-937', 0, NULL, 'condition_pending', 'low', NULL, '2025-05-27 07:17:03', '2025-05-27 07:17:03', 16, 9, 'CR419771'),
