	(939, 'داخلی 4577 - 04 1404/02/14 -درخواست دسترسی سرویس های پروژه کارت مجازی', 'جهت پیاده سازی کارت مجازی شهروند نیاز به پیاده سازی سرویس های زیر می باشد:\r\nسرویس کارت: امکان رونوشت کارت\r\nسرویس مارکت کردن ترمینال و گروه پذیرندگی (اضافه /حذف ترمینال جدید در گروه پذیرندگی)\r\nامکان گزارش گیری : گزارش تراکنش کارت های مجازی روی مارکت ذکر شده بر اساس شناسه ملی پایانه\r\n', '202505-939', 2, NULL, 'Condition_official_bill', 'low', NULL, '2025-05-27 08:14:24', '2025-08-05 09:19:25', 1, 9, 'CR419771'),
	(940, 'خطای 3 پایانه 14878215', 'با سلام و احترام\r\nپایانه 14878215 در خرید دارای خطای 3 میباشد.\r\nبا سپاس', '202505-940', 3, 49, 'Condition_final_done', 'medium', NULL, '2025-05-27 12:00:03', '2025-12-30 06:18:41', NULL, NULL, NULL),
	(941, 'پیگیری نامه 8010 پرگار', 'باسلام و احترام به اطلاع میرساند باتوجه به این که قبلا پیمانکار مستقیم تاپ در اینتک در قسمت تعاریف--&gt;  انبار کارت پیمانکاران ---&gt; مخزن کارت طرح رو جستجو میکردن و بعددر قسمت عملیات --&gt; انواع کارت بوده که اضافه میکردند در حال حاضر این دسترسی گرفته شده و امکان اضافه نمودن طرح مورد نظر در اینتک را ندارند. خواهشمند است جهت اضافه شدن ستون درخواست شده به پیمانکار مستقیم تاپ دستور مقتضی صادر فرمایید تا امکان صدور کارتها هرچه سریعتر امکان پذیر باشد. باتشکر\r\nدرخصوص صدور کارتهای زندان سمت پیمانکاران  (این متن ارجاع نامه از واحد صدور کارت می باشد و نامه هم پیوست شده است.) ', '202505-941', 8, 36, 'Condition_final_done', 'high', NULL, '2025-05-31 07:00:40', '2025-07-19 09:05:38', NULL, NULL, NULL),
	(942, 'خطای 3 پایانه 13190130', 'با سلام و احترام\r\nپایانه 13190130 دارای خطای 3 میباشد.\r\nبا سپاس', '202505-942', 3, 49, 'Condition_final_done', 'medium', NULL, '2025-05-31 10:11:48', '2025-12-30 06:18:37', NULL, NULL, NULL),
	(943, 'خطای 2 پایانه 14508804', 'با سلام و احترام\r\nپایانه 14508804 دارای خطای 2 میباشد\r\nبا سپاس', '202505-943', 3, 49, 'Condition_final_done', 'medium', NULL, '2025-05-31 10:12:38', '2025-12-30 06:18:36', NULL, NULL, NULL),
	(944, 'خطای 33', 'باسلام و احترام\r\nخواهشمند است علت خطای 33 کارت ذیل بررسی گردد.\r\n6274-1233-3051-8446\r\n\r\nباسپاس', '202505-944', 1, 25, 'Condition_final_done', 'high', NULL, '2025-05-31 11:18:55', '2026-02-21 09:10:36', NULL, NULL, NULL),
	(945, 'خطای تغییر حساب ', 'با سلام\r\nپایانه های زیر تغییر حساب انجام داده اند.\r\nاما روی سوییچ اینتک حساب قبلی را چک میکند و بنابراین خطای 03 مشاهده میشود \r\nدر صورتیکه باید حساب جدید چک شود\r\n\r\nپایانه 1\r\n30761057\r\nشماره شبای قدیم\r\nIR500130100000000297516474\r\nشماره شبای جدید\r\nIR250210000003000255024371\r\n\r\nپایانه 2\r\n30753787\r\nشماره شبای قدیم\r\nIR500130100000000297516474\r\nشماره شبای جدید\r\nIR250210000003000255024371\r\n\r\nهر دو پایانه متعلق به یک شخص می باشد.', '202505-945', 3, 10, 'Condition_final_done', 'high', NULL, '2025-05-31 14:46:33', '2026-02-21 11:45:32', NULL, NULL, NULL),
	(946, 'اختلال در کانال های تستی', 'با سلام\r\nعدم امکان تراکنش خرید روی کانال تستی 40800 و 4080\r\nخواهشمند است بررسی شود.', '202506-946', 3, 10, 'Condition_final_done', 'high', NULL, '2025-06-01 09:17:13', '2025-09-09 10:38:08', NULL, NULL, NULL),
	(947, 'اعلام بروز خطا در تراکنش شماره مرجع 200031615016 و درخواست بررسی', 'با سلام و احترام،\r\nبدین‌وسیله به اطلاع می‌رساند یک تراکنش با شماره مرجع (RRN) 200031615016 با خطای &quot;Internal Server Error - 500&quot; مواجه شده است.\r\nخواهشمند است ضمن بررسی موضوع، در صورت وجود هرگونه اشکال در مسیر پردازش تراکنش، اقدامات لازم جهت رفع آن را در اسرع وقت به‌عمل آورده و نتیجه را اعلام فرمایید.\r\n\r\nبا تشکر و احترام', '202506-947', 7, 26, 'Condition_final_done', 'high', NULL, '2025-06-01 10:36:23', '2026-02-22 14:06:18', NULL, NULL, NULL),
	(948, 'درخواست برگرداندن کلید data در متد confirm-transaction', 'با سلام و احترام،\r\n\r\nبدین‌وسیله خواهشمند است دستور فرمایید در پاسخ JSON وب‌سرویس، متد confirm-transaction، کلید مورد استفاده قبلی با عنوان data برگردانده شود که شامل اطلاعات زیر بوده است:\r\n• token\r\n• CardNumberMasked\r\n• RRN\r\nاز همکاری و مساعدت جنابعالی کمال تشکر را داریم.\r\n', '202506-948', 7, 26, 'Condition_final_done', 'high', NULL, '2025-06-01 10:54:28', '2026-05-12 07:33:04', NULL, NULL, NULL),
	(949, 'ارائه  فایل اطلاعات  track2 کارت شماره تقاضا 615837', 'با سلام و احترام، خواهشمند است نسبت به ارائه فایل اطلاعات  track2 کارت شماره تقاضای 615837 برای رایت روی CD و ارائه به پیمانکار صدور کارت دستورات و  اقدامات لازم را مبذول نمایید. با سپاس ', '202506-949', 8, 36, 'condition_in_progress', 'high', NULL, '2025-06-02 04:46:39', '2025-06-02 08:13:07', NULL, NULL, NULL),
	(950, ' اعلام ID گروه کارت های مولتی سگمنت-اندیکاتور 11252', 'در سرویس set settle mentبرای تخصیص مدل تسهیم پایانه ، تعدادی گروه کارت تعریف شده که جهت استفاده در سرویس نیاز به Card Group ID آنها می باشد.گروه کارتهای ایجاد شده در تصویر پیوست ارائه می گردد.\r\nمستند جهت ارائه به بهره برداران اماده و فقط نیاز به اعلام این مورد می باشد.لذا خواهشمند است تسریع فرمائید.', '202506-950', 4, 37, 'Condition_final_done', 'medium', NULL, '2025-06-02 06:54:48', '2026-02-22 13:52:31', NULL, NULL, NULL),
	(951, 'بررسی خطا با Response code=12', 'با سلام و احترام  خواهشمند است علت افزایش  خطای زیر در تاریخ های 11و 10 خرداد ماه 1404 بررسی گردد\r\nResponse code=12\r\ninternal reason code=11 \r\nنمونه ترمینال \r\n30712682\r\n11647134', '202506-951', 3, 10, 'Condition_final_done', 'medium', NULL, '2025-06-02 10:30:55', '2026-02-21 09:07:38', NULL, NULL, NULL),
	(952, 'وجود مغایرت شماره تلفن همراه پس از اصلاح و تغییر ، در منوهای مختلف اینتک - اندیکاتور7981', '\r\nپس از تغییر شماره کارت در منوی کارت /اطلاعات تماس، اصلاح مشخصات بطور کامل انجام نمی شود و مطابق تصویر پیوست در قسمتی شماره همراه قدیم مشتری و در جائی دیگر شماره جدید نمایش داده می شود.این موضوع هنگام فعالسازی کارت به روش پیامکی باعث نمایش خطای &quot; اطلاعات وارد شده صحیح نمی باشد&quot; می شود.تصویر نامه با شرح کامل و و نیز تصویر نمایش خطای اعلام شده جهت بهره برداری به پیوست می باشد\r\n', '202506-952', 9, NULL, 'Condition_regect', 'medium', NULL, '2025-06-02 11:38:39', '2025-07-12 08:41:14', 16, 9, 'CR420945'),
	(953, 'غیر فعال کردن ترمینال پس از دریافت خطای 03 از شاپرک', 'با سلام و احترام\r\nخواهشمند است ترمینال هایی که از شاپرک یکبار کد خطای 03  (03=responce code) دریافت می کنند، غیر فعال شوند.\r\nآقای محب تایید دادند.\r\nبا سپاس', '202506-953', 3, 10, 'Condition_final_done', 'high', NULL, '2025-06-02 15:01:30', '2026-02-21 11:44:31', NULL, NULL, NULL),
	(954, 'صندوق مجازی امیران', 'باسلام و احترام\r\nخواهشمند است صندوق مجازی امیران برای نام کاربری ذیل ایجاد گردد.\r\namiranSandogh\r\nباسپاس', '202506-954', 1, 25, 'Condition_final_done', 'high', NULL, '2025-06-03 05:53:58', '2026-02-21 11:44:26', NULL, NULL, NULL),
	(955, 'خطا 14', 'باسلام و احترام\r\nخواهشمند است علت کد خطا تراکنش های صورت گرفته با شماره کارت ذیل بررسی گردد.\r\n6274124499507543\r\nباسپاس', '202506-955', 1, 25, 'Condition_final_done', 'high', NULL, '2025-06-03 07:49:29', '2025-12-30 06:03:59', NULL, NULL, NULL),
	(956, 'علت کدخطاهای سرویس شارژ بن کارت', 'باسلام و احترام\r\nخواهشمند است فایلی مبنی بر نمایش علت کدخطاهای سرویس شارژ بن کارت ارسال گردد.\r\nباسپاس', '202506-956', 1, 25, 'condition_in_progress', 'high', NULL, '2025-06-07 07:23:57', '2025-06-07 09:37:15', NULL, NULL, NULL),
	(957, 'گزارش بانک اقتصاد نوین', 'باسلام و احترام \r\nخواهشمند است &quot; گزارش تراکنش کارت&quot;  از تاریخ  01-11-1403 تا تاریخ 10-03-1404 برای کلیه کارت های صادر شده ارسال گردد.\r\nشایان ذکر است گزارش مذکور بر روی بک آفیس صادرکنندگی خروجی نمی دهد. \r\nباسپاس', '202506-957', 1, 25, 'Condition_final_done', 'high', NULL, '2025-06-07 07:46:43', '2026-02-21 11:44:47', NULL, NULL, NULL),
	(958, 'اطلاعات مورد نیاز  جهت تست شناسه بهداد', 'با سلام\r\nاطلاعات مورد نیاز  جهت تست شناسه بهداد خدمتتان ارسال می گردد.\r\nترمینال دامپزشکی:31135144\r\nIBAN: IR590100004001038301006103\r\n\r\nدرآمد حاصل از خدمات بهداشتی - ماده 14: کد ردیف درآمدی 140104\r\nحساب: 4001038301006103\r\n\r\nدرآمد موضوع ماده (5) قانون نظارت شرعی بر ذبح و صید: کد ردیف درآمدی 160125\r\nحساب: 4001038301016201\r\n\r\nتبصره 23 - تمرکز وجوه درآمد عوارض حاصل از داروهای دامی آماده به مصرف: کد ردیف درآمدی 160176\r\nحساب: 4001038301019288\r\n\r\nکد ردیف درآمدی رقم 10 تا 15 شناسه واریز هست\r\n', '202506-958', 3, 10, 'Condition_regect', 'high', NULL, '2025-06-07 10:02:43', '2025-07-09 08:33:02', NULL, NULL, NULL),
	(959, 'زمان تراکنش-پیامک', 'باسلام و احترام\r\nزمان تراکنش بر روی پیامک های ارسالی شماره موبایل  09116647910 متعلق به شماره کارت ذیل، اشتباه می‌باشد.\r\nنمونه زمان تراکنش اشتباه جهت بررسی به پیوست ارسال می‌گردد.\r\nخواهشمند است بررسی بفرمایید.\r\n6274-1244-9000-0571\r\nباسپاس', '202506-959', 1, 25, 'Condition_final_done', 'high', NULL, '2025-06-07 10:35:13', '2026-02-21 11:44:10', NULL, NULL, NULL),
	(960, 'درخواست ایجاد رمز یکسان برای سفر کارت های خرید گروه باختر', 'باسلام واحترام \r\nباتوجه به اين كه براي دارنده كارت رمز اينترنتي صادر نشده ؛ خواهشمند است برای  لیست شماره کارتهای ضمیمه شده ‍ رمز اينترنتي یکسان 123456 صادر شود. خواهشمند است در اين خصوص دستورات لازم صادر فرماييد. باتشكر', '202506-960', 8, 36, 'Condition_final_done', 'high', NULL, '2025-06-07 10:49:04', '2025-07-19 09:05:34', NULL, NULL, NULL),
	(961, 'مشاهده تعداد بالای  خطای با Response code=12 , internal reason code= 11', 'با سلام \r\nبه صورت روزانه تعداد زیادی خطای &quot;سرویس پرداخت نامعتبر است&quot;مشاهده میشود\r\n  خطای با  Response code=12 , internal reason code= 11 \r\nخواهشمند است بررسی و علت مشخص گردد\r\nنمونه RRN جهت بررسی 511817611330 \r\n\r\nبا سپاس\r\n', '202506-961', 3, 10, 'Condition_final_done', 'high', NULL, '2025-06-07 13:13:12', '2026-02-21 11:43:54', NULL, NULL, NULL),
	(962, 'درخواست بررسی و رفع مشکل عدم تطابق پیام‌های خطای تراکنش با کدهای پاسخ', 'با سلام و احترام،\r\n\r\nبدین‌وسیله به استحضار می‌رساند در فرآیند انجام تراکنش‌های پرداخت اینترنتی از طریق درگاه، مواردی از عدم تطابق میان کدهای پاسخ تراکنش (ResponseCode) و پیام‌های نمایشی به کاربران مشاهده شده است که موجب سردرگمی کاربران و افزایش مراجعات پشتیبانی گردیده است.\r\n\r\nبه عنوان مثال، در شرایطی که تراکنش به علت عدم موجودی کافی کارت بانکی کاربر با شکست مواجه می‌شود، پیام نمایشی به صورت کلی و غیر دقیق با عنوان &quot;عملیات ناموفق&quot; ارائه می‌گردد، در حالی که انتظار می‌رود پیام دقیق‌تری مانند &quot;موجودی کافی نمی‌باشد&quot; نمایش داده شود که منطبق با کد پاسخ بازگشتی از شتاب یا سوئیچ بانکی (نظیر کد 51 - Insufficient Funds) باشد.\r\n\r\nاین موضوع می‌تواند تجربه کاربری را تحت تأثیر منفی قرار داده و حتی منجر به برداشت نادرست کاربر از وضعیت حساب بانکی یا درگاه پرداخت گردد.\r\n\r\nلذا خواهشمند است دستور فرمایید موضوع مورد بررسی فنی قرار گرفته و در صورت امکان، پیام‌های خطای نمایشی در درگاه پرداخت متناسب با کد پاسخ بازگشتی از سوی سوئیچ بانکی اصلاح و به‌روزرسانی گردد.\r\n\r\nپیشاپیش از همکاری و توجه شما سپاسگزاریم.', '202506-962', 1, 26, 'condition_acepted_test_auto', 'high', NULL, '2025-06-08 05:39:39', '2026-05-12 12:00:31', NULL, NULL, NULL),
	(963, 'عدم اعمال تغییر شماره موبایل دارنده کارت ', 'با سلام، با توجه به اینکه شماره موبایل دارنده دارت یکی از آیتم های  اطلاعاتی مهم و ضروری سرویس های مختلف (از جمله تراکنش) می باشد ولی متاسفانه برای تغییر آن در سامانه بکافیس دارندگی مشکل وجود دارد که یک نمونه از مشکلات در فایل پیوست جهت استحضار خدمتتان ارسال می گردد. لذا خواهشمند جهت برطرف نمودن مشکل و ثبت تغییر شماره موبایل برای یک بار و بدون نیاز به تکرار آن اقدامات لازم را مبذول نمایید. با سپاس ', '202506-963', 8, 36, 'Condition_regect', 'high', NULL, '2025-06-08 06:03:32', '2025-06-08 10:04:21', NULL, NULL, NULL),
	(964, 'غیر فعال سازی ترمینال های لیست پیوست', 'با سلام و احترام\r\nخواهشمند ترمینال های لیست پیوست غیر فعال گردد.\r\nبا تشکر\r\n', '202506-964', 3, 10, 'Condition_final_done', 'high', NULL, '2025-06-08 07:21:45', '2026-02-21 11:43:45', NULL, NULL, NULL),
	(965, 'وجود مغایرت شماره تلفن همراه پس از اصلاح و تغییر ، در منوهای مختلف اینتک - اندیکاتور7981', 'پس از تغییر شماره کارت در منوی کارت /اطلاعات تماس، اصلاح مشخصات بطور کامل انجام نمی شود و مطابق تصویر پیوست در قسمتی شماره همراه قدیم مشتری و در جائی دیگر شماره جدید نمایش داده می شود.این موضوع هنگام فعالسازی کارت به روش پیامکی باعث نمایش خطای &quot; اطلاعات وارد شده صحیح نمی باشد&quot; می شود.تصویر نامه با شرح کامل و و نیز تصویر نمایش خطای اعلام شده جهت بهره برداری به پیوست می باشد\r\n', '202506-965', 9, NULL, 'Condition_final_done', 'medium', NULL, '2025-06-08 10:02:56', '2026-05-12 07:45:16', 16, 9, 'CR420945'),
	(966, ' داخلی 8729 -اضافه کردن تاریخ ثبت در منو کارت/گروه کارت اینتک و امکان نمایش تاریخ ثبت و نام نمایندگی در گزارشات', 'به پیوست نامه درخواست با شرح جزئیات آن ارائه می گردد.\r\nبا توجه به اینکه یکبار درخواست پشتیبانی ثبت شده و زمان زیادی جهت بررسی و اعلام توسعه ای بودن درخواست گذشته ، لطفا در صورت امکان تسریع فرمائید.', '202506-966', 9, NULL, 'Condition_final_done', 'low', NULL, '2025-06-08 10:04:35', '2026-05-12 07:45:09', 16, 9, 'CR421569'),
	(967, 'فعال و غیرفعال سازی NFC', 'با سلام و احترام؛\r\nبدین‌وسیله به استحضار می‌رساند با توجه به نیاز به امکان فعال/غیرفعال سازی NFC توسط کاربر در سامانه BackOffice خواهشمند است دستور فرمایید تا مساعدت لازم در این زمینه انجام گیرد.', '202506-967', 1, 26, 'Condition_final_done', 'high', NULL, '2025-06-08 11:32:19', '2026-05-12 07:33:28', NULL, NULL, NULL),
	(968, 'محدود سازی قابلیت گروه کارت امیران', 'باسلام و احترام\r\nخواهشمند است قابلیت تراکنش های خرید و موجودی به پایانه های فایل پیوست محدود گردد.\r\nباسپاس\r\n\r\n', '202506-968', 1, 25, 'Condition_final_done', 'high', NULL, '2025-06-08 11:49:49', '2026-02-21 11:43:41', NULL, NULL, NULL),
	(969, 'دسترسی به ویو AcqTerminalCapability', 'با سلام و احترام؛\r\nبدین‌وسیله به استحضار می‌رساند، به منظور انجام وظایف محوله و تسریع در روند بررسی و تحلیل داده‌ها، نیاز به دسترسی به ویو دیتابیس با نام AcqTerminalCapability داریم. \r\nلطفاً در صورت صلاحدید، اقدامات لازم جهت اعطای این دسترسی را مبذول فرمایید.\r\nبا تشکر', '202506-969', 4, 26, 'Condition_final_done', 'high', NULL, '2025-06-08 12:10:43', '2026-02-22 14:06:31', NULL, NULL, NULL),
	(970, 'دسترسی انواع چاپ در اینتک به روح اله زاده', 'با سلام خواهشمند است دستور دسترسی به منوی انبار کارت پیمانکاران + انواع چاپ را به اینجانب (Nahid Rohallahzadeh)  را صادر فرمایید. باتشکر', '202506-970', 8, 36, 'Condition_final_done', 'low', NULL, '2025-06-08 13:03:13', '2025-07-19 09:05:28', NULL, NULL, NULL),
	(971, 'شاخص دسترسی‌پذیری سوئیچ', 'با سلام و احترام\r\nدر خصوص شاخص «دسترسی‌پذیری سوئیچ»، کوئری‌ای طراحی کرده‌ام که بر اساس محاسبه تعداد تراکنش‌های موفق و ناموفق (پذیرندگی و کاربری) مقدار شاخص را به‌صورت روزانه استخراج می‌کند.\r\nدر بررسی خروجی، وضعیت نهایی برخی روزها به صورت «بحرانی» نمایش داده می‌شود. لطفاً بررسی فرمایید که آیا کوئری اجرا شده از نظر منطق محاسباتی و دسته‌بندی وضعیت‌ها (مطابق با استاندارد شاپرک) صحیح است یا نیاز به اصلاح دارد؟\r\nWITH ErrorCodes AS (\r\n    SELECT value AS Code, &#039;پذیرندگی&#039; AS Type FROM (VALUES\r\n        (&#039;3&#039;),(&#039;5&#039;),(&#039;6&#039;),(&#039;25&#039;),(&#039;30&#039;),(&#039;34&#039;),(&#039;55&#039;),(&#039;64&#039;),(&#039;67&#039;),(&#039;72&#039;),(&#039;77&#039;),(&#039;79&#039;),\r\n        (&#039;83&#039;),(&#039;86&#039;),(&#039;92&#039;),(&#039;94&#039;),(&#039;96&#039;),(&#039;97&#039;)\r\n    ) AS T(value)\r\n    UNION ALL\r\n    SELECT value AS Code, &#039;کاربری&#039; AS Type FROM (VALUES\r\n        (&#039;2&#039;),(&#039;14&#039;),(&#039;23&#039;),(&#039;40&#039;),(&#039;51&#039;),(&#039;54&#039;),(&#039;56&#039;),(&#039;57&#039;),(&#039;58&#039;),(&#039;59&#039;),(&#039;61&#039;),\r\n        (&#039;62&#039;),(&#039;63&#039;),(&#039;65&#039;),(&#039;75&#039;),(&#039;78&#039;),(&#039;4256&#039;)\r\n    ) AS T(value)\r\n),\r\nClassifiedTxn AS (\r\n    SELECT\r\n        CAST(CreatedOn AS DATE) AS TxnDate,\r\n        CASE \r\n            WHEN ResponseCode = &#039;00&#039; THEN &#039;موفق&#039;\r\n            WHEN EXISTS (\r\n                SELECT 1 FROM ErrorCodes E WHERE E.Code = RTRIM(ResponseCode)\r\n            ) THEN &#039;ناموفق&#039;\r\n            ELSE &#039;سایر&#039;\r\n        END AS TxnStatus\r\n    FROM [B2STxn].[rep].[RefahTransaction]\r\n    WHERE CreatedOn BETWEEN &#039;2025-04-21&#039; AND &#039;2025-05-22&#039;\r\n),\r\nDailyStats AS (\r\n    SELECT\r\n        TxnDate,\r\n        COUNT(CASE WHEN TxnStatus = &#039;موفق&#039; THEN 1 END) AS SuccessCount,\r\n        COUNT(CASE WHEN TxnStatus = &#039;ناموفق&#039; THEN 1 END) AS FailedCount\r\n    FROM ClassifiedTxn\r\n    GROUP BY TxnDate\r\n),\r\nFinalAvailability AS (\r\n    SELECT\r\n        TxnDate,\r\n        SuccessCount,\r\n        FailedCount,\r\n        CAST(SuccessCount * 100.0 / NULLIF(SuccessCount + FailedCount, 0) AS DECIMAL(6,3)) AS AvailabilityPercent\r\n    FROM DailyStats\r\n)\r\n\r\n-- خروجی نهایی با وضعیت رنگی\r\nSELECT\r\n    FORMAT(TxnDate, &#039;yyyy/MM/dd&#039;, &#039;fa-IR&#039;) AS [تاریخ شمسی],\r\n    SuccessCount AS [تراکنش موفق],\r\n    FailedCount AS [تراکنش ناموفق],\r\n    AvailabilityPercent AS [درصد دسترسی‌پذیری],\r\n    CASE\r\n        WHEN AvailabilityPercent &gt;= 99.9 THEN N&#039;وضعیت قابل قبول&#039;\r\n        WHEN AvailabilityPercent &gt;= 99.7 THEN N&#039;وضعیت هشدار&#039;\r\n        ELSE N&#039;وضعیت بحرانی&#039;\r\n    END AS [وضعیت]\r\nFROM FinalAvailability\r\nORDER BY TxnDate;\r\n\r\nبا تشکر\r\n', '202506-971', 3, 26, 'condition_acepted_test_auto', 'high', NULL, '2025-06-09 12:38:24', '2025-07-29 05:10:55', NULL, NULL, NULL),
	(972, 'افزودن کارت جدید به گروه کارت فولاد', 'با سلام\r\nبا توجه به عم امکان افزودن گروهی کارت جدید،\r\nخواهشمند است لیست ضمیمه به گروه کارت فولاد افزوده گردد', '202506-972', 3, 10, 'Condition_final_done', 'high', NULL, '2025-06-09 12:57:13', '2026-02-21 11:43:36', NULL, NULL, NULL),
	(973, 'اصلاح نشانی اندیکاتورهای 9736843 و 9747906', 'باسلام و احترام خواهشمند است شماره کارت های ارسال شده و نشانی های اعلام شده که به رنگ صورتی  در دیتا بیس اینتک اصلاح شود تا نشانی در نامه خوش آمدگویی هنگام صدور بصورت کامل درج شود(فایل ضمیمه بصورت زیپ شده ضميمه شد) -  باتشکر ازهمکاری شما ', '202506-973', 4, 36, 'Condition_final_done', 'high', NULL, '2025-06-10 09:21:22', '2026-02-22 13:52:37', NULL, NULL, NULL),
	(974, 'افزودن ترمینال به پروژه  Close loop امیران', 'با سلام\r\nخواهشمند است ترمینال های لیست پیوست به ترمینال های پروژه  Close loop امیران افزوده گردد.\r\nبا تشکر', '202506-974', 3, 10, 'Condition_regect', 'low', NULL, '2025-06-10 11:54:05', '2025-06-11 05:13:08', NULL, NULL, NULL),
	(975, 'کاهش خطای پذیرندگی - جدید', 'با سلام و احترام\r\nگزارشی از لیست خطاهای پذیرندگی دریافت شده از شاپرک به پیوست خدمتتان ارسال می گردد.\r\nخواهشمند است راهکاری جهت کاهش خطای تراکنش نامعتبر خطای 12 و مک نامعتبر خطای 63 و پذیرنده نامعتبر 03 و همچنین تغییر روز مالی 77 ارائه و پیاده سازی شود.', '202506-975', 3, 10, 'Condition_final_done', 'high', NULL, '2025-06-11 07:15:15', '2026-02-21 11:43:29', NULL, NULL, NULL),
	(976, 'درخواست Api برای گزارش تراکنش ها', 'باسلام و احترام\r\nخواهشمند است:\r\n1. Api ای برای گزارش تراکنش ها با پارامترهای خروجی ذیل ایجاد گردد.:\r\nشماره کارت ( اختیاری ) \r\nبازه تاریخی _ اجباری\r\n\r\n2. وب سرویس مذکور به گونه ای ایجاد گردد که تنها گروه کارت های انتخاب شده برای نام کاربری مورد نظر در خروجی متد مذکور نمایش داده شود.\r\n \r\nباسپاس', '202506-976', 1, 25, 'Condition_final_done', 'high', NULL, '2025-06-11 09:35:32', '2026-02-21 11:45:28', NULL, NULL, NULL),
	(977, 'خطا در بارگذاری فایل', 'باسلام و احترام\r\nپس از بارگذاری فایلی که شناسه ملی شرکت به عنوان کدملی اشخاص ثبت شده است، پبغام خطا &quot; آیتم نامعتبر &quot; _ فایل پیوست _ نمایش داده میشود.\r\nباسپاس', '202506-977', 1, 25, 'Condition_final_done', 'high', NULL, '2025-06-22 07:41:44', '2026-02-21 09:07:31', NULL, NULL, NULL),
	(978, 'عدم مشاهده گزارشات کارت و سندهای کارت در سامانه اینتک صادرکنندگی ', 'باسلام واحترام \r\nطی بررسی های به عمل آمده از سندهای کارت سوئیچ اینتک تراکنش های کارت روز جاری(۱۴۰۴/۰۳/۲۱) قابل نمایش نمی باشدباتوجه به نیاز این اداره (واحد مالی) جهت بررسی رفع مشکل دستور مقتضی راصادرفرمائید.\r\nآدرس گزارش:اینتک دارندگی /گزارش مالی/گزارش تراکنش دارنده کارت \r\nو همچنین درخواست های ثبت شده توسط واحدپشتیبانی دارندگان  به طور نمونه شماره تقاضای 9828232 \r\n', '202506-978', 8, 36, 'Condition_final_done', 'high', NULL, '2025-06-25 10:22:46', '2025-07-19 09:05:25', NULL, NULL, NULL),
	(979, 'علت مسدود شدن کارت', 'باسلام و احترام\r\nخواهشمند است علت مسدود شدن کارت ذیل را اعلام بفرمایید.\r\n\r\nشایان ذکر است آخرین تراکنش کارت مذکور در تاریخ 1404/03/22 با شماره مرجع ذیل و کدپاسخ 34 صورت گرفته و بعد از آن کارت مسدود شده است.\r\n\r\n\r\n6274-1244-9123-8261\r\n\r\nRRN\r\n327512805245', '202506-979', 1, 25, 'Condition_final_done', 'high', NULL, '2025-06-28 08:54:24', '2025-12-30 06:02:33', NULL, NULL, NULL),
	(980, 'پنل فروشگاه امیران', 'باسلام و احترام\r\nخواهشمند است برای نام کاربری amiranstore   در منو جستجوی کارت و گزارش تراکنش های کارت تنها کارت های گروه امیران نمایش داده شود.\r\nباسپاس', '202506-980', 1, 25, 'Condition_final_done', 'high', NULL, '2025-06-28 10:20:08', '2026-02-21 11:43:16', NULL, NULL, NULL),
	(981, 'عدم نمایش گزارش فروش شارژ پین', 'با سلام و احترام\r\nبه استحضار می‌رساند، گزارش فروش شارژ پین سوییچ مهرانا و بانک تجارت در مسیر &quot;اینتک پذیرندگی/گزارشات/ سرجمع فروش\r\nشارژ&quot; در تاریخ 1404/03/22 نمایش داده نمی‌شود. خواهشمنداست نسبت به رفع مشکل اقدام مقتضی مبذول فرمایید.', '202506-981', 4, 43, 'Condition_final_done', 'medium', NULL, '2025-06-28 10:57:40', '2026-02-22 13:52:42', NULL, NULL, NULL),
	(982, 'اصلاح نشانی اندیکاتورهای 9736843 و 9747906', 'باسلام و احترام خواهشمند است شماره کارت های ارسال شده و نشانی های اعلام شده که به رنگ صورتی  در دیتا بیس اینتک اصلاح شود تا نشانی در نامه خوش آمدگویی هنگام صدور بصورت کامل درج شود(فایل ضمیمه بصورت زیپ شده ضميمه شد) -  \r\n&#039;باتوجه به اين كه نشاني در اينتك اصلاح شده است اما هنوز زماني كه فايل صدور جديد ساخته ميشود همان آدرس قبلي نمايش داده ميشود/ نشاني اعمال نشده است.&#039;.&quot;SR422398 دارندگی &quot;\r\nباتشکر ', '202506-982', 8, 36, 'Condition_final_done', 'high', NULL, '2025-06-28 12:29:43', '2025-07-19 09:05:16', NULL, NULL, NULL),
	(983, 'افزودن وضعیت کهربا در قالب ویو', 'با سلام و احترام\r\nبدین‌وسیله به استحضار می‌رساند با توجه به نیازمندی‌های جدید در فرآیند گزارش‌گیری و تحلیل داده‌ها، افزودن وضعیت جدید با عنوان کهربا در قالب یک View در پایگاه داده ضروری می‌باشد.\r\nلطفاً دستور فرمایید اقدامات لازم در این خصوص در اسرع وقت صورت پذیرد تا امکان بهره‌برداری از داده‌های مرتبط با این وضعیت در سامانه فراهم گردد.\r\nپیشاپیش از همکاری و همراهی جنابعالی کمال تشکر را دارم.', '202506-983', 9, 26, 'Condition_final_done', 'high', NULL, '2025-06-29 06:46:44', '2026-05-12 07:38:13', NULL, NULL, NULL),
	(984, 'ایجاد دسترسی به دستگاه صدور کارت از طریق بکافیس دارندگی  برای واحد دارندگان کارت ', 'با سلامو احترام،\r\nبه استحضار می رساندحسب دستور مدیریت محترم واحدجناب آقاي صافدل جهت رضایت مشتریان حضوري و صدورکارت تکی نیاز به ایجاد دسترسی به دستگاه پرینترصدورکارت به مشخصات دستگاه تکرو رنگی31 Smart به همراه ماژول مگنت، ریبون رنگی  (همانند دستگاه های شعب) در بکافیس دارندگی برای کاربری های b.behbam و rohallahzadeh می باشد.همچنین خواهشمند است  با سپاس \r\n', '202506-984', 8, 36, 'Condition_final_done', 'high', NULL, '2025-06-29 10:48:34', '2025-07-19 09:05:12', NULL, NULL, NULL),
	(985, 'غیر فعالسازی ترمینال ها تیرماه - پارت اول', 'با سلام\r\nخواهشمند است ترمینالها در سوییچ غیر فعال گردد.\r\n سپاس \r\n', '202506-985', 3, 10, 'Condition_final_done', 'medium', NULL, '2025-06-29 13:44:23', '2025-12-30 06:02:27', NULL, NULL, NULL),
	(986, ' کلید کانال 10010', '\r\n\r\n با سلام و احترام\r\n\r\nکلید کانال 10010 به ایمیل آقای صدوقیان ارسال میگردد.\r\n\r\nخواهشمند است فیلد 53 را ارسال فرمایید.\r\n\r\nبا سپاس\r\n', '202506-986', 3, 10, 'Condition_final_done', 'high', NULL, '2025-06-30 11:45:19', '2026-02-21 09:01:41', NULL, NULL, NULL),
	(987, 'درخواست ایندکس‌گذاری فیلدهای id و CreatedOn در جدول RefahTransaction', 'با سلام و احترام؛\r\nاحتراماً، با توجه به بررسی‌های صورت گرفته و به منظور بهبود عملکرد کوئریها و افزایش سرعت دسترسی به اطلاعات در جدول RefahTransaction، خواهشمند است دستور فرمایید نسبت به ایندکس‌گذاری فیلدهای id و CreatedOn در این جدول اقدامات لازم صورت پذیرد.\r\nپیشاپیش از همکاری و توجه شما کمال تشکر را دارم.', '202507-987', 4, 26, 'Condition_final_done', 'high', NULL, '2025-07-01 08:35:00', '2026-05-12 07:33:45', NULL, NULL, NULL),
	(988, 'راه اندازی کانال محلی تاپ و بانک پارسیان-اندیکاتور 11459', 'درخواست راه اندازی کانال محلی با بانک پارسیان بر اساس استاندارد شتاب و تولید فایل جهت تسویه با پذیرنده (لازم بذکر است هماهنگی های لازم با جناب آقای دارائی صورت گرفته است)', '202507-988', 9, NULL, 'Condition_acepted_invoice', 'low', NULL, '2025-07-01 11:46:12', '2026-08-03 07:31:31', 16, 9, ' CR424217'),
	(989, 'داخلی 4577 -درخواست تکمیلی تیکت CR419771 -درخواست دسترسی سرویس های پروژه کارت مجازی', 'مجددا پیرو نیازمندی اعلام شده سرویس های زیر در خصوص پروژه کارت مجازی مورد نیاز فوری می باشد:\r\n1-سرویس ایجاد گروه پذیرندگی در سوئیچ Issuery\r\n2-سرویس اتصال گروه مشتری/ گروه کارت به گروه پذیرندگی\r\n3-امکان استعلام لیست پایانه های گروه پذیرندگی بر اساس گروه پذیرندگی/پایانه\r\nلطفا با توجه به اینکه این درخواست در تکمیل درخواست CR419771 و بسیار فوری  می باشد، دستور تسریع صادر فرمائید.', '202507-989', 9, NULL, 'Condition_need_action', 'medium', NULL, '2025-07-01 11:55:48', '2025-07-30 07:04:19', 16, 9, 'CR424053'),
	(990, 'تخصیص کارت به مارکت', 'باسلام و احترام\r\nخواهشمند است کارت های فایل پیوست ( گروه کارت  بن - دفاتر و نمایندگی ها )  به مارکت &quot; پروژه فروش کارتخوان&quot; تخصیص داده شود.\r\nباسپاس', '202507-990', 1, 25, 'Condition_final_done', 'high', NULL, '2025-07-01 14:35:59', '2025-09-09 10:35:13', NULL, NULL, NULL),
	(991, 'خطا در سرور منو ویرایش گروهی مشتریان', 'باسلام و احترام\r\nدر منو ویرایش گروهی مشتریان خطا در سرور رخ می دهد.\r\nباسپاس', '202507-991', 1, 25, 'Condition_final_done', 'high', NULL, '2025-07-02 05:58:03', '2026-02-21 09:07:22', NULL, NULL, NULL),
	(992, 'خطای عدم ارتباط با مرکز', 'با سلام و احترام\r\nپایانه 14991616 خطای عدم ارتباط با مرکز دارد.\r\nبا سپاس', '202507-992', 3, 49, 'Condition_final_done', 'medium', NULL, '2025-07-02 10:28:55', '2025-12-30 06:23:53', NULL, NULL, NULL),
	(993, 'درخواست cast و تغییر نوع داده فیلد CreateDate به نوع Integer', 'با سلام و احترام\r\nبدین وسیله و پیرو بررسی های انجام شده، خواهشمند است دستور فرمایید نسبت به تغییر نوع داده‌ای فیلد CreatedOn به Integer و Cast آن بصورت تاریخ شمسی در جدول RefahTransaction اقدام لازم صورت پذیرد.\r\nپیشاپیش از همکاری جنابعالی کمال تشکر را دارم.', '202507-993', 4, 26, 'Condition_final_done', 'high', NULL, '2025-07-02 13:13:59', '2026-02-22 14:05:07', NULL, NULL, NULL),
	(994, 'اعمال تنظیمات ترمینال تستی برای ترمینال 20075860', 'با سلام\r\nخواهشمند است ترمینال 20075860 به ترمینال های تستی اضافه گردد.\r\nبا سپاس', '202507-994', 3, 10, 'Condition_final_done', 'high', NULL, '2025-07-08 05:30:41', '2025-09-09 10:35:28', NULL, NULL, NULL),
	(995, 'تنظیمات کانال 7030 جهت انجام تراکنش کهربا', 'با سلام و احترام\r\nخواهشمند است تنظیمات کانال 7030  به گونه ای تغییر یابد که قابلیت انجام تراکنش کهربا وجود داشته باشد.\r\nبا سپاس', '202507-995', 3, 10, 'Condition_final_done', 'low', NULL, '2025-07-08 09:11:41', '2025-09-09 10:35:49', NULL, NULL, NULL),
	(996, 'پیاده سازی گزارش مغایرت مدل دستگاه بروی بک افیس', '\r\nبا سلام و احترام\r\n\r\nخواهشمند است بروی بک افیس جدید در بخش گزارشات، تب &quot;مغایرت مدل دستگاه&quot;، گزارشی از مغایرت های مدل های دستگاه کارتخوان نمایش داده شود. \r\nهدف شناسایی مغایرت مدل دستگاه های کارتخوان ثبت شده در سامانه جام جم و مدل ارسال شده در پیام  تراکنش دستگاه کارتخوان (مدل دستگاه در فیلد 48 تگ 4 به سوئیچ ارسال می شود) می باشد.\r\nAPI از سامانه جام جم نیز به پیوست خدممتان ارسال می گردد. در خصوص API ارسال شده سرویس جدیدی با نام SwitchService ایجاد گردید.\r\nدر سرویس فوق متدی با نام GetSerialDetail ایجاد گردید، در این متد پارامتر ورودی ترمینال است. این متد اطلاعات سریالهای منصوب دستگاه پوز از جمله مدل دستگاه کارتخوان را بازمی گرداند.\r\nنقش جدیدی به نام &quot;سرویس سوئیچ&quot; ایجاد گردید.\r\nاطلاعات کاربری :\r\nUser: intekservice\r\nPass:Aa@1234567890 \r\nراهنمای مستند سرویس سوئیچ به پیوست ارسال می گردد.\r\n', '202507-996', 3, 10, 'condition_in_progress', 'high', NULL, '2025-07-08 10:06:29', '2025-07-08 10:30:45', NULL, NULL, NULL),
	(997, 'پیاده سازی شناسه بهداد', '\r\nروش پیاده سازی شناسه بهداد:\r\nشناسه بهداد در تراکنش به سوئیچ ارسال خواهد شد. سوئیچ توسط الگوریتم ضمیمه شده  شناسه را بررسی و  در صورت صحیح بودن جهت تسویه شماره شبا صحیح را انتخاب خواهد کرد.\r\n', '202507-997', 3, 10, 'Condition_regect', 'high', NULL, '2025-07-09 04:29:57', '2025-07-09 10:08:15', NULL, NULL, NULL),
	(998, 'افزودن کد صنف انرژی و حمل و نقل', 'با سلام و احترام؛\r\nبدین‌وسیله خواهشمند است دستور فرمایید کد صنف انرژی و حمل و نقل با مشخصات زیر در سوئیچ تعریف گردد:\r\n\r\n• کد صنف: 9810\r\n• کد تکمیلی صنف: 98100001\r\n• ده برابر سقف مبلغی خرید ( 20 میلیارد ریال )\r\n\r\nخواهشمند است اقدامات لازم در این خصوص در اسرع وقت صورت پذیرد و نتیجه آن اعلام گردد.\r\n\r\n', '202507-998', 3, 26, 'Condition_final_done', 'high', NULL, '2025-07-09 06:57:08', '2026-02-22 14:04:51', NULL, NULL, NULL),
	(999, 'حذف نام پیمانکار غیرفعال و غیرضروری', 'با سلام و احترام\r\nخواهشمند است در قسمت صدور کارت و پیمانکار چاپ، نسبت به حذف نام های زیر اقدام فرمایید.\r\n0\r\nS06\r\n14981\r\nبا تشکر', '202507-999', 4, 36, 'Condition_final_done', 'low', NULL, '2025-07-09 07:10:12', '2025-07-19 09:05:08', NULL, NULL, NULL),
	(1000, 'تغییر قابلیت ها و الگوها', 'با سلام، خواهشمند است قابلیتهای کارت های مددجویانی با کد محصول 42 و 44 می باشندبه شرح ذیل قابلیت ها تغییر یابد\r\n-  قابلیت خرید نوع پایانه کارتخوان از 15.000.000 ریال به 18.000.000 ریال\r\n- در الگوی کارت  حداکثر اعتبار شتابی از 50.000.000 ریال به 150.000.000 ,  حداکثر اعتبار شارژ شتابی از 30,000,000 به 50.000.000 ریال \r\n-  قابلیت (انتقال به) کارت های مددجویانی با کد محصول 42 و 44 می باشند  از 30.000.000 به 50.000.000 ریال تغییر یابد .\r\nبا سپاس', '202507-1000', 8, 36, 'Condition_final_done', 'high', NULL, '2025-07-09 07:18:25', '2025-07-19 09:05:04', NULL, NULL, NULL),
	(1001, 'گزارش درخواستی بانک', 'باسلام و احترام\r\nخواهشمند است گزارش های درخواستی بانک به شرح ذیل ارسال گردد:\r\n\r\nتاریخ گزارشات : از ابتدای سوئیچ اینتک تا تاریخ  31-03-1404 باشد\r\n\r\n1. شماره کارت- نوع کارت- نام دارنده کارت (حقیقی و حقوقی) - مبلغ شارژ - تاریخ شارژ\r\n\r\n2. شماره کارت- نوع تراکنش - مبلغ تراکنش\r\n\r\nباسپاس', '202507-1001', 1, 25, 'Condition_final_done', 'high', NULL, '2025-07-09 08:05:19', '2026-02-21 11:43:11', NULL, NULL, NULL),
	(1002, ' ایجاد IV Pass برای  فایل decrypt پیمانکار چاپ &quot;تجارت الکترونیک پارسیان&quot;', 'با سلام و احترام، با عنایت به راه اندازی امکان صدور کارت موردی در شرکت برای پرسنل واحد پشتیبانی دارندگان خواهشمند است  در خصوص ایجاد IV Pass  و ارائه فایل  decrypt  اقدامات لازم را مبذول نمایید. به پیوست فایل encrypt  نمونه خدمتتان ارسال می گردد. با سپاس ', '202507-1002', 8, 36, 'Condition_final_done', 'high', NULL, '2025-07-09 10:04:08', '2025-07-19 09:05:00', NULL, NULL, NULL),
	(1003, 'درخواست API', 'با سلام و احترام\r\nخواهشمند است API جهت استعلام شباهای تعریف شده پشت ترمینال \r\nو API  جهت تغییر شبای اصلی پشت ترمینال(فقط برای Iban ها فعال)\r\nرا ارسال فرمایید.', '202507-1003', 3, 10, 'Condition_final_done', 'medium', NULL, '2025-07-09 12:18:18', '2026-02-21 11:43:07', NULL, NULL, NULL),
	(1004, 'محدود سازی نام کاربری به یک گروه کارت', 'باسلام و احترام \r\nخواهشمند است دسترسی های نام کاربری ذیل تنها به گروه کارت &quot;بن- دفاتر و نمایندگی ها  &quot; محدود گردد.\r\nنام کاربری\r\nn.mojtabaei\r\nباسپاس', '202507-1004', 1, 25, 'Condition_final_done', 'high', NULL, '2025-07-12 07:21:06', '2026-02-21 09:02:08', NULL, NULL, NULL),
	(1005, 'خطای 2 پایانه 14508688', 'با سلام و احترام\r\nپایانه 14508688 دارای خطای 2 میباشد.\r\nبا سپاس', '202507-1005', 3, 49, 'Condition_final_done', 'medium', NULL, '2025-07-12 12:33:22', '2025-12-30 06:23:57', NULL, NULL, NULL),
	(1006, 'افزودن ترمینال به لیست ترمینال های تستی', 'با سلام\r\nخواهشمند است ترمینال 31235836 به عنوان ترمینال تستی تعریف گردد.', '202507-1006', 3, 10, 'Condition_final_done', 'high', NULL, '2025-07-13 05:48:59', '2025-12-30 06:02:21', NULL, NULL, NULL),
	(1007, 'عدم کارکرد سرویس آنی https://boiss.pec.ir/apiservices/api/cardServices/Turnover روی تاپیار', 'با سلام، به استحضاز می رساند بروزرسانی اطلاعات کارت که توسط شعب بانک پارسیان در تاپیار استفاده می شود امروز دچار اختلال شده است و پاسخی ارائه نمی دهد. نمونه Request و Response خدمتتان ارسال می گردد. \r\nRequest\r\n{\r\n    &quot;CardNo&quot;: &quot;6221062431209048&quot;,\r\n    &quot;FromDate&quot;: &quot;1385/01/01&quot;,\r\n    &quot;ToDate&quot;: &quot;1404/04/22&quot;,\r\n    &quot;SecPin&quot;: null,\r\n    &quot;Pin&quot;: null,\r\n    &quot;CardPatternIDs&quot;: null,\r\n    &quot;CardGroupIDs&quot;: null\r\n}\r\n\r\nResponse\r\n{\r\n    &quot;success&quot;: true,\r\n    &quot;error_code&quot;: null,\r\n    &quot;error_message&quot;: &quot;&quot;,\r\n    &quot;data&quot;: [],\r\n    &quot;additionalData&quot;: null\r\n}\r\n', '202507-1007', 8, 36, 'Condition_final_done', 'high', NULL, '2025-07-13 11:08:53', '2025-07-19 09:04:56', NULL, NULL, NULL),
	(1008, 'حضور نیروهای فنی جهت انجام ممیزی داخلی', 'با سلام و احترام\r\nخواهشمند است جهت انجام ممیزی داخلی APP سوئیچ \r\n1- نیروی فنی پایگاه داده  روز  سه شنبه مورخ  1404/04/24 ساعت 14\r\n2- نیروی فنی APP سوئیچ  روز  یکشنبه مورخ 1404/04/29  ساعت 10 \r\nدر شرکت پرداخت نوین حضور داشته باشند.\r\nبا سپاس\r\n\r\nبا سپاس\r\n', '202507-1008', 3, 10, 'Condition_final_done', 'medium', NULL, '2025-07-13 15:04:46', '2026-02-21 09:02:21', NULL, NULL, NULL),
	(1009, 'عدم تسویه شارژهای Top up ناموفق ', 'با سلام  و احترام\r\nخواهشمند است شارژهای Top up ناموفق  در فایل تسویه با تامین کننده وجود نداشته باشد.\r\nنمونه\r\n Rrn:\r\n707144197234\r\nRrn:\r\n707176898232\r\nخواهشمند است در صورت نیاز به توضیحات بیشتر با شماره 09126654323- خانم بذرپاچ- تماس حاصل فرمایید.\r\nبا سپاس\r\n', '202507-1009', 3, 10, 'Condition_final_done', 'high', NULL, '2025-07-14 06:48:11', '2026-02-21 11:42:07', NULL, NULL, NULL),
	(1010, 'خطای 91 پروژه کلوز لوپ', 'با سلام\r\nدر خصوص پروژه کلوز لوپ، ترمینال 31235836 برای تراکنش IPG\r\n و ترمینال 20075860 برای پوز خطای 91 دریافت میشود.\r\nخواهشمند است بررسی و لاگ را جهت ارائه به بانک ارسال فرمایید.', '202507-1010', 3, 10, 'Condition_final_done', 'high', NULL, '2025-07-14 09:43:34', '2025-12-30 06:03:38', NULL, NULL, NULL),
	(1011, 'ویرایش گروهی مشتریان حقوقی', 'باسلام و احترام\r\nخواهشمند است در منو مشتریان،  ویرایش گروهی مشتریان حقوقی پیاده سازی گردد.\r\nباسپاس', '202507-1011', 1, 25, 'condition_in_progress', 'medium', NULL, '2025-07-14 13:05:17', '2025-07-15 06:23:09', NULL, NULL, NULL),
	(1012, 'خطای 2 پایانه 14830247', 'با سلام و  احترام\r\nپایانه 14830247 دارای خطای 2 میباشد\r\nبا سپاس', '202507-1012', 3, 49, 'Condition_final_done', 'medium', NULL, '2025-07-14 13:44:21', '2025-12-30 06:24:01', NULL, NULL, NULL),
	(1013, 'دیتای کامل 18 گروه مشتری رایزکو', 'باسلام و احترام\r\nخواهشمند است گزارش اطلاعات کامل گروه مشتری های شرکت رایزکو از جمله کد ملی و شماره موبایل و ....ارسال بفرمایید.\r\n (اطلاعات  18 گروه مشتری با نام رایزکو  لطفا ارسال گردد ) \r\n\r\nباسپاس', '202507-1013', 1, 25, 'Condition_final_done', 'high', NULL, '2025-07-15 09:51:12', '2026-02-21 09:02:36', NULL, NULL, NULL),
	(1014, 'ارائه گزارش شارژهای پارسی کارت اپلیکیشن تاپ', 'با سلام، پیرو مذاکره آقای محمدی و خانم تربتی فرد خواهشمند است نسبت به ارائه گزارش شارژهای انجام شده از طریق منوی پارسی کارت اپلیکیشن تاپ از ابتدای امسال تا کنون اقدام نمایید و همچنین روش دریافت گزارش مذکور را از طریق بکافیس و یا دیتابیس دارندگی اعلام بفرمایید. در ضمن نمونه گزارش شارژ پارسی کارت دریافتی  از شرکت تابان  به پیوست خدمتتان ارسال می گردد. با سپاس ', '202507-1014', 8, 36, 'condition_in_progress', 'low', NULL, '2025-07-16 07:06:48', '2025-07-16 10:09:47', NULL, NULL, NULL),
	(1015, 'دریافت API تنظیمات و چاپ رسید', '\r\nبا سلام خواهشمند است API تنظیمات و چاپ رسید را ارسال فرمایید.\r\nبا سپاس', '202507-1015', 3, 10, 'Condition_final_done', 'medium', NULL, '2025-07-16 07:53:04', '2026-02-09 12:48:23', NULL, NULL, NULL),
	(1016, 'تعریف درصد تسهیم در مرحله تعریف شبا', 'با سلام \r\nاحتراما پیرو متد api/switchs/3/terminals/342/multi-account در Swagger  \r\n در متد ارسالی تنها لیست شبا ها قابل تعریف می باشد در صورتیکه نیازمندی به این صورت است که در زمان تعریف حساب ها، درصد تسهیم هم در همان مرحله تعریف گردد.\r\nدر حال حاضر با استفاده از متدهای موجود چند حسابی به صورت کامل تعریف می شود ولی درصد تسهیم به صورت دستی در بک افیس تنطیم میگردد.\r\nدر صورت نیاز به توضیحات بیشتر با خانم بذرپاچ با شماره 09126654323 تماس حاصل فرمایید.\r\nبا سپاس \r\n', '202507-1016', 3, 10, 'condition_acepted_test_auto', 'medium', 1, '2025-07-19 05:34:49', '2026-02-22 13:30:53', NULL, NULL, NULL),
	(1017, 'تغییر متن پیامک', 'باسلام و احترام\r\nخواهشمند است متن پیامک های واریز و برداشت مطابق با فایل پیوست تغییر یابد.\r\nباسپاس', '202507-1017', 1, 25, 'Condition_final_done', 'high', NULL, '2025-07-19 11:16:53', '2026-02-21 11:41:19', NULL, NULL, NULL),
	(1018, 'درخواست صدور و چاپ 8 رقم آخر شماره کارتهای مجازی-اندیکاتور13543', 'در فرآیند صدور منتهی به چاپ کارتها، امکان انتخاب گزینه ای بعنوان &quot;چاپ تنها هشت رقم آخر شماره کارت&quot; ایجاد شود.\r\nکلیه کارت‌های مجازی در پنل سمت سازمان و مشتری و نیز روی جسم کارت با شماره ۸ رقم آخر شناسایی شود. این موضوع فقط به سمت خارج سازمان است و طبیعتا پنل‌های داخلی و سوئیچ را متأثر نمی‌سازد. همچنین با توجه به اینکه این کارت‌ها فقط روی کارتخوان استفاده می‌شوند نیازی به درج CVV2 هم ندارند\r\n\r\nدلیل: برای جلوگیری از ایجاد مشکل و عدم انطباق با دستورالعمل‌های بانک مرکزی', '202507-1018', 9, NULL, 'condition_acepted_test_auto', 'medium', NULL, '2025-07-20 08:43:04', '2026-10-07 16:08:21', 16, 9, 'CR428278'),
	(1019, 'خطای 2 پایانه 14554526', 'با سلام و احترام\r\nپایانه 14554526 دارای خطای 2 میباشد\r\nبا سپاس', '202507-1019', 3, 49, 'Condition_final_done', 'medium', NULL, '2025-07-20 12:30:16', '2025-12-30 06:18:32', NULL, NULL, NULL),
	(1020, 'تغییر نمایندگی', 'باسلام و احترام\r\nتغییر نمایندگی فایل پیوست با خطا مواجه می‌گردد.\r\n( نمایندگی فعلی کارت های فایل پیوست متفاوت می‌باشد )\r\nباسپاس', '202507-1020', 1, 25, 'Condition_final_done', 'high', NULL, '2025-07-20 14:06:07', '2025-09-09 10:39:42', NULL, NULL, NULL),
	(1021, 'ویو دیتابیس کشتی‌رانی', 'با سلام و احترام؛\r\nهمانطور که قبلاً در ارتباط با پروژه کشتی‌رانی با مهندس افشار مطرح کرده بودیم، لطفاً در صورت امکان یک VIEW در دیتابیس ایجاد فرمایید که شامل اطلاعات تراکنش‌های موفق و ناموفق این پروژه باشد. این VIEW به منظور تسهیل در بررسی و تحلیل وضعیت تراکنش‌ها بسیار ضروری و مفید خواهد بود.', '202507-1021', 9, 26, 'Condition_final_done', 'high', NULL, '2025-07-21 05:04:30', '2026-05-12 07:37:47', NULL, NULL, NULL),
	(1022, 'شاخص میانگین طول صف دقیقه‌ای ماهانه و تأثیر بر پایداری و عملکرد سوئیچ', 'میانگین طول صف دقیقه‌ای\r\nشاخص طول صنف دقیقه ای ماهانه،‌ حداکثر تراکنشهای منتظر در کل دقایق یک ماه راه نشان میدهد، بالارفتن این شاخص به معنی بالا رفتن طول صف ها به صورت لحظه ای در سوئیچ استو گذر از آستانه مشخصی که بستگی به ظرفیت سوئیچ دارد باعث ایجاد ناپایداری و اختلال در رفتار سوئیچ و یا غیرعادی شدن رفتار سوئیچ می‌شود. این شاخص باید همواره مورد بررسی قرار گیرد. کندی های شتاب پایگاه داده و به طور کلی کانالهای خروجی سوئیچ در بالا رفتن این شاخص موثر هستند.', '202507-1022', 3, 26, 'Condition_final_done', 'high', NULL, '2025-07-21 05:12:33', '2026-05-12 08:07:51', NULL, NULL, NULL),
	(1023, 'دانتایم مورخ  بامداد جمعه  03/05/1404', 'با سلام و احترام\r\nخواهشمند است جهت آپدیت سیستم عامل های سرورهای اینتک در تاریخ بامداد جمعه  03/05/1404 آمادگی خود را اعلام فرمایید.\r\nبا سپاس', '202507-1023', 3, 10, 'Condition_final_done', 'high', NULL, '2025-07-21 06:42:43', '2025-09-09 10:39:32', NULL, NULL, NULL),
	(1024, 'مغایرت در گردش کارت تنخواه شرکت علی بابا 6221064104127069', 'با سلام و احترام ، با توجه به بررسی بعمل امده از گردش کارت شماره 6221064104127069   در تاریخ 1403/08/23   خرید انجام داده که مانده موجودی ان به مقدار 212.915.000 ریال کمتر در ستون موجودی نمایش داده شده است لذا با توجه به فایل و توضیحات ارائه شده خواهشمند است جهت بررسی دستور مقتضی صادر فرمائید . با تشکر', '202507-1024', 8, 36, 'Condition_final_done', 'high', NULL, '2025-07-21 07:20:29', '2025-09-09 10:27:49', NULL, NULL, NULL),
	(1025, 'عدم نمایش نام گروه مرکز قلب تهران', 'باسلام \r\nباتوجه به عدم نمایش نام گروه: مرکز قلب تهران شناسه خارجی :2224 و کد تفضیل: 131144  و نمایندگی صحیح : تهران11 (جنوب غرب تهران) 1017\r\nخواهشمند است جهت رفع مشکل نام گروه نامبرده در اینتک و نمایش آن دستور مقتضی صادر فرمایید. باتشکر', '202507-1025', 8, 36, 'Condition_final_done', 'high', NULL, '2025-07-21 07:49:46', '2025-09-09 10:27:40', NULL, NULL, NULL),
	(1026, 'تغییر کد سویئچ ترمینال11879037', 'با سلام\r\nخواهشمند است کد سوئیچ ترمینال 11879037 از 3 به 7 تغییر کند ', '202507-1026', 3, 10, 'Condition_final_done', 'high', NULL, '2025-07-21 08:49:08', '2025-12-30 06:02:09', NULL, NULL, NULL),
	(1027, 'اطلاع رسانی دانتایم مورخ جمعه 3 مرداد 1404 - جهت بروز رسانی سیستم عامل سرور های سوئیچ اینتک   ', 'با سلام و احترام\r\n۱- واحد درخواست دهنده: اداره زیرساخت\r\n۲- شرح تغییرات: بروز رسانی سیستم های عامل سرور های سوئیچ اینتک\r\n۳- تاریخ شروع: جمعه 3 مرداد ساعت 01:00\r\n۴- تاریخ پایان: جمعه 3 مرداد ساعت 06:00\r\n۵- سرویس های تحت تاثیر: سوئیچ اینتک\r\n۶- دلایل:رعایت الزامات امنیت و افتا\r\n٧- افراد مطلع: فناوری اطلاعات \r\n٨- افراد پاسخگو: آقای احمدزاده\r\n* مدت زمان قطع شدن سوئیچ ۲۰ دقیقه پیش بینی می گردد\r\n', '202507-1027', 3, 10, 'Condition_final_done', 'medium', NULL, '2025-07-22 08:20:04', '2025-09-09 10:34:45', NULL, NULL, NULL),
	(1028, 'تعریف PrCode جدید جهت پروژه اربعین (ebcome)', 'با سلام\r\nخواهشمند است دو PrCode جهت پروژه اربعین تعریف گردد.\r\n\r\n  PrCode اول: جهت تراکنش های خرید - واریز به شماره شبای IR080170000000117844584007 - بانک ملی- شرکت راهبرد ایده آل امین\r\n PrCode دوم: جهت سایر تراکنش‌ها - واریز به شماره شبای  IR390600302601110488511001 - بانک مهر - شرکت همراه کسب و کارهای هوشمند\r\n\r\nبا سپاس', '202507-1028', 3, 10, 'Condition_final_done', 'high', NULL, '2025-07-22 09:58:27', '2026-02-21 11:40:53', NULL, NULL, NULL),
	(1029, 'درخواست ایجاد یوزر جدید جهت دسترسی به سرویس های transfer و turn over', 'یوزر جدیدی جهت دسترسی یه دو سرویس مذکور ایجاد شود.\r\nلازم است در شرح سند مالی آنها &quot;جهت ریفاند داخلی صورت می گیرد&quot; قید شود.\r\nجزئیات درخواست با هماهنگی آقایان اصغرزاده و افضلی ثبت شده است.\r\n( بدلیل فوریت موضوع وبنا به دستور شفاهی آقای اصغرزاده تیکت ثبت شد\r\n\r\nبسیار فوری بوده و به دستور آقای دکتر ساکیانی همین امروز انجام گردد.', '202507-1029', 9, NULL, 'condition_acepted_test_auto', 'high', NULL, '2025-07-22 10:33:52', '2026-10-07 16:08:21', 16, 9, 'CR428949'),
	(1030, 'خطای 2 پایانه 13327076 ', 'با سلام و احترام \r\nپایانه 13327076 دارای خطای 2 میباشد\r\nبا سپاس', '202507-1030', 3, 49, 'Condition_final_done', 'medium', NULL, '2025-07-22 11:12:35', '2025-12-30 06:18:27', NULL, NULL, NULL),
	(1031, 'خطای 2 پایانه 15016555', 'با سلام و احترام\r\nپایانه 15016555 دارای خطای 2 میباشد\r\nبا سپاس', '202507-1031', 3, 49, 'Condition_final_done', 'medium', NULL, '2025-07-23 08:16:13', '2025-12-30 06:24:06', NULL, NULL, NULL),
	(1032, 'دریافت خروجی اکسل رکوردهای خطا دار بر روی سرویس شاهکار ', 'باسلام و احترام\r\nدر منو صدور کارت، رکوردهای خطا دار بر روی سرویس شاهکار بصورت مشخص نمایش داده شوند و دریافت خروجی اکسل رکوردهای خطا دار امکان پذیر گردد.\r\nباسپاس', '202507-1032', 1, 25, 'condition_in_progress', 'high', NULL, '2025-07-23 09:53:10', '2025-07-23 11:06:08', NULL, NULL, NULL),
	(1033, 'دسترسی تغییر کلید', 'با سلام و احترام\r\nخواهشمند است با توجه به نیاز دسترسی تغییر کلید ، برای کاربر با یوزر m.behzadkia دسترسی مذکور را اعمال فرمایید.\r\nبا سپاس', '202507-1033', 3, 49, 'Condition_final_done', 'medium', NULL, '2025-07-23 10:33:11', '2025-12-30 06:24:12', NULL, NULL, NULL),
	(1034, 'عدم نمایش گزارش فروش شارژ پین در تاریخ 404/03/22', 'با سلام و احترام\r\nبه استحضار می‌رساند، گزارش فروش شارژ پین سوییچ مهرانا و بانک تجارت در مسیر &quot;اینتک پذیرندگی/گزارشات/ سرجمع فروش\r\nشارژ&quot; در تاریخ 1404/03/22 نمایش داده نمی‌شود(تمامی رکوردها با مقدار 0 پر شده است).\r\nخواهشمنداست نسبت به رفع مشکل اقدام مقتضی مبذول فرمایید.', '202507-1034', 4, 43, 'condition_in_progress', 'medium', NULL, '2025-07-26 05:29:17', '2025-07-27 07:05:43', NULL, NULL, NULL),
	(1035, 'عدم امکان دریافت خروجی اکسل و CSV گزارش شارژ کارت ', 'باسلام و احترام\r\n دریافت خروجی اکسل و CSV ، گزارش  &quot; شارژ کارت&quot;  امکان پذیر نمی‌باشد.\r\nباسپاس', '202507-1035', 1, 25, 'Condition_final_done', 'high', NULL, '2025-07-26 05:42:31', '2026-02-21 11:40:48', NULL, NULL, NULL),
	(1036, 'بروز خطا در عملیات مارکت کردن پایانه ', 'با سلام و احترام\r\nدر منوی &quot;کارت&quot; - &quot;ثبت پایانه های خارجی&quot; به خطای تصویر پیوست مواجه می شویم. خواهشمند است بررسی نمایید.\r\nبا تشکر', '202507-1036', 8, 36, 'Condition_final_done', 'high', NULL, '2025-07-26 12:05:24', '2025-09-09 10:27:30', NULL, NULL, NULL),
	(1037, 'خطای ترمینال', 'با سلام\r\nاحتراما به استحضار می رساند نمونه ترمینال 31206301 بعد از دریافت پنج بار خطای 03 شاپرکی با کد خطای 6205 در کد علت خارجی(کدشبای ارسالی برای این پذیرنده فروشگاهی تعریف نشده است )، غیرفعال گردیده است، درصورتیکه میبایست پس  از یکبار دریافت خطای 03 غیر فعال شود.\r\n(طبق درخواست پرداخت نوین که هر ترمینال پس از دریافت یکبار خطای 03 غیر فعال گردد)\r\nدر ادامه بعد از 5 بار تراکنش 03 با خطای شاپرکی، نوع خطا به (4-4-ترمینال غیر فعال) تغییر یافته است ولی ترمینال را در بک افیس فعال نشان داده میشود .\r\n\r\nنمونه ترمینال دیگر 12171157 میباشد که به صورت صحیح بعد از یکبار خطای 03 با علت خارجی 6205 غیرفعال گردید ولی بعد از اینکه مشکل رفع گردید و ترمینال را مجدد در سوییچ فعال کردیم، با خطای 58 مواجه شدیم و بعد از چک کردن ترمینال مشخص شد که کدسوییچ ترمینال به جای عدد 7 به عدد 3 تغییر یافته است و به همین خاطر خطای 58 می دهد .\r\nاجبارا ترمینال را با پورت و ای پی سیپایی مجدد راه اندازی نمودیم و  تراکنش موفق انجام شد اما اگر مجدد پورت و ای پی را اینتکی تنظیم شود باز با خطای 58 مواجه خواهیم شد\r\nبا توجه به اینکه برای یک سری از ترمینال ها امکان تنظیم پورت و ای پی روی سیپا وجود ندارد و مشکل پذیرنده به هیچ صورت برطرف نمی شود تا زمانیکه ترمینال جهت تغییر کدسوییچ  به اینتک اعلام شود و همچنین امکان اعلام تک به تک پایانه ها به این صورت بسیار دشوار میباشد \r\nخواهشمند است این دو پایانه را بررسی نمایید و مشکل به صورت تعمیم یافته برای بقیه ترمینال ها نیز برطرف شود .\r\nتوضیح اینکه در این چند روز اخیر این قبیل موارد زیاد شده است و تنها دو نمونه ترمینال جهت بررسی خدمت حضور ارسال شده است.\r\nبا سپاس\r\n', '202507-1037', 3, 10, 'Condition_final_done', 'high', NULL, '2025-07-27 04:44:58', '2025-09-09 10:34:37', NULL, NULL, NULL),
	(1038, 'حذف شماره موبايل گروه مددجويان در بك آفيس دارندگی', 'باسلام و احترام خواهشمند كليه شماره موبايل هاي ثبت شده براي كارت هاي مسدود و غير مسدود فایل پیوست توسط همكاران شرکت اينتك از سیستم حذف شود ؛ طي بررسي هاي به عمل آمده : (طبق تیکت SR429432)\r\nبه دليل اطلاعات مشابهي كه براي مددجويان و يا مشتريان حقيقي ثبت شده است  و براي صدور جديد يك شماره مشتري مشترك براي هردو استفاده ميشود موبايل براي شخص حقيقي ثبت ميشود و همان اطلاعات براي مددجو نيز به روزرساني ميشود و موبايل ثبت ميشود. همچنين زماني كه پروژه كارتهاي مددجو سرباز و پرسنل و یا صدور کارت برای پرسنل بنياد تعاون و يا مددجويان راي باز راه اندازي شد. چون براي اين موارد بايد كارت براي سرباز و پرسنل , پرسنل بنياد تعاون يا مددجويان راي باز صادر ميشد برخي از نمايندگي ها اطلاعات آنها را در گروه مددجويان ارسال نموده و براي آنان صدور كارت در گروه مجددجويان انجام شده است و زماني كه كارت درگروه و الگوي صحيح ثبت شد چون اطلاعات مشتري قبلا در سيستم بوده ؛ از همان شماره مشتري استفاده شده و موبايل دارنده براي مددجويان به روزرساني شده است.  با سپاس ', '202507-1038', 8, 36, 'Condition_final_done', 'low', NULL, '2025-07-28 07:09:23', '2025-09-09 10:27:26', NULL, NULL, NULL),
	(1039, 'اطلاع رسانی دانتایم  بامداد جمعه 10 مرداد', 'با سلام و عرض ادب\r\n\r\n۱- واحد درخواست دهنده: اداره شبکه و مرکز داده\r\n۲- شرح تغییرات: بروزرسانی فایروال DMZ\r\n۳- تاریخ شروع: بامداد جمعه 10 مرداد ساعت ۰۱:۰۰\r\n۴- تاریخ پایان: بامداد جمعه 10 مرداد ساعت ۰۳:۰۰\r\n۵- میزان قطعی/اختلال: 10 دقیقه\r\n۶- سرویس های تحت تاثیر: کلیه سرویس های تراکنشی و غیر تراکنشی\r\n۷- دلایل: رفع آسیب پذیری ها و رعایت الزامات شاپرک\r\n۸- افراد مطلع: فناوری اطلاعات \r\n۹- افراد پاسخگو: توازنی زاده\r\nهماهنگی ها: نیاز به تست و بررسی سرویس های تراکنشی بعد از پایان تغییر\r\n\r\nباسپاس\r\n', '202507-1039', 3, 10, 'Condition_final_done', 'high', NULL, '2025-07-28 10:26:10', '2026-02-21 11:40:42', NULL, NULL, NULL),
	(1040, 'خطای در مرحله نهائی درخواست &quot;صدور رونوشت&quot;', 'با سلام، لطفا نسبت به حذف درخواست  &quot;صدور رونوشت&quot; شماره اندیکاتور 10060795 و شماره تقاضاهای 634959 و 634953 نمایندگی بوشهر اقدامات لازم را مبذول نمایید. با سپاس ', '202507-1040', 8, 36, 'Condition_final_done', 'high', NULL, '2025-07-28 12:00:05', '2025-09-09 10:27:16', NULL, NULL, NULL),
	(1041, 'بررسی شماره تقاضا وضعیت در حالت بازسازی فایل', 'باسلام، احتراما باستحضار میرساند شماره تقاضا های 634895-634896-634897-634898  در حالت بازسازی فایل می باشد وامکان صدور کارت میسر نمی باشد .لذا خواهمشنداست در خصوص رفع مشکل بوجود آمده اقدام مقتضی انجام پذیرد .باتشکر', '202507-1041', 8, 36, 'Condition_final_done', 'high', NULL, '2025-07-28 12:02:36', '2025-09-09 10:27:10', NULL, NULL, NULL),
	(1042, 'گزارش شارژ صندوق ', 'باسلام و احترام\r\nخواهشمند است گزارش شارژ صندوق بر روی بک آفیس صادرکنندگی پیاده سازی گردد.\r\nباسپاس', '202507-1042', 1, 25, 'condition_acepted_test_auto', 'high', NULL, '2025-07-29 06:02:59', '2026-05-26 05:20:02', NULL, NULL, NULL),
	(1043, 'اعلام &quot;خطا در مرحله نهائی&quot;در سامانه اینتک براي نمايندگي اصفهان ', ' باسلام و احترام در هنگام رونوشت به صورت آنی در سامانه اینتک خطا به شرح تصویر پیوست نمایش داده می شود.شماره تقاضای 635005 می باشد. خواهشمند است اقدامات لازم صورت پذيرد. باسپاس', '202507-1043', 8, 36, 'Condition_final_done', 'high', NULL, '2025-07-29 06:18:29', '2025-09-09 10:27:03', NULL, NULL, NULL),
	(1044, 'خطای  خطای &quot;خطا در مرحله نهائی&quot;  نماینده اصفهان', 'باسلام و احترام ، لطفا جهت برطرف نمودن خطای &quot;خطا در مرحله نهائی&quot;  شماره تقاضاهای 634974، 634967، 634968، 634965 نمایندگی اصفهان اقدامات لازم صورت پذيرد. باسپاس', '202507-1044', 8, 36, 'Condition_final_done', 'high', NULL, '2025-07-29 12:21:21', '2025-09-09 10:26:48', NULL, NULL, NULL),
	(1045, 'درخواست حذف شماره موبايل هاي مددجو براي زندانيان', 'باسلام و احترام خواهشمند كليه شماره موبايل هاي ثبت شده براي كارت هاي مسدود و غير مسدود در فايل پيوست توسط همكاران شرکت اينتك حذف شود ؛ (قبلا با درخواست: SR429432 وضعیت: حل شده تاریخ ایجاد:   ۱۴۰۴/۰۵/۰۱ - شماره موبایل ها از پنل ارسال پيامك حذف شده در حال حاضر لطفا در بکافیس دارندگی نمایش اطلاعات مثل منوی کارت - کارت نيز موبايل ها ي ثبت شده حذف شده و نمايش داده نشود. با سپاس ', '202507-1045', 4, 36, 'Condition_final_done', 'high', NULL, '2025-07-29 12:53:47', '2025-09-09 10:28:27', NULL, NULL, NULL),
	(1046, 'مهم - رفع موارد پویش آسیب پذیری پذیری تیر ماه سال 1404', 'با سلام و احترام\r\nبه اطلاع میرساند نتایج پویش آسیب پذیری تیر ماه سال 1404و همچنین آخرین پورت اسکن با استفاده از سامانه TVM به پیوست تقدیم میگردد.\r\nخواهشمند است در اسرع وقت جهت رفع موارد اعلام گردد. پویش بعدی در  تاریخ 31/5/ 1404 صورت خواهد پذیرفت.\r\nبا سپاس\r\n****رمز فایل پیوستی از خانم کمایی دریافت گردد ****\r\n', '202507-1046', 3, 10, 'Condition_final_done', 'high', NULL, '2025-07-29 13:20:22', '2026-02-21 11:40:38', NULL, NULL, NULL),
	(1047, 'دامپ یا مستند تسهیم شناسه دار', 'با سلام  و احترام \r\nخواهشمند است دامپ یا مستند مرتبط با تسهیم شناسه دار (جهت پیاده سازی بروی دستگاه کارتخوان) را ارسال فرمایید.\r\nتسهیم شناسه دار: در این نوع تسهیم به ازای هر حساب علاوه بر شماره شبا و مبلغ، یک شناسه پرداخت نیز ارسال میگردد\r\n\r\nبه عنوان مثال :\r\niban1,amount1,purchaseId1;\r\niban2,amount2,purchaseId2;\r\n...\r\niban10,amount10,purchaseId10;\r\n\r\namount=amount1+amount2+...+amount10\r\n\r\nبا سپاس\r\n', '202507-1047', 3, 10, 'Condition_final_done', 'high', NULL, '2025-07-30 05:31:09', '2026-02-21 11:40:31', NULL, NULL, NULL),
	(1048, 'ارزیابی تاریخ انقضاء شناسه - پروژه کشتی‌رانی', 'با سلام و احترام،\r\nبه استحضار می‌رساند با توجه به نیازمندی‌های فنی پروژه کشتی‌رانی، الگوریتم مشخصی جهت تولید شناسه‌ها از سوی شرکت توسعه فناوری رفاه پردیس طراحی گردیده است که در ساختار آن، اطلاعات مربوط به تاریخ انقضا نیز به‌صورت کدشده لحاظ شده است.\r\n\r\nخواهشمند است دستور فرمایید در سمت سوئیچ، فرآیندی پیاده‌سازی گردد تا شناسه‌های دریافتی بر اساس الگوریتم اعلامی تحلیل شده و تاریخ انقضای استخراج‌شده از آن مورد بررسی و اعتبارسنجی قرار گیرد. بدیهی است که انجام این اقدام در راستای اطمینان از صحت تراکنش‌ها و افزایش امنیت فرایندهای مرتبط می‌باشد.\r\n\r\nپیشاپیش از همکاری و توجه جناب‌عالی کمال تشکر را داریم.', '202507-1048', 3, 26, 'Condition_regect', 'high', NULL, '2025-07-30 05:54:50', '2026-02-09 06:33:09', NULL, NULL, NULL),
	(1049, 'خطای 92  - پروژه اربعین', 'با سلام \r\nدر خصوص پروژه اربعین \r\nPr code: 410000\r\n خطای 92 دریافت می شود. خواهشمند است بررسی و رفع فرمایید.\r\nبا سپاس', '202507-1049', 3, 10, 'Condition_final_done', 'high', NULL, '2025-07-30 05:56:52', '2026-02-21 09:10:08', NULL, NULL, NULL),
	(1050, 'خطای در مرحله نهائی نمایندگی خوزستان', 'با سلام، پیرور مذاکره تلفنی شماره تقاضاهای (635027، 634946، 635025) نمایندگی خوزستان در خصوص خطای &quot;خطا در مرحله نهائی&quot; در خواست صدور خدمتتان ارسال می گردد. با سپاس ', '202508-1050', 8, 36, 'Condition_final_done', 'high', NULL, '2025-08-02 06:46:53', '2025-09-09 10:28:23', NULL, NULL, NULL),
	(1051, 'درخواست ایجاد View دیتابیس با دسترسی محدود جهت مشاهده تراکنش‌های شرکت کشتی‌رانی', 'با سلام و احترام،\r\n\r\nبدین‌وسیله به اطلاع می‌رساند، جهت بررسی و نظارت دقیق‌تر بر تراکنش‌های مالی مربوط به شرکت کشتی‌رانی، نیازمند ایجاد یک View در دیتابیس شما می‌باشد که اطلاعات مربوطه را مشاهده نماید.\r\n\r\nبا توجه به الزامات امنیتی و کنترل سطح دسترسی، خواهشمند است این View تنها برای یک کاربر اختصاصی، یعنی بانک رفاه،تعریف گردد.\r\n\r\nلطفاً در صورت امکان، نسبت به ایجاد View مذکور اقدام فرمایید و اطلاعات مربوط به نام کاربری و رمز عبور دسترسی اختصاص داده‌شده را به صورت رسمی به این واحد اعلام نمایید تا اقدامات لازم از سوی تیم فنی صورت پذیرد.\r\n\r\nاز همکاری ارزشمند شما کمال تشکر را داریم.', '202508-1051', 9, 26, 'Condition_final_done', 'high', NULL, '2025-08-02 07:52:39', '2026-05-12 07:35:21', NULL, NULL, NULL),
	(1052, 'ارائه دسترسی تغییر و صدور مجدد رمز کارت مجازی ', 'با سلام و احترام، خواهشمند است مطابق نامه پیوست  در خصوص امکان ارائه دسترسی تغییر رمز و صدورمجدد رمز  کارت مجازی (پروژه کارت های مجازی شرکت تابان آتی پرداز) و نحوه ازائه آن دستورات و اقدامات لازم را مبذول نموده و رهنمود های لازم را ارائه نمایید. با سپاس ', '202508-1052', 8, 36, 'Condition_need_action', 'high', NULL, '2025-08-02 08:35:16', '2025-08-04 07:57:03', NULL, NULL, NULL),
	(1053, 'زمان دقیق برگزاری مانور سایت پشتبان', 'با سلام و احترام\r\nخواهشمند است زمان دقیق برگزاری مانور سایت پشتیبان را جهت هماهنگی های لازم، به صورت مکتوب اعلام فرمایید.\r\nبا توجه به اهمیت آمادگی واحد ها در زمان اجرای مانور، اعلام زمان بندی از پیش، به منظور برنامه ریزی و اطمینان از همکاری موثر ضروری می باشد.\r\nبا سپاس\r\n', '202508-1053', 3, 10, 'Condition_final_done', 'high', NULL, '2025-08-02 13:27:24', '2025-09-09 10:34:28', NULL, NULL, NULL),
	(1054, 'رفع مشکل در سامانه اینتک مخزن کارت  پیمانکار سپاس', 'با سلام و احترام \r\nخواهشمند است با توجه به مشکل پیش آماده در سامانه اینتک  پیمانکار سپاس به شرح ذیل:قسمت تعاریف -انبار کارت پیمانکاران- مخزن کارت  گزینه اضافع کردن تعداد با خطای تصویر پیوست مواجه میشود. \r\nلذا خواهشمند است در صورت امکان جهت رفع مشکل پیمانکار اقدامات لازم مبذول نمایید. \r\nبا تشکر از همراهی شما', '202508-1054', 8, 36, 'Condition_final_done', 'low', NULL, '2025-08-03 11:59:00', '2025-09-09 10:26:39', NULL, NULL, NULL),
	(1055, 'خطای مک (مغایرت در مک پیام دریافتی) ترمینال  20077507', 'با سلام\r\nبرای اولین تراکنش دستگاه با نسخه RKI با شماره ترمینال  20077507 بروی کانال جدید 10010، خطای مک (مغایرت در مک پیام دریافتی) دریافت می شود\r\nخواهشمند است بررسی فرمایید.\r\nبا سپاس', '202508-1055', 3, 10, 'Condition_final_done', 'high', NULL, '2025-08-03 14:41:46', '2025-09-09 10:39:23', NULL, NULL, NULL),
	(1056, 'بررسی مشکل  ارسال تراکنش تسویه اتوماتیک (220) پس از ارسال 420 از سوی دستگاه پوز', 'با سلام و احترام\r\nترمینال 30789134 در تاریخ 1404/04/31 تراکنشی با شماره مرجع 512346099284   به مبلغ 21400000 داشته است. \r\nدر زمان 59;33;11 تراکنش خرید انجام شده که بلافاصله تراکنش 420 از سوی پوز نیز ارسال گردیده ولی خطای 25 دریافت کرده است.\r\nچرا با توجه به اینکه رسید ناموفق چاپ شده است همچنان سوییچ تراکنش تسویه اتوماتیک (220) را ارسال کرده است؟\r\nچرا با توجه به تعدد نمونه های مشابه نسبت به رفع آن توجهی صورت نگرفته است؟\r\nخواهشمند است بررسی و رفع گردد.\r\nبا سپاس\r\n', '202508-1056', 3, 10, 'Condition_final_done', 'high', NULL, '2025-08-03 15:16:49', '2025-12-30 06:02:03', NULL, NULL, NULL),
	(1057, 'حذف حالت پیش فرض مقادیر چاپ رسید', 'با سلام و احترام\r\nخواهشمند است حالت پیش فرض مقادیر چاپ رسید برداشته شود.\r\nبا سپاس', '202508-1057', 3, 10, 'Condition_final_done', 'medium', NULL, '2025-08-04 07:07:30', '2026-02-21 11:40:21', NULL, NULL, NULL),
	(1058, 'ایجاد کاربر جدید برای ثبت تیکت', 'با سلام و احترام، خواهشمند است در خصوص ایجاد دسترسی برای سامانه تیکتینگ اینتک برای سرکار خانم سحر سلیمی با مشخصات ذیل اقدام مقتضی مبذول فرمایید.\r\nنام و نام خانوادگی : سحر سلیمی\r\nایمیل : s.salimi@pec.ir\r\nکد ملی : 0017513707\r\nموبایل : 09106707477', '202508-1058', 1, 43, 'Condition_final_done', 'low', NULL, '2025-08-04 11:57:19', '2026-02-22 13:52:46', NULL, NULL, NULL),
	(1059, 'حجم و میزان تحمل سرویس (tps) برای سایت پشتیبان', 'با سلام \r\nخواهشمند است با توجه به تجهیزاتی که در خصوص سایت پشتیبان تخصیص یافته حجم و میزان تحمل سرویس (tps) را اعلام بفرمایید\r\nبا سپاس', '202508-1059', 3, 10, 'Condition_final_done', 'high', NULL, '2025-08-04 12:39:17', '2025-09-09 10:38:35', NULL, NULL, NULL),
	(1060, 'درخواست در نظر گرفتن تراکنش‌های دارای پاسخ ۴۲۰ با ۲۲۰ متعاقب به عنوان موفق', 'با سلام و احترام؛\r\nخواهشمند است ترتیبی اتخاذ فرمایید که تراکنش‌هایی که ابتدا با کد پاسخ ۴۲۰ مواجه می‌شوند و بلافاصله پس از آن کد ۲۲۰ برای همان تراکنش صادر می‌شود، به عنوان تراکنش موفق در نظر گرفته شوند.\r\nبا توجه به تأثیر مستقیم این موضوع بر فرآیندهای عملیاتی، خواهشمند است این درخواست به قید فوریت بررسی و اعمال گردد.', '202508-1060', 3, 26, 'Condition_final_done', 'high', NULL, '2025-08-05 05:46:07', '2026-02-22 14:04:26', NULL, NULL, NULL),
	(1061, 'تغییر سوییچ کد 12171157  ', 'با سلام\r\n خواهشمند است سوییچ کد ترمینال 12171157  به عدد 7 تغییر یابد.\r\nبا سپاس', '202508-1061', 3, 10, 'Condition_final_done', 'high', NULL, '2025-08-05 07:24:33', '2025-12-30 06:01:54', NULL, NULL, NULL),
	(1062, 'بررسی اعمال تسهیم پرداخت شناسه دار', 'با سلام\r\nخواهشمند است تراکنس تسهیم شناسه دار  ترمینال 11332265 بررسی گردد آیا تسهیم به درستی اعمال شده است؟\r\nشماره مرجع 5124499180139', '202508-1062', 3, 10, 'Condition_final_done', 'medium', NULL, '2025-08-05 12:06:05', '2026-02-21 11:26:56', NULL, NULL, NULL),
	(1063, 'ارائه تراکنش ها بدون تاخیر در &quot;گزارش تراکنش دارنده کارت&quot;', 'با سلام و احترام، به استحضار می رساند در سامانه بکافیس دارندگی اینتک، گزارشات مالی/گزارش تراکنش دارنده کارت ، تراکنش ها ی اسناد با یک روز تاخیر ارائه می شود به  دلیل نیاز واحد مالی، واحد مذکور خواستار ارائه تراکنش ها به صورت لحظه ای و بدون تاخیر می باشند. لذا خواهشمند است در این خصوص اقدامات و دستورات لازم را مبذول نمایید. با سپاس ', '202508-1063', 8, 36, 'Condition_final_done', 'high', NULL, '2025-08-06 07:07:13', '2025-09-09 10:26:29', NULL, NULL, NULL),
	(1064, 'افزایش مبلغ واریز تاپ', 'با سلام و احترام\r\nخواهشمند است الگوهایی که قابلیت واریز تاپ را دارند به 100 میلیون تومان با تعداد تراکنش 5 عدد در روز افزایش یابند. باتشکر', '202508-1064', 8, 36, 'Condition_final_done', 'high', NULL, '2025-08-06 09:14:43', '2025-09-09 10:26:18', NULL, NULL, NULL),
	(1065, 'خطای 58 - ترمینال 12171157  ', '\r\nبا سلام\r\nبرای  ترمینال 12171157  خطای 58 با کد علت&quot; داخلی 3-3 رکورد مجوزهای ترمینال یافت نشد &quot; مشاهده می شود خواهشمند است بررسی و رفع گردد.\r\nبا سپاس ', '202508-1065', 3, 10, 'Condition_final_done', 'high', NULL, '2025-08-06 09:32:38', '2025-09-09 10:34:11', NULL, NULL, NULL),
	(1066, 'درخواست بررسی سرویسهای موجود جهت استفاده در پروژه کارت های مجازی close loop با کد محصول 26', 'با سلام و احترام، \r\nبا توجه به فوریت راه اندازی پروژه کارت مجازی Close Loop (در پروژه شهروند و ...) با کد محصول 26 با قابلیت شارژ مجدد ، طی مذاکره شفاهی جناب آقایان محمدی و جهانگیر برخی از سرویس ها به شرح زیر در بک آفیس اینتک موجود بود. لذا  خواهشمند است سرویس های معادل که امکان بهره برداری از آنها در این پروژه وجود دارد را اعلام فرمائید.\r\nلیست سرویسها:\r\n1-Balance\r\n2- VirtualIssueGiftCard\r\n3-Active\r\n4-DeActive\r\n5-ChargeCard\r\n6-GetPrimaryPassword\r\n7-RenewCard\r\n', '202508-1066', 1, 37, 'Condition_final_done', 'medium', NULL, '2025-08-06 12:04:53', '2026-02-22 13:52:57', NULL, NULL, NULL),
	(1067, 'خطای 58 - ترمینال 11880500', 'با سلام\r\nبرای  ترمینال 11880500 خطای 58 با کد علت&quot; داخلی 3-3 رکورد مجوزهای ترمینال یافت نشد &quot; مشاهده می شود خواهشمند است بررسی و رفع گردد.\r\n(سوئیچ کد این ترمینال  باید 7 باشد)\r\nبا سپاس ', '202508-1067', 3, 10, 'Condition_final_done', 'high', NULL, '2025-08-09 08:40:44', '2025-09-09 10:34:04', NULL, NULL, NULL),
	(1068, 'خطای 58 - ترمینال 11880500', 'با سلام\r\nبرای  ترمینال 11880500 خطای 58 با کد علت&quot; داخلی 3-3 رکورد مجوزهای ترمینال یافت نشد &quot; مشاهده می شود خواهشمند است بررسی و رفع گردد.\r\n(سوئیچ کد این ترمینال  باید 7 باشد)\r\nبا سپاس ', '202508-1068', 3, 10, 'Condition_final_done', 'high', NULL, '2025-08-09 08:52:39', '2025-09-09 10:34:00', NULL, NULL, NULL),
	(1069, 'ترتیب فایل چاپ کارت منو صدور المثنی', 'با سلام و احترام\r\nخواهشمند است خروجی فایل چاپ کارت در منو صدور المثنی، به ترتیب &quot; شماره کارت &quot; ایجاد گردد.\r\n\r\nدر شرایط فعلی شماره کارت های فایل چاپ کارت دارای ترتیب نمی باشند.\r\n\r\nباسپاس', '202508-1069', 1, 25, 'Condition_final_done', 'high', NULL, '2025-08-10 07:03:28', '2026-02-21 11:26:42', NULL, NULL, NULL),
	(1070, 'خطای 3 هنگام خرید در بک آفیس', 'با سلام و احترام\r\nدر بعضی پایانه ها در بک آفیس اینتک به دلیل خطای 3 در هنگام خرید امکان نصب دستگاه پوز میسر نمیباشد اما همان پایانه بر روی سوئیچ سامان نصب و تراکنش دارد.پس از بررسی در بک آفیس ، علت خارجی و خطای &quot;کد کسب و کار پذیرنده ی فروشگاهی معتبر نمی باشد 6202 &quot; نمایش داده میشود.\r\nبه عنوان مثال پایانه 15055209 در بک آفیس دارای خطای 3 میباشد اما بر روی سوئیچ سامان دارای تراکنش.\r\nخواهشمند است با توجه به تعدد موارد اینچنینی بررسی فرمایید.\r\nبا سپاس\r\n', '202508-1070', 3, 49, 'Condition_final_done', 'medium', NULL, '2025-08-10 13:17:41', '2025-12-30 06:18:22', NULL, NULL, NULL),
	(1071, 'عدم تخصیص طرح کارت به پیمانکار ', 'با سلام، به استحضار می رساند طبق اعلام یکی از  پیمانکاران  چاپ کارت (پیمانکار مستقیم تاپ)  با کاربری golchin-parkashi2 و رول &quot;TestSOC و انواع چاپ&quot; در منوی تعاریف - انبارکارت اصلی طرح کارت را انتخاب و ثبت می کند ولی در منوی  تعاریف - انبارکارت پیمانکاران ، طرح انتخابی را نمی تواند مشاهده و استفاده کند . لذا خواهشمند است در این خصوص اقدامات لازم را مبذول نمایید. با سپاس ', '202508-1071', 8, 36, 'condition_in_progress', 'high', NULL, '2025-08-11 06:28:42', '2025-08-11 13:01:03', NULL, NULL, NULL),
	(1072, 'داخلی 4577 -ارجاع ردیف 48(درخواست دسترسی سرویس های پروژه کارت مجازی)درخواست تکمیلی تیکت : 419771-424053', 'پیرو مذاکرات تلفنی و به‌منظور رفع مشکلات پیش‌آمده در سرویس صدور کارت با نام، بدین‌وسیله درخواست می‌شود سرویس‌های زیر برای پروژه مذکور فراهم/فعال گردد:\r\nالف) سرویس یکپارچه «صدور کارت با نام کلوز لوپ مجازی شهروند» که در همان لحظه و در قالب یک درخواست، اقدامات زیر را انجام دهد:\r\nصدور کارت با مشخصات فردی؛\r\nشارژ کارت به مبلغ تعیین‌شده در همان لحظه؛\r\nفعال‌سازی کارت در همان لحظه؛\r\nمارکت‌کردن کارت روی گروه پذیرندگی تعیین‌شده در همان لحظه.\r\nب) سرویس‌های تکمیلی موردنیاز:\r\n– شارژ مجدد و دشارژ کارت؛\r\n– رونوشت.', '202508-1072', 0, NULL, 'condition_pending', 'low', NULL, '2025-08-11 06:58:01', '2025-08-11 06:58:01', 16, 9, 'CR434148'),
	(1073, 'داخلی 4577 -ارجاع ردیف 48(درخواست دسترسی سرویس های پروژه کارت مجازی)درخواست تکمیلی تیکت : 419771-424053', 'پیرو مذاکرات تلفنی و به‌منظور رفع مشکلات پیش‌آمده در سرویس صدور کارت با نام، بدین‌وسیله درخواست می‌شود سرویس‌های زیر برای پروژه مذکور فراهم/فعال گردد:\r\nالف) سرویس یکپارچه «صدور کارت با نام کلوز لوپ مجازی شهروند» که در همان لحظه و در قالب یک درخواست، اقدامات زیر را انجام دهد:\r\nصدور کارت با مشخصات فردی؛\r\nشارژ کارت به مبلغ تعیین‌شده در همان لحظه؛\r\nفعال‌سازی کارت در همان لحظه؛\r\nمارکت‌کردن کارت روی گروه پذیرندگی تعیین‌شده در همان لحظه.\r\nب) سرویس‌های تکمیلی موردنیاز:\r\n– شارژ مجدد و دشارژ کارت؛\r\n– رونوشت.', '202508-1073', 2, NULL, 'condition_acepted_test_auto', 'low', NULL, '2025-08-11 07:01:53', '2026-10-07 16:08:21', 16, 9, 'CR434148'),
	(1074, 'ثبت تراکنش‌های پروژه کشتیرانی به تفکیک شماره‌های IBAN موجود در پایگاه داده', 'با سلام و احترام\r\n\r\nبدینوسیله اعلام می‌گردد، با توجه به الزامات پروژه کشتی‌رانی، مقرر است فرآیند ثبت تراکنش‌ها به نحوی انجام پذیرد که به ازای هر تراکنش، به تعداد IBAN یک تراکنش در جدول مربوطه در پایگاه داده، رکورد مجزا ایجاد گردد.\r\nاین ثبت باید به صورت تفکیکی بر اساس هر IBAN انجام شود حتی در مواردی که شماره مرجع تراکنش تکراری درج شود.\r\nهمچنین برای تراکنش‌های دستگاه POS نیز همین روال صورت گردد.\r\n\r\nخواهشمند است اقدامات لازم جهت پیاده‌سازی و رعایت این رویه در سامانه مربوطه به عمل آید.', '202508-1074', 9, 26, 'Condition_official_bill', 'high', NULL, '2025-08-11 10:53:50', '2025-09-13 12:06:45', NULL, NULL, NULL),
	(1075, 'خطای &quot;انبار کارت پیمانکاران&quot;  برای پیمانکار سپاس ', 'با سلام، با توجه به تصویر پیوست پیمانکار سپاس در منوی تعاریف- انبار کارت پیمانکاران با انتخاب سپاس-عملیات : انواع چاپ، دنا -انبار کارت   با خطا مواجه می شود. لطفا بررسی و برطرف گردد.  با سپاس ', '202508-1075', 8, 36, 'Condition_final_done', 'high', NULL, '2025-08-13 06:20:30', '2025-09-09 10:26:08', NULL, NULL, NULL),
	(1076, 'درخواست تغییر نوع کارت', 'با سلام و احترام\r\nخواهشمند است &quot;نوع کارت&quot;  کارت های صادر شده  شناسه های صدور  682 و 721 و 735 و 761 از &quot; خرید&quot; به &quot; خرید با شارژ مجازی &quot; تغییر یابد.\r\nباسپاس\r\n', '202508-1076', 1, 25, 'Condition_final_done', 'low', NULL, '2025-08-13 06:23:49', '2026-02-21 11:26:32', NULL, NULL, NULL),
	(1077, 'درخواست لاگ IPG جهت اولویت‌های شاپرک', 'با سلام و احترام؛\r\nبدینوسیله شرکت پرداخت نوین به منظور هم‌راستاسازی فرآیندهای فنی و رعایت الزامات شاپرک، درخواست دریافت لاگ IPG مرتبط با اولویت‌های شاپرک را دارد. اطلاعات یادشده جهت پایش، تحلیل و ارائه مستندات تکمیلی به شرکت شاپرک مورد نیاز است.\r\nخواهشمند است دستور فرمایید نسبت به ارسال لاگ‌های مذکور در اسرع وقت، همکاری لازم مبذول گردد.\r\nپیشاپیش از مساعدت و همکاری ارزشمند جنابعالی کمال قدردانی را داریم.\r\n', '202508-1077', 3, 26, 'Condition_final_done', 'high', NULL, '2025-08-16 09:27:48', '2026-02-22 14:04:20', NULL, NULL, NULL),
	(1078, 'ایجاد PRcode جدید  با کد  950000 ا', 'با سلام و احترام\r\nخواهشمند است برای MTI: 800\r\n  PrCode جدیدی با کد  950000 ایجاد گردد \r\nو همچنین در پاسخ MTI: 810 مقدار فیلد 32 را بر گرداند\r\nهدف از این نیازمندی پیاده سازی فیلد 90 می باشد.\r\n', '202508-1078', 3, 10, 'Condition_regect', 'high', NULL, '2025-08-16 16:35:42', '2025-08-20 09:07:07', NULL, NULL, NULL),
	(1079, 'افزودن کارت به گروه کارت فولاد', 'با سلام و احترام\r\nخواهشمند است در گروه کارت فولاد کارت های قبلی حذف وکارت های جدید اضافه شود.\r\nلطفا نام گروه کارت تغییری نکند.\r\nلطفا در صورت هر گونه ابهام با شماره 09129596175 تماس حاصل فرمایید.', '202508-1079', 3, 10, 'Condition_final_done', 'high', NULL, '2025-08-17 04:52:37', '2026-02-21 11:26:24', NULL, NULL, NULL),
	(1080, 'عدم محدویت سقف تراکنش برای صنوف خاص', ' با سلام واحترام\r\nبه استحضار می رساند کد اصناف ذکر شده در ذیل شامل صنوف خاص بوده و بایستی سقف مبلغ تراکنش برای این صنوف برداشته شود،لذا خواهشمند است در این خصوص اقدامات لازم را مبذول نمایید.\r\nکد صنف:6211 صندوق های سرمایه گذاری\r\nکد صنف :6212 کارگزاری های بورسی\r\nکد صنف :9803 خودرویی(کسب و کار های ویژه)\r\nبا سپاس فراوان\r\n', '202508-1080', 3, 10, 'Condition_final_done', 'medium', NULL, '2025-08-17 05:02:22', '2025-09-09 10:33:56', NULL, NULL, NULL),
	(1081, 'موارد ممیزی داخلی - بخش اول', 'با سلام و احترام\r\nطی ممیزی داخلی موارد زیر مشاهده شد. خواهشمند است در اسرع وقت بررسی و رفع گردد.\r\nبا سپاس', '202508-1081', 3, 10, 'Condition_final_done', 'high', NULL, '2025-08-17 05:11:53', '2026-02-21 11:26:17', NULL, NULL, NULL),
	(1082, 'مشکل در ویرایش گروه کارت ', 'با سلام و احترام، با توجه به رخداد &quot;IR435051&quot; کاربر در هنگام تغییر نمایندگی گروه کارت در منوی کارت-گروه کارت همانند تصویر پیوست هنگام ویرایش از لیست نمایندگیها  گزینه مورد نظر را انتخاب کرده و ثبت می کند. ولی در جدول ISSCardGroup طبق تصویر ارسالی کد نمایندگی در فیلد AgencyID جدول مذکور درج می گردد (در حالی باید در آن  Id جدول Agency درج گردد) و سپس در هنگام جستجو گروه کارت مورد نظر نمایش داده نمی شود و سیستم خطا می دهد . لذا خواهشمند است نسبت به برطرف نمودن مشکل مذکور اقدامات لازم را مبذول نمایید. \r\nمتن رخداد  IR435051 : &quot;سلام  در اینتک دارندگی زیر مجموعه کارت --بعد گروه کارت لطفا نام نمایندگی در گروه شرکت مهندسی طرح و توسعه راهبرد انرژی به نام ( تهران شمال شرق- خاوران الکترونیک پارسیان( کد 1250و نام گروه آسفالت توس به نام نمایندگی ( تهران مرکز- پردیس هوشمند پارسیان (کد 1251تغییر یابد .با تشکر&quot;', '202508-1082', 8, 36, 'Condition_final_done', 'high', NULL, '2025-08-17 06:56:54', '2025-09-09 10:25:50', NULL, NULL, NULL),
	(1083, 'عدم نمایش کامل منوی تعاریف - قابلیت ها ', 'با سلام از روز سه شنبه دسترسی به منوی تعارف، قابلیت ها، الگو، نمایش جزئیات (نمایش جزئیات) قطع می باشد. (خانم روح اله زاده) ', '202508-1083', 8, 36, 'Condition_final_done', 'high', NULL, '2025-08-17 06:58:30', '2025-09-09 10:25:38', NULL, NULL, NULL),
	(1084, 'درخواست بررسی خطای نوبیتکس', 'زمان تست تراکنش توسط دبیت کارت روی درگاه با خطای پیوست مواجه می شدند.\r\n\r\nتاریخ اعلام و درخواست بررسی به اینتک 1404/05/21', '202508-1084', 1, 37, 'Condition_final_done', 'low', NULL, '2025-08-17 07:46:55', '2026-02-22 13:53:08', NULL, NULL, NULL),
	(1085, 'خطای 58 برای مبالغ بالاتر از 50 میلیون تومان', 'با سلام و احترام\r\nپایانه 15068454 برای مبالغ بالاتر از 500,000,000 ریال خطای 58 دارد و تراکنش ناموفق ثبت میگردد.\r\nخواهشمند است نسبت به افزایش سقف مبلغ تراکنش اقدامات لازم را مبذول فرمایید.\r\nبا سپاس', '202508-1085', 3, 49, 'Condition_final_done', 'medium', NULL, '2025-08-18 11:21:21', '2025-12-30 06:24:19', NULL, NULL, NULL),
	(1086, ' تست و آزمون گواهی پروژه نماد روز دوشنبه مورخ 1404/06/03 - مهم', ' با سلام و احترام\r\nپیرو تست و آزمون بر روی سایر IIN های آن شرکت در پروژه گواهی نماد سدرا به استحضار می رساند، \r\nتاریخ تست و آزمون آن شرکت بر روی Bin:052 روز دوشنبه مورخ 03/06/1404 خواهد بود . از این رو مقتضی است اقدامات لازم در این خصوص را بعمل آورید.\r\nبا سپاس\r\n', '202508-1086', 3, 10, 'Condition_final_done', 'high', NULL, '2025-08-19 05:37:52', '2025-09-09 10:33:40', NULL, NULL, NULL),
	(1087, 'وارده 12067-ارائه سرویس شارژ گروهی کارت کادونا', 'درخواست ایجاد سرویس شارژ گروهی کارتهای کادونا با شرایط زیر:\r\nامکان شارژ گروهی با سقف تعدادی 50کارت\r\nامکان شارژ با مبالغ مختلف در یک درخواست\r\nلازم بذکر است سرویس شارژ تکی که در حال حاضر در حال استفاده است ChargeKadonaCard می باشد\r\n', '202508-1087', 2, NULL, 'condition_acepted_test_auto', 'low', NULL, '2025-08-19 10:35:49', '2026-10-07 16:08:21', 16, 9, 'CR434189'),
	(1088, 'داخلی 16669-درخواست سرویس های صدور کارت مجازی بی نام عطف به صدور مجوز سرویس ', 'در پروژه کارت مجازی بی نام سرویس یکپارچه زیر موردنیاز است. لازم بذکر است مجوزهای لازم طی مراحل همین نامه اخذ شده\r\n1-صدور کارت بی‌نام از رنج های از پیش تعریف شده\r\n2-شارژ آنی و شارژ مجدد کارت به مبلغ اعلامی.\r\n3-مارکت/ست‌شدن کارت روی پایانه‌های ازپیش‌تعریف‌شده.\r\n4-فعال‌سازی کارت در لحظه صدور\r\n5-بدون نیاز به اعلام منبع شارژ (نظیر شماره چک).\r\n6-صدور رونوشت و تمدید', '202508-1088', 2, NULL, 'Condition_official_bill', 'low', NULL, '2025-08-19 10:37:26', '2025-10-07 08:52:58', 16, 9, 'CR434162'),
	(1089, 'دامپ پارس نشده (خام) تراکنش خرید Consumer QR', 'با سلام و احترام\r\nخواهشمند است جهت توسعه سرویس Consumer QR کهربا، دامپ پارس نشده (خام) تراکنش خرید را ارسال فرمایید.\r\nبا تشکر \r\n', '202508-1089', 3, 10, 'Condition_regect', 'medium', NULL, '2025-08-20 05:10:55', '2025-08-26 07:22:50', NULL, NULL, NULL),
	(1090, 'رفع خطای پذیرندگی خرداد و تیر 1404- مهم', 'با سلام \r\nاحتراما گزارش خطاهای پذیرندگی خرداد و تیر 1404 به پیوست ارسال می گردد.\r\nخواهشمند است تا تاریخ 05 شهریور ما 1404 راهکار  و برنامه زمانبندی جهت رفع خطاهای موجود ارائه فرمایید \r\nو در صورت نیاز به اعمال تغییرات بروی سوییچ جهت هماهنگی برگزاری دانتیام اعلام فرمایید.\r\nبا سپاس\r\n', '202508-1090', 3, 10, 'Condition_final_done', 'high', NULL, '2025-08-20 06:40:12', '2026-02-21 08:39:53', NULL, NULL, NULL),
	(1091, 'افزودن متن برای پیامک شارژ کارت', 'باسلام و احترام\r\nخواهشمند است بر روی منو شارژ کارت قسمتی جهت وارد نمودن متن برای پیامک واریزی اضافه گردد.\r\nاین متن تنها برای شارژهای بک آفیسی _ واریزی های بک آفیسی  _ می‌باشد.\r\nباسپاس', '202508-1091', 1, 25, 'Condition_final_done', 'high', NULL, '2025-08-20 09:00:18', '2026-02-21 08:40:08', NULL, NULL, NULL),
	(1092, 'غیر فعالسازی مرداد ماه', 'با سلام و احترام\r\nخواهشمند است ترمینال های لیست پیوست بروی سوئیچ غیر فعال گردد.\r\nبا سپاس\r\n', '202508-1092', 3, 10, 'Condition_final_done', 'high', NULL, '2025-08-25 10:16:30', '2026-02-21 08:40:12', NULL, NULL, NULL),
	(1093, 'عدم نمايش نام گروه آبياران سربند با شناسه خارجي 14453 در قسمت گروه كارت', 'باسلام به اطلاع ميرساند در قسمت دارندگي بك آفيس قسمت كارت زير مجموعه آن گروه كارت : نام گروه آبياران سربند با شناسه خارجي 14453 در قسمت گروه كارت جستجو كه ميشود. نام گروه نمايش داده نميشود و اطلاعاتي يافت نميشود. خواهشمند است جهت رفع مشكل دستور مقتضي صادر فرماييد. باتشكر', '202508-1093', 8, 36, 'Condition_final_done', 'high', NULL, '2025-08-25 13:25:13', '2025-09-09 10:24:27', NULL, NULL, NULL),
	(1094, 'موارد سایت پشتیبان جهت ممیزی روز چهارشنبه مورخ 5 شهریور ماه', ' با سلام و احترام \r\nخواهشمند است با توجه به ممیزی روز چهارشنبه مورخ 5 شهریور ماه و انجام تراکنش نمونه و مشاهده لاگ توسط کارشناسان شاپرک در هاست بهرامی  موارد زیر تحویل گردد:\r\n1-   تحویل sp دیتابیس جهت مانیتورینگ تک تک کانالها در سامانه Zabbix سایت پشتیبان\r\n2- راه اندازی مانیتوینگ acq-monitoring سایت پشتیبان\r\n3- مستندات و سیگنالینگ سایت پشتیبان\r\n4- دسترسی Splank  به دیتابیس \r\nبا سپاس', '202508-1094', 3, 10, 'Condition_final_done', 'high', NULL, '2025-08-25 14:14:41', '2026-02-21 08:40:16', NULL, NULL, NULL),
	(1095, 'انتقال تراکنشهای قبض، شارژ و تاپ آپ از سوئیچ سیپا به سوییچ اینتک', '\r\n با سلام و احترام\r\nخواهشمند است بررسی فرمایید آیا امکان انتقال  تراکنشهای قبض، شارژ و تاپ آپ از سوئیچ سیپا به سوییچ اینتک وجود دارد یا خیر؟ \r\nدر صورت وجود چالش در این خصوص چالش ها را اعلام فرمایید\r\nبا سپاس', '202508-1095', 3, 10, 'Condition_final_done', 'medium', NULL, '2025-08-26 05:34:37', '2026-02-21 08:51:35', NULL, NULL, NULL),
	(1096, 'گزارش باگ های بک آفیس', 'با سلام و احترام؛\r\nبه پیوست فایل تصاویر باگ‌های سامانه back office به حضور ارسال میگردد. \r\nمطابق با تصاویر پیوست شده، فایل شماره ۱، پس از سرچ کردن در EditTextهای شماره‌پایانه/شماره‌پذیرنده/نام‌پذیرنده هیچ یک از عملیات‌های تخصیص IP/تخصیص کاربر بدرستی عمل نمی‌کند.\r\nفایل شماره ۲، مطابق با تصویر جستجو بدرستی عمل نمی‌کند.\r\nفایل شماره ۳، گزینه‌ی آخرین صفحه بدرستی عمل نمی‌کند.', '202508-1096', 2, 26, 'Condition_final_done', 'high', NULL, '2025-08-26 06:33:00', '2026-02-22 14:04:15', NULL, NULL, NULL),
	(1097, 'خطای رمز اشتباه در شماره کارت های هدیه زندان همدان', 'باسلام و احترام به اطلاع میرساند برخی از شماره کارتهای هدیه نمایندگی همدان خطای رمز اشتباه است میدهد و با توجه به این که رمز جدید برای شماره کارت اخذ میشود باز هم خطای رمز اشتباه است میدهد . لطفا جهت برررسی و رفع خطا دستور مقتضی صادر فرمایید. باتشکر \r\nشماره کارت \r\n6221062335829198\r\n6221062335829206\r\n6221062335829214\r\n فایل های تصاویر پیوست شده است. ', '202508-1097', 8, 36, 'Condition_final_done', 'high', NULL, '2025-08-27 05:42:01', '2026-02-22 13:53:13', NULL, NULL, NULL),
	(1098, 'درخواست ایجاد سه سرویس &quot;تعریف گروه کارت تسهیم جدید&quot; و&quot;ویرایش گروه کارت تسهیم قبلی&quot; و&quot; استخراج گروه کارت های سوییچ&quot;جهت سینک کردن اطلاعات گروه کارت تسهیم با هر دو سوییچ اینتک و مهرانا(درخواست 3624جیرا)', 'جهت سینک کردن اطلاعات گروه کارت تسهیم با هر دو سوییچ حداقل به سرویس های زیر نیاز است:\r\n.1 سرویس جهت تعریف گروه کارت جدید\r\n.1.1 ورودی: عنوان گروه کارت\r\n.1.2 خروجی: کد تخصیص یافته به گروه کارت\r\n.2 سرویس جهت ویرایش گروه کارت قبلی\r\n.2.1 ورودی: عنوان گروه کارت و کد گروه کارت\r\n.2.2 خروجی: کد گروه کارت ویرایش شده\r\n.3 سرویس جهت استخراج گروه کارت های سوییچ\r\n.3.1 ورودی: کد گروه کارت یا عنوان گروه کارت یا بدون ورودی\r\n.3.2 خروجی: لیست موارد با توجه به ورودی\r\n\r\n\r\nجهت استفاده در سرویس تسهیم ', '202508-1098', 2, NULL, 'Condition_regect', 'low', NULL, '2025-08-27 08:25:19', '2025-09-09 06:00:12', 16, 9, 'CR437035'),
	(1099, 'عدم نمايش كارتي كه نمايندگي يا گروه كارت تغيير مينمايد', 'سلام به اطلاع ميرساند كارت هايي از  نمايندگي تهران6 -كد 1033 به نمايندگي جديد : تهران شمال غرب-شرکت توسعه تجارت آراد باختر كد نمايندگي كد 1252 امكان مشاهده اطلاعات كارت وجود ندارد. مثلا در قسمت كارت - كارت -و يا ساير قسمت هاي ديگر مانند گزارش صدور و يا بخشهايي ديگر كه كارت جستجو ميشود/ با كاربري كد 1252 نيز امكان مشاهده اطلاعات وجود ندارد. \r\nكارتها از قسمت عمليات گروهي تغيير نمايندگي كارت تغيير داده ميشود\r\nبه عنوان مثال گروه : سازمان ملی زمین و مسکن كد گروه: 13668 ', '202508-1099', 8, 36, 'Condition_final_done', 'high', NULL, '2025-08-30 06:38:54', '2025-09-09 10:23:58', NULL, NULL, NULL),
	(1100, 'خطای 3 بر روی پایانه 15088062', 'با سلام و احترام\r\nپایانه 15088062 به دلیل خطای 6206-کدشبای ارسالی فعال نمی باشد دارای خطای 3 میباشد.\r\nلازم به ذکر است همین پایانه بر روی دستگاه سامان دارای تراکنش میباشد.\r\nخواهشمند است بررسی فرمایید.', '202508-1100', 3, 49, 'Condition_final_done', 'medium', NULL, '2025-08-30 10:48:36', '2025-12-30 06:24:22', NULL, NULL, NULL),
	(1101, 'درخواست بررسی دلیل صدور دو کارت برای یک کد ملی در نوبیتکس', 'با سلام و احترام، برای کد ملی 0082901654 دو کارت با شماره های زیر صادر شده است.لطفا بررسی شود که آیا در سرویس صدور نوبیتکس نیز مانند سایر کارتها ، یونیک بودن شماره ملی و عدم صدور دو کارت از یک محصول مد نظر قرار گرفته است؟\r\n\r\n6221064875066819 \r\n6221064861424568 ', '202508-1101', 7, 37, 'Condition_final_done', 'medium', NULL, '2025-08-30 10:50:07', '2026-02-22 13:53:22', NULL, NULL, NULL),
	(1102, 'عدم ثبت گروهی تسهیم / تخفیف در سامانه اینتک', 'با سلام واحترام ، \r\nبا عنایت به ثبت درخواست گروهی تخفیف در سامانه اینتک و همچنین تخصیص گروهی پایانه ها به سرویس پرداخت در مورخ 1404/06/05 همچنان در وضعیت ارسال شده به سوئیچ باقی مانده است. لذا با توجه به پیگیری نمایندگی خواهشمند است دستور اقدام عاجل صادر فرمایید.باتشکر', '202508-1102', 8, 51, 'condition_acepted_test_auto', 'medium', NULL, '2025-08-31 08:00:29', '2026-10-07 16:08:21', NULL, NULL, NULL),
	(1103, 'مشکل در فعال سازی/ غیر فعال سازی گروهی سرویس پرداخت در backoffice پذیرندگی سوئیچ اینتک ', 'با سلام \r\nاحتراما در فعالسازی/ غیر فعالسازی پایانه بصورت گروهی در سرویس پرداخت ، پس از آپلود فایل و ارسال به سوئیچ سرویس درخواستی برای پایانه فعال / غیر فعال نمی گردد.خواهمشند است دستور فرمایید با توجه به اهمیت موضوع در اسرع وقت مشکل برطرف گردد. باتشکر ', '202508-1103', 8, 51, 'condition_acepted_test_auto', 'medium', NULL, '2025-08-31 08:03:06', '2026-10-07 16:08:21', NULL, NULL, NULL),
	(1104, 'عدم نمايش نام برخي از گروه هاي كارت در قسمت گروه كارت', 'با سلام\r\n           احتراما به اطلاع میرساند  اخیرا مشاهده شده در اینتک دارندگی کارت:  قسمت کارت زیر مجموعه آن، گروه کارت  نام برخی از گروه های کارت یافت نمیشود.  و این موضوع باعث ایجاد مشکل در قسمت های دیگر برنامه میشود و امکان ثبت صدور کارت یا ... وجود ندارد.\r\nبه عنوان مثال گروه های ذیل در قسمت گروه کارت یافت نمیشود\r\nنام گروه : داده پرداز تصمیم ساز- تنخواه شناسه خارجی 14967\r\nنام گروه: آبیاران سربند شناسه خارجی 14453\r\nنام گروه : اوان - توسعه فن آوران  شناسه خارجی 1  (نام نمایندگی قبلی بدون نمایندگی)\r\n           شایان ذکر است در مواردی که تغییر نمایندگی صورت پذیرفته باشد این اتفاق صورت میگیرد اما بصورت قطعی نمیتوان گفت تنها دلیل عدم نمایش سایر گروه ها به این دلیل بوده است.  و نیاز به بررسی کلی و رفع مشکل دارد. خواهشمند است جهت رفع مشکل ایجاد شده دستور مقتضی صادر فرمایید. باتشکر', '202508-1104', 8, 36, 'Condition_final_done', 'high', NULL, '2025-08-31 08:44:47', '2025-09-09 10:23:44', NULL, NULL, NULL),
	(1105, 'پیاده سگمنت بر روی مارکت', 'باسلام و احترام\r\nعلاوه بر سگمنت اصلی، کارت ها دارای سگمنت دیگری باشند که این سگمنت دوم تنها بر روی مارکت اعمال گردد\r\nباسپاس', '202508-1105', 1, 25, 'condition_in_progress', 'high', NULL, '2025-08-31 14:42:23', '2025-09-02 07:35:57', NULL, NULL, NULL),
	(1106, 'درخواست بررسی خطای نوبیتکس', 'با سلام و احترام، \r\nنوبیتکس زمان فعالسازی کارت با OTP با خطای &quot;درخواست کارت یافت نشد&quot; مواجه می شود.\r\nاین خطا از روز چهارشنبه به آقای محمدی اعلام شده است.لطفا در اسرع وقت بررسی فرمائید.\r\nبا سپاس', '202509-1106', 1, 37, 'Condition_final_done', 'medium', NULL, '2025-09-06 06:15:53', '2025-09-09 10:23:32', NULL, NULL, NULL),
	(1107, 'افزایش تعداد رکوردهای صدور کارت', 'باسلام و احترام\r\nخواهشمند است تعداد رکوردهای مجاز برای فرایند صدور کارت به تعداد 10000 رکورد افزایش یابد.\r\nدر حال حاضر این تعداد 1200 رکورد می‌باشد.\r\nباسپاس', '202509-1107', 1, 25, 'Condition_final_done', 'high', NULL, '2025-09-06 09:36:06', '2026-02-21 11:26:13', NULL, NULL, NULL),
	(1108, 'درخواست افزودن قبوض شرکت پرداخت نوین در سوئیچ شرکت رفاه پردیس', 'با سلام و احترام؛\r\n\r\nاحتراماً، بدین‌وسیله به اطلاع می‌رساند که کلیه قبوض مرتبط با شرکت پرداخت نوین می‌بایست در سوئیچ شرکت رفاه پردیس اضافه و ثبت گردد.\r\nخواهشمند است اقدامات لازم در این خصوص انجام و نتیجه به این شرکت اعلام گردد.\r\n\r\nپیشاپیش از همکاری‌های شما صمیمانه سپاسگزاریم.', '202509-1108', 3, 26, 'Condition_final_done', 'high', NULL, '2025-09-06 11:12:32', '2026-02-22 14:04:11', NULL, NULL, NULL),
	(1109, 'ایجاد نام کازبری برای آقای عاطفی ', 'با سلام، خواهشمند ایت در سامانه تیکتینگ شرکت اینتک نام کاربری برای آقای عاطفی با مشخصات ذیل ایجاد نمایید:\r\nنام و نام خانوادگی : پویا عاطفی\r\nآدرس ایمیل : p.atefi@pec.ir\r\nشماره موبایل : 09123351486\r\nبا سپاس ', '202509-1109', 8, 36, 'Condition_final_done', 'high', NULL, '2025-09-06 12:04:16', '2025-12-30 06:14:38', NULL, NULL, NULL),
	(1110, 'نمایش اطلاعات تگ 48 فیلد 81 در دیتابیس', 'با سلام و احترام\r\nدر تگ 48 فیلد 81 مقدارد Sign code قرار میگیرد \r\nخواهشمند است این مقدار دیتابیس ذخیره گردد که امکان گزارش گیری از ترمینال ها بر این اساس Sign code وجود داشته باشد.\r\nبرای مثال دستگاه کارتخوان ترمینال 30011431 در تاریخ 1404-06-15 مقدار   Sign code : 102030405060708090  را به سوئیچ ارسال کرده است \r\nبا سپاس', '202509-1110', 3, 10, 'Condition_final_done', 'medium', NULL, '2025-09-06 14:15:17', '2026-02-21 11:26:03', NULL, NULL, NULL),
	(1111, 'اصلاح نوع تراکنش شارژ موبایل اپراتور به عنوان اوراق گام', 'با سلام و احترام،\r\n\r\nبدین‌وسیله اعلام می‌گردد که کد نوع تراکنش ۲۵ در سیستم بک‌آفیس که به اشتباه به عنوان شارژ موبایل اپراتور ثبت شده است، باید اصلاح و به عنوان اوراق گام منظور گردد.\r\n\r\nبا تشکر و احترام', '202509-1111', 3, 26, 'Condition_final_done', 'high', NULL, '2025-09-07 09:08:32', '2026-02-24 13:02:18', NULL, NULL, NULL),
	(1112, 'درخواست بررسی وجود سرویس گروهی تغییر حداقل و حداکثر مبلغ پایانه ', 'در اینتک سرویسی برای آپدیت مقادیر فیلدهای حداقل مبلغ تراکنش و حداکثر مبلغ تراکنش پایانه وجود دارد که در سطح پایانه و به صورت تکی می باشد و برای یک پایانه خاص این مقادیر را ویرایش می کند (UpdateVipTerminal) . در حال حاضر نیاز به سرویسی وجود دارد که این مبالغ به صورت گروهی ویرایش شود به عنوان مثال برای گروهی از پایانه ها بتوان این مقادیر را تغییر داد. با توجه به نیاز فعلی آیا در اینتک سرویسی وجود دارد که با استفاده از آن ، امکان ویرایش حداقل/حداکثر مبلغ تراکنش به صورت گروهی فراهم باشد؟  لطفا بفرمایید امکان ویرایش این دو فیلد از طریق چه سرویس هایی وجود دارد؟', '202509-1112', 1, 37, 'Condition_final_done', 'low', NULL, '2025-09-07 10:33:33', '2025-12-30 06:14:28', NULL, NULL, NULL),
	(1113, 'خطای 58 ترمینال 12141235', 'با سلام\r\nترمینال 12141325 خطای 58 دریافت میکند\r\nلطفا بررسی فرمایید\r\nبا سپاس\r\n', '202509-1113', 3, 10, 'Condition_final_done', 'high', NULL, '2025-09-07 10:57:10', '2025-09-09 10:33:19', NULL, NULL, NULL),
	(1114, 'افزودن شماره RRN بر روی متد شارژ مستقیم صندوق', 'باسلام و احترام\r\nخواهشمند است بر روی متد شارژ مستقیم صندوق، پارامتر ورودی RRN نیز اضافه گردد.\r\nدر صورت ارسال RRN تکراری ، خطا رخ دهد و از انجام شارژ تکراری جلوگیری گردد.\r\nخواهشمند است کد خطایی که پس از ارسال RRN تکراری رخ می دهد نیز ارسال گردد.\r\nباسپاس', '202509-1114', 1, 25, 'Condition_final_done', 'high', NULL, '2025-09-07 13:29:57', '2026-02-21 11:25:58', NULL, NULL, NULL),
	(1115, 'اصلاح عنوان فارسی پایانه ها', 'با سلام و احترام؛\r\nپیرو جلسه برگزار شده در تاریخ ۱۴۰۴/۰۶/۱۶ با جناب آقای یاوری و بر اساس بررسی های انجام شده، به استحضار می‌رساند عنوان فارسی تمامی پایانه ها به اشتباه مثلا با عبارت &quot;پایانه شماره ۷۰۰۰۶۸۸۸۷&quot;، ثبت شده است.\r\nشایان ذکر است مقدار صحیح این عنوان باید نام کسب و کار پذیرنده باشد؛ بعنوان مثال &quot;بازرگانی آیلار تجارت&quot;.\r\nلازم به ذکر است این عنوان در فرآیند دریافت رمز پویا توسط مشتریان نمایش داده می‌شود و اصلاح آن از اهمیت ویژه‌ای برخوردار است.\r\nخواهشمند است دستور فرمایید اقدامات لازم جهت اصلاح عنوان فارسی تمامی پایانه‌ها در اسرع وقت صورت پذیرد.\r\n\r\nبا تشکر', '202509-1115', 3, 26, 'condition_acepted_test_auto', 'high', NULL, '2025-09-08 05:39:56', '2026-06-07 09:21:33', NULL, NULL, NULL),
	(1116, 'فایل تسویه تراکنش های پروژه کلوز لوپ', 'با سلام و احتارم\r\nخواهشمند است فایل تسویه تراکنش های پروژه کلوز لوپ   با شماره ترمینال 20075860 در تاریخ 1404-06-03 جهت ارائه به بانک ارائه گردد.\r\nبا سپاس', '202509-1116', 3, 10, 'condition_in_progress', 'high', NULL, '2025-09-08 11:03:45', '2025-10-20 10:56:57', NULL, NULL, NULL),
	(1117, 'تسهیم درصدی IPG', 'با سلام و احترام،\r\n\r\nاحتراماً، به استحضار می‌رساند که در پروژه‌ی نظام مهندسی نیاز است راهکاری فراهم گردد تا امکان تعیین تراکنش تسهیم (api​/settlementPurchase) به صورت درصدی از مبدا وجود داشته باشد. لطفاً موضوع را بررسی و اقدامات لازم را مبذول فرمایید.\r\n\r\nبا تشکر و احترام', '202509-1117', 3, 26, 'Condition_final_done', 'high', NULL, '2025-09-09 10:49:32', '2026-02-22 14:03:58', NULL, NULL, NULL),
	(1118, 'درخواست عدم نمایش تقاضا های ایجاد شده در پیمانکاران مختلف ', 'پیرو مذاکره با پیمانکاران مختلف صدور کارت متوجه شدیم تقاضا هایی که در اینتک ثبت میشوند برای همه پیمانکاران قابل مشاهده است در صورتی که نباید به این شکل باشد . بعنوان مثال اگه تقاضایی جهت پیگیری به شرکت گلچین(پیمانکار مستقیم تاپ) اعلام شود اما تقاضا مربوط به شرکت الماس دنا (سپاس) باشد نباید اصلا اطلاعاتی در این مورد برای شرکت گلچین نماییش داده شود اما در حال حاضر تمامی تقاضا های نامربوط به شرکت گلچین برای این شرکت قابل مشاهده است . (مثال : شماره تقاضا 633074) \r\n', '202509-1118', 8, 52, 'condition_in_progress', 'low', NULL, '2025-09-09 11:53:51', '2025-09-11 09:18:44', NULL, NULL, NULL),
	(1119, 'گزارش شارژوب سرویس', 'طی بررسـی هـاي به عمـل آمـده ازگزارش سـرویس شارژکـارت هـدیه فیلـدهـاي شـماره پایانه ،rrn و شـماره کارت\r\nشارژکننـده درگزارش شارژکـارت ازوب ســرویس بصـورت null میباشـد،لاـزم به ذکر میباشـد سـرویس فوق توسـط\r\nشرکت تابان آتی پرداز فراخوانی وتوسط شـرکت اینتک شارژکارت صورت میگیرد لذا ترتیبی اتخاذگردد تافیلدهاي مورد\r\nنظر درگزارش به آدرس ذیل نمایش داده شود.\r\nاینتک دارندگی/گزارش مالی/گزارش شارژکارت از وب سرویس', '202509-1119', 8, 52, 'Condition_need_action', 'low', NULL, '2025-09-09 11:57:46', '2025-09-15 06:47:15', NULL, NULL, NULL),
	(1120, 'LOM   پروژه کلوز لوپ ', 'با سلام \r\nLOM   پروژه کلوز لوپ را تهیه و ارسال فرمایید.\r\nبا سپاس', '202509-1120', 3, 10, 'Condition_final_done', 'high', NULL, '2025-09-09 12:56:43', '2026-02-21 11:25:52', NULL, NULL, NULL),
	(1121, ' Pr code جهت انجام پروژه جدیدی به نام کیوسک طلا', 'با سلام و احترام\r\nخواهشمند است جهت انجام پروژه جدیدی به نام کیوسک طلا\r\nPr code جدیدی تعریف گردد که به واسه آن شماره موبایل را  سوئیچ دریافت کند\r\nقبل از انجام تراکنش،  سوئیچ  با استفاده از شماره موبایل و شماره کارت، سرویس احراز هویت قوی شاپرک فراخوانی  شود در صورت موفق بودن استعلام، اجازه انجام تراکنش شاپرکی را صادر کند\r\nدر غیر اینصورت با اعلام خطاای مشخص از انجام تراکنش جلوگیری کند.\r\nبا سپاس ', '202509-1121', 3, 10, 'Condition_regect', 'high', NULL, '2025-09-09 13:05:40', '2025-10-05 10:26:44', NULL, NULL, NULL),
	(1122, 'وایت‌لیست (White List)', 'با سلام پ\r\nبا توجه به تعدد نسخه‌های فعال بر روی سوئیچ‌، و همچنین بروز مشکلات متعدد ناشی از مغایرت نسخه‌ها، وجود باگ‌های فنی در برخی نسخه‌های قدیمی، و با در نظر گرفتن اهمیت استفاده از آخرین نسخه‌های به‌روز، خواهشمند است، پیاده‌سازی سازوکار وایت‌لیست (White List) جهت مدیریت نسخه‌های قابل‌اجرا روی سوئیچ‌ها صورت پذیرد.\r\nبا تشکر', '202509-1122', 3, 10, 'condition_acepted_test_auto', 'medium', NULL, '2025-09-11 07:21:52', '2026-03-14 11:38:06', NULL, NULL, NULL),
	(1123, 'بررسی خطا در استعلام کارت نوبیتکس', 'با سلام و احترام، نوبیتکس زمان استعلام کارت تستی با مشخصات تصویر پیوست ، با خطامواجه می شود.لازم بذکر است این کارت تستی در بک آفیس صادر شده است.', '202509-1123', 2, 37, 'Condition_final_done', 'low', NULL, '2025-09-13 06:38:17', '2025-12-30 06:13:50', NULL, NULL, NULL),
	(1124, 'ایجاد کانال Permanent  با کلید ثابت', 'با سلام و احترام\r\nخواهشمند است جهت اتصال لودبالانسر به سوئیچ،  کانال Permanent  ایجاد گردد و برای هر کانال یک کلید ثابت 1C1C1C  در نظر گرفته شود.\r\nلطفا در صورت نیاز به توضیحات بیشتر با آقای جهانگیری تماس حاصل فرمایید.\r\nبا سپاس\r\n', '202509-1124', 3, 10, 'Condition_final_done', 'high', NULL, '2025-09-13 07:22:47', '2025-12-30 06:01:48', NULL, NULL, NULL),
	(1125, 'تبدیل  کانال 4061  به کانال permanent  جهت پروژه کیوسک طلا ', 'با سلام\r\nخواهشمند است کانال 4061 تبدیل به کانال permanent  جهت پروژه کیوسک طلا شود و کلیدهای MAC,Pin,Data  نیز ارسال گردد. \r\nدر صورت عدم امکان این امر کانال جدیدی اختصاص یابد\r\nبا سپاس', '202509-1125', 3, 10, 'Condition_final_done', 'high', NULL, '2025-09-13 11:04:41', '2026-02-21 11:25:46', NULL, NULL, NULL),
	(1126, 'اتصال سگمنت مگارت به کیف پول تابان', 'اتصال سگمنت یک سگمنت مگا کارت صادرککندگی اینتک به عنوان اکسترنال اکانتینگ به کیف پول اعتباری تابان آتی پرداز - لازم به ذکر است قسمت اتصال سگمنت مگا کارت روی سوییچ صادرککندگی توسط آقای دارایی پایده سازی شده است و تست انجام شده است (نیازمند صدور پیش فاکتور ) - مستندات جدید شرکت تابان جهت به روز رسانی سرویس های کیف پول برای آقای دارایی ارسال خواهد شد.\r\nجهت اتصال سگمنت به کیف پول نیازمند وب سرویس جهت ارائه به شرکت تابان می باشد.\r\nهمچنین برای اتصال سگمنت مورد نظر به مگا کارت نیاز مند پر شدن چند فیلد مختلف می باشد لطفا برای توضیحات با آقای تفضلی تماس گرفته شود', '202509-1126', 9, NULL, 'Condition_official_bill', 'low', NULL, '2025-09-14 10:25:42', '2025-10-07 08:50:53', 16, 9, 'CR390061'),
	(1127, 'درخواست اصلاح تقاضا 640247  درج رمز دوم برای این تقاضا', 'باسلام و احترام به اطلاع میرساند در تقاضا 640247  رمز انتخاب نشده و این تقاضا در مرحله انتظار چاپ رمز باقی مانده و شرکت گلچین امکان صدور کارت را ندارد. لطفا برای این تقاضا رمز دوم انتخاب شود (درج شود ) تا امکان صدور این کارت وجودداشته باشد و به مرحله فعالسازی تبدیل شود ', '202509-1127', 8, 36, 'Condition_final_done', 'high', NULL, '2025-09-14 11:53:03', '2025-12-30 06:13:41', NULL, NULL, NULL),
	(1128, 'نمایش رکوردهای تکراری در فایل صدور کارت', 'باسلام و احترام\r\nخواهشمند است پس از بارگزاری فایل صدور کارت در صورت وجود رکورد تکراری ، &quot; ردیف رکوردهای تکراری &quot;  نمایش داده شود.\r\nباسپاس', '202509-1128', 1, 25, 'Condition_final_done', 'high', NULL, '2025-09-14 12:35:54', '2026-02-21 11:25:21', NULL, NULL, NULL),
	(1129, 'تغییر نوع کارت ', 'باسلام و احترام\r\nخواهشمند است نوع کارت های گروه کارت &quot; بن - شهرداری مشهد&quot; از &quot; خرید &quot; به &quot; مگا&quot; تغییر یابد.\r\nباسپاس', '202509-1129', 1, 25, 'Condition_final_done', 'high', NULL, '2025-09-14 12:48:55', '2026-02-21 08:40:55', NULL, NULL, NULL),
	(1130, 'حذف گروه کارت بن - پارس توان پرسام', 'باسلام و احترام\r\nخواهشمند است گروه کارت   &quot; بن - پارس توان پرسام&quot;    به شناسه 241  از منو گروه کارت حذف گردد.\r\nباسپاس', '202509-1130', 1, 25, 'Condition_final_done', 'high', NULL, '2025-09-16 06:28:03', '2026-02-21 08:40:45', NULL, NULL, NULL),
	(1131, 'مشکل خطای 03', 'با سلام و احترام\r\nدر چند روز اخیر شاهد تعداد ترمینال با خطای 03 هستیم \r\nکه در سامانه جام جم هیچ تغییری نداشته اند\r\nخواهشمند است در اسرع وقت بررسی گردد.\r\nنمونه\r\n30116989\r\n', '202509-1131', 3, 10, 'Condition_final_done', 'high', NULL, '2025-09-16 08:00:51', '2026-02-21 09:10:46', NULL, NULL, NULL),
	(1132, 'عدم نمایش رسوب (موجودی) برخی کارت ها', '\r\nموجودی برخی از کارت ها در جدول ISSReport.rep.DepositMoneyTest نمایش داده نمی شود. \r\n\r\nدر ستون موجودی فایل پیوست بصورت null نمایش داده میشود.\r\n', '202509-1132', 8, 52, 'Condition_final_done', 'medium', NULL, '2025-09-16 08:19:53', '2026-02-22 13:53:30', NULL, NULL, NULL),
	(1133, 'درج کلیدهای توسن در LB', 'با سلام\r\nخواهمند است در خصوص پروژه  سایت پشتیبان کلیدهای (ارسال شده)توسن در لود بالانسر  درج گردد.\r\nبا سپاس', '202509-1133', 3, 10, 'Condition_final_done', 'high', NULL, '2025-09-16 09:11:46', '2026-02-21 11:25:12', NULL, NULL, NULL),
	(1134, 'کانال P interchange  ', 'با سلام\r\nخواهشمند است کانال ارتباطی بین GW سایت بهرامی (پشتبان) وGW سایت پردیس به کانال P interchange  تبدیل گردد. که امکان درج اطلاعات در بروی دیتابیس وجود داشته باشد.\r\nبا سپاس', '202509-1134', 3, 10, 'Condition_final_done', 'low', NULL, '2025-09-16 09:15:57', '2026-02-21 11:25:05', NULL, NULL, NULL),
	(1135, 'حذف درخواست 640638 (صدور و شارژ)', 'با توجه به ثبت مجدد درخواست صدور و شارژ کارتهاي هدیه دانش آموزي شرکت پالایش پارسیان سپهر خواهشمند است در خصوص حذف شماره تقاضاي 640638 دستور مقتضی صادر فرمایید.', '202509-1135', 8, 52, 'Condition_final_done', 'medium', NULL, '2025-09-16 10:49:03', '2026-02-22 13:53:38', NULL, NULL, NULL),
	(1136, 'پیاده سازی فیلد 32 ', 'با سلام \r\nخواهشمند است جهت پیاده سازی فیلد 90 کانال جدید (یا از کانال های خالی موجود) ایجاد گردد\r\nکه شامل  فیلد 32 و همه فیلدهای مورد نیاز جهت تراکنش  باشد.\r\nهمچنین این تغییرات بروی کانال تستی 40800 نیز پیاد سازی گردد.\r\n', '202509-1136', 3, 10, 'Condition_final_done', 'medium', NULL, '2025-09-16 14:04:51', '2026-02-21 09:01:03', NULL, NULL, NULL),
	(1137, 'گزارش مشکل در اعمال تغییرات سطح دسترسی در بک‌آفیس', 'با سلام و احترام،\r\n\r\nپیرو بررسی‌های انجام شده در بخش بک‌آفیس، به اطلاع می‌رساند که در منوی امنیت بطور مثال در گزینه نقش AcquireAdmin، سطح دسترسی پایانه‌ها در بخش «تخصیص مدل تسهیم» شامل دو مورد می‌باشد. متأسفانه زمانی که هر دو مورد را ثبت می‌کنیم، تغییرات اعمال نمی‌گردد و تنظیمات به‌روزرسانی نمی‌شوند.\r\n\r\nلطفاً در صورت امکان راهنمایی و همکاری لازم جهت رفع این مشکل را مبذول فرمایید.', '202509-1137', 1, 26, 'Condition_final_done', 'low', NULL, '2025-09-17 07:30:25', '2026-02-22 14:03:51', NULL, NULL, NULL),
	(1138, 'رد درخواست شارژ توسط واحد دارندگان کارت', 'باسلام و احترام\r\nخواهشمند است امکان &quot;رد درخواست شارژ توسط واحد دارندگان کارت &quot; قبل از اینکه تایید مالی صورت گیرد، پیاده سازی گیرد.\r\nباسپاس\r\n\r\n', '202509-1138', 1, 25, 'Condition_final_done', 'high', NULL, '2025-09-17 08:29:59', '2026-02-21 09:00:49', NULL, NULL, NULL),
	(1139, 'مغایرت نام پذیرنده در سامانه MMS و درگاه پرداخت', 'با سلام و احترام،\r\n\r\nبنا به بررسی‌های انجام شده، مشخص گردید که نام پذیرنده در سامانه MMS با نام پذیرنده ثبت شده در درگاه پرداخت مغایرت دارد. به عنوان نمونه، پذیرنده باشگاه خلیج فارس در سامانه MMS به اشتباه تحت عنوان باشگاه پارسه در درگاه پرداخت ثبت شده است.\r\n\r\nلطفاً در اسرع وقت نسبت به اصلاح این مغایرت اقدام فرمایید تا از بروز مشکلات احتمالی جلوگیری گردد.', '202509-1139', 1, 26, 'Condition_final_done', 'medium', NULL, '2025-09-17 11:42:33', '2026-02-22 14:03:45', NULL, NULL, NULL),
	(1140, 'باگ غیرفعال بودن مدل تسهیم کشتی‌رانی', 'با سلام و احترام؛\r\nمطابق با تصاویر پیوست شده، ترمینال مربوط به پروژه کشتی‌رانی، 70054258، مدل تسهیم آن بعد از انجام ویرایش همچنان غیرفعال می‌باشد.\r\nضمناً مطابق با تصویر ۲، وضعیت آن را فعال نشان می‌دهد.\r\nلطفاً همکاری لازم جهت رفع این مشکل را مبذول فرمایید.\r\n\r\n', '202509-1140', 1, 26, 'Condition_final_done', 'high', NULL, '2025-09-20 06:24:28', '2026-05-12 07:34:52', NULL, NULL, NULL),
	(1141, 'دریافت گزارش', 'خواهشمند است جهت ارسال گزارش سازمان هایی که قابلیت &quot;انتقال از&quot;فعال دارند اقدام فرمایید. با سپاس\r\nشایان ذکر است امکان دریافت این گزارش براي واحد دارندگان در منو &quot;تعاریف&quot;و قسمت &quot;قابلیت ها&quot;میسر نمیباشد.\r\n', '202509-1141', 4, 52, 'Condition_final_done', 'low', NULL, '2025-09-20 07:32:46', '2026-02-22 13:53:46', NULL, NULL, NULL),
	(1142, 'نمایش تراکنش های سروشی بر روی گزارش تراکنش های کارت بک آفیس صادرکنندگی', 'باسلام و احترام\r\nخواهشمند است تراکنش های 200 ای که سروشی شده اند، بر روی گزارش تراکنش های کارت بک آفیس صادرکنندگی نمایش داده شوند.\r\n\r\nتراکنش های مذکور با  &quot; فیلدی&quot;  یا  &quot;عنوانی &quot; از سایر تراکنش های 200 مجزا گردد.\r\n\r\nباسپاس', '202509-1142', 1, 25, 'condition_acepted_test_auto', 'high', NULL, '2025-09-20 08:27:53', '2026-05-24 11:22:03', NULL, NULL, NULL),
	(1143, 'ترمینال تستی', 'با سلام\r\nخواهشمند است لیست ضمیمه به ترمینال های تستی اضافه گردد.\r\nبا سپاس', '202509-1143', 3, 10, 'Condition_final_done', 'medium', NULL, '2025-09-21 06:33:40', '2026-02-21 08:51:28', NULL, NULL, NULL),
	(1144, ' فیلد 53 جدید برای کانال 10010', 'با سلام و احترام\r\nخواهشمند است فیلد 53 جدید برای کانال 10010 ایجاد گردد.\r\nبا سپاس', '202509-1144', 3, 10, 'Condition_final_done', 'high', NULL, '2025-09-21 12:48:00', '2026-02-21 08:49:39', NULL, NULL, NULL),
	(1145, 'تخصیص پایانه به مارکت پروژه فروش کارتخوان', 'باسلام و احترام\r\nخواهشمند است شناسه صدور کارت 1153 از گروه کارت &quot;بن - دفاتر و نمایندگی&quot;  به مارکت  &quot; پروژه فروش کارتخوان &quot; تخصیص داده شود.\r\nباسپاس\r\n', '202509-1145', 1, 25, 'Condition_final_done', 'high', NULL, '2025-09-21 13:56:08', '2026-02-21 08:51:22', NULL, NULL, NULL),
	(1146, 'شخصی سازی عمودی کارت-داخلی 21729', 'با سلام و احترام، با توجه به طراحی کارتهای پیش پرداخت جدید لازم است امکان چاپ اطلاعاتی از قبیل شماره کارت ،نام و نام خانوادگی ، تاریخ انقضاء و CVV2 پشت کارت و بصورت عمودی (مانند تصویر پیوست) ایجاد شود.\r\nلازم بذکر است بنا به درخواست واحد متقاضی امکان انتخاب چاپ این اطلاعات بصورت افقی یا عمودی توسط کارشناس وجود داشته باشد.\r\nدلیل:طراحی و چاپ کارتها با این الگو', '202509-1146', 2, NULL, 'condition_acepted_test_auto', 'low', NULL, '2025-09-22 08:17:18', '2026-10-07 16:08:21', 16, 9, ' CR440603'),
	(1147, 'گزارش سرجمع تراکنش به تفکیک گروه کارت_  به تفکیک تاریخ', 'باسلام و احترام\r\nخواهشمند است گزارشی همانند ، گزارش سرجمع تراکنش به تفکیک گروه کارت پیاده سازی گردد به گونه ای که با انتخاب بازه تاریخی، جمع تعداد و مبلغ به تفکیک روز نمایش داده شود.\r\nباسپاس', '202509-1147', 1, 25, 'Condition_final_done', 'high', NULL, '2025-09-22 11:13:35', '2026-02-21 08:51:17', NULL, NULL, NULL),
	(1148, 'خطای 25 ساید 1 تراکنش فارا', 'با سلام \r\nتراکنش استعلام فارا چرا در ساید 1 خطای 25 دریافت کرده است ؟!\r\nلطفا بررسی شود.\r\nلاگ به پیوست خدمتتان ارسال میگردد.\r\nبا تشکر', '202509-1148', 3, 10, 'Condition_final_done', 'high', NULL, '2025-09-22 12:33:29', '2025-12-30 05:55:38', NULL, NULL, NULL),
	(1149, 'رسید تغییر رمز دوم کارت', 'در رسید تغییر رمز دوم کارت های صادرکنندگی تاپ اطلاعت تاریخ انقضا و cvv چاپ نمی شود.\r\\r\n\r\n \r\n\r\nBIT0=&gt;0200\r\n\r\nBIT2=&gt;6221064807150798\r\n\r\nBIT3=&gt;870000\r\n\r\nBIT4=&gt;000000000000\r\n\r\nBIT7=&gt;0922090457\r\n\r\nBIT11=&gt;000005\r\n\r\nBIT12=&gt;090456\r\n\r\nBIT13=&gt;0922\r\n\r\nBIT14=&gt; [####]\r\n\r\nBIT17=&gt;0922\r\n\r\nBIT18=&gt;6012\r\n\r\nBIT19=&gt;364\r\n\r\nBIT25=&gt;02\r\n\r\nBIT26=&gt;12\r\n\r\nBIT32=&gt;622106\r\n\r\nBIT35=&gt; [622106#############################]\r\n\r\nBIT37=&gt;757102667428\r\n\r\nBIT41=&gt;00002940\r\n\r\nBIT42=&gt;000000000010204\r\n\r\nBIT43=&gt;?r?c???3?§???-?&gt;???-?????3?r?-??,?·?_?-??????&quot;?_?`?¶????r?r?,??THRIR\r\n\r\nBIT48=&gt;000475EF27917DEF\r\n\r\nBIT49=&gt;364\r\n\r\nBIT52=&gt; [04##############]\r\n\r\nBIT53=&gt;0202010302000000\r\n\r\nBIT60=&gt; [FILTERED]\r\n\r\nBIT62=&gt;0200000000001221000000000050000Y0000000\r\n\r\nBIT100=&gt;622106\r\n\r\nBIT128=&gt;9F1A469600000000\r\n\r\n \r\n\r\\r\n\r\nMessage Len: 241\r\n\r\nHeader  Len: 0\r\n\r\nH=&gt;\r\n\r\nBIT0=&gt;0210\r\n\r\nBIT2=&gt;6221064807150798\r\n\r\nBIT3=&gt;870000\r\n\r\nBIT4=&gt;000000000000\r\n\r\nBIT6=&gt;000000000000\r\n\r\nBIT7=&gt;0922090457\r\n\r\nBIT11=&gt;000005\r\n\r\nBIT12=&gt;090456\r\n\r\nBIT13=&gt;0922\r\n\r\nBIT14=&gt; [####]\r\n\r\nBIT15=&gt;0922\r\n\r\nBIT32=&gt;622106\r\n\r\nBIT37=&gt;757102667428\r\n\r\nBIT38=&gt;870039\r\n\r\nBIT39=&gt;00\r\n\r\nBIT41=&gt;00002940\r\n\r\nBIT42=&gt;000000000010204\r\n\r\nBIT49=&gt;364\r\n\r\nBIT51=&gt;364\r\n\r\nBIT62=&gt;0200000000001221000000000050000Y0000000\r\n\r\nBIT100=&gt;622106\r\n\r\nBIT128=&gt;ECFA87B1FD975667', '202509-1149', 3, 42, 'condition_acepted_test_auto', 'low', NULL, '2025-09-23 04:52:02', '2026-08-05 12:59:10', NULL, NULL, NULL),
	(1150, 'تغییر شارژ پارسی کارت ', 'با سلام و احترام، \r\nخواهشمند است جهت تغییر سقف جمع مبلغ شارژ پارسی کارت در روز به 15 میلیون تومان و سقف تعدادی تراکنش به 5 تراکنش اقدام مقتضی صورت پذیرد. با سپاس', '202509-1150', 8, 52, 'Condition_final_done', 'medium', NULL, '2025-09-23 05:53:48', '2026-02-22 13:53:54', NULL, NULL, NULL),
	(1151, 'درخواست پیاده سازي پنل سقف وکف پایانه -اندیکاتور 22192', 'با سلام و احترام، پیرو بررسیهاي صورت گرفته طی تیکت پشتیبانی 1112و اعلام عدم وجود سرویس سقف وکف تراکنش پایانه ، لطفا بر اساس مستند پیوست پیاده سازی صورت گیرد.\r\n', '202509-1151', 2, NULL, 'condition_acepted_test_auto', 'low', NULL, '2025-09-23 06:22:14', '2026-10-07 16:08:21', 16, 9, 'CR440266'),
	(1152, 'خارج کردن ترمینال از پروژه کلوزلوپ', 'با سلام\r\nخواهشمند است در اسرع وقت ترمینال 30777844 از پروژه کلوز لوپ خارج شود \r\nمغایرت ایجاد شده است\r\nبا سپاس', '202509-1152', 3, 10, 'Condition_final_done', 'high', NULL, '2025-09-23 11:15:54', '2025-12-30 05:55:31', NULL, NULL, NULL),
	(1153, 'جستجوی کاربر بر اساس نام کاربری', 'با سلام و احترام؛\r\nمطابق با تصویر پیوست شده، جستجو بر اساس نام کاربری عمل نمی‌کند.\r\nلطفاً همکاری لازم جهت رفع این مشکل را مبذول فرمایید.', '202509-1153', 2, 26, 'Condition_final_done', 'medium', NULL, '2025-09-27 10:50:47', '2026-04-12 07:44:00', NULL, NULL, NULL),
	(1154, 'عملکرد نادرست دکمه‌ی &quot;آخرین صفحه&quot;', 'با سلام و احترام؛\r\nمطابق با تصویر پیوست شده، فرضاً اگر در گزارش کل تراکنش‌ها، ۴۰ صفحه وجود داشته باشد، دکمه‌ی آخرین صفحه‌ (یعنی صفحه چهلم) باید به درستی عمل کند و کاربر مجبور به طی کردن متوالی صفحات نباشد.\r\nلطفاً همکاری لازم جهت رفع این مشکل را مبذول فرمایید.', '202509-1154', 2, 26, 'Condition_final_done', 'medium', NULL, '2025-09-27 11:27:55', '2026-04-12 07:43:38', NULL, NULL, NULL),
	(1155, 'سرویس استعلام قبض موبایل سوییچ پذیرندگی آریانا-داخلی 23271', 'بـا توجه به غیر فعـال شـدن سـرویس اسـتعلام قبض موبایل در سـرویس esb وجایگزین شـدن سـرویسir.pec.hub جهت به روز رسانی و توسـعه ماژول اسـتعلام قبض موبایل درسوییچ پذیرندگی آریانا ارائه می گردد. مستندمورد نیاز به پیوست است.(متقاضی آقای تفضلی بر اساس مستندات ارائه شده آقای عسگری)', '202509-1155', 2, NULL, 'condition_acepted_test_auto', 'low', NULL, '2025-09-28 08:39:09', '2026-10-07 16:08:21', 16, 9, 'CR442078'),
	(1156, 'عدم نمایش درخواست های کارت برای برخی کاربران', 'منوی کارت - درخواست های کارت - گروه کارت (شناسه خارجی 13048 -شعبه تاپ چابهار- کادونا مویرگی ) - جستجو\r\n\r\nدسترسی خانم سوزانی suzani چهار ردیف نمایش داده می شود\r\nدسترسی v.jafari  و p.atefi موردی نمایش داده نمی شود.', '202509-1156', 8, 52, 'Condition_final_done', 'medium', NULL, '2025-09-30 05:31:38', '2026-02-22 13:54:02', NULL, NULL, NULL),
	(1157, 'درخواست نمایش تیک انتخاب 8 رقم شماره کارت ', 'با سلام و احترام، پیرو پیاده سازی امکان چاپ تنها 8 رقم آخر شماره کارت با زدن تیک داخل باکس ایجاد شده زمان ثبت درخواست کارت جدید، چنانچه نیاز به بررسی و یا ویرایش این مورد باشد باید در منوی درخواست کارت/جستجو/عملیات(انتخاب نمایش جزئیات) این باکس نمایش داده شده تا کاربر بتواند صحت انتخاب خود را بازبینی و یا در صورت نیاز ویرایش نماید.\r\nلطفا بررسی و اقدام شود.\r\nبا سپاس', '202509-1157', 7, 37, 'Condition_final_done', 'low', NULL, '2025-09-30 07:27:53', '2026-02-22 13:54:18', NULL, NULL, NULL),
	(1158, 'روت تراکنش های توسن (خرید و موجودی)', '\r\nبا سلام\r\nخواهشمند است اقدامات لازم جهت روت تراکنش های خرید و موجودی توسن بروی پورت های 9731 و 9732  صورت پذیرد .\r\n\r\nبرای هر کانال یک کلید ثابت 1C1C1C  در نظر گرفته شده است', '202510-1158', 3, 10, 'Condition_final_done', 'high', NULL, '2025-10-01 10:52:48', '2026-02-21 08:42:07', NULL, NULL, NULL),
	(1159, 'مغایرت ترمینال ', 'با سلام\r\nترمینال   30777844 در تاریخ 14040606 مبلغ 17.000.000 ریال تراکنش موفق با شماره مرجع 512754340127 انجام داده است\r\nولی در فرم 9 وجود ندارد علت چیست؟\r\nبا سپاس', '202510-1159', 3, 10, 'Condition_regect', 'high', NULL, '2025-10-01 12:47:16', '2025-10-04 11:31:46', NULL, NULL, NULL),
	(1160, 'تمدید تاریخ انقضا کارت', 'خواهشمند است در خصوص تغییر تاریخ انقضا کارت های فایل پیوست تا مورخ 1405/12/29 اقدام مقتضی صورت پذیرد. با سپاس', '202510-1160', 8, 52, 'Condition_final_done', 'high', NULL, '2025-10-04 08:08:23', '2026-02-22 13:54:27', NULL, NULL, NULL),
	(1161, 'درخواست بررسی خطای نوبیتکس هنگام درخواست ارسال پیامک فعالسازی', 'سلام و احترام،\r\nنوبیتکس هنگام درخواست ارسال پیامک فعالسازی برای کارت 6221064875066579 با خطای زیر مواجه می شود:\r\n \r\n{ &quot;Message&quot;: &quot;حساب کارت پیدا نشد ErrorCode : E22-46&quot;, &quot;ErrorCode&quot;: 4, &quot;IsSuccess&quot;: false } \r\n \r\n', '202510-1161', 1, 37, 'Condition_final_done', 'high', NULL, '2025-10-05 06:46:28', '2025-12-30 06:13:28', NULL, NULL, NULL),
	(1162, 'خطا در تست سرویس صدور بانام مجازی', 'با سلام و احترام، در سرویس صدور بانام مجازی این خطا مشاهده می شود.لطفا بررسی و مرتفع شود.با سپاس', '202510-1162', 2, 37, 'Condition_final_done', 'low', NULL, '2025-10-05 10:51:51', '2026-02-22 13:54:33', NULL, NULL, NULL),
	(1163, 'تراکنش اوراق گام در IPG', 'با سلام و احترام؛\r\nبه استحضار می‌رساند در درگاه پرداخت نیاز است قابلیت تراکنش اوراق گام فراهم گردد. خواهشمند است اقدامات لازم جهت انجام تراکنش‌های اوراق گام در اسرع وقت صورت پذیرد.', '202510-1163', 2, 26, 'condition_acepted_test_auto', 'high', NULL, '2025-10-05 13:19:57', '2025-12-03 07:08:18', NULL, NULL, NULL),
	(1164, 'عدم نمایش اطلاعات تماس برخی کارت ها', 'با سلام و احترام؛ طبق اعلام همکاران دارندگان، اطلاعات تماس برخی کارت ها خالی می باشد.\r\nنمونه : 6221064878135611\r\nمسیر گزارش: کارت - کارت - (عملیات) اطلاعات تماس\r\n', '202510-1164', 8, 52, 'Condition_final_done', 'low', NULL, '2025-10-07 06:17:56', '2026-02-22 13:54:40', NULL, NULL, NULL),
	(1165, 'مغایرت شماره کارت درج شده بر روی کارت و شماره کارت در سامانه', 'باسلام\r\nاحتراما باستحضار میرساند برای شماره کارت 6221064407410954 در سیستم کارت 6221064407410956 نمایش داده می شود رقم اخر شماره کارت مغایرت دارد باتوجه به اینکه می بایستی اطلاعات دقیق به واحد حقوقی جهت اعلام به دادسرا وزندان اعلام گردد .دلیل این مغایرت بررسی واعلام گردد.باتشکر\r\nMaryam molahoseini - IR444232', '202510-1165', 8, 52, 'Condition_final_done', 'low', NULL, '2025-10-08 06:36:52', '2026-02-22 13:56:02', NULL, NULL, NULL),
	(1166, 'عملیاتی سازی پروژه سوئیچ شارژ', 'با سلام\r\nبا توجه به اتمام پیاده سازی تیکت 271 خواهشمند است این پروژه عملیاتی شود.\r\nبا سپاس', '202510-1166', 3, 10, 'Condition_regect', 'high', NULL, '2025-10-08 06:51:53', '2025-10-08 10:21:24', NULL, NULL, NULL),
	(1167, ' داخلی 21019 - 04-درخواست نوبیتکس در خصوص حذف مانده از پیامک', 'ا سلام و احترام، شرکت نوبیتکس در خواست حذف مانده از پیامک را دارد و همچنین به جای عبارت &quot;خرید از حساب اصلی&quot; عبارت &quot;خرید از کارت &quot;عنوان شود. نمونه ای به شرح ذیل ارائه می گردد. باتشکر\r\n\r\nپیامکی که در حال حاضر ارسال می شود:\r\n\r\nخریدازحساب اصلی \r\n\r\n-2,300,000 \r\n‎6221*6926 \r\n06/31 06:41\r\n\r\nمانده:00\r\n\r\nپیامکی که درخواست دارند ارسال شود:\r\n\r\nخرید از کارت\r\n\r\n-2,300,000 \r\n‎6221*6926 \r\n06/31 06:41\r\n\r\n ', '202510-1167', 2, NULL, 'condition_acepted_invoice_auto', 'low', NULL, '2025-10-08 08:09:59', '2026-08-05 12:59:10', 16, 9, 'CR443722'),
	(1168, 'درخواست بررسی نواقص و درخواست‌های بانک سینا طی اندیکاتور24590', 'با سلام و احترام، پیرو پیاده سازی و تحویل درخواست های فاز اول بانک سینا ، موارد به شرح زیر را بعنوان نیازمندی هایی که قرار بوده اصلاح گردند ، اعلام نموده اند.\r\nخواهشمند است بررسی و اعلام نظر فرمائید.\r\n1-اصلاح پنل دارندگان جهت نمایش درصفحه مرورگر دسکتاپ\r\nUiپنل دارندگان میبایست responsive باشد\r\n2-قراردادن گزارش تاریخچه کارت در منوي گزارشات\r\n3- رفع نواقص تکمیل اطلاعات مشتریان\r\nباوارد نمودن شماره کارت مشتري اطلاعات مشتري از سامانه یاقوت دریافت و نمایش داده میشودکه این اطلاعات درحال حاضر ناقص است.\r\n4-درپنل دارندگان کارت تولید رمز دوم اضافه گردد\r\nدرگزارش تراکنش کارت امکان مشاهده تعدادومبلغ کل تراکنشها برا اساس فیلتر هاوجود ندارد ، یکجا نمایش نمیدهد\r\n5-ارسال پیامک:مقرر بودجهت ارسـال پیامـک رمز دوم براي دارنـدگان کارت هنگام شارژ از پنل دارنـدگی، سـرویس مربوطه بر روي وب سرویس یاقوت در اختیار اینتک قرارداده شودو راه اندازي گردد .', '202510-1168', 2, 37, 'condition_in_progress', 'low', NULL, '2025-10-08 09:57:56', '2026-01-31 09:35:05', NULL, NULL, NULL),
	(1169, 'تغییر منوی المثنی همانند منوی صدور_ مجازی', 'باسلام و احترام\r\nخواهشمند است منوی صدور المثنی همانند منوی صدور کارت تغییر _ افزودن cvv2 و رمز دوم _داده شود.\r\nبرای نوع کارت مجازی نیازمند این هستیم که Cvv2 و رمز دوم ، غیرفعال گردد و در فایل چاپ رمز موجود نباشد.\r\nباسپاس', '202510-1169', 1, 25, 'Condition_final_done', 'high', NULL, '2025-10-11 13:45:05', '2026-02-21 09:00:34', NULL, NULL, NULL),
	(1170, 'حذف درخواست 640638 (صدور و شارژ)', 'پیرو تیکت 1135 و اعلام عدم امکان حذف درخواست از سوی اینتک و تاکید همکاران دارندگان جهت نیاز به حذف درخواست، خواهشمند است ارائه طریق فرمایید.', '202510-1170', 8, 52, 'Condition_final_done', 'low', NULL, '2025-10-12 07:05:20', '2026-02-22 13:56:08', NULL, NULL, NULL),
	(1171, 'سریال متصل به پایانه اینتکی', 'با سلام و احترام\r\nاحترماً، به منظور به‌روزرسانی اطلاعات و مستندسازی تجهیزات پرداخت الکترونیک، نیازمند لیست کامل شماره سریال دستگاه‌های کارت‌خوان (POS) متصل به پایانه‌های اینتکی میباشیم.\r\nخواهشمند است اقدامات لازم را مبذول فرمایید.\r\nشایان ذکر است لیست ترمینال‌های مربوطه به پیوست ارائه شده است.\r\nبا سپاس', '202510-1171', 3, 49, 'Condition_final_done', 'medium', NULL, '2025-10-13 05:00:32', '2025-12-30 06:24:36', NULL, NULL, NULL),
	(1172, 'تغییر کد  سوئیچ ترمینال 12208377', 'با سلام و احترام\r\nخواهشمند است کد سویچ ترمینال  12208377 کد سوئیچ از 3 به 7 تغییر یابد.\r\nبا سپاس', '202510-1172', 3, 10, 'Condition_final_done', 'high', NULL, '2025-10-13 05:59:47', '2026-02-21 09:00:15', NULL, NULL, NULL),
	(1173, 'تغییر قابلیت در الگوی کارتهای مددجویان ', 'با سلام خواهشمند است کلیه کارتهای مددجویان با نوع کارت خرید در منوی تعاریف+قابلیت ها+ نوع تراکنش خرید+نوع پایانه کارتخوان+حداکثر مبلغ و مبلغ برداشت روزانه از 18.000.000 به 15.000.000 تغییر یابد. باتشکر\r\n\r\nتیکت: SR444712\r\nکاربر: Nahid Rohallahzadeh', '202510-1173', 8, 52, 'Condition_final_done', 'low', NULL, '2025-10-13 09:33:21', '2026-02-22 13:56:12', NULL, NULL, NULL),
	(1174, 'درخواست Import دیتا های لازم با توجه به آغاز فرآیند عملیاتی پروژه «اتصال کارت به کیف پول»', 'با سلام و احترام،ضمن تشکر از عملیاتی شدن پروژه اتصال کیف پول به سگمنت و  موکول شدن  پیاده سازی دو درخواست ورود اطلاعات اولیه لازم به بعد ،طبق توافق قبلی با جناب آقای محمدی قرار بر ارسال این اطلاعات و Import آن توسط اینتک شد، لذا به پیوست دو لیست اکسل به شرح زیر جهت اقدام ارائه می گردد. تسریع در اقدام مزید امتنان خواهد بود.\r\n1- لیست تخصـیص کدسگمنت اعتباري(29497) به گروهی از کدخدمتها(لیست کدخدمت ها پیوست شده است)\r\n2-لیست تخصـیص گروهی پایانه ها به گروهی ازکدخدمتها (لیست کل پایانه هاوکدخدمت ها پیوست شده است)', '202510-1174', 7, 37, 'Condition_final_done', 'high', NULL, '2025-10-13 10:21:42', '2025-12-30 06:13:19', NULL, NULL, NULL),
	(1175, 'مغایرت تراکنش در حساب کنترلی', 'با سلام و احترام طی بررسی بعمل آمده از گردش کارتهای کنترلی شرکت فولاد خوزستان محرز گردید که تراکنش از کارت مخزن آن شرکت کسر و با توجه به موفق بودن تراکنش و ارائه خدمات در گزارش کارت کنترلی  قابل نمایش نمی باشد وبرای  آن تراکنش گردشی ایجاد نگردیده است و این موضوع باعث ایجاد مغایرت در ارائه گزارشات به آن سازمان محترم گردیده است لذا فایل پیوست بصورت نمونه جهت بررسی و هر گونه اقدام ارسال می گردد . با تشکر\r\n\r\nآدرس گزارش: اینتک دارندگی / گزارش مالی /گزارش تراکنش حساب کنترلی دارنده کارت\r\n\r\nنامه: داخلی 24842 - 04\r\nکاربر: ناهید روح اله زاده کردی', '202510-1175', 8, 52, 'Condition_final_done', 'high', NULL, '2025-10-14 09:21:08', '2026-02-22 13:56:22', NULL, NULL, NULL),
	(1176, 'مغایرت نام پذیرنده در سامانه MMS و درگاه پرداخت', 'با سلام و احترام،\r\n\r\nبنا به بررسی‌های انجام شده، مشخص گردید که نام پذیرنده در سامانه MMS با نام پذیرنده ثبت شده در درگاه پرداخت مغایرت دارد. به عنوان نمونه، پذیرنده باشگاه خلیج فارس در سامانه MMS به اشتباه تحت عنوان باشگاه پارسه در درگاه پرداخت ثبت شده است.\r\n\r\nلطفاً در اسرع وقت نسبت به اصلاح این مغایرت اقدام فرمایید تا از بروز مشکلات احتمالی جلوگیری گردد.', '202510-1176', 4, 26, 'Condition_final_done', 'medium', NULL, '2025-10-15 06:47:58', '2025-12-30 06:16:46', NULL, NULL, NULL),
	(1177, 'تخصیص مارکت &quot; رویداد چهش نوین&quot;', 'با سلام و احترام\r\nخواهشمند است به لیست پیوست مارکت &quot;  رویداد چهش نوین &quot; تخصیص داده شود.\r\nباسپاس', '202510-1177', 1, 25, 'Condition_final_done', 'high', NULL, '2025-10-15 09:24:57', '2026-02-21 09:00:10', NULL, NULL, NULL),
	(1178, 'ایجاد دسترسی با نقش رونوشت انفرادی', 'نام کاربری s.dabiri	با نقش رونوشت انفرادی توسط اینجانب ایجاد شده است لذا خواهشمند است در خصوص ایجاد تغییرات لازم جهت مشابهت با دسترسی e.ostovar	اقدامات لازم را مبذول فرمایید. با سپاس', '202510-1178', 8, 52, 'Condition_final_done', 'low', NULL, '2025-10-18 12:28:48', '2026-02-22 13:56:32', NULL, NULL, NULL),
	(1179, 'RRN متفاوت در تراکنش فارایی شرکت کیان', 'با سلام و احترام\r\nدر خصوص تراکنش فارا در صورتیکه پرداخت نوین تراکنش را انجام دهد RRN تراکنش در پاسخ MTI=110  و MTI=200 یکی است \r\nولی در پروژه دیگر که شرکت کیان تراکنش فارایی را انجام میدهد و بخش شاپرکی توسط پرداخت نوین انجام میشود RRN ها متفاوت است\r\nخواهشمند است راه حلی جهت این موضوع ارائه فرمایید.\r\nبا سپاس', '202510-1179', 3, 10, 'Condition_regect', 'high', NULL, '2025-10-20 07:07:16', '2025-10-20 11:30:42', NULL, NULL, NULL),
	(1180, 'تخصیص کارت به گروه کارت فولاد', 'با سلام و احترام\r\nبا توجه به مشکل موجود در اضافه کردن فایل به گروه کارت خواهشمند است فایل ضمیمه به گروه کارت فولاد اضافه گردد.\r\nو مشکل رفع گردد.\r\nبا سپاس', '202510-1180', 3, 10, 'Condition_final_done', 'high', NULL, '2025-10-20 07:32:34', '2026-02-21 08:41:53', NULL, NULL, NULL),
	(1181, 'مشکل درمشاهده گزارشات و برخی منوها برای اینجانب و نیز کاربران دیگر', 'با سلام و احترام، با وجود اینکه دسترسی های اینجانب با نام کاربری m.khazali در سطح کاربران کارت و مالی و در برخی موارد ادمین می باشد اما در برخی گزارشات امکان مشاهده ندارم.همچنین این مشکل برای برخی کاربران دارندگان نیز وجود داشته و چندین بار اعلام نموده اند اما مشکل مرتفع نشده است.با توجه به اینکه اینجانب رابط اینتک و تاپ بوده و جهت تست و بررسی موارد توسعه های نیاز به دسترسی به این موارد دارم لطفا هر چه سریعتر مشکل مرتفع گردد.\r\nبا سپاس', '202510-1181', 8, 37, 'Condition_final_done', 'high', NULL, '2025-10-21 06:58:58', '2025-12-30 06:13:02', NULL, NULL, NULL),
	(1182, 'تغییر سوئیچ کد ', '12236197\r\n12236210\r\nبا سلام خواهشمند برای هر دو ترمینال سوئیچ کد از 3 به 7 تغییر کند\r\nبا سپاس', '202510-1182', 3, 10, 'Condition_final_done', 'high', NULL, '2025-10-21 10:14:26', '2026-02-21 08:41:42', NULL, NULL, NULL),
	(1183, 'ایجاد دسترسی با نقش رونوشت انفرادی  (تیکت توسعه)', 'با توجه به زمانبر شدن اقدام اجرایی توسط اینتک در خصوص ایجاد دسترسی با نقش رونوشت انفرادی با شماره تیکت 202510-1178 خواهشمند است این دسترسی در اختیار این اداره قرار گیرد تا در دفعات بعدی، نیاز به مکاتبه با اینتک و لزوم اقدام از سوی آن شرکت منتفی گردد. با سپاس', '202510-1183', 2, 52, 'Condition_regect', 'low', NULL, '2025-10-21 12:51:59', '2025-10-25 09:02:13', NULL, NULL, NULL),
	(1184, 'درخواست رفع اشکال در فعالسازی کارت - IR446308', 'با سلام\r\n           احتراما به اطلاع می رسان ددر قسمت دارندگی بخش کارت - درخواست های کارت زمانی که یک نفر کارت خود را از طریق اپلیکیشن تاپ فعال نماید کل درخواست از وضعیت فعالسازی خارج میشود و به وضعیت انجام شده تبدیل میشود. درصورتی که کل کارتها فعال نشده باید وضعیت آن در مرحله فعالسازی باشد.\r\n           در این حین زمانی که کاربر رسید فعالسازی را دریافت مینماید و باید کارت ها را فعال نماید گمان بر این میگزارد که کلیه کارتها طی نامه دیگری فعال شده و درخواست در مرحله انجام شده است و به سازمان اعلام مینماید که کارتها قبلا فعال شده است. درصورتی که مابقی کارتها غیرفعال باقی مانده. \r\n           به عنوان مثال تقاضا 644596 شماره کارت ردیف 5 توسط اپلیکیشن تاپ فعال شده 6221064841188481  و مابقی کارتها باید بصورت گروهی فعال شود. (گروه کارت یکسان است : مهندسی و ساخت تاسیسات دریایی ایران ) \r\n\r\nشماره تیکت: IR446308\r\nدرخواست دهنده: Leila Suzani', '202510-1184', 8, 52, 'Condition_final_done', 'low', NULL, '2025-10-21 12:55:22', '2026-02-22 13:56:47', NULL, NULL, NULL),
	(1185, 'تسهیم و تخفیف همزمان', 'باسلام و احترام \r\nبه استحضار می‌رساند، در خصوص اجرای پروژه «کارت سلامت» ، مقرر گردیده است مبالغ تراکنش‌ها پس از اعمال تخفیف، مطابق درخواست شرکت نوتاش و بر اساس اطلاعات حساب‌های معرفی‌شده، به‌صورت تسهیمی تسویه گردد\r\n توضیح بیشتر اینکه تسهیم معمولی با هر کارتی روی پوز برای حساب های تعریف شده ، در سوییچ اعمال شود ولی برای گروه کارت خاصی که در پیوست ارسال شده است، ابتدا تخفیف با درصد تعیین شده اعمال گردد و سپس تسهیم انجام شود\r\n\r\nخواهشمند است اعلام فرمایید به چه صورت این تخفیف و تسهیم اعمال گردد؟ با حالت های مختلف تست شد ولی اعمال نشد.\r\nترمینال  30016080 جهت تست', '202510-1185', 3, 10, 'Condition_final_done', 'high', NULL, '2025-10-21 13:18:41', '2026-02-21 08:51:10', NULL, NULL, NULL),
	(1186, 'هزینه پیاده سازی', 'با سلام و احترام\r\nدر خصوص تراکنش فارا در صورتیکه پرداخت نوین تراکنش را انجام دهد RRN تراکنش در پاسخ MTI=110  و MTI=200 یکی است \r\nولی در پروژه دیگر که شرکت کیان تراکنش فارایی را انجام میدهد و بخش شاپرکی توسط پرداخت نوین انجام میشود RRN ها متفاوت است هدف این است که   RRN ها یکی باشد.\r\nبا توجه به اینکه اعلام شده بود این مورد پیاده سازی نشده است خواهشمند است هزینه پیاده سازی را اعلام فرمایید.\r\nبا سپاس', '202510-1186', 3, 10, 'Condition_regect', 'medium', NULL, '2025-10-22 13:10:05', '2025-11-08 08:37:17', NULL, NULL, NULL),
	(1187, 'گزارش ', 'باسلام و احترام\r\nخواهشمند است گزارشات ذیل ارسال گردد:\r\n1.گزارش شارژ مهر ماه از 14040701 تا 14040730 \r\n2.گزارش شارژ &quot;کارت خرید&quot;  صرفا برای &quot;نمایندگی پرداخت نوین&quot;  از ابتدای شروع کار سوییچ تا پایان مهر 1404\r\n3.گزارش سرجمع موجودی به تفکیک نوع کارت \r\nباسپاس', '202510-1187', 1, 25, 'Condition_final_done', 'high', NULL, '2025-10-25 06:16:21', '2026-02-21 08:41:34', NULL, NULL, NULL),
	(1188, 'مشاهده خطای  03 در مانور سایت پشتیبان ', 'با سلام و احترام\r\nخواهشمند است خطای مانور سایت پشتیبان رفع گردد:\r\nمشاهده خطای  03 در برخی از تراکنش ها به علت ارسال تراکنش پایانه های سیپا بروی هر دو BIN1 , BIN2 و دریافت خطای 03 از BIN 2', '202510-1188', 3, 10, 'Condition_final_done', 'high', NULL, '2025-10-26 08:10:02', '2026-02-21 09:00:03', NULL, NULL, NULL),
	(1189, 'خطای 34 بروی پورت های 1000 و 3333', 'با سلام\r\nخواهشمند است بررسی و رفع گردد.\r\nنمونه 11710919', '202510-1189', 3, 10, 'Condition_regect', 'high', NULL, '2025-10-26 08:24:30', '2025-10-26 11:05:28', NULL, NULL, NULL),
	(1190, 'خطای 84 ترمینال ', 'با سلام و احترام\r\nترمینال های 30656424 و  30656278 در تراکنش فارا خطای 84 دریافت میکنند.\r\nخواهشمند است بررسی گردد.\r\nبا سپاس', '202510-1190', 3, 10, 'Condition_final_done', 'high', NULL, '2025-10-26 12:12:28', '2026-02-21 08:59:46', NULL, NULL, NULL),
	(1191, 'تکمیل اطلاعات لیست سرورها', 'با سلام\r\n\r\nخواهشمند است برای لیست سرورهای ارسال شده \r\nنرم افزاری که روی سرور مورد نظر هاست شده یا دیتابیسی که روی سرور وجود دارد به ازاری  مشخص گرددد.\r\nبا سپاس', '202510-1191', 1, 10, 'Condition_final_done', 'high', NULL, '2025-10-26 14:03:24', '2026-02-21 08:41:21', NULL, NULL, NULL),
	(1192, 'شتاب 8 / گزارش فرم 9 شرکت‌های ارائه دهنده خدمات پرداخت در خصوص فرایند &quot;خرید با تایید اولیه&quot; ', 'با سلام و احترام\r\nطبق درخواست شاپرک در راستای اجرایی شدن فرایند &quot;خرید با تایید اولیه&quot; خواهشمند است جهت کد تابع  گزارش فرم شماره 9 مطابق جدول پیوست اقدام گردد.\r\nبا سپاس', '202510-1192', 3, 10, 'condition_in_progress', 'medium', NULL, '2025-10-27 05:46:42', '2025-10-27 06:49:22', NULL, NULL, NULL),
	(1193, 'گزارش شارژ کارت', 'باسلام و احترام\r\nگزارش شارژ درخواستی شامل انواع کارت ( خرید، هدیه، مگا، توریست، . ...) می باشد. همچنین  گزارش تراکنش گروه مشتری &quot; بن - پارتیان &quot; نیز از ابتدای تا پایان روز 30 ام مهر ماه ایجاد گردد.\r\nخواهشمند است تاریخ به میلادی ، مبالغ به ریال و تفکیک شارژ بک آفیس و سان و ... در آن قابل مشاهده باشد\r\nباسپاس', '202510-1193', 1, 25, 'Condition_final_done', 'high', NULL, '2025-10-27 08:33:39', '2026-02-21 08:50:11', NULL, NULL, NULL),
	(1194, 'غیرفعال کردن دسترسی خانم بکتاش', 'با سلام و احترام؛\r\nبا عنایت به جدایی سرکار خانم آرام بکتاش از اداره ی پشتیبانی سیستم های کاربردی، خواهشمند است در خصوص غیرفعال نمودن دسترسی تیکتینگ ایشان اقدام مقتضی انجام پذیرد. با سپاس', '202510-1194', 1, 52, 'Condition_final_done', 'low', NULL, '2025-10-27 10:54:06', '2026-02-22 13:56:52', NULL, NULL, NULL),
	(1195, 'درخواست گزارش سرجمع از سوئیچ یک', 'با سلام و احترام، لطفا با توجه به مستندات پیوست گزارش سرجمع در سوئیچ یک ایجاد شود.\r\n(بنا به اعلام پیامکی جناب آقای اصغر زاده و ارائه مستند توسط آقای فرهمند و خانم حسین زاده)', '202510-1195', 2, NULL, 'Condition_in_progress', 'medium', NULL, '2025-10-27 13:02:36', '2026-01-20 11:33:22', 16, 9, 'CR446825'),
	(1196, 'ایجاد دسترسی با نقش رونوشت انفرادی (تیکت توسعه)', 'با توجه به زمانبر شدن اقدام اجرایی توسط اینتک در خصوص ایجاد دسترسی با نقش رونوشت انفرادی با شماره تیکت 202510-1178 خواهشمند است این دسترسی در اختیار این اداره قرار گیرد تا در دفعات بعدی، نیاز به مکاتبه با اینتک و لزوم اقدام از سوی آن شرکت منتفی گردد. با سپاس', '202510-1196', 2, NULL, 'condition_in_progress', 'medium', NULL, '2025-10-27 13:03:29', '2026-05-05 10:51:32', 16, 9, 'CR446905'),
	(1197, 'درخواست حذف کارتابل دارندگان، چاپ 8 رقم آخر شماره کارت و ارسال به پیمانکار سپاس(دنا) بصورت دیفالت و قرار گرفتن در وضعیت نهائی &quot;در انتظار فعال سازی&quot; در صدور کارت مجازی شهروند(نامه شماره4577 و13543)', 'با سلام و احترام،کلیه کارت‌های مجازی با کد طرح یکسان ارائه خواهند شد. همچنین مطابق با نامه ، هشت رقم آخر شماره کارت بر روی کارت درج می‌گردد. لازم به ذکر است کارتها در دو مدل با نام و بی نام قابلیت چاپ دارند که در مدل بی نام پارامتر نام نیز از روی کارت حذف می گردد.در این فرآیند شرکت تابان در صورت جذب گروه جدید مشتری به دارندگان اعلام نموده و کد گروه مشتری را دریافت می کند.با هماهنگی خانم روح اله زاده پس از ثبت درخواست نیازی به ارجاع به کارتابل دارندگان نبوده و طبق هماهنگی آقای افضلی و اینتک جهت کنترل های مالی به کارتابل مالی ارجاع می شود.پس از تائید مالی به صورت دیفالت به پیمانکار دنا(سپاس) ارجاع و در وضعیت آماده تخصیص و سپس آماده چاپ قرار گرفته و پس از چاپ کارت در وضعیت &quot;در انتظار فعالسازی &quot; خواهد بود.\r\nلازم بذکر است موارد بصورت کلی در درخواست های توسعه ای جداگانه اعلام و پیاده سازی شده و این تیکت جهت جمع بندی موارد خردی است که تلفنی اعلام و در حال انجام است.', '202510-1197', 2, NULL, 'condition_acepted_test_auto', 'high', NULL, '2025-10-27 13:04:30', '2026-10-07 16:08:21', 16, 9, 'CR446531'),
	(1198, 'مستند API سرویس پرداخت موبایلی از طریق NFC - دریافت زمانبندی پیاده سازی', 'با سلام و احترام\r\nدر خصوص  پروژه  «پلتفرم پرداخت موبایلی از طریق NFC»، مستند فنی API  مبتنی بر استاندارد (NFC Data Exchange Format) NDEF به  پیوست خدمتتان  ارسال می‌گردد.\r\nخواهشمند است پس از بررسی مستند، برنامه زمان‌بندی پیاده‌سازی را اعلام فرمایید.\r\nبا سپاس\r\n', '202510-1198', 1, 10, 'condition_acepted_invoice_auto', 'medium', NULL, '2025-10-27 15:18:55', '2026-10-03 08:27:48', NULL, NULL, NULL),
	(1199, 'اختلال در سرویس OTP', 'با سلام و احترام؛\r\nبدینوسیله به اطلاع می‌رساند که سرویس ارسال رمز یکبار مصرف (OTP) در سامانه ما از تاریخ ۱۴۰۴/۰۸/۰۵ دچار اختلال شده و کاربران قادر به دریافت رمز نمی‌باشند. لطفاً در اسرع وقت نسبت به بررسی و رفع مشکل سرویس مذکور اقدام فرمایید.\r\nبا تشکر از همکاری شما', '202510-1199', 3, 26, 'Condition_final_done', 'high', NULL, '2025-10-28 08:54:24', '2025-12-30 06:16:34', NULL, NULL, NULL),
	(1200, ' رمز اول و دوم کارت های گروه &quot; ی کارت &quot;', 'باسلام و احترام\r\nبه استحضار می رساند کارت های فایل پیوست متعلق به پروژه مادر فرزندی و گروه کارت  &quot; ی کارت &quot; می‌باشند و کارت ها قبلا _ در پارت های متفاوت  _ صادر شده اند.\r\nخواهشمند است رمز اول و دوم کارت های فایل پیوست ارسال گردد.\r\nباسپاس', '202510-1200', 1, 25, 'Condition_final_done', 'high', NULL, '2025-10-28 10:17:37', '2026-02-21 08:39:43', NULL, NULL, NULL),
	(1201, 'درخواست دریافت شماره کارت های مجازی صادره ', 'با توجه به پیاده سازی صدور کارت های مجازی با نام و بی نام شهروند نیاز به پیاده سازی سرویسی برای دریافت شماره کارت های صادر شده از طریق شماره تقاضا نیز می باشد.\r\nپیرو هماهنگی با جناب آقای محمدی این تیکت صرفا جهت ثبت دقیق تقاضا و در راستای تیکت اصلی به شمارهCR434148 می باشد.', '202510-1201', 2, NULL, 'condition_acepted_test_auto', 'low', NULL, '2025-10-29 08:31:27', '2026-10-07 16:08:21', 16, 9, 'CR448685'),
	(1202, 'تسهیم و تخفیف ترمینال ۳۱۱۲۱۹۷۴', '\r\nبا سلام\r\nبرای ترمینال ۳۱۱۲۱۹۷۴ تسهیم و تخفیف در بک آفیس اعمال شده است .\r\nاین پایانه ۴ درصد تسهیم برای هر تراکنش معمولی میخواهد و برای گروه کارت خاصی که در سامانه بک آفیس به نام نیلودرمان نوتاش, تعریف شده است نیاز است ابتدا یازده درصد تخفیف اعمال شود و سپس بعد از آن، چهار درصد تسهیم برای حساب شریک تجاری اعمال گردد .\r\nولی با هر نوع و مدل تعریف تسهیم و تخفیف در بک افیس، تغییرات مورد نظر هنگام تراکنش اعمال نمی شود . خواهشمند است مشکل بررسی گردد\r\nباسپاس\r\n', '202510-1202', 3, 10, 'Condition_final_done', 'medium', NULL, '2025-10-29 14:26:07', '2026-02-21 08:50:04', NULL, NULL, NULL),
	(1203, 'تغییر رمز کارت هدیه', 'با سلام و احترام\r\nخواهشمند است نسبت به تغییر رمز الگوهای کارت هدیه مطابق با الگوهای ذیل مساعدت فرمایید.\r\nلطفا شروط ذیل را مدنظر قرار دهید حتما:\r\n(حتما نام پیمانکار چاپ &quot;سپاس&quot; باشد // کارت های هدیه در بازه &quot; 1404/01/01 الی 1404/08/10 &quot; در نظر گرفته شود)\r\n1. کارت هدیه\r\n2. کارت هدیه - نوروزی\r\n3. کارت هدیه جدید 2\r\n4. کارت هدیه کادونا جدید\r\n5. کارت هدیه کادونا جدید - نمایندگی\r\n6. کارت هدیه ویژه پارسیان 2\r\n7. کارت هدیه ویژه نمایندگی2\r\nبا تشکر\r\n\r\nکاربر: behnam behbam\r\nتیکت: SR449051', '202511-1203', 4, 52, 'Condition_final_done', 'high', NULL, '2025-11-01 11:34:28', '2026-02-22 13:56:56', NULL, NULL, NULL),
	(1204, 'بررسی علت خطا در تراکنش‌های تاریخ ۱۴۰۴/۰۸/۱۰', 'با سلام و احترام؛\r\n\r\nضمن ارسال فایل اکسل مربوط به تراکنش‌های اخیر، خواهشمند است در اسرع وقت نسبت به بررسی موارد مندرج در فایل اقدام فرمایید و علت بروز خطا در تراکنش‌های مشخص‌شده را اعلام نمایید.\r\n\r\nبا توجه به اهمیت موضوع، رسیدگی فوری مورد تأکید است.', '202511-1204', 3, 26, 'Condition_final_done', 'high', NULL, '2025-11-02 06:29:47', '2026-02-22 14:03:26', NULL, NULL, NULL),
	(1205, 'برگشت رمز', 'با سلام و احترام\r\nخواهشمند است نسبت به بازگشت رمز الگوهای کارت هدیه مطابق با الگوهای ذیل مساعدت فرمایید.\r\nلطفا شروط ذیل را مدنظر قرار دهید حتما:\r\n(حتما نام پیمانکار چاپ &quot;سپاس&quot; باشد // کارت های هدیه در بازه &quot; 1404/01/01 الی 1404/08/10 &quot; در نظر گرفته شود)\r\n1. کارت هدیه\r\n2. کارت هدیه - نوروزی\r\n3. کارت هدیه جدید 2\r\n4. کارت هدیه کادونا جدید\r\n5. کارت هدیه کادونا جدید - نمایندگی\r\n6. کارت هدیه ویژه پارسیان 2\r\n7. کارت هدیه ویژه نمایندگی2\r\nلطفا اولویت اول برگشت دادن رمز &quot;کارت های فعال&quot; و اولویت بعدی &quot;کارت های غیرفعال&quot; باشد.\r\nهمچنین کارت های پیوست تغییر رمز داده نشود.\r\nبا تشکر\r\nکاربر: behnam behbam\r\nتیکت : SR449460\r\n\r\n*** عطف به تیکت 202511-1203 - تغییر رمز ***\r\n\r\n', '202511-1205', 4, 52, 'Condition_final_done', 'low', NULL, '2025-11-02 11:04:31', '2026-02-22 13:57:03', NULL, NULL, NULL),
	(1206, 'الزام شاپرک مبنی بر عدم نمایش شماره کارت در گزارش فایل اکسل بک‌آفیس', 'با سلام و احترام؛\r\n\r\nبدین‌وسیله به اطلاع می‌رساند با توجه به الزامات امنیتی و حفظ محرمانگی اطلاعات مشتریان، خواهشمند است ترتیبی اتخاذ فرمایید تا در گزارش‌های خروجی فایل اکسل سامانه بک‌آفیس، شماره کارت‌ها به‌صورت Mask شده نمایش داده شوند و از نمایش کامل شماره کارت خودداری گردد.\r\n\r\nاین اقدام در راستای رعایت اصول امنیت اطلاعات، جلوگیری از افشای داده‌های حساس و انطباق با سیاست‌های حفظ حریم خصوصی سازمان می‌باشد.', '202511-1206', 1, 26, 'Condition_final_done', 'high', NULL, '2025-11-02 11:36:11', '2025-12-30 06:16:23', NULL, NULL, NULL),
	(1207, 'کندی سرعت سامانه', 'با سلام و احترام؛\r\nدرخواست پیگیری موارد کندی اینتک دارندگی', '202511-1207', 8, 52, 'condition_acepted_test_auto', 'low', NULL, '2025-11-02 13:37:59', '2026-03-15 11:46:45', NULL, NULL, NULL),
	(1208, 'درخواست بانک جهت تکمیل گزارش صدور کارتهای شعب(اندیکاتور28945 )', 'با سلام و احترام، بانک نیاز به گزارشی دارد که تاریخ و زمان دقیق درخواست کارت از شعب را از لحظه ثبت درخواست تا زمانیکه کارتها بدستشان می رسد قابل رصد باشد.در حال حاضر امکان مشاهده تاریخ ثبت درخواست و تاریخ تحویل کارتها برایشان وجود دارد ولی لازم است دو مورد به شرح زیر در گزارشات ایجاد شود :\r\n1. تاریخ ورود به کارتابل و تایید درخواست توسط همکاران در دو مدیریت پشتیبانی ونگهداشت مشتریان و مدیریت مالی\r\n2. تاریخ ایجاد فایل صدور کارت و ارائه به پیمانکار', '202511-1208', 1, 37, 'condition_in_progress', 'medium', NULL, '2025-11-03 06:20:58', '2025-11-03 06:48:15', NULL, NULL, NULL),
	(1209, 'تخصیص در سوییچ ترمینال و سریال ', 'با سلام  خواهشمند است \r\nبرای ترمینال های لیست پیوست(هر دو فایل ) سریال های جدید بروی سوئیچ  تخصیص یابد.\r\n', '202511-1209', 1, 10, 'Condition_final_done', 'high', NULL, '2025-11-03 12:20:14', '2026-02-21 08:39:27', NULL, NULL, NULL),
	(1210, 'درخواست گزارش &#039;اطلاعات کارت‌های مجازی و گروه پایانه‌های تعریف شده در ارتباط با کارت‌ها&#039;', '\r\nبه اسـتحضار میرسانـدحوزه مبـارزه با پولشویی اعلام نموده که ضـرورت دارد گزارشـی در ارتباط با محصولات داراي\r\nماهیت حلقه بسـته (loop-closed (ارائـه گردد. در همین راسـتا ضـرورت دارد اطلاعـاتی در ارتبـاط بـا کارتهاي مجازي\r\nپارسیان تکمیل گردد. فرمت اطلاعات درخواستی در قالب 3کاربرگ، به شرح ذیل تقدیم حضور میگردد:\r\n.1 اطلاعات ومشخصات هویتی کارت هاي مجازي منقضی نشده (فعال سیستمی)\r\n.2 اطلاعات ومشخصات گروه پایانه هاي در ارتباط با هرگروه کارت و قابلیتهاي تراکنشی تعریف شده روي پایانه ها\r\n.3 فهرست شماره پایانه هاي تعریف شده از سوي شرکت در ارتباط با هرگروه پایانه\r\nبنـابراین بـا توجه به اهمیت موضوع و بـا عنـایت به محـدودیت زمانی اعلام شـده از سوي شاپرك،خواهشـمنداست اطلاعات\r\nدرخواستی مطابق با فرمت ارائه شده در پیوست نامه با قیدفوریت ارائه گردد.', '202511-1210', 4, 52, 'condition_acepted_test_auto', 'high', NULL, '2025-11-04 09:51:44', '2026-06-01 07:55:04', NULL, NULL, NULL),
	(1211, 'اعمال قالب گزارش الکترونیکی شاپرک', 'با سلام و احترام\r\n باستحضار می‌رساند مستند« قالب گزارش الکترونیکی شاپرک برای ارائه‌دهندگان خدمات پرداخت» با لحاظ نمودن درصد مالیات بر ارزش افزوده به همراه نمونه‌ای از قالب مذکور به پیوست ایفاد می گردد. \r\nباتشکر ', '202511-1211', 3, 10, 'Condition_need_action', 'medium', NULL, '2025-11-05 07:12:54', '2025-11-05 10:57:52', NULL, NULL, NULL),
	(1212, 'بابت تغییر پیمانکار چاپ از سپاس(دنا) به پیمانکار مستقیم (گلچین)-ارجاع ردیف های 74 و77 اندیکاتور 4577', 'با سلام و احترام،پیرو مذاکره تلفنی با توجه به فوریت موضوع لطفا در اسرع وقت پیمانکار پیش فرض چاپ کارت های مجازی شهروند را از سپاس(دنا) به پیمانکار مستقیم(گلچین) تغییر دهید. با سپاس', '202511-1212', 8, 37, 'Condition_final_done', 'medium', NULL, '2025-11-05 08:12:42', '2025-12-30 06:12:54', NULL, NULL, NULL),
	(1213, 'RNN یکسان برای فارا و شرکت کیان', 'با سلام و احترام\r\nدر خصوص تراکنش فارا در صورتیکه پرداخت نوین تراکنش را انجام دهد RRN تراکنش در پاسخ MTI=110  و MTI=200 یکی است \r\nولی در پروژه دیگر که شرکت کیان تراکنش فارایی را انجام میدهد و بخش شاپرکی توسط پرداخت نوین انجام میشود RRN ها متفاوت است\r\nخواهشمند است راه حلی جهت این موضوع ارائه فرمایید.\r\nبا سپاس', '202511-1213', 3, 10, 'Condition_regect', 'high', NULL, '2025-11-05 09:55:01', '2026-05-19 10:34:02', NULL, NULL, NULL),
	(1214, ' زمانبندی پیاده سازی شتاب8 ', 'با سلام و احترام،\r\n با عنایت به نامه ارسال شده از سوی شرکت شاپرک با موضوع اعلام زمانبندی پیاده سازی شتاب8 ،خواهشمند است  گانت چارت  و زمان بندی پروژه حداکثر  تا تاریخ 1404.08.5  ارائه گردد. \r\nباتشکر ', '202511-1214', 3, 10, 'condition_under_review', 'high', NULL, '2025-11-05 11:59:49', '2025-12-08 07:13:34', NULL, NULL, NULL),
	(1215, 'نتایج پویش آسیب پذیری آبان ماه سال 1404', ' با سلام و احترام\r\n\r\nبه اطلاع میرساند نتایج پویش آسیب پذیری آبان ماه سال 1404  به پیوست تقدیم میگردد.\r\n\r\n خواهشمند است در خصوص رفع موارد در اسرع وقت اقدام فرمایید. پویش بعدی در  تاریخ آذر ماه 1404  صورت خواهد پذیرفت.\r\nرمز فایل از خانم کمایی دریافت گردد.\r\nبا سپاس ', '202511-1215', 1, 10, 'Condition_final_done', 'medium', NULL, '2025-11-08 07:00:52', '2026-02-21 08:38:19', NULL, NULL, NULL),
	(1216, 'درخواست اصلاح کد خدمتهای Import شده .اندیکاتور 26031', 'با سلام و احترام،همانگونه که مستحضرید طی تیکت 1174 درخواست Import کد خدمت و پایانه ها ارسال و انجام شده بود اما پس از بررسی همکاران حوزه POS مشخص شد پایانه ها با مشکل پارامترگیری مواجه شده اند و نیاز به اصلاح کد خدمتها می باشد.لذا پیرو اعلام تلفنی روز چهارشنبه و ارسال فایل اصلاحی در واتساپ جهت جلوگیری از بروز اختلال در پایانه های فروشگاه های زنجیره ای درخواست انجام با فوریت بالا داشته و روز پنج شنبه نیز تائیدیه انجام را از جناب آقای حیدری مقدم دریافت کردیم اما هنوز اصلاح لازم صورت نگرفته و فروشگاه ها با مشکل مواجه شده اند .خواهشمند است تسریع فرمائید.\r\nفایل اصلاحی به پیوست ارائه می گردد.\r\nبا سپاس', '202511-1216', 8, 37, 'Condition_final_done', 'low', NULL, '2025-11-08 07:18:40', '2026-02-22 13:57:09', NULL, NULL, NULL),
	(1217, 'نمایش تراکنش های اینترنتی گام ', 'باسلام و احترام\r\nخواهشمند است بر روی بک آفیس پذیرندگی تراکنش های اینترنتی گام نیز نمایش داده شود.\r\nباسپاس', '202511-1217', 1, 25, 'Condition_final_done', 'low', NULL, '2025-11-08 13:46:26', '2026-02-21 08:38:14', NULL, NULL, NULL),
	(1218, 'افزودن فیلد 48 تگ 38 &quot;نام بانک&quot;', 'با سلام  و اجترام\r\nخواهشمند است در فیلد 48 تگ 38 &quot;نام بانک&quot; نمایش داده شود.\r\nنمونه به پیوست ارسال میشود.', '202511-1218', 3, 10, 'Condition_do_action', 'medium', NULL, '2025-11-09 06:29:32', '2026-05-04 13:13:30', NULL, NULL, NULL),
	(1219, ' پیشنهادات فرآیندی یا ساز و کار اجرایی مرتبط پروژه برگشت از خرید ', '\r\n\r\nبا سلام و احترام\r\n\r\nبا توجه به  عملیاتی شدن پروژه برگشت از خرید Refund  و نطر به اهمیت انجام احراز هویت قوی پذیرنده در زمان ارسال تراکنشهای برگشت از خرید از سوی شرکت های ارائه دهنده پرداخت\r\n\r\nالزامی است  که پیشنهادات فرآیندی یا ساز و کار اجرایی مرتبط با موضوع ارائه گردد.\r\n\r\nبا سپاس\r\n', '202511-1219', 3, 10, 'Condition_final_done', 'high', NULL, '2025-11-09 09:01:59', '2026-02-21 08:38:00', NULL, NULL, NULL),
	(1220, 'گزارش روزانه تراکنش‌های با خطای ۴۲۰ در مهرماه', 'با سلام و احترام؛\r\n\r\nلطفاً گزارش روزانه‌ای از تعداد کل تراکنش‌هایی که در مهرماه با کد خطای ۴۲۰ مواجه شده‌اند، به همراه تعداد تراکنش‌های دارای کد ۴۲۰ که شامل شناسه مرجع (RRN) می‌باشند، ارائه فرمایید.', '202511-1220', 3, 26, 'Condition_final_done', 'high', NULL, '2025-11-09 11:38:34', '2026-02-22 14:03:22', NULL, NULL, NULL),
	(1221, 'کف مبلغ تراکنش برای تمامی بانک ها 2000 ', 'با سلام و احترام\r\nخواهشمند است کف مبلغ تراکنش برای تمامی بانک ها 2000 ریال در نظر گرفته شود\r\nبا سپاس', '202511-1221', 3, 10, 'Condition_final_done', 'high', NULL, '2025-11-09 11:54:43', '2026-02-21 08:37:22', NULL, NULL, NULL),
	(1222, 'ایجاد دسترسی با نقش رونوشت انفرادی', 'نام کاربری rohallahzadeh	با نقش رونوشت انفرادی ایجاد شده است لذا خواهشمند است در خصوص ایجاد تغییرات لازم جهت مشابهت با دسترسی e.ostovar  اقدامات لازم را مبذول فرمایید. با سپاس', '202511-1222', 4, 52, 'Condition_final_done', 'low', NULL, '2025-11-09 12:17:02', '2026-02-22 13:57:17', NULL, NULL, NULL),
	(1223, 'خطای 34', 'باسلام و احترام\r\nبر روی شماره کارت \r\n6274123331211470 کلیه تراکنش ها خطای 34 دریافت میکنند.\r\nخواهشمند است علت خطا را اعلام بفرمایید.\r\nباسپاس', '202511-1223', 1, 25, 'Condition_final_done', 'high', NULL, '2025-11-09 15:05:38', '2026-02-21 08:37:13', NULL, NULL, NULL),
	(1224, 'مشکل در غیر فعال کردن گزینه خرید ترمینال', 'با سلام و احترام \r\nبا توجه به اینکه نیاز به غیر فعال کردن گزینه خرید برای برخی از ترمینال ها وجود داشت اقدام به انجام این کار بروی بک افیس شد\r\nولی خطاهای زیر مشاهده شد:\r\n بروی بک افیس قدیم : پس از 24 ساعت، به حالت قبل یعنی فعال بودن گزینه خرید باز گشت\r\nبروی بک افیس جدید خطای کد شبا یافت نشد مشاهده شد حتی با وجود وارد کردن شبای جدید\r\n\r\nخواهشمند است :\r\n1- ابتدا برای ترمینال های لیست پیوست گزینه خرید غیر فعال شود\r\n2- سپس مشکل بک افیس حل شود\r\nبا سپاس\r\n\r\n گزینه خرید غیرفعال شده ', '202511-1224', 3, 10, 'Condition_final_done', 'high', NULL, '2025-11-10 08:07:58', '2026-02-21 08:37:09', NULL, NULL, NULL),
	(1225, 'خطای 03 ترمینال 12243407', '\r\nبا سلام\r\nترمینال ۱۲۲۴۳۴۰۷ یکبار در شاپرک غیرفعال گردیده است و سپس فعالسازی مجدد انجام شده است و پس از فعال کردن ترمینال به صورت دستی در بک آفیس، خطای ۰۳ با اینترنال شماره ترمینال در جدول ترمینال ها پیدا نشد مواجه میشویم .\r\nخواهشمند است این ترمینال فعال و مشکل مربوطه رفع شود .\r\n', '202511-1225', 3, 10, 'Condition_final_done', 'high', NULL, '2025-11-10 08:41:11', '2025-12-30 05:55:18', NULL, NULL, NULL),
	(1226, 'خطای افزودن حساب جدید ', 'با سلام\r\nترمینال های 30328879\r\n30328815 \r\nشخص سه حساب شریک تجاری داشته است جهت تعریف حساب جدید،  خطای بروی سامانه خطای سوئیچ (یکی از شباهای قبلی پذیرنده در تسهیم استفاده شده و قابل حذف نیست) مشاهده میشود\r\nحساب جدید در شاپرک آپدیت شد است.', '202511-1226', 3, 10, 'Condition_final_done', 'high', NULL, '2025-11-11 06:19:34', '2026-02-21 08:36:53', NULL, NULL, NULL),
	(1227, 'بررسی خطای 500 روی swagger', 'با سلام و احترام، آقای ثابت از همکاران این مدیریت برای استفاده از swagger با خطای 500 مواجه شده و امکان تست ندارند. آدرس:http://172.25.1.59:7080/swagger/index.html\r\nلطفا بررسی و رفع اشکال شود. با تشکر', '202511-1227', 4, 37, 'Condition_final_done', 'medium', NULL, '2025-11-11 06:25:02', '2025-12-30 06:12:36', NULL, NULL, NULL),
	(1228, 'عدم اعمال تغییر حساب ', 'با سلام \r\nترمینال های\r\n 12213778\r\n12208312\r\n12208310\r\n12208307\r\nتغییر حساب در سوئیچ سیپا موفق ولی در سوئیچ اینتک ناموفق  و اعمال نشده می باشد.', '202511-1228', 3, 10, 'Condition_final_done', 'low', NULL, '2025-11-11 06:35:46', '2026-02-21 08:36:44', NULL, NULL, NULL),
	(1229, 'افزودن گروه کارت در فایل چاپ کارت', 'باسلام و احترام\r\nخواهشمند است همانند تیکت 796 ، در فایل چاپ کارت برای نوع کارت های  &quot; خرید با شارژ مجازی &quot;  و  &quot; مگا کارت &quot; ،  نیز گروه کارت اضافه گردد.\r\nباسپاس', '202511-1229', 1, 25, 'condition_acepted_test_auto', 'high', NULL, '2025-11-11 06:55:41', '2026-05-16 11:46:57', NULL, NULL, NULL),
	(1230, 'درخواست دیتای جداول سرویس گروه کارت(متقاضی آقای ثابت)', 'با سلام و احترام، آقای ثابت از همکاران توسعه نرم افزار متقاضی درخواست به شرح زیر می باشند:\r\n\r\nبا توجه به پیاده سازی سرویس گروه کارت در تاپیار، خواهشمندم دسترسی به دیتای جداول این سرویس در اینتک (به صورت مستقیم یا export) را فراهم فرمایید.\r\n\r\nبا تشکر', '202511-1230', 4, 37, 'Condition_regect', 'low', NULL, '2025-11-11 08:09:18', '2025-12-30 12:39:40', NULL, NULL, NULL),
	(1231, 'مقدار فیلد 53 جدید در خصوص کانال 10010 ', 'با سلام و احترام\r\nخواهشمند است مقدار فیلد 53 جدیدی در خصوص کانال 10010 جهت پابلیش نسخه جدید روی این کانال ایجاد و ارائه فرمایید.\r\nکلید در روز یکشنبه آتی مورخ 1404-08-25 ارایه خواهد شد.\r\nبا تشکر', '202511-1231', 3, 10, 'condition_acepted_test_auto', 'medium', NULL, '2025-11-11 12:48:49', '2026-04-05 13:44:07', NULL, NULL, NULL),
	(1232, 'تراکنش برگشت از خرید( ریفاند )شاپرکی سوییچ پذیرندگی اینتک-اندیکاتور31007', 'با سلام و احترام، طبق درخواست آقای تفضلی این ماژول در خصوص سوئیچ و ایجاد امکان ریفاند روی سوئیچ پذیرندگی می باشد.\r\nدر صورت نیاز به توضیحات بیشتر با آقای تفضلی تماس حاصل شود)با سپاس', '202511-1232', 2, NULL, 'condition_acepted_invoice_auto', 'low', NULL, '2025-11-12 07:46:25', '2026-10-07 16:08:37', 16, 9, 'CR452220'),
	(1233, 'پرداخت وجوه دولتی ', 'باسلام و احترام\r\nخواهشمند است سرویس پرداخت وجوه دولتی از طریق درگاه پرداخت اینترنتی پیاده سازی گردد.\r\nباسپاس', '202511-1233', 1, 25, 'Condition_regect', 'high', NULL, '2025-11-12 08:14:28', '2026-01-07 09:00:34', NULL, NULL, NULL),
	(1234, 'تغییر سوئیچ کد  ترمینال 11728614  ', 'با سلام\r\nخواهشمند است برای ترمینال\r\n11728614  سوئیچ کد به 7 تغییر کند ', '202511-1234', 3, 10, 'Condition_final_done', 'high', NULL, '2025-11-15 10:19:45', '2025-12-30 05:55:12', NULL, NULL, NULL),
	(1235, 'حذف فیلدهای دلیل انسداد و توضیحات انسداد کارت های اعلامی در تیکت 1160', 'با توجه به تمدید تاریخ انقضای کارت های ذکر شده در تیکت 1160 (فایل پیوست) ، خواهشمند است فیلد دلیل انسداد و توضیحات انسداد کارت ها، خالی گردد.', '202511-1235', 4, 52, 'Condition_final_done', 'low', NULL, '2025-11-15 10:31:20', '2026-02-22 13:57:21', NULL, NULL, NULL),
	(1236, 'عدم نمایش برخی تقاضا درخواست کارت', 'برخی تقاضاها نظیر موارد ذیل برای کاربر h.zolfaghari  نمایش داده نمیشود. خواهشمند بررسی فرمایید\r\nدر قسمت کارت - درخواست های کارت\r\n شماره تقاضاهای نمونه : 642802-643164-642905', '202511-1236', 8, 52, 'Condition_final_done', 'low', NULL, '2025-11-15 12:31:43', '2026-02-22 13:57:26', NULL, NULL, NULL),
	(1237, 'RRN متفاوت شرکت کیان تراکنش فارایی ', 'با سلام و احترام\r\nدر خصوص تراکنش فارا در صورتیکه پرداخت نوین تراکنش را انجام دهد RRN تراکنش در پاسخ MTI=110  و MTI=200 یکی است \r\nولی در پروژه دیگر که شرکت کیان تراکنش فارایی را انجام میدهد و بخش شاپرکی توسط پرداخت نوین انجام میشود RRN ها متفاوت است\r\nخواهشمند است راه حلی جهت این موضوع ارائه فرمایید.\r\nبا سپاس', '202511-1237', 3, 10, 'Condition_regect', 'low', NULL, '2025-11-15 13:27:14', '2025-11-29 07:38:35', NULL, NULL, NULL),
	(1238, 'جدول جامع کدهای خطا در تراکنش‌های پرداخت', 'با سلام و احترام؛\r\nبا توجه به اهمیت پایش و مدیریت تراکنش‌ها، نیاز است تا فهرست کامل حالت‌های مختلف خطا، شامل خطای پذیرندگی، خطای کاربری، خطای صادرکنندگی و خطای شاپرکی، به همراه Response Code، InternalReasonCode، ExternalReasonCode متناظر هر یک، لطفاً بصورت شفاف، دقیق و در قالب یک جدول جامع جهت بهره‌برداری فنی ارائه گردد.', '202511-1238', 3, 26, 'Condition_final_done', 'high', NULL, '2025-11-16 06:11:30', '2026-02-22 14:03:17', NULL, NULL, NULL),
	(1239, 'پیاده سازی تراکنش بازگشت ار خرید', 'با سلام و احترام\r\nخواهشمند است تراکنش بازگشت از خرید پیاده سازی گردد.\r\nبا سپاس', '202511-1239', 3, 10, 'condition_in_progress', 'high', NULL, '2025-11-16 07:20:36', '2025-11-16 11:04:42', NULL, NULL, NULL),
	(1240, 'لیست تمامی کارت ها غیر از کارت های هدیه', 'با سلام و احترام؛\r\nخواهشمند است در خصوص ارسال لیست تمامی کارت ها بغیر از کارت های هدیه با فیلترهای زیر اقدام فرمایید. با سپاس\r\nشماره کارت - نام و نام خانوادگی - کدملی - موبایل - گروه مشتری - نام نمایندگی - تاریخ صدور -  تاریخ انقضا - وضعیت (فعال/غیرفعال)- مسدودی - وضعیت انقضا - الگوی کارت - گروه کارت - نوع کارت', '202511-1240', 8, 52, 'Condition_final_done', 'high', NULL, '2025-11-16 10:19:43', '2026-02-22 13:57:31', NULL, NULL, NULL),
	(1241, 'برگرداندن خطای 63 به دستگاه کارتخوان در صورت اشتباه بودن مک پیام', 'با سلام \r\nخواهشمند است به در صورت اشتباه بودن مک پیام، خطای 63  به دستگاه کارتخوان ارسال گردد.\r\nبا سپاس', '202511-1241', 3, 10, 'Condition_need_action', 'low', NULL, '2025-11-17 06:03:53', '2025-11-19 06:35:32', NULL, NULL, NULL),
	(1242, 'ایجاد کانال جدید مشابه 4080', 'با سلام \r\nخواهشمند است کانال جدیدی  مشابه کانال 4080\r\nکه شامل فیلد 53 , 32 نیز باشد، ایجاد نمایید.\r\nهدف این است که فیلد 90 پیاده سازی گردد که برای پیاده اسزی این مورد نیاز است در فیلد 32 تراکنش 810 این فیلد به دستگاه کارتخوان ارسال گردد.\r\nبا سپاس\r\n', '202511-1242', 3, 10, 'Condition_final_done', 'high', NULL, '2025-11-17 12:00:05', '2026-02-21 08:35:35', NULL, NULL, NULL),
	(1243, 'ویرایش رنج کارت ترمینال های پروژه  میکامال', 'با سلام و احترام\r\nخواهمند است برای ترمینال های لیست ضمیمه شده\r\nرنج کارت \r\nاز \r\n5054-1660-1163-0000\r\nتا\r\n5054-1660-1176-0009\r\nویرایش گردد. \r\nدر صورت نیاز به اطلاعات بیشتر با خانم شایان 09301622168 تماس حاصل فرمایید.\r\nبا سپاس', '202511-1243', 3, 10, 'Condition_final_done', 'medium', NULL, '2025-11-17 12:26:09', '2026-02-21 08:35:13', NULL, NULL, NULL),
	(1244, 'مشاهده تخصیص یک سریال به دو ترمینال مختلف', 'با سلام و احترام\r\nیک سریال به روی دو پایانه مختلف بایند شده است \r\nلطفا بررسسی فرمایید چراکه ارتباط سریال و پایانه بهید یک به یک باشد.\r\nنمونه به پیوست ارسال شده است.\r\n', '202511-1244', 3, 10, 'Condition_regect', 'high', NULL, '2025-11-17 13:27:39', '2025-11-19 06:15:47', NULL, NULL, NULL),
	(1245, 'خطای 03 برای ترمینال های ۳۰۶۰۶۵۵۶ و ۳۰۶۰۴۲۳۳', 'با سلام \r\nاحتراما به استحضار می رساند جهت ترمینال های \r\n۳۰۶۰۶۵۵۶ و ۳۰۶۰۴۲۳۳ تغییرحساب از بانک رفاه انجام شده است و ترمینال ها فعال می‌باشند ولی همچنان خطای ۰۳ دارند .\r\nخواهشمند است مشکل رفع گردد .\r\nباسپاس\r\n', '202511-1245', 3, 10, 'Condition_final_done', 'medium', NULL, '2025-11-18 06:02:02', '2026-02-21 08:35:01', NULL, NULL, NULL),
	(1246, 'اعلام نواقص و درخواست‌های بانک سینا جهت پیگیری24590-ارجاع 17', '\r\n1) افزودن گروهی مشتریان در داشبورد مشتریان: با توجه به اینکه مشتریان براساس شماره کارت تعریف می‌شوند، لازم است این بخش با افزودن گروهی کارت در داشبورد صادرکنندگی یکی شود. هر دو بخش از دیتای کارت استفاده می‌کنند و انجام عملیات در هر دو پنل به‌صورت جداگانه منجر به دوباره‌کاری خواهد شد.\r\n2) افزودن کارت – وضعیت کارت: وضعیت کارت هنگام اضافه کردن بررسی نمی‌شود. با توجه به اینکه اطلاعات کارت از طریق سامانه یاقوت قابل دریافت است، لازم است کارت‌های با وضعیت Close، Hot و المثنی ثبت نشوند و در صورت وجود، به کاربر خطای شماره رکورد نامعتبر نمایش داده شود.\r\n3) تعریف مشتری حقوقی – اطلاعات شهر: به دلیل عدم دریافت اطلاعات شهر که فیلد ضروری است، امکان تعریف مشتری حقوقی جدید وجود ندارد.\r\n4) نوع کاربران در داشبورد امنیت: در حال حاضر نوع کاربران قابل تنظیم توسط بانک نیست. لازم است این قابلیت اصلاح و به بانک امکان تعریف کاربران با تقسیم‌بندی زیر داده شود:\r\nادمین\r\nکاربر ستاد\r\nکاربر مالی\r\nکاربر منطقه\r\nکاربر شعبه\r\n5) ارسال پیامک رمز و یوزر کاربران در داشبورد امنیت: قابلیت ارسال پیامک حاوی نام کاربری و رمز عبور برای کاربران ایجاد گردد.\r\n6) روال مغایرت‌گیری تراکنش‌ها: روال مشخصی برای مغایرت‌گیری تراکنش‌ها تعریف نشده است. لازم است مستندات مربوطه ارائه گردد.\r\n7) داشبورد حسابداری: تاکنون داشبورد حسابداری به بانک تحویل نشده و توضیحی در این خصوص ارائه نشده است.\r\n8) اصلاح گروه کارت: در صورت تعریف اشتباه گروه کارت، لازم است مشخص شود از چه محلی و به چه نحوی قابل اصلاح است.\r\n9) حذف اطلاعات تستی: در صورت امکان، همکاری لازم برای حذف اطلاعاتی که همکاران بانک و اینتک برای تست سامانه تعریف کرده‌اند، صورت گیرد.\r\n', '202511-1246', 1, 37, 'Condition_do_action', 'low', NULL, '2025-11-18 10:38:43', '2025-12-15 09:03:36', NULL, NULL, NULL),
	(1247, 'درخواست مستندات راهنمای کاربری و فنی سامانه بانک سینا -اندیکاتور24590-ارجاع 20 ', 'لطفأ مستندات راهنمای کاربری و فنی سامانه را بابت ارائه خدمات پشتیبانی و مدیریت دسترسی ارائه فرمائید. با سپاس', '202511-1247', 2, 37, 'Condition_final_done', 'medium', NULL, '2025-11-18 10:41:22', '2026-02-22 13:57:43', NULL, NULL, NULL),
	(1248, 'پیاده سازی اوراق گام برای رفاه پردیس ', '\r\nبا سلام و احترام\r\nخواهشمند است پروژه اوراق گام پایانه های فروش برای شرکت  رفاه پردیس با ویژگی های زیر پیاده سازی گردد:\r\nامکان انجام تراکنش صرفا با مضرب یک میلیون ریال\r\nپیغام خطای مناسب در صورت وارد کردن مبالغی خارج از مضرب یاد شده \r\n', '202511-1248', 3, 10, 'Condition_regect', 'medium', NULL, '2025-11-18 10:49:07', '2026-02-21 08:34:55', NULL, NULL, NULL),
	(1249, 'غیرفعال کردن کارت', 'خواهشمند است در خصوص  غیرفعال کردن کارت ذیل اقدام مقتضی صورت پذیرد. با سپاس\r\n6221064426531881', '202511-1249', 4, 52, 'Condition_final_done', 'medium', NULL, '2025-11-18 13:25:06', '2026-02-22 13:57:48', NULL, NULL, NULL),
	(1250, 'متد فعال سازی/غیرفعال سازی - رمز اول و رمز دوم', 'باسلام و احترام\r\nخواهشمند است متدهای ذیل با پارامترهای تکی / گروهی پیاده سازی گردد:\r\n1.متد فعال سازی کارت\r\n2.متد غیرفعال سازی کارت\r\n3.متد صدور رمز اول کارت\r\n4..متد صدور رمز دوم کارت\r\nباسپاس', '202511-1250', 1, 25, 'condition_acepted_test_auto', 'high', NULL, '2025-11-18 14:08:37', '2026-05-26 05:20:02', NULL, NULL, NULL),
	(1251, 'پیاده سازی سوئیچ شارژ', 'با سلام\r\nبا توجه به اتمام پیاده سازی تیکت 271  و رد شدن تیکت شماره 1166 به علت ارسال سناریو، \r\nسناریو به پیوست این تیکت ارسال شده است. خواهشمند است این پروژه در اسرع وقت عملیاتی شود.\r\nبا سپاس', '202511-1251', 11, 10, 'Condition_regect', 'high', NULL, '2025-11-19 06:30:26', '2026-07-21 11:01:57', NULL, NULL, NULL),
	(1252, 'فعال شدن ترمینال ها بروی سوئیچ- آبان ماه', 'با سلام\r\nخواهشمند است ترمینال های لیست پیوست بروی سوئیچ فعال شود\r\nتوجه : فعال شود\r\nسپاس', '202511-1252', 3, 10, 'Condition_final_done', 'high', NULL, '2025-11-19 08:44:44', '2026-02-21 08:34:26', NULL, NULL, NULL),
	(1253, 'تمدید تاریخ انقضا بن کارت', 'باسلام و احترم \r\nخواهشمند است تاریخ انقضای کارت های فایل پیوست به مدت 3 سال تمدید گردد.\r\nباسپاس', '202511-1253', 1, 25, 'Condition_final_done', 'high', NULL, '2025-11-20 12:52:03', '2025-12-30 06:28:01', NULL, NULL, NULL),
	(1254, 'کد شعبه بانک ، نام شعبه بانک ، کد ارسال شعبه بانک ', 'خواهشمنداست در خصوص تهیه فایل اکسل که شامل کد شعبه بانک ، نام شعبه بانک ، کد ارسال شعبه بانک در سیستم اینتک می باشد اقدام مقتضی انجام پذیرد.\r\n\r\nکاربر درخواست دهنده: ملاحسینی\r\nتیکت : IR454410', '202511-1254', 4, 52, 'Condition_final_done', 'low', NULL, '2025-11-22 09:32:23', '2026-02-22 13:57:55', NULL, NULL, NULL),
	(1255, 'گزارش شارژ کارت آبان ماه', 'باسلام و احترام\r\nخواهشمند است گزارش شارژ کارت از تاریخ 14040801 تا پایان  14040830 ارسال گردد.\r\nباسپاس', '202511-1255', 1, 25, 'Condition_final_done', 'high', NULL, '2025-11-22 09:53:04', '2025-12-30 06:27:51', NULL, NULL, NULL),
	(1256, 'افزودن آخرین پروتکل بر روی  سوییچ های تستی ', 'باسلام و احترام\r\nخواهشمند است سوییچ های تستی پرداخت نوین با آی پی 087.107.134.136 با پورت های 4080 و 40800 طبق آخرین پروتکل تعیین شده با پرداخت نوین تعریف گردد.\r\n(کارت های اقتصاد نوین از Close Loop خارج شود و آخرین پروتکل اضافه گردد)\r\nباسپاس', '202511-1256', 3, 25, 'Condition_final_done', 'high', NULL, '2025-11-22 12:22:25', '2026-02-21 08:34:16', NULL, NULL, NULL),
	(1257, 'عدم نمایش برخی اندیکاتورها در گزارش &quot;درخواست های کارت&quot;', 'عدم نمایش اندیکاتور 10949047 در  &quot;درخواست های کارت&quot; و نمایش همان اندیکاتور در &quot;گزارش صدور کارت&quot;\r\n\r\nکاربر درخواست دهنده : سوزانی', '202511-1257', 4, 52, 'Condition_final_done', 'low', NULL, '2025-11-22 12:35:06', '2026-02-22 13:58:04', NULL, NULL, NULL),
	(1258, 'پیگیری تغییر سگمنت کارت 6221064874756865(بروز اختلاف  در سگمنت کارت و سگمنت استفاده شده)', 'با سلام و احترام، پیرو مذاکرات و اعلام مشکل در گروه واتساپ طی مورخ 1404/09/01،فردی با مراجعه به شهروند و خرید از سگمنت معیشت خود ، بدون داشتن سگمنت اعتباری خریدش روی سوئیچ با این سگمنت نمایش داده شده است.طی بررسی هاو اعلام آقای پرویزی ،زمانی که تراکنش انجام شده اکانت آیدی کارت29497 (اعتبار خرید) بوده اما در حال حاضر آیدی عوض شده و مشکلی از سمت سوئیچ نیست.\r\nلطفا ضمن بررسی موضوع چنانچه لاگی وجود دارد اعلام شود که این تغییرات توسط چه فردی و چه زمانی اتفاق افتاده است؟\r\nضمنا تصویر ارسالی با ذکر شماره کارت به پیوست ارائه می گردد.', '202511-1258', 1, 37, 'Condition_final_done', 'medium', NULL, '2025-11-26 10:54:27', '2026-02-22 13:58:09', NULL, NULL, NULL),
	(1259, 'درخواست حل موضوعات پشتیبانی مطرح شده در جلسه سینا با حضور آقای محمدی', '\r\nبا سلام و احترام،پیرو جلسه برگزار شده با بانک سینا و چک شدن تک به تک موارد با جناب آقای محمدی بصورت آنلاین ، برخی موارد در حد راهنمائی حل شد و مواردی باقی ماند که قرار بر ارسال آنها طی تیکت برای آقای محمدی شد.\r\nلیست باگ ها و مشکلات اعلامی در جلسه مورخ 2 آذرماه به شرح ذیل می باشد:\r\n۱. موضوع سرویس های مربوط به افزودن کارت و مشتری توسط شرکت بررسی و در صورت امکان داشبورد مشتریان و صادرکنندگی ادغام گردد.\r\n۲. در صورتی که در فرایند import کارت ها خطایی وجود داشته باشد شرح دقیق خطا نمایش داده نمی شود.(بصورت دقیق شماره کارتی که باعث بروز خطا شده مشخص نیست)\r\n۳. قرار شدلیست شهر و کشورهای مشکل دار به بانک اعلام گردد.\r\n۴. پنل تسویه پذیرندگان بصورت کامل به بانک تحویل گردد.\r\n۵. در پنل پذیرندگان فیلتر تاریخ کار نمی کند.\r\n۶. در صورت انتقال موجودی کارت، کارت قبلی غیرفعال نمی شود.\r\n۷. واکشی دیتا مشتریان با یاقوت به درستی انجام نمی شود. نمونه آن شناسه ۱۰۱۷۸ می باشد.\r\n۸. در زمان افزودن کارت بصورت گروهی بصورت رندوم خطا سرویس cvv2 کارت قطع میباشد رخ می دهد.\r\n۹. مستندات اموزشی بصورت کامل با ذکر جزییاتی که در جلسه مطرح شد(مانند اینکه برای دیدن برخی آیتم ها باید روی گزینه رایت کلیک کرد) تهیه و به بانک تحویل گردد.\r\n۱۰. با یوزر ادمین دسترسی به گزارش سرجنع تراکنش به تفکیک گروه کارت وجود ندارد.\r\n', '202511-1259', 7, 37, 'condition_in_progress', 'medium', NULL, '2025-11-29 09:56:13', '2025-11-30 05:33:48', NULL, NULL, NULL),
	(1260, 'درخواست بررسی علت خطاها با کد پاسخ ۷۷', 'با سلام و احترام؛\r\n\r\nبا توجه به لزوم بررسی علت بروز خطاهای ResponseCode = 77 در تراکنش‌های تاریخ 1404/09/07، خواهشمند است ضمن بررسی، علت بروز آنرا اعلام بفرمایید.\r\nشایان ذکر است برخی از نمونه RRN این تراکنش‌ها به شرح زیر است:\r\n200120807443\r\n200120880562\r\n200121043481\r\n200120952899\r\n200120621506\r\n200121246998\r\n200116399801\r\n200121050955\r\n200120879141', '202511-1260', 3, 26, 'Condition_final_done', 'low', NULL, '2025-11-29 10:37:35', '2026-02-22 14:03:09', NULL, NULL, NULL),
	(1261, 'غیر فعال کردن JOB فعال سازی مجدد برای نسخه های خاص', 'با سلام لطفا این جاب غیر فعال گردد.\r\n اگر پایایه ای با نسخات شامل  (&#039;1.1.1&#039;, &#039;1.1.2&#039;, &#039;1.1.3&#039;, &#039;1.1.4&#039;, &#039;1.1.5&#039;, &#039;1.2.2&#039;)  نباشد،\r\n شماره سریال با &#039;S&#039; و &#039;P&#039; شروع شود\r\nو قابلیت خریدش غیر فعال باشد،\r\nاتوماتیک قابلیت خرید برای آن پایانه  فعال شود.\r\n', '202511-1261', 3, 10, 'Condition_final_done', 'high', NULL, '2025-11-30 07:30:29', '2026-02-21 08:34:08', NULL, NULL, NULL),
	(1262, 'رفع مشکل چاپ کارت های نوبیتکس توسط پیمانکار', 'با سلام و احترام، نوبیتکس درخواست کارتی با شماره تقاضای651077 ثبت کرده اما پیمانکار چاپ آنرا نمی دیده است.پس از پیگیری ها مشخص شده مرحله  &quot;در انتظار تخصیص کارت توسط پیمانکار&quot; حذف شده و به همین دلیل پیمانکار متوجه اینکه درخواست جدیدی آمده نشده و با جستجوی شماره تقاضا در مرحله&quot; در انتظار تخصیص پیمانکار چاپ &quot; و ارجاع دستی به مرحله بعدی موفق به چاپ کارتها شده است.لطفا بررسی و مشکل رفع شود.\r\n', '202511-1262', 1, 37, 'Condition_do_action', 'low', NULL, '2025-11-30 08:50:05', '2025-12-15 09:10:02', NULL, NULL, NULL),
	(1263, 'خطای 34', 'باسلام و احترام\r\nپیرو تمدید تاریخ انقضا کارت های فایل پیوست ، به استحضار می رساند کلیه تراکتش های کارت های فایل پیوست خطای 34 &quot;احتمال تقلبی بودن تراکنش.کارت توسط دستگاه ضبط شود&quot; دریافت می نمایند.\r\nخواهشمند است اقدامات مقتضی را مبذول فرمایید.\r\nباسپاس', '202511-1263', 1, 25, 'Condition_final_done', 'high', NULL, '2025-11-30 14:23:54', '2025-12-30 06:27:40', NULL, NULL, NULL),
	(1264, 'پیاده سازی موارد زیر جهت آمادگی آزمون شتاب8(روی سوئیچ پذیرندگی)-اندیکاتور17344', 'با سلام و احترام، لطفا تراکنش های زیر ایجاد  شود.(در صورت نیاز با آقای تفضلی تماس حاصل شود)\r\n1-بررسی آدرس دارنده کارت\r\n2-بررسی اطلاعات دارنده کارت\r\n3-سرویس خرید چند مرحله اي (خرید با تاییدیه اولیه)\r\n4-ریفاند آنلاین', '202512-1264', 9, NULL, 'condition_acepted_invoice_auto', 'medium', NULL, '2025-12-01 06:25:02', '2026-10-07 16:08:37', 16, 9, 'CR453180'),
	(1265, 'خطای يکي از شباهاي قبلي پذيرنده در تسهيم استفاده شده و قابل حذف نيست', 'با سلام\r\n در خصوص افزودن حساب به شماره ترمینال 31500569 متعلق به شرکت ایرانسل با کد خطا برگشت داده شده است لذا خواهشمند است درخصوص رفع مشکل ارائه طریق نمایید.\r\nبا سپاس فراوان\r\n\r\n', '202512-1265', 3, 10, 'Condition_final_done', 'high', NULL, '2025-12-01 07:27:18', '2026-02-21 08:33:57', NULL, NULL, NULL),
	(1266, 'باگ فایل اکسل گزارش تراکنش ها در بک آفیس', 'با سلام و احترام؛\r\nبا توجه به اهمیت دریافت گزارش اکسل تراکنش های بک آفیس بر حسب هر ترمینال، بصورت کلی و بدون فیلتر تاریخ، خواهشمند است اقدامات لازم جهت رفع مشکل گزارش تراکنش های نامرتبط در این نوع گزارشات را مبذول فرمایید.', '202512-1266', 1, 26, 'Condition_final_done', 'high', NULL, '2025-12-01 07:53:27', '2025-12-30 06:16:08', NULL, NULL, NULL),
	(1267, 'ایجاد فرایندی جهت جلوگیری انجام تراکنش تکراری  در کمتر از 20 ثانیه', 'با سلام\r\nخواهشمند است جهت جلوگیری از انجام تراکنش Duplicate فرآیندی(Job) اجرا شود که از انجام تراکنش با یک شماره ترمینال، یک مبلغ و یک شکاره کارت یکسان در کمتر از 20 ثانیه جلوگیری شود.\r\nنمونه تراکنش  Dublicte\r\n513221745310 ,RRN=513221733478', '202512-1267', 3, 10, 'Condition_regect', 'high', NULL, '2025-12-01 10:35:41', '2025-12-10 06:49:45', NULL, NULL, NULL),
	(1268, 'افزودن کد صنف عطاری به سامانه بک آفیس', 'با سلام و احترام\r\nبه استحضار می‌رساند، حسب بررسی و استعلام به‌عمل‌آمده از سوئیچ سامان، کد 5915 مربوط به صنف عطاری و گیاهان دارویی جایگزین کد 8099 شده است. با این حال، کد مذکور در بخش پذیرندگان و در قسمت صنف سامانه بک‌آفیس قابل مشاهده نمی‌باشد.\r\nخواهشمند است دستور فرمایید ضمن بررسی موضوع، نسبت به افزودن کد مذکور در سامانه اقدام لازم به عمل آید.\r\nبا سپاس', '202512-1268', 3, 49, 'Condition_final_done', 'medium', NULL, '2025-12-02 11:31:42', '2026-02-21 12:15:31', NULL, NULL, NULL),
	(1269, 'عملیاتی شدن کانال 10010', 'با سلام و احترام\r\nخواهشمند است کانال 10010 بروی نود 30 با همان کلیدهای اعمال شده، عملیاتی گردد.\r\nبا سپاس', '202512-1269', 3, 10, 'Condition_final_done', 'high', NULL, '2025-12-02 12:22:01', '2026-02-21 08:33:49', NULL, NULL, NULL),
	(1270, 'تعریف صندوق مجازی آبفا اهواز', 'باسلام و احترام \r\nخواهشمند است صندوق مجازی برای شرکت  آبفا اهواز ایجاد گردد.\r\nنام کاربری ذیل برای این کاربر ایجاد شده است، خواهشمند است کاربر مذکور تنها صندوق متعلق به خودش را مشاهده کند و سایر صندوق ها را نبیند.\r\nAbfaSandogh\r\n\r\nباسپاس\r\n', '202512-1270', 1, 25, 'Condition_final_done', 'high', NULL, '2025-12-02 12:25:10', '2026-02-21 08:33:29', NULL, NULL, NULL),
	(1271, 'درخواست ارائه گزارشات سوئیچ و اولویت‌بندی فعالیت‌های نیروی مقیم شرکت اینتک', 'با سلام و احترام،\r\n\r\nبدین‌وسیله درخواست می‌گردد نیروی مقیم شرکت اینتک که در روزهای یکشنبه و چهارشنبه به مدت هشت ساعت در محل شرکت رفاه پردیس حضور می‌یابد، از این پس گزارش‌های مربوط به وضعیت سوئیچ را به واحدهای ذی‌ربط در شرکت رفاه پردیس ارائه نماید.\r\n\r\nبا توجه به اهمیت این گزارش‌ها در روند کاری و ضرورت هماهنگی‌های داخلی، شایسته است گزارش‌های موفق، ناموفق، ناموفق‌های کسب‌وکاری/کاربری به‌صورت تفکیک‌شده، همراه با زمان پاسخ تراکنش‌ها و میزان دسترسی‌پذیری سوئیچ به‌صورت منظم ارسال شود.\r\n\r\nهمچنین انتظار می‌رود پیگیری امور روزمره، انجام چک‌های ضروری و رسیدگی به باگ‌های مرتبط با سوئیچ در اولویت فعالیت همکاران محترم شرکت اینتک در روزهای حضور ایشان (یکشنبه و چهارشنبه) قرار گیرد.', '202512-1271', 3, 26, 'Condition_final_done', 'high', NULL, '2025-12-03 06:18:34', '2026-02-22 14:03:05', NULL, NULL, NULL),
	(1272, 'بررسی امکان شارژ کارت های مسدود شده یا منقضی', 'با سلام و احترام؛\r\nبا توجه به اعلام همکاران، امکان شارژ کارت های مسدودی و یا منقضی شده توسط شعب بانک وجود دارد لذا خواهشمند است در این خصوص (امکان یا عدم امکان این امر) اعلام نظر فرمایید. با سپاس', '202512-1272', 8, 52, 'condition_acepted_test_auto', 'low', NULL, '2025-12-03 06:57:47', '2026-03-15 11:46:45', NULL, NULL, NULL),
	(1273, 'درخواست بررسی خطای سرویس فعالسازی نوبیتکس', 'با سلام و احترام، طی بررسی سرویس اینتک خطای 404 میدهد.تصاویر به پیوست می باشد.', '202512-1273', 1, 37, 'condition_in_progress', 'medium', NULL, '2025-12-03 08:35:27', '2026-07-14 07:03:11', NULL, NULL, NULL),
	(1274, 'تست و پیاده سازی مانده توکنی', 'با سلام و احترام\r\nپیاده سازی مانده توکنی (موجودی اینترنتی) پیاده سازی گردد.\r\nبا سپاس\r\n', '202512-1274', 3, 10, 'Condition_final_done', 'high', NULL, '2025-12-03 11:49:08', '2026-02-21 08:33:20', NULL, NULL, NULL),
	(1275, 'تخصیص شبای قدیم پس از تعویض دستگاه', 'با سلام و احترام\r\n\r\nترمینال 11285324 تعویض دستگاه انجام داده و طی این فرآیند شبا قدیم دستگاه جایگزین شده است\r\nطی بررسی های انجام شده مشکل از  سرویس سامانه جام جم نمی باشد چرا که بروی سوئیچ دیگر شبای درست ثبت شده است.\r\n\r\nشبا قدیم :IR620550263180005418220001\r\nشبا جدید :IR630550263100105418220001', '202512-1275', 3, 10, 'Condition_final_done', 'medium', NULL, '2025-12-03 12:42:54', '2025-12-30 05:55:07', NULL, NULL, NULL),
	(1276, 'رفع خطای 92 ترمینال دوم کیوسک طلا ', 'با سلام \r\nخواهشمند است خطای 92 ترمینال 12111081   مرتبط با پروژه کیوسک طلا رفع گردد\r\nبا سپاس', '202512-1276', 3, 10, 'condition_in_progress', 'low', NULL, '2025-12-03 13:13:08', '2025-12-06 07:11:03', NULL, NULL, NULL),
	(1277, 'فرآیند مانا-اندیکاتور 34095(متقاضی فنی خانم نوری)', 'با سلام و احترام،در خصوص سامانه مانا با توجه به فورس زمانی اعلام شده، دو رویکرد پیاده سازی آنلاین و آفلاین به صورت موازی در پروسه انجام قرار داشته اما رویکرد افلاین در الویت قرار دارد. پیاده سازی آفلاین: لازم است اینتک مطابق با فایل های پیوست این نامه، به صورت روزانه فایل های واحد کارت شامل ثبت کارت های جدید و یا کارت های شامل اصلاح مشخصات را مطابق با ورودی سرویس های داکیمونت های پیوست و همچنین نمونه فایل های اکسل، در مسیر SFTP مشترک با شرکت کاسپین به آدرس 192.168.243.98 با یوزر و پسوردی که در اختیار کارشناس اینتک قرار می گیردتا قبل از ساعت 17 در مسیر lotus_files/mana_pec/in/  قرارداده و جواب آن را نیز در ساعت 13 روز بعد در مسیر lotus_files/mana_pec/out/ دریافت نماید و اقدام به آپدیت دیتا موجود در سامانه issuer نماید. لازم است checkbox ای نیز با عنوان &quot;مانا&quot; در کنار سایر فیلدهای جاری سامانه issuer قرار گیرد تا نتیجه نهائی فراخوانی در سامانه مانا در این فیلد آپدیت گردد. نکات: 1. جهت ایجاد تمایز میان فایل های مانا تجارت الکترونیک با بانک پارسیان لازم است تا فایل ها به صورت زیر نام گذاری شود. فایل ها از ایندکس 100 شروع شود. فیلد trace داخل فایل تا 8 رقم دارد و لازم است از عدد 990001 شروع گردد. نام گذاری فایل های ثبت و آپدیت: mana_cardEnrollment_v01_yyyy_MMdd_indext.txt mana_cardModify_v01_yyyy_MMdd_indext.txt 2. با وجود امکان ثبت اطلاعات بن کارتهای صادر شده توسط شبکه بانکی کشور در سامانه مانا از تاریخ ۱۴۰۴/۱۰/۰۱ از انجام تراکنش توسط بن کارت هایی که در سامانه یاد شده درج نشده باشند؛ جلوگیری خواهد شد. لذا فورس زمانی 19 آذر ماه برای انجام خواهیم داشت.', '202512-1277', 2, NULL, 'condition_acepted_test_auto', 'low', NULL, '2025-12-06 08:17:05', '2026-10-07 16:08:21', 16, 9, 'CR457554'),
	(1278, 'خطای ترمینال در جدول ترمینل ها پیدا نشد', 'با سلام و احترام\r\nبرای ترمینال 06118711، خطای &quot;ترمینال در جدول ترمینل ها پیدا نشد&quot; مشاهده میشود.\r\n', '202512-1278', 3, 10, 'Condition_final_done', 'high', NULL, '2025-12-06 09:21:12', '2025-12-30 05:54:53', NULL, NULL, NULL),
	(1279, 'خطای 34', 'باسلام و احترام\r\nخواهشمند است علت خطای 34 بر روی کارت ذیل را اعلام بفرمایید.\r\n\r\n6274124491847830\r\nباسپاس', '202512-1279', 1, 25, 'Condition_final_done', 'high', NULL, '2025-12-06 12:22:40', '2025-12-30 06:27:34', NULL, NULL, NULL),
	(1280, 'فایل صدور کارت _ خطای سرور', 'باسلام و احترام\r\n\r\nهنگام بارگذاری فایل صدور کارت ( فایل پیوست ) خطای سرور رخ میدهد.\r\n\r\nاطلاعات صدور کارت \r\n\r\nنوع کارت : خرید با شارژ مجازی\r\n\r\nالگوی کارت : مجازی - الگوی جامع\r\n\r\nگروه کارت : مجازی - کارت خرید فروشگاه جانبازان\r\n\r\nنمایندگی : دفتر قم دو\r\n\r\nمارکت: فروشگاه جانبازان\r\n\r\nرمز دو و CCV2 حذف شود\r\n\r\nباسپاس', '202512-1280', 1, 25, 'Condition_final_done', 'high', NULL, '2025-12-07 06:48:10', '2026-02-21 08:33:06', NULL, NULL, NULL),
	(1281, 'فعالسازی کد محصول جدید (85)', 'با سلام و احترام\r\nبا توجه به الزامات جدید جدید از جانب بانک ایران زمین ، خواهشمند است دستور فرمایید فرآیند فعالسازی رنج محصول 85 بر روی سوئیچ اینتک انجام گیرد.\r\nبر اساس برنامه ریزی انجام شده برای ارائه خدمات جدید به مشتریان و با توجه به لزوم صدور کارت روی رنج مذکور، ضروری است این کارت قابلیت های بن کارت صادره فعلی با رنج 31 و 41 را نیز دارا باشد.\r\nپیشاپیش از همراهی صمیمانه همکاران محترم کمال تشکر و سپاسگزاری را دارم\r\nخواهشمند است جهت هرگونه ابهاماتی با خانم کوره بازی به شماره  09122716048 تماس حاصل فرمایید.\r\nبا سپاس\r\n', '202512-1281', 3, 49, 'Condition_regect', 'medium', NULL, '2025-12-07 07:07:56', '2025-12-13 12:10:02', NULL, NULL, NULL),
	(1282, 'تغییر سوئیچ کد ترمینال 06118711', 'با سلام\r\nخواهشمند است  سوئیچ کد ترمینال  06118711 از 3 به 7 تغییر یابد', '202512-1282', 3, 10, 'Condition_final_done', 'high', NULL, '2025-12-07 12:38:53', '2025-12-30 05:54:46', NULL, NULL, NULL),
	(1283, 'پاک کردن اطلاعات اضافه سرور 10.0.72.126', 'با سلام\r\nبا توجه به بررسی صورت گرفته مشخص شد که حجم زیاد اطلاعات موجود بروی این سرور (4 ترا) 10.0.72.126 مرتبط با کپی کردن دیتابیس این پروژه از روی دیتابیس اصلی بوده و برخی اطلاعات غیر ضروری نیز منتقل شده است.\r\nخواهشمند است اطلاعات غیر ضروری در اسرع وقت پاک شود.\r\nبا سپاس', '202512-1283', 3, 10, 'Condition_final_done', 'medium', NULL, '2025-12-08 06:58:09', '2025-12-30 05:54:40', NULL, NULL, NULL),
	(1284, 'عدم تسویه سگمنت اعتباری ', 'کلیه خرید های انجام شده با کارتهای مگاکارت ( سگمنت اعتباری ) بدلیل مشکل سمت اینتک تسویه نشده اند بررسی فرمایید\r\n /// شماره نامه 457123\r\n //// کاربر درخواست دهنده : عرفانه اکبری ', '202512-1284', 8, 52, 'Condition_regect', 'low', NULL, '2025-12-09 11:58:40', '2025-12-13 08:15:42', NULL, NULL, NULL),
	(1285, ' خطای 03-ترمینال 11367451', 'با سلام\r\nترمینال 11367451  خطای 03- در جدول ترمینال ها پیدا نشد- را دریافت می کند.\r\nبا توجه به مشاهده شدن زیاد این خطا بروی ترمینال ها خواهشمند است به صورت رشه ای رفع گردد.\r\nبا سپاس', '202512-1285', 3, 10, 'Condition_final_done', 'high', NULL, '2025-12-10 09:50:43', '2025-12-30 05:54:26', NULL, NULL, NULL),
	(1286, 'ایجاد تغییرات در پیمانکار چاپ در اینتک (نامه 35207)', 'با توجه به درخواست همکاران دارندگان، خواهشمند است اقدامات پیوست در خصوص تغییر پیمانکاران چاپ در بخش &quot;درخواست کارت - جدید - صدور رونوشت یا صدور کارت&quot; صورت پذیرد.\r\nجابجایی &quot;سپاس&quot; با &quot;دنا&quot;\r\nجابجایی &quot;پیمانکار مستقیم&quot; با &quot;گلچین&quot;\r\nگزینه &quot;داتیس آریانا تیم&quot; حذف گردد\r\nرویه اجرایی &quot;تجارت الکترونیک پارسیان&quot; با گزینه &quot;4&quot; یکسان شود.\r\n\r\nهمچنین خواهشمند است رویکرد (work flow) اجرایی در صورت انتخاب گزینه 4 بصورت شفاف برای مشخص و ارائه گردد. با سپاس\r\n\r\n* با توجه به اهمیت موضوع در صورت هرگونه ابهام شماره تماس آقای ذوالفقاری در پیوست ارائه شده است.', '202512-1286', 8, 52, 'Condition_final_done', 'low', NULL, '2025-12-13 05:09:47', '2026-02-22 13:58:19', NULL, NULL, NULL),
	(1287, 'درخواست تکمیل وب سرویس های چندحسابی اینتک-اندیکاتور35231(متقاضی: آقای ثابت)', 'با سلام و احترام،خواهشمند است وب سرویسهاي چندحسابی (مستند پیوست)به شرح زیر تکمیل و اجرا شود.\r\n1. اندپوینت   TerminalMultiAccount\r\nفیلدی در ورودی جهت تعریف اولویت(priority) اضافه شود.\r\n2. اندپوینتی جدید جهت نمایش اطلاعات مربوط به شماره شباهای پذیرنده تعریف شود\r\nورودی:شماره ترمینال\r\nخروجی:شماره شبا،شماره حساب،عنوان،اولویت،فعال/غیرفعال بودن\r\n3.اندپوینتی جدید جهت ویرایش اطلاعات چندحسابی تعریف شود\r\nورودی:شماره ترمینال،شماره شبا،شماره حساب،عنوان،اولویت،فعال/غیرفعال بودن\r\n', '202512-1287', 1, 37, 'condition_acepted_test_auto', 'low', NULL, '2025-12-13 07:17:50', '2026-06-20 10:51:35', NULL, NULL, NULL),
	(1288, 'روت ترمینال به سوئیچ اینتک 30549853 ', 'با سلام \r\nخواهشمند است  ترمینال 30549853 از لود بالانسر \r\nبه جای سوئیچ رفاه به سوئیچ اینتک روت شود.', '202512-1288', 3, 10, 'Condition_final_done', 'high', NULL, '2025-12-15 11:30:49', '2025-12-30 05:54:13', NULL, NULL, NULL),
	(1289, 'اعلام مشخصات سرور موردنیاز برای بک آفیس جدید', 'با توجه به راه اندازی نسخه جدید بک آفیس دارندگی، خواهشمند است server specification مورد نیاز اعلام گردد.', '202512-1289', 4, 52, 'Condition_final_done', 'low', NULL, '2025-12-15 12:13:33', '2026-02-22 13:58:28', NULL, NULL, NULL),
	(1290, 'نمایش ساعت تراکنش بر روی متن پیامک', 'باسلام و احترام\r\nخواهشمند است بر روی متن پیامک تراکنش های کارت ، به جای ساعت محلی ابزارپذیرش،   &quot;  ساعت تراکنش &quot; نمایش داده شود.\r\nباسپاس', '202512-1290', 1, 25, 'Condition_regect', 'high', NULL, '2025-12-16 10:00:45', '2026-05-20 07:01:51', NULL, NULL, NULL),
	(1291, 'تغییر سوئیچ کد 11441104', 'با سلام خواهشمند است \r\nسوئیچ کد ترمینال 11441104 از 3 به 7 تغییر کند', '202512-1291', 3, 10, 'Condition_final_done', 'high', NULL, '2025-12-16 12:32:09', '2026-02-21 08:30:23', NULL, NULL, NULL),
	(1292, 'درخواست دسترسی جهت توسعه پروژه چند شبایی اینتک(آقای ثابت)', 'لطفا جهت توسعه پروژه چند شبایی اینتک، دسترسی به سرور\r\n172.25.1.54:8090/apiservices\r\nرا برای یوزر PecDeveloper ایجاد نمایید.', '202512-1292', 7, 37, 'Condition_final_done', 'low', NULL, '2025-12-17 05:33:26', '2025-12-30 06:12:27', NULL, NULL, NULL),
	(1293, ' پیاده سازی پرداخت چند مرحله ای', 'با سلام و احترام\r\nخواهشمند است پرداخت چند مرحله ای پیاده سازی گردد.\r\nبا سپاس', '202512-1293', 3, 10, 'condition_under_review', 'medium', NULL, '2025-12-20 07:54:22', '2025-12-20 10:41:41', NULL, NULL, NULL),
	(1294, 'خطاهای کانال تستی RKI', 'با سلام\r\nبروی کانال تست فیلد 48 تگ 98 شناسه یکتا توسط سوئیچ برگردانده نمیشود\r\nهمچنین امکان تراکنش شارژ پین با خطای 420 دریافت می کند \r\n  ترمینال جهت تست 20077509\r\n\r\n', '202512-1294', 3, 10, 'condition_acepted_test_auto', 'high', NULL, '2025-12-20 10:33:11', '2026-03-14 11:38:06', NULL, NULL, NULL),
	(1295, 'مشکل تراکنش تلفنی فارا', 'با سلام\r\nدر  تراکنش تلفنی فارا، اعتبار صفر نمایش داده میشد اطفا بررسی و رفع گردد.\r\nبا تشکر', '202512-1295', 3, 10, 'Condition_final_done', 'high', NULL, '2025-12-20 10:55:31', '2026-02-21 08:30:10', NULL, NULL, NULL),
	(1296, 'تخصیص مارکت به کارت ', 'باسلام و احترام\r\nخواهشمنداست به 3 عدد شماره کارت فایل پیوست مارکت &quot; رویداد جهش نوین &quot; با  شناسه های 2606 ( IIN 581672052)  و 2607  ( IIN 581672051)  تخصیص داده شود.\r\nباسپاس', '202512-1296', 1, 25, 'Condition_final_done', 'high', NULL, '2025-12-20 14:19:45', '2026-02-21 08:32:13', NULL, NULL, NULL),
	(1297, 'مشکل  ثبت تسهیم شریک تجاری', 'با سلام واحترام\r\nباستحضار می رساند در زمان ثبت تسهیم شریک تجاری با خطا (E22  يکي از شباهاي قبلي پذيرنده در تسهيم استفاده شده و قابل حذف نيست) برگشت داده میشود لذا خواهشمند است در خصوص رفع مشکل ارائه طریق نمایید.\r\n شماره ترمینال: 31425572', '202512-1297', 3, 10, 'Condition_regect', 'high', NULL, '2025-12-21 10:51:00', '2025-12-23 07:56:36', NULL, NULL, NULL),
	(1298, 'روت ترمینال 12221082 به نود 101', 'با سلام\r\nخواهشمند است ترمینال 12221082 بروی نود 101 قابلیت انجام تراکنش داشته باشد\r\nبا سپاس', '202512-1298', 3, 10, 'Condition_final_done', 'high', NULL, '2025-12-22 07:25:31', '2026-02-21 08:32:58', NULL, NULL, NULL),
	(1299, 'رفع خطای کد پاسخ 12 با کد علت خارجی 3', 'با سلام و احترام\r\n با توجه به گزارش شاپرک،  بیشترین خطای شاپرکی مربوط به کد خطای 12 میباشد.\r\nخواهشمند است کد پاسخ 12 با کد علت خارجی 3 (اطلاعات یک بیت نامعتبر می باشد) بررسی و رفع گردد.\r\nفایل خطاهای روز &#039;2025-12-22&#039; جهت بررسی به پیوست خدمتتان ارسال خواهد شد.\r\n', '202512-1299', 3, 10, 'Condition_final_done', 'high', NULL, '2025-12-23 07:38:37', '2026-02-21 08:32:06', NULL, NULL, NULL),
	(1300, 'درخواست گزارش', 'با سلام و احترام؛\r\n\r\nخواهشمند است گزارش درخواستی برای بازه زمانی سال 1403 ارسال گردد\r\n\r\nشارژ کارت هدیه (به تفکیک نام شعب)\r\nرفع مسدودي کارت هدیه / خرید (به تفکیک نام شعب)\r\nبرگشت از واریز (به تفکیک نام شعب)\r\nدرخواست صدور کارت هدیه (به تفکیک نام شعب)\r\nصدور رمز توسط شعب (به تفکیک نام شعب)\r\n\r\nگزارشات درخواستی بصورت سرجمع (تعداد کارت و مبلغ به تفکیک شعب) و همچنین بصورت ریز (رکورد به رکورد کارت ها) مورد درخواست می باشد.', '202512-1300', 4, 52, 'Condition_final_done', 'low', NULL, '2025-12-23 10:06:41', '2026-02-22 13:58:32', NULL, NULL, NULL),
	(1301, 'تخصیص کارت به مارکت شرگت پخش هیرکان', 'باسلام و احترام\r\nخواهشمند است شماره کارت های فایل پیوست به مارکت با شناسه های  2643 و 2642  (شرگت پخش هیرکان) تخصیص داده شوند.\r\nباسپاس', '202512-1301', 1, 25, 'Condition_final_done', 'high', NULL, '2025-12-23 10:55:04', '2026-02-21 08:29:27', NULL, NULL, NULL),
	(1302, 'رسپانس کد -1 برای تراکنش های با rrn ', 'با سلام\r\nرسپانس کد -1 برای تراکنش های با rrn های 514342154856 و 514342961255\r\nمشاهده شده و تسویه انجام نشده لطفا بررسی گردد', '202512-1302', 3, 10, 'Condition_final_done', 'high', NULL, '2025-12-27 10:11:09', '2026-02-21 08:29:14', NULL, NULL, NULL),
	(1303, 'عدم ارسال تگ 99 فیلد  تگ 48 از سوی سوئیچ', 'با سلام\r\nترمینال 30651031 در پاسخ 210 فیلد 48 تگ 99 دستور چاپ از سوی سوئیچ ارسال نمیشود.\r\nیعنی تگ 99 ارسال نمیشود\r\nلطفا بررسی و رفع گردد.', '202512-1303', 3, 10, 'Condition_final_done', 'high', NULL, '2025-12-28 09:22:08', '2026-02-21 08:27:55', NULL, NULL, NULL),
	(1304, 'اعلام IP Source , distination  تان جهت درخواست دسترسی بهWrapper پارسیان', 'با سلام و احترام، با توجه به درخواست اعلامی در واتساپ به شرح زیر، لطفا آدرس های مبدا و مقصد را جهت ثبت تیکت دسترسی تان اعلام و تائید فرمائید.\r\n&quot;خانم خزلی لطفا برای پیاده سازی سرویس آنلاین مانا دسترسی به Wrapper پارسیان از طریق MikroTik مستقر در شرکت Intek باز گردد&quot;\r\n\r\nDestination:\r\n172.25.1.51:555\r\n', '202512-1304', 1, 37, 'Condition_regect', 'high', NULL, '2025-12-28 10:25:44', '2025-12-31 08:03:27', NULL, NULL, NULL),
	(1305, ' شناسه بهداد برای ترمینال31233307 ', 'با سلام و احترام\r\n\r\nبا توجه به نیاز پذیرنده با شماره ترمینال 31233307 به قابلیت انجام تراکنش با شناسه بهداد به طوری که به ازای هر تراکنش و شناسه یک واریز جداگانه انجام شود خواهشمند است در صورت امکان اقدام لازم صورت پذیرد\r\n\r\nلازم به ذکر است در حال حاضر سرویس مربوط با یک IBAN جهت پذیرنده به صورت تجمیعی تسویه می شود\r\n\r\n \r\n\r\nنمونه تراکنش : \r\n\r\nTerminalid : 31233307\r\n\r\nRRN: 514254500623\r\n\r\nAdditional data : {&quot;EncNationalCode&quot;:&quot;DJDy6TUWDaSMFE5BOdGZ6SmFKGW0cT8BH2FFFDzwMpo=&quot;,&quot;ThirdPartyCode&quot;:480,&quot;IdPay&quot;:&quot;334061374234840010018219002159&quot;}\r\n\r\n', '202512-1305', 3, 10, 'Condition_need_action', 'medium', NULL, '2025-12-28 11:41:42', '2026-02-15 10:48:18', NULL, NULL, NULL),
	(1306, 'تغییر سوئیچ کد از 3 به 7', '\r\nبا سلام\r\nخواهشمند است سوئیچ کد از 3 به 7 تغییر یابد\r\n\r\n12255250\r\n11679573\r\n11928719\r\n12254250', '202512-1306', 3, 10, 'Condition_final_done', 'medium', NULL, '2025-12-28 11:52:47', '2026-02-21 08:32:00', NULL, NULL, NULL),
