	(1362, 'عملیاتی نمودنکانال ثابت برروی سوییچ سیپا  با پورت 9731', '\r\nبا سلام و احترام\r\nبه استحضار می رساند کانال ثابت برروی سوییچ سیپا  با پورت 9731 پیاده سازی شده و تست های تراکنش انجام شده است \r\nلذا خواهشمند است در خصوص عملیاتی نمودن و انتقال تراکنش های TOSANPOSCHANNEL توسط شرکت اینتک به کانال مذکور در  ساعت 12 بامداد روز دوشنبه مورخ 6 بهمناعلام  آمادگی فرمایید.\r\nبا سپاس\r\n', '202601-1362', 3, 10, 'Condition_final_done', 'high', NULL, '2026-01-25 07:49:58', '2026-02-21 08:31:45', NULL, NULL, NULL),
	(1363, 'تغییر سوئیچ کد از 3 به 7 ', 'با سلام \r\nخواهشمند است سوئیچ کد ترمینال زیر از 3 به 7 تغییر کند\r\n12268225\r\n12245409\r\n12219124', '202601-1363', 3, 10, 'Condition_final_done', 'low', NULL, '2026-01-25 07:55:27', '2026-02-21 08:23:44', NULL, NULL, NULL),
	(1364, 'درخواست روت ترمینال انیاک', 'با سلام و احترام\r\nترمینال های فایل پیوست جهت روت انیاک تقدیم حضورتان می شود. خواهشمند است در این خصوص اقدامات لازم را مبذول فرمایید.\r\n\r\nبا تشکر', '202601-1364', 1, 31, 'Condition_final_done', 'low', NULL, '2026-01-25 09:05:07', '2026-02-22 13:15:06', NULL, NULL, NULL),
	(1365, ' درخواست ارسال شده از سوی شرکت شاپرک در خصوص ارائه راهکار Soft HSM (SSM) ', 'با سلام واحترام،\r\nبا توجه به درخواست ارسال شده از سوی شرکت شاپرک در خصوص ارائه راهکار Soft HSM (SSM) ، خواهشمنداست پیشنهادات خود را در قالب\r\nمستندات فنی و  دیاگرام عملکرد سرویس  ارائه فرمایید.  \r\n باتشکر \r\n', '202601-1365', 3, 10, 'Condition_final_done', 'high', NULL, '2026-01-25 10:08:02', '2026-02-21 08:23:37', NULL, NULL, NULL),
	(1366, 'پیاده سازی پروژه سوخت', 'با سلام\r\nخواهشمند است  پروژه سوخت پیاده سازی گردد\r\nمستندات به پیوست خدمتتان ارسال می گردد.\r\nرمز فایل از خانم کمایی دریافت گردد.\r\nبا سپاس', '202601-1366', 3, 10, 'Condition_regect', 'medium', NULL, '2026-01-25 10:30:43', '2026-04-26 09:36:03', NULL, NULL, NULL),
	(1367, 'روت ارتباط فردا', 'با درود\r\nاحتراماً، ترمینال های پیوست جهت روت ارتباط فردا، به حضورتان ارسال می گردد.\r\nبا تشکر', '202601-1367', 1, 31, 'Condition_final_done', 'low', NULL, '2026-01-25 10:36:33', '2026-02-22 13:15:03', NULL, NULL, NULL),
	(1368, 'موارد درخواستی دارندگان در گزارشات مانا با توجه به پیاده سازی سرویس ', 'با سلام و احترام،طی مذاکراه هفته گذشته با آقای محمدی در گزارش ایجاد شده برای سرویس مانا موارد زیر مورد نیاز است:\r\n1-در گروه کارت شناسه خارجی و کدتفضیل اضافه شود2-امکان جستجو با نام مشتری3- امکان جستجو با گروه پایانه4-در نمایندگی فیلد شناسه اشتباه نمایش داده می شود(بعنوان مثال کد شناسه تهران تجارت الکترونیک 1001 است اما 5 نمایش میدهد)5-شناسه اعلام شده در گروه کارت با شناسه خارجی برابر نیست 6-امکان گزارش گیری بر اساس تاریخ انقضاء با بازه های زمانی قابل انتخاب(مثلا سه ماهه)\r\nلازم بذکر است آقای محمدی گفتند با توجه به حجم داده ها و احتمال کندی در گزارشات ، موضوع را با آقای سعید موسوی نیز بررسی می کنند.', '202601-1368', 1, 37, 'Condition_final_done', 'medium', NULL, '2026-01-26 07:22:40', '2026-06-07 08:06:30', NULL, NULL, NULL),
	(1369, ' فرآیند و نام متدهای روال تغییر /افزودن شبا برای ترمینال های دارای تسهیم', 'با سلام و احترام\r\nداکیومنت فرآیند و نام متدهای روال  تغییر /افزودن شبا برای ترمینال های دارای تسهیم جهت ارائه به پیمانکار سامانه جام جم ارائه دهید.\r\nبا سپاس', '202601-1369', 3, 10, 'Condition_final_done', 'high', NULL, '2026-01-26 09:54:58', '2026-02-21 08:23:25', NULL, NULL, NULL),
