	(1399, 'پر شدن اتوماتیک سقف اعتبار برای صنوف خاص 999999999', 'با سلام واحترام\r\nبه استحضار می رساند کد اصناف ذکر شده در ذیل شامل صنوف خاص بوده خواهشمند است در صورت انتخاب هر کدام از این صنوف سقف اعتبار به صورت اتوماتیک 999999999 پر شود\r\nکد صنف:6211 صندوق های سرمایه گذاری\r\nکد صنف :6212 کارگزاری های بورسی\r\nکد صنف :9803 خودرویی(کسب و کار های ویژه)\r\n\r\n\r\nبا سپاس فراوان', '202602-1399', 1, 10, 'condition_acepted_test_auto', 'medium', NULL, '2026-02-03 07:44:08', '2026-08-12 15:51:45', NULL, NULL, NULL),
	(1400, 'پیاده سازی قابلیت کیوسک بر روی بک آفیس صادرکنندگی', 'باسلام و احترام\r\nخواهشمند است بر روی منوی قابلیت  بک آفیس صادرکنندگی، قابلیت بر روی پایانه &quot; کیوسک &quot; نیز اضافه گردد.\r\nباسپاس', '202602-1400', 1, 25, 'condition_acepted_test_auto', 'high', NULL, '2026-02-03 09:23:45', '2026-05-10 14:58:14', NULL, NULL, NULL),
	(1401, 'عدم نمایش اطلاعات تماس برخی کارت ها - درخواست بررسی علت', 'پیرو تیکت های ایجاد شده در خصوص عدم نمایش اطلاعات تماس برخی کارت ها (بعنوان نمونه تیکت 1164 و 1347 ) و تکرار این مورد برای برخی کارت های جدید، خواهشمند است در خصوص بررسی علت بروز این امر و اتخاذ رویکرد اجرایی جهت جلوگیری از تکرار آن اقدام فرمایید. با سپاس ', '202602-1401', 8, 52, 'condition_acepted_test_auto', 'low', NULL, '2026-02-03 10:08:00', '2026-05-11 12:26:14', NULL, NULL, NULL),
	(1402, 'ایجاد دسترسی با نقش رونوشت انفرادی', 'نام کاربری m.safdel	با نقش رونوشت انفرادی ایجاد شده است لذا خواهشمند است در خصوص ایجاد تغییرات لازم جهت مشابهت با دسترسی e.ostovar  اقدامات لازم را مبذول فرمایید. با سپاس\r\n(نمونه تیکت قبل 1222 )', '202602-1402', 4, 52, 'condition_acepted_test_auto', 'low', NULL, '2026-02-03 11:17:47', '2026-03-15 11:46:45', NULL, NULL, NULL),
	(1403, 'روت ارتباط فردا', ' \r\nبا سلام و عرض ادب\r\n \r\nاحتراماً، ترمینال های پیوست جهت روت، به حضورتان ارسال می گردد.\r\n', '202602-1403', 1, 31, 'condition_acepted_test_auto', 'low', NULL, '2026-02-03 11:39:27', '2026-03-14 08:31:21', NULL, NULL, NULL),
	(1404, 'عدم فراخوانی متد OrderCancelation در برخی از تراکنش های فارا', 'با درود\r\nمطابق با روال پیشین در صورتی که متد ItemOrder از فارا فراخوانی شود و تراکنش منجر به تراکنش خرید نگردد (مشتری تراکنش را رها کند) یک تراکنش 420 از سمت ترمینال برای سویچ ارسال گردیده تا حساب مشتری از بلاک بودن رها شود\r\nاما سمت سوئیچ می بایست متد OrderCancelation به محض دریافت تراکنش 420 از سمت پایانه از فارا فراخوانی گردد که متاسفانه این عملیات انجام نشده و حدود 5 دقیقه کلیه تراکنش ها از سمت فارا با پاسخ &quot;description\\&quot;:\\&quot;user have a active request\\&quot; مواجه می گردد\r\nدر صورتی که متد OrderCancelation بعد از دریافت تراکنش 420 از سمت ترمینال از فارا فراخوانی گردد دیگر تراکنش ها با پاسخ اعلامی مواجه نمی شوند\r\nبا تشکر', '202602-1404', 3, 31, 'condition_acepted_test_auto', 'low', NULL, '2026-02-07 06:41:11', '2026-06-08 06:41:12', NULL, NULL, NULL),
	(1405, 'درخواست داکیومنت سرویس اطلاعات تماس نمایندگی', 'با سلام و احترام، لطفا مستندات موجود را ارائه فرمائید. با سپاس', '202602-1405', 1, 37, 'Condition_regect', 'medium', NULL, '2026-02-07 07:08:03', '2026-02-07 13:47:19', NULL, NULL, NULL),
	(1406, 'درخواست شارژ (خانم قانع)', 'وضعیت شماره اندیکاتور 11459504 &quot;انجام شده&quot; می باشد ولی در جزییات &quot;در حال انجام&quot; می باشد. مطابق پیوست\r\n\r\nدرخواست دهنده: خانم قانع - تلفنی\r\n', '202602-1406', 4, 52, 'condition_acepted_test_auto', 'low', NULL, '2026-02-07 09:25:50', '2026-03-15 11:46:45', NULL, NULL, NULL),
	(1407, 'درخواست روت ترمینال انیاک', 'با سلام و احترام\r\nترمینال های فایل پیوست جهت روت انیاک تقدیم حضورتان می شود. خواهشمند است در این خصوص اقدامات لازم را مبذول فرمایید.\r\nبا تشکر', '202602-1407', 1, 31, 'condition_acepted_test_auto', 'low', NULL, '2026-02-07 09:37:51', '2026-03-14 08:31:21', NULL, NULL, NULL),
	(1408, 'بررسی هزینه و تغییرات حذف چهار صفر از پول ملی', 'با سلام واحترام،\r\n          با عنایت به نامه ارسال شده از سوی شرکت شاپرک در خصوص اجرای حذف چهار صفر از پول ملی و لزوم اجرای این طرح در شبکه پرداخت، خواهشمند است  بررسی لازم در این خصوص صورت پذیرد و هزینه ها و تغییرات مرتبط با این موضوع، مطابق سر فصل های اعلامی در متن نامه و یا سر فصل های کلان دیگر  تهیه و جهت ارائه به شاپرک  تا تاریخ 1404-11-19 ارسال گردد.\r\n  باتشکر \r\n \r\n', '202602-1408', 3, 10, 'Condition_need_action', 'high', NULL, '2026-02-07 09:41:41', '2026-02-09 06:05:46', NULL, NULL, NULL),
	(1409, 'عدم نمایش ترمینال در بک افیس', 'با سلام\r\nترمینال 06136315  با تاریخ نصب 26-03-1403 \r\nدر بک افیس نمایش داده نمیشود. \r\nلطفا بررسی گردد.', '202602-1409', 3, 10, 'condition_acepted_test_auto', 'high', NULL, '2026-02-07 09:59:47', '2026-03-14 11:38:06', NULL, NULL, NULL),
	(1410, 'درخواست وب سرویس اطلاعات تماس نمایندگی(CR467671)', 'با سلام و احترام، لطفا وب سرویسی برای دو فرم پیوست جهت Callکردن اطلاعات تماس ایجاد شود .', '202602-1410', 2, 37, 'Condition_regect', 'medium', NULL, '2026-02-07 11:36:22', '2026-02-18 10:28:58', NULL, NULL, NULL),
	(1411, 'دسترسی سامانه تیکتینگ (کیارش یوسفی)', 'دسترسی سامانه تیکتینگ (کیارش یوسفی)', '202602-1411', 4, 52, 'condition_acepted_test_auto', 'low', NULL, '2026-02-07 13:40:24', '2026-03-15 11:46:45', NULL, NULL, NULL),
	(1412, 'کدخطای 58 فارا', 'با سلام\r\nترمینال 30780938 در تراکنش فارا خطای 58 دریافت می کند\r\n دامپ پیوست جهت بررسی به شرکت فارا اعلام گردید و پاسخ (این ترمینال به دلیل توکن اشتباه این خطا را دارد ( توکن قبلی ارسال شده) ) از آن شرکت دریافت شد\r\nخواهشمند است علت ارسال توکن منقضی شده بررسی و اعلام گردد.\r\nبا سپاس\r\n', '202602-1412', 3, 10, 'Condition_regect', 'medium', NULL, '2026-02-07 13:52:18', '2026-02-14 09:14:35', NULL, NULL, NULL),
	(1413, 'افزودن رکورد واریز بر روی رسید صورتحساب کیوسک', 'با سلام و احترام\r\nخواهشمند است رکورد واریز بر روی رسید صورتحساب کیوسک اضافه گردد، در حال حاضر صفر نمایش داده میشود.\r\nرسیدصورتحساب  کیوسک و رسید صورتحساب  خودپرداز برای آقای پرویزی و آقای محمدی قبلا ارسال شده است.\r\nباسپاس', '202602-1413', 1, 25, 'Condition_regect', 'high', NULL, '2026-02-07 14:28:52', '2026-06-07 09:06:06', NULL, NULL, NULL),
	(1414, 'اعمال تسهیم به صورت اشتباه', 'با سلام\r\n احتراما به استحضار می رساند؛ در پروژه ی نیلودرمان نوتاش(تراکنش با گروه کارت های مشخص شده ی نوتاش)، بعد از ثبت ترمینال باید ابتدا تخفیف بر روی ترمینال انجام شود و بعد از اعمال تخفیف، روی مبلغ باقی مانده بین حساب ها تسهیم صورت پذیرد .\r\nدر حال حاضر تسهیم و تخفیف جهت ترمینال های موردنظر بر روی سوییچ تعریف شده است، ولی تقسیم مبلغ به درستی انجام نمی شود و به این صورت است که ابتدا بر روی حساب شریک تجاری تعریف شده، از روی کل مبلغ( قبل از اعمال شدن تخفیف) تسهیم اعمال می شود و سپس بر روی کل مبلغ، تخفیف اعمال می شود و باقی مانده ی مبلغ شریک تجاری از مبلغ با تخفیف، برای شبای اصلی واریز می گردد .\r\nنمونه ترمینال جهت بررسی بیشتر خدمت حضور ارسال می گردد :\r\n31717082\r\nترمینال فوق دارای 11 درصد تخفیف و 4 درصد تسهیم بر روی حساب شریک تجاری  می باشد \r\nشماره مرجع: 514916816610  کل مبلغ تراکنش: 100000   مبلغ بعد از اعمال تخفیف : 89000\r\nمبلغ بعد از اعمال تسهیم 96 درصد و تخفیف11 درصد برروی شبای اصلی به شماره ی  IR810550131000207506004001  برابر 85000 در صورتی که مبلغ صحیح باید 85440 باشد \r\nمبلغ بعد از اعمال تسهیم 4 درصد و تخفیف 11 درصد برروی شبای شریک تجاری به شماره ی  IR070550131044507538573002  برابر 4000 در صورتی که مبلغ صحیح باید 3560 باشد\r\n\r\n\r\n11992494 \r\n\r\nشماره مرجع 514721149578   مبلغ کل: 1000000   مبلغ بعد از اعمال تخفیف: 850000  دارای 15 درصد تخفیف و 4.1 درصد تسهیم \r\nIR750550131085006713234001   مبلغ اعمال شده بعد از تخفیف و تسهیم :809,000 در صورتیکه مبلغ صحیح باید 815150 باشد \r\nIR070550131044507538573002  مبلغ اعمال شده بعد از تخفیف و تسهیم  :41,000  در صورتیکه مبلغ صحیح باید 34850 باشد\r\n\r\n', '202602-1414', 3, 10, 'condition_acepted_test_auto', 'high', NULL, '2026-02-08 07:48:45', '2026-03-14 11:38:06', NULL, NULL, NULL),
	(1415, 'راه اندازی کانال محلی تاپ و بانک پارسیان-اندیکاتور 11459(CR424217)', 'با سلام و احترام، پیرو مذاکره تلفنی با آقای حیدری مقدم لطفا در خصوص راه اندازی کانال محلی با بانک کارآفرین(کانال دوازدهم) دستور مقتضی صادر نمائید.با تشکر\r\n', '202602-1415', 2, 37, 'Condition_need_action', 'low', NULL, '2026-02-08 09:56:08', '2026-06-29 06:08:05', NULL, NULL, NULL),
	(1416, 'بررسی لایه حذف 4 صفر از پول ملی', 'با درود\r\nمطابق تصمیم گیری در خصوص حذف 4 صفر از پول ملی خواهشمند است دستور فرمایید\r\nزمانبندی تغییرات نرم افزاری سوئیچ پرداخت به این شرکت اعلام گردد\r\nبا تشکر', '202602-1416', 2, 31, 'Condition_regect', 'high', NULL, '2026-02-08 11:29:39', '2026-05-26 06:04:25', NULL, NULL, NULL),
	(1417, 'اطلاعات mask شده ی فیلد ۵۵', 'با سلام و احترام\r\n\r\nلاگ زیر داده ی مربوط به ریسپانس تراکنش خرید نظام مهندسی اردبیل می باشد.\r\nدر صورتی که مقدار 4 بایت اول آن را نمایش بدهیم به صورت\r\n0؟؟؟ در می آید. خواهشمندم این مورد را از طریق اینتک پیگیری نمایید که چه Valueای برای ما ارسال می کنند.\r\n\r\nبا تشکر\r\n\r\nfield 55 len: 19\r\nfield 55 bufferlog: 07 30 01 01 00 02 50 00 00 00 00 00 00 00 00 00 00 00 00', '202602-1417', 1, 31, 'condition_acepted_test_auto', 'low', NULL, '2026-02-09 05:55:20', '2026-05-02 07:11:31', NULL, NULL, NULL),
	(1418, 'روت ارتباط فردا', 'با سلام و عرض ادب\r\n \r\nاحتراماً، ترمینال های پیوست جهت روت ارتباط فردا، به حضورتان ارسال می گردد.\r\nخواهشمند است جهت اعلام به نمایندگیها در صورت انجام روت در ایمیل پاسخ ارسال فرمایید.\r\n', '202602-1418', 1, 31, 'condition_acepted_test_auto', 'low', NULL, '2026-02-09 07:06:15', '2026-03-14 08:31:21', NULL, NULL, NULL),
	(1419, 'تغییر سوئیچ کد از 3 به 7', '11615018\r\n11961091\r\n12020762\r\n11799568\r\n11870771\r\nخواهشمند است کد ترمینال های فوق از 3 به 7 تغییر یابد', '202602-1419', 3, 10, 'Condition_final_done', 'high', NULL, '2026-02-09 08:03:16', '2026-04-05 06:36:30', NULL, NULL, NULL),
	(1420, 'امکان انتخاب نوع مسدودی کارت (مسدودی با امکان شارژ/بدون امکان شارژ)-اندیکاتور43640 ', 'با سلام و احترام\r\nهمانطور که مستحضرید در حال حاضر اگر کارتی مسدود باشد، امکان واریز شارژ به آن کارت میسر می باشد.\r\nخواهشمند است ترتیبی اتخاذ فرمایید تا انسداد در 2 حالت زیر صورت پذیرد:\r\n1. کارت مسدودی که امکان شارژ داشته باشد.\r\n2. کارت مسدودی که امکان شارژ نداشته باشد.\r\nبا تشکر', '202602-1420', 2, 37, 'condition_acepted_test_auto', 'low', NULL, '2026-02-09 10:17:15', '2026-06-20 10:51:35', NULL, NULL, 'CR468664'),
	(1421, 'موارد بک افیس جدید', 'با سلام  احترام\r\nموارد بک افیس جهت بررسی و اصلاح به پیوست خدمتتان ارسال می گردد.', '202602-1421', 3, 10, 'condition_in_progress', 'high', NULL, '2026-02-09 11:33:53', '2026-04-20 12:51:06', NULL, NULL, ''),
	(1422, 'بررسی بیت 116 در سوئیچ اینتک', 'با سلام و احترام\r\nدر تراکنش های کهربا تراکنش های ورودی ترمینال به سوئیچ فیلد 116 موجود است مطابق با لاگ ضمیمه ، فیلد فوق شناسه برنامه انجام دهنده تراکنش است\r\n\r\nخواهشمند است دستور فرمایید آیا شناسه فوق ذخیره می گردد یا خیر، در صورتی که شماسه فوق ذخیره نمی گردد دستور فرمایید نسبت به ذخیره و ارائه ویو پایگاه داده اقدام گردد\r\nبا تشکر', '202602-1422', 3, 31, 'condition_acepted_test_auto', 'medium', NULL, '2026-02-10 11:06:17', '2026-08-15 05:09:28', NULL, NULL, ''),
	(1423, 'تغییر سوئیچ کد از 3 به 7', 'تغییر سوئیچ کد از 3 به 7\r\n12221141\r\n11465928\r\n', '202602-1423', 3, 10, 'Condition_final_done', 'high', NULL, '2026-02-10 12:43:34', '2026-02-14 12:40:06', NULL, NULL, ''),
	(1424, 'تراکنش موفق با رسید ناموفق', 'با سلام و احترام\r\nبرخی از تراکنش ها با وجود رسید ناموفق و صدور 420 توسط کارتخوان، موفق و با پذیرنده تسویه می گردد\r\n\r\nنمونه تراکنش :\r\nترمینال : 21534226\r\nمرجع : 858690457396\r\nمبلغ : 120,000,000 ریال\r\nتاریخ : 1404.11.20\r\n\r\nتراکنش فوق با وجود صدور 420 ساید 1 بلافاصله پس از تراکنش، دارای 220 ساید 2 توسط سوئیچ است و طبق استعلام از حسابداری الکترونیک موفق و تسویه شده است.\r\nاین موارد با توجه به رسید صادره موجب شکایت مشتری گردیده است.\r\nباسپاس', '202602-1424', 3, 31, 'Condition_final_done', 'high', NULL, '2026-02-14 05:40:13', '2026-04-05 06:36:36', NULL, NULL, ''),
	(1425, 'شارژ دلخواه کارتخوان', 'با سلام و احترام\r\nپیرو تست انجام شده در خصوص شارژ تاپ آپ با مبلغ دلخواه خطای پیوست مشاهده گردیده است\r\nبا تشکر', '202602-1425', 3, 31, 'condition_acepted_test_auto', 'medium', NULL, '2026-02-14 05:43:02', '2026-05-23 06:56:02', NULL, NULL, ''),
	(1426, 'روت ارتباط فردا', 'با سلام و عرض ادب\r\n \r\nاحتراماً، ترمینال های پیوست جهت روت ارتباط فردا، به حضورتان ارسال می گردد.\r\n \r\nبا سپاس\r\n', '202602-1426', 1, 31, 'Condition_final_done', 'low', NULL, '2026-02-14 13:18:35', '2026-04-05 06:36:26', NULL, NULL, ''),
	(1427, 'تسویه تراکنش با اینکه ترمینال ریورز داشته است', 'باسلام و احترام\r\nخواهشمند است بررسی فرمایید چرا تراکنش با شماره مرجع 858576567569 دارای Mti 420 ریورس ان مشخص نگردیده است\r\nبا درود', '202602-1427', 3, 31, 'Condition_final_done', 'high', NULL, '2026-02-15 12:28:20', '2026-04-05 06:36:16', NULL, NULL, ''),
	(1428, 'پیاده سازی سامانه اینتک دارندگی جدید', 'با سلام و احترام؛\r\nعطف به جلسه برگزار شده در خصوص پیاده سازی سامانه جدید اینتک دارندگی خواهشمند است در خصوص موارد ذیل اقدام مقتضی صورت پذیرد:\r\n1. تمام قسمت های توسعه یافته نسخه جدید بر روی سرور کنونی (پورت تستی) و سرور جدید راه اندازی و عملیاتی شود.\r\n2. موارد توسعه ای سامانه جدید در 4 فصل جهت بررسی در جلسات اعلام گردد.  ', '202602-1428', 2, 52, 'condition_in_progress', 'low', NULL, '2026-02-15 13:47:17', '2026-04-20 12:51:05', NULL, NULL, ''),
	(1429, 'دریافت پروتکل از اینتک - خرید کالابرگ با رمز OTP', 'با درود\r\nخواهشمند است در خصوص پیاده سازی تراکنش های فارا کالا برگ مبتنی بر OTP به جای شماره کارت و پیاده سازی متد های جدید مطابق با مستند جدید، دستور فرمایید پیش فاکتور مربوطه در خصوص ارائه پروتکل جدید برای تولید ترمینال ارائه گردد\r\nitemorderbyotp\r\npurchaseinquirybyotp\r\nconfirmorderbyotp\r\nreverseorderbyotp\r\nordercancelationbyotp', '202602-1429', 2, 31, 'Condition_pendency', 'medium', NULL, '2026-02-16 06:16:44', '2026-05-26 11:26:47', NULL, NULL, ''),
	(1430, 'خالی کردن فضای دیسک 10.0.71.112', 'با سلام\r\nacq-proc01 free disk space on c:\\\\10.0.71.112\r\nخواهشمند است فضای دیسک خالی گردد.\r\nبا سپاس', '202602-1430', 3, 10, 'condition_acepted_test_auto', 'high', NULL, '2026-02-16 06:29:23', '2026-03-14 11:38:06', NULL, NULL, ''),
	(1431, 'درخواست روت ترمینال انیاک', 'با سلام و احترام\r\nترمینال های فایل پیوست جهت روت انیاک تقدیم حضورتان می شود. خواهشمند است در این خصوص اقدامات لازم را مبذول فرمایید.\r\nبا تشکر', '202602-1431', 1, 31, 'condition_acepted_test_auto', 'low', NULL, '2026-02-16 07:35:38', '2026-03-14 08:31:21', NULL, NULL, ''),
	(1432, 'عدم ارسال پیامک برای الگوی تعاونی اعتبار کارکنان گروه صنعتی ایران خودرو', 'با سلام ودرود \r\nلطفا&quot; ترتیبی اتخاذ فرمایید  برای الگوی تعاونی اعتبار کارکنان گروه صنعتی ایران خودرو از رنج 6013510 الی 6063510 هرگونه پیامک (اعم از تراکنش، اعلام موجودی و سایر موارد)  ارسال نگردد . باتشکر \r\n\r\nدرخواست دهنده : Leili Hejazi\r\nتیکت :   SR468882', '202602-1432', 8, 52, 'condition_acepted_test_auto', 'low', NULL, '2026-02-16 07:35:47', '2026-05-16 05:33:48', NULL, NULL, '  SR468882'),
	(1433, 'تغییر قابلیت والگو در کارتهای مددجویان', 'با سلام خواهشمند است قابلیت خرید در الگوی کارت مددجویان از مبلغ 15,000,000 ریال به 20.000.000  و همچنین \r\nدر قسمت الگو کلیه ی الگوهای مددجویان در حداکثر اعتبار شتابی از 150.000.000 ریال به 200.000.000 ریال تغییر یابد. باتشکر\r\n\r\nدرخواست دهنده: Nahid Rohallahzadeh\r\nتیکت:   SR469605', '202602-1433', 8, 52, 'Condition_final_done', 'low', NULL, '2026-02-16 07:41:11', '2026-04-05 06:36:08', NULL, NULL, '  SR469605'),
	(1434, 'درخواست حذف شماره تقاضا ', 'با سلام و احترام \r\nخواهشمند است به دستور سرکار خانم رو ح الله زاده ، به دلیل امکان ثبت مجدد رونوشت کارت ها به دلیل خطای شماره کارت کمتر از 14 روز رونوشت شده باید  شماره تقاضای اعلام شده در اینتک حذف شود .\r\n662025-661921-661660-661580-661517-661516-661514-661513-661512-661511-661693-661545-661572\r\n\r\nدرخواست دهنده : vosgha jafari\r\nتیکت :   SR466216', '202602-1434', 8, 52, 'Condition_final_done', 'low', NULL, '2026-02-16 07:43:06', '2026-04-05 06:35:57', NULL, NULL, '  SR466216'),
	(1435, 'آخرین آپدیت سیگنالینگ سایت پشتیبان', 'با سلام\r\nخواهشمند است با توجه به ممیزی شاپرک، آخرین آپدیت سیگنالینگ سایت پشتیبان را تا تاریخ 26-11-1404 ارائه فرمایید \r\nبا سپاس', '202602-1435', 3, 10, 'Condition_final_done', 'high', NULL, '2026-02-16 08:00:30', '2026-04-05 06:35:51', NULL, NULL, ''),
	(1436, 'خطا در تعویض iban در دستگاه', 'با درود و ادب\r\nهنگام تعویض حساب با شماره سه در پوز به خطا میخورند\r\n\r\nترمینال : 31281202 و 31281203\r\n\r\nMTI-1:700\r\nPrCode-1:10\r\n\r\nعلت داخلی : 12-3-رکوردی برای نگاشت کد پردازش یافت نشد', '202602-1436', 1, 31, 'condition_acepted_test_auto', 'medium', NULL, '2026-02-16 09:27:22', '2026-03-14 08:31:21', NULL, NULL, ''),
	(1437, 'روت ارتباط فردا', 'با سلام و عرض ادب\r\n \r\nاحتراماً، ترمینال های پیوست جهت روت، به حضورتان ارسال می گردد.\r\n \r\nبا سپاس\r\n', '202602-1437', 1, 31, 'condition_acepted_test_auto', 'low', NULL, '2026-02-16 12:22:44', '2026-03-14 08:31:21', NULL, NULL, ''),
