	(1462, 'UP و Down کردن کانل 7093', 'با سلام \r\nخواهشمند است UP و Down کردن کانل 7093 صورت پذیرد.\r\nبا سپاس\r\n', '202602-1462', 3, 10, 'condition_acepted_test_auto', 'high', NULL, '2026-02-22 08:46:12', '2026-04-05 13:44:07', NULL, NULL, ''),
	(1463, 'درخواست روت ترمینال ارتباط فردا', 'با سلام و عرض ادب\r\n \r\nاحتراماً، ترمینال های پیوست جهت روت ارتباط فردا، به حضورتان ارسال می گردد.\r\n', '202602-1463', 1, 31, 'Condition_final_done', 'low', NULL, '2026-02-22 10:57:48', '2026-04-05 06:28:47', NULL, NULL, ''),
	(1464, 'عدم درج کلید واژه Service در بخش اطلاعات اضافی تراکنش سرویس پرداخت', 'با سلام و احترام \r\n\r\nپیرو اطلاعات پیوست\r\nاطلاعات سرویس پرداخت تراکنش های اعلامی در فیلد pAddData ثبت شده اما در ویو CT_TransactionData  اینتک رکوردی با DataKey=Service  بابت آن ثبت نشده است ، در اطلاعات ضمیمه شده نمونه ای از اطلاعات به عنوان مثال ذکر شده است که کلید واژه Service را دارا می باشد\r\n\r\nشماره مرجع نمونه:\r\n858896305463\r\n858896309178\r\n858896311536', '202602-1464', 3, 31, 'condition_acepted_test_auto', 'low', NULL, '2026-02-23 04:33:44', '2026-04-08 09:37:35', NULL, NULL, ''),
	(1465, 'درخواست روت ترمینال انیاک', 'با سلام و احترام\r\nترمینال های فایل پیوست جهت روت انیاک تقدیم حضورتان می شود. خواهشمند است در این خصوص اقدامات لازم را مبذول فرمایید.\r\nبا تشکر', '202602-1465', 1, 31, 'Condition_final_done', 'low', NULL, '2026-02-23 07:17:48', '2026-02-24 13:06:37', NULL, NULL, ''),
	(1466, 'تغییر سوئیچ کد از 3 به 7', 'با سلام و احترام\r\nخواهشمند است سوئیچ کد از 3 به 7 تغییر کند- این مرتبط با قبل هست جدید نیست\r\n\r\nترمینال: 12255709', '202602-1466', 3, 10, 'Condition_final_done', 'high', NULL, '2026-02-23 09:08:31', '2026-04-05 06:27:54', NULL, NULL, ''),
	(1467, 'گزارش  گروه کارت تنخواه - قبضینو', 'باسلام و احترام\r\nخواهشمند است گزارشات ذیل به دلیل حجم بالای رکوردها ارسال گردد:\r\n1.گزارش شارژ مخزن قبضینو  از تاریخ  14031001 تا 14041130\r\n2.گزارش تراکنش های گروه کارت تنخواه - قبضینو  از تاریخ  14031001 تا 14041130\r\nباسپاس', '202602-1467', 1, 25, 'condition_acepted_test_auto', 'high', NULL, '2026-02-23 12:00:57', '2026-05-10 14:58:14', NULL, NULL, ''),
	(1468, 'درخواست روت ترمینال انیاک', 'با سلام و احترام\r\nترمینال های فایل پیوست جهت روت انیاک تقدیم حضورتان می شود. خواهشمند است در این خصوص اقدامات لازم را مبذول فرمایید.\r\nبا تشکر', '202602-1468', 1, 31, 'Condition_final_done', 'low', NULL, '2026-02-24 08:28:35', '2026-04-05 06:27:40', NULL, NULL, ''),
	(1469, 'آپدیت UID', 'با سلام \r\nخواهشمند است UID  ترمینال های لیست پیوست آپدیت گردد.\r\nبا سپاس', '202602-1469', 3, 10, 'Condition_final_done', 'high', NULL, '2026-02-24 11:34:18', '2026-04-05 06:27:23', NULL, NULL, ''),
	(1470, 'حذف بین بانک ها با االویت بالا مطابق با نامه شاپرک', 'با درود\r\nحذف بین بانک ها با شناسه های زیر مطابق با سند پیوست و نامه شاپرک\r\n(&#039;627381&#039;,&#039;505809&#039;,&#039;636949&#039;,&#039;639599&#039;,&#039;505801&#039;,&#039;507677&#039;,&#039;636214&#039;)', '202602-1470', 1, 31, 'condition_acepted_test_auto', 'high', NULL, '2026-02-25 05:44:07', '2026-04-26 05:51:45', NULL, NULL, ''),
	(1471, 'عدم اعمال تخفیف برای تراکنش های فارا', 'با سلام و احترام\r\nبا توجه به اینکه اعتبار فارایی در فیلد 5 و مبلغ تخفیفهم در فیلد 5 درج میشود خواهشمند است برای تراکنش های فارا تخفیف اعمال نشود\r\nبا سپاس', '202602-1471', 3, 10, 'condition_acepted_test_auto', 'high', NULL, '2026-02-25 07:51:10', '2026-05-02 10:36:08', NULL, NULL, ''),
	(1472, ' افزدون شبای شریک تجاری', '\r\n\r\nبا سلام\r\n\r\nخواهشمند است شبای فایل ضمیمه به صورت دستی اصلاح گردد.\r\n\r\nبا سپاس\r\n\r\n\r\nبا سپاس \r\n', '202602-1472', 3, 10, 'condition_acepted_test_auto', 'high', NULL, '2026-02-25 14:17:52', '2026-05-11 08:43:12', NULL, NULL, ''),
	(1473, 'اصلاح نام فروشگاه مطابق با لیست زیر بر روی پایگاه داده ', 'با درود\r\nخواهشمند است نام پذیرنده و نام فروشگاه و ترمینال مطابق با لیست ضمیمه به روز رسانی گردد\r\nبا تشکر', '202603-1473', 3, 31, 'condition_acepted_test_auto', 'low', NULL, '2026-03-14 08:32:47', '2026-05-02 07:11:31', NULL, NULL, ''),
	(1474, 'تغییر موجودی الگوی مددجویان', 'مطابق فایل پیوست\r\nتغییر موجودی ثابت الگوی مددجویان با کد محصول 42 و 44 از 150000000 به 200.000.000 ریال (حداکثر اعتبار شتابی) و تراکنش خرید از 18.000.000 به 40.000.000 ریال ', '202603-1474', 4, 52, 'condition_acepted_test_auto', 'medium', NULL, '2026-03-15 11:51:00', '2026-04-06 16:14:30', NULL, NULL, '22641'),
	(1475, 'درخواست تمدید تاریخ انقضا', 'درخواست دهنده: خانم روح اله زاده\r\nتیکت : SR472792\r\n\r\nبا سلام و احترام\r\nخواهشمند است در صورت امکان نسبت به تمدید تاریخ انقضا کارت هایی که تا تاریخ انقضا آن ها 1405/01/31 می باشد را تا یک سال افزایش دهید به جز موارد ذیل:\r\nنوع کارت ذیل:\r\nکارت هدیه\r\nگروه کارت های ذیل:\r\nمارکت اول\r\nپارتیان\r\nدفاتر پیشخوان\r\nبهساز کاشانه\r\nبهسامان\r\nاتکا\r\nنجم خاورمیانه\r\nالگو ذیل:\r\nمجازی', '202603-1475', 4, 52, 'condition_acepted_test_auto', 'medium', NULL, '2026-03-16 09:14:25', '2026-05-02 11:41:32', NULL, NULL, ''),
	(1476, 'افزایش سقف مبلغ ترمینال های فعال', 'با سلام و احترام\r\n لطفا سقف مبلغ برای تمامی ترمینال ها با وضعیت فعال پوز از دو مبلغ\r\n1000000001 و 2000000001 به 4000000001 ریال افزایش یابد\r\nلطفا فقط همین دو مبلغ افزایش یابد\r\nبا تشکر', '202603-1476', 3, 31, 'condition_acepted_test_auto', 'low', NULL, '2026-03-16 09:43:26', '2026-05-16 06:44:33', NULL, NULL, ''),
	(1477, 'خطا در تراکنش ترمینال 11651648 ', 'با سلام و احترام\r\nترمینال 11651648 با انجام تراکنش خطای 58 با شرح &quot;58-6-حساب در جدول شماره حساب ها برای ترمینال یافت نشد&quot; دریافت میکند.\r\nلطفا بررسی فرمایید.\r\nبا تشکر', '202603-1477', 3, 31, 'condition_acepted_test_auto', 'low', NULL, '2026-03-17 05:47:23', '2026-04-08 09:37:35', NULL, NULL, ''),
	(1478, 'تمدید تاریخ انقضا بن کارت - جانبازان', 'با سلام و احترام؛\r\nخواهشمند است کارتهای پیوست از پایان زمان تاریخ انقضا به مدت یکسال تمدید گردد.\r\nبا تشکر', '202603-1478', 1, 25, 'condition_acepted_test_auto', 'high', NULL, '2026-03-25 08:44:50', '2026-04-22 05:44:26', NULL, NULL, ''),
	(1479, 'خطای 58 ترمینال 15462552', 'با درود و ادب\r\n\r\n15462552\r\nخطای 58 دارند\r\n\r\n58-4-بر اساس جدول مجوزها، ترمینال مجاز به انجام این نوع تراکنش نیست\r\n\r\n\r\n=======\r\nشماره تماس\r\nآقای کیکاوسی : 09145581079', '202603-1479', 1, 31, 'condition_acepted_test_auto', 'low', NULL, '2026-03-28 07:32:15', '2026-04-18 06:27:43', NULL, NULL, ''),
	(1480, 'مسدود سازی امکان شارژ کارت های کادونا', 'با سلام و احترام؛ خواهشمند است در خصوص سلب امکان شارژ تمامی کارت های کادونا که تا کنون شارژ نشده اند *** غیر از کار های فایل پیوست (آخرین درخواست کادونا 14041224 با شماره اندیکاتور)*** اقدام فرمایید. با سپاس', '202603-1480', 4, 52, 'condition_acepted_test_auto', 'medium', NULL, '2026-03-29 13:00:54', '2026-04-27 08:53:45', NULL, NULL, ''),
	(1481, 'گزارش ', 'باسلام و احترام\r\nخواهشمند است گزارشات ذیل ارسال گردد.\r\nباسپاس\r\n1. گزارش سرجمع شارژ به تفکیک گروه مشتری از تاریخ ۳۰ بهمن ۱۴۰۳ تا ۳۰ بهمن \r\n۱۴۰۴\r\n2.گزارش سرجمع خرجکرد(تراکنش) به تفکیک گروه مشتری از تاریخ ۳۰ بهمن ۱۴۰۳ تا ۳۰ بهمن ۱۴۰۴\r\n3. گزارش سرجمع مانده به تفکیک گروه مشتری از تاریخ ۳۰ بهمن ۱۴۰۳ تا ۳۰ بهمن ۱۴۰۴\r\n4.هر ۳ گزارش اول مجدد برای تاریخ ۱ فروردین ۱۴۰۴ تا پایان اسفند ۱۴۰۴\r\n5. هر ۳ گزارش اول برای تاریخ ۱ فروردین ۱۴۰۳ تا پایان اسفند ۱۴۰۳\r\n6.هر ۳ گزارش اول برای تاریخ ۱ فروردین ۱۴۰۲ تا پایان اسفند ۱۴۰۲\r\n', '202604-1481', 1, 25, 'condition_acepted_test_auto', 'high', NULL, '2026-04-01 11:20:44', '2026-05-10 14:58:14', NULL, NULL, ''),
	(1482, 'گزارش سرجمع شارژ ، سرجمع خرجکرد , مانده به تفکیک هر کارت', 'باسلام و احترام\r\nخواهشمند است گزارش ذیل از تاریخ  &quot; 1  بهمن ۱۴۰۳ &quot;  تا   &quot;۳۰ دی ۱۴۰۴ &quot;   ایجاد گردد.\r\n\r\nدر گزارش فقط بن کارت ها ( کارت هدیه و مجازی جز گزارش نباشند  ) در نظر گرفته شوند.\r\n\r\nفیلدهای گزارش شامل :\r\n1.شماره کارت\r\n2. گروه کارت \r\n3.سرجمع شارژ _  شارژ بک آقبسی و وب سرویسی\r\n****برای گروه پارتیان تراکنش های انتقال به هم به عنوان نوع تراکنش شارژ در نظر گرفته شود.\r\n\r\n4.سرجمع خرجکرد(تراکنش) _ همه تراکنش های موفقی که مبلغ از کارت کاربر کسر شده است شامل خرید، شارژ قبض ، برداشت از خودپرداز و ....\r\n\r\n5.مانده تاریخ 30 دی 1404 هر کارت \r\n\r\n\r\nباسپاس', '202604-1482', 1, 25, 'condition_acepted_test_auto', 'high', NULL, '2026-04-04 05:30:24', '2026-05-10 14:58:14', NULL, NULL, ''),
	(1483, 'ایجاد دسترسی با نقش رونوشت انفرادی', 'نام کاربری s.taghitabar با نقش رونوشت انفرادی ایجاد شده است لذا خواهشمند است در خصوص ایجاد تغییرات لازم جهت مشابهت با دسترسی e.ostovar اقدامات لازم را مبذول فرمایید. با سپاس', '202604-1483', 8, 52, 'condition_acepted_test_auto', 'low', NULL, '2026-04-04 09:19:15', '2026-05-02 11:41:32', NULL, NULL, ''),
	(1484, 'تغییر ساعت ویو  (Txn800-soc) ', 'با سلام احترام،\r\n\r\nجهت دریافت صحیح لاگ های تراکنش های 0800، دستگاه های کارتخوان لازم است view ساخته شده تیم امنیت (Txn800-soc) در دیتابیس b2stxn سرور .10210.0.72 ، زمان از 48 ساعت اخیر به بعد ست (فیلتر) شود.\r\n\r\nبا تشکر.', '202604-1484', 4, 10, 'condition_acepted_test_auto', 'medium', NULL, '2026-04-04 09:22:18', '2026-04-26 07:12:45', NULL, NULL, ''),
	(1485, ' گزارش شارژ کارت اسفند ماه', 'باسلام و احترام\r\nخواهشمند است گزارش شارژ کارت اسفند ماه از اول اسفند ماه تا 30 اسفند ماه ارسال گردد.\r\nگزارش شامل فیلدهای ذیل باشد:\r\n\r\nگروه کارت \r\nشماره کارت\r\nنوع کارت \r\nنام نمایندگی\r\nمبلغ شارژ\r\nتاریخ شارژ\r\nابزار شارژ\r\n\r\nباسپاس', '202604-1485', 1, 25, 'condition_acepted_test_auto', 'high', NULL, '2026-04-05 08:17:07', '2026-05-10 14:58:14', NULL, NULL, ''),
	(1486, 'گزارش رسوب اسفند ماه', 'باسلام و احترام\r\nخواهشمند است گزارش رسوب اسفند ماه از اول اسفند ماه تا 30 اسفند ماه ارسال گردد.\r\nگزارش شامل فیلدهای ذیل باشد:\r\n\r\nگروه کارت \r\nشماره کارت\r\nنوع کارت \r\nنام نمایندگی\r\nرسوب \r\nسود\r\n\r\nباسپاس', '202604-1486', 1, 25, 'condition_acepted_test_auto', 'high', NULL, '2026-04-05 08:19:17', '2026-05-10 14:58:14', NULL, NULL, ''),
	(1487, 'کدخطای 96', 'باسلام و احترام\r\nشماره کارت ذیل با کد خطای 96  مواجه می گردد.\r\n6274-1244-9000-0878\r\n\r\nخواهشمند است جهت رفع مشکل راه حل ارایه بفرمایید.\r\nباسپاس', '202604-1487', 1, 25, 'condition_acepted_test_auto', 'high', NULL, '2026-04-05 09:42:45', '2026-05-02 06:05:45', NULL, NULL, ''),
	(1488, 'خطای بیزینسی روی وب سرویس تخصیص کارت به گروه کارت در پذیرندگی', 'خطای بیزینسی روی وب سرویس تخصیص کارت به گروه کارت در پذیرندگی \r\n\r\n{\r\n  &quot;success&quot;: false,\r\n  &quot;errors&quot;: [\r\n    {\r\n      &quot;code&quot;: &quot;E22-1357&quot;,\r\n      &quot;message&quot;: &quot;کارت متعلق به گروه کارت دیگر می باشد.&quot;\r\n    }\r\n  ]\r\n}\r\n\r\n\r\ncurl -X &#039;POST&#039; \\\r\n  &#039;http://172.25.1.59:7080/api/card-groups/90/assign-card-to-cardGroup&#039; \\\r\n  -H &#039;accept: /&#039; \\\r\n  -H &#039;Content-Type: application/json&#039; \\\r\n  -d &#039;{\r\n  &quot;panNumber&quot;: &quot;5041721099739030&quot;\r\n}&#039;', '202604-1488', 8, 52, 'condition_acepted_test_auto', 'low', NULL, '2026-04-06 16:15:30', '2026-05-11 05:08:22', NULL, NULL, ''),
	(1489, 'دریافت خطای 12 در هنگام تغییر حساب، ترمینال به شماره 13947403', 'با درود\r\nدریافت خطای 12 در هنگام تغییر حساب، شبا سمت اینتک موجود است\r\n\r\n\r\n2026-04-08 13:01:17.401\r\n![CDATA[[Transaction Manager]]\r\n[TMS_ChangeActiveAccount]	\r\n[TMS_ChangeActiveAccount]	Trace Number = 000005\r\n[TMS_ChangeActiveAccount]	Transaction persisted with ID = 92075853384\r\n[TMS_ChangeActiveAccount]	Try to change new IBAN=IR570560080281000777777015\r\n[TMS_ChangeActiveAccount]	Try to call other switch\r\n[TMS_ChangeActiveAccount]	try to send=&gt;{&quot;CardHolderIpAddress&quot;:&quot;1.1.1.1&quot;,&quot;RequestorAPP&quot;:&quot;SEPSW&quot;,&quot;MTI&quot;:700,&quot;PrCode&quot;:&quot;100014&quot;,&quot;Pan&quot;:null,&quot;Amount&quot;:0.0,&quot;TraceNo&quot;:&quot;5&quot;,&quot;LocalDatetime&quot;:&quot;2026-04-08T13:01:17.3585297+03:30&quot;,&quot;PosCondition&quot;:14,&quot;IIN&quot;:&quot;581672041&quot;,&quot;RRN&quot;:0,&quot;TerminalNo&quot;:&quot;13947403&quot;,&quot;AdditionalData&quot;:&quot;IR570560080281000777777015&quot;,&quot;Currency&quot;:0,&quot;PinBlock&quot;:null,&quot;CVV&quot;:null,&quot;ExpireDate&quot;:null,&quot;OriginalTxnInfo&quot;:&quot;&quot;,&quot;AdditionalItems&quot;:{},&quot;MAC&quot;:&quot;&quot;}\r\n[TMS_ChangeActiveAccount]	recive response 40 from sw={&quot;MTI&quot;:710,&quot;PrCode&quot;:&quot;100014&quot;,&quot;Pan&quot;:null,&quot;Amount&quot;:0.0,&quot;SettlementAmount&quot;:0.0,&quot;TraceNo&quot;:&quot;5&quot;,&quot;LocalDatetime&quot;:&quot;2026-04-08T13:01:17&quot;,&quot;IIN&quot;:&quot;581672041&quot;,&quot;RRN&quot;:0,&quot;TerminalNo&quot;:&quot;13947403&quot;,&quot;AuditCode&quot;:&quot;000005&quot;,&quot;AdditionalData&quot;:&quot;IR570560080281000777777015&quot;,&quot;Currency&quot;:0,&quot;ResponseCode&quot;:12,&quot;AdditionalItems&quot;:{},&quot;MAC&quot;:&quot;&quot;}\r\n[TMS_ChangeActiveAccount]	try to set old account=IR250560080281000777777009\r\n[TMS_ChangeActiveAccount]	Change OLD Account IR250560080281000777777009