	(1490, 'لیست سرویس پرداخت‌های اینتک', 'درخواست لیست سرویس پرداخت‌های اینتک - مطابق فایل پیوست', '202604-1490', 8, 52, 'condition_acepted_test_auto', 'low', NULL, '2026-04-11 06:36:23', '2026-05-02 11:41:32', NULL, NULL, '45780 '),
	(1491, 'روت ارتباط فردا', 'با سلام و عرض ادب\r\n\r\nاحتراماً، ترمینال های پیوست جهت روت ارتباط فردا، به حضورتان ارسال می گردد.\r\n\r\nبا سپاس\r\n', '202604-1491', 3, 31, 'condition_acepted_test_auto', 'low', NULL, '2026-04-11 08:01:03', '2026-05-02 07:11:31', NULL, NULL, ''),
	(1492, 'درخواست روت ترمینال انیاک', 'با سلام و احترام\r\nترمینال های فایل پیوست جهت روت انیاک تقدیم حضورتان می شود. خواهشمند است در این خصوص اقدامات لازم را مبذول فرمایید.\r\nبا تشکر', '202604-1492', 3, 31, 'condition_acepted_test_auto', 'low', NULL, '2026-04-11 08:03:05', '2026-05-02 07:11:31', NULL, NULL, ''),
	(1493, ' استعلام شاهکار در قسمت کارت کارت', 'باسلام به اطلاع میرساند \r\nسامانه استعلام شاهکار در قسمت اینتک دارندگی قسمت کارت / کارت\r\nشماره کارت  را که جستجو میکنیم و اطلاعات مشتری را که می آورد و از  قسمت عملیات/ اطلاعات تماس / اطلاعات تماس که اصلاح میشود خطای شماره موبایل مربوط به این کدملی نمیباشد میدهد. // به عنوان مثال شماره کارت خودم 6221064807147422 // با شماره موبایل 09123487643 \r\nاصلاح شماره تماس کارت بصورت گروهی و تکی هر دو باتیک استعلام شاهکار خطا میدهد.\r\n\r\nکاربر اعلام کننده : Leila Suzani\r\nشماره تیکت: IR473731', '202604-1493', 8, 52, 'condition_acepted_test_auto', 'low', NULL, '2026-04-11 11:28:26', '2026-05-11 05:08:22', NULL, NULL, 'IR473731'),
	(1494, 'درخواست بررسی تراکنش با شماره مرجع  68092578604 ', 'باسلام و احترام\r\nتراکنش با شماره مرجع 68092578604 بر روی پایانه آسان پرداخت صورت گرفته و مبلغ تراکنش از کارت باموفقیت کسر شده است و پیرو  پیگیری صورت گرفته از سمت شرکت  آسان پرداخت مبلغ به حساب پذیرنده واریز نشده و مبلغ به حساب پرداخت نوین برگشت داده شده است. \r\nپیرو بررسی صورت گرفته از واحد مالی پرداخت نوین مبلغ به حساب پرداخت نوین برگشت داده نشده است.\r\nخواهشمند است تراکنش کذکور را بررسی بفرمایید.\r\nباسپاس', '202604-1494', 1, 25, 'condition_acepted_test_auto', 'high', NULL, '2026-04-11 13:07:03', '2026-05-12 14:46:04', NULL, NULL, ''),
	(1495, ' ساخت کلید عمومی TLS 1.2 برای سوئیچ سپ 1 اینتک', 'با سلام و احترام\r\n\r\n   نظر به منقضی شدن کلید عمومی شرکت پرداخت الکترونیک سامان (041 و 043) در تاریخ 11/02/1405 ، مقتضی است اقدامات لازم در خصوص تولید و ارسال کلید عمومی جدید لایه TLS (Certificate) را بعمل آورید.\r\n\r\n ساخت کلید عمومی TLS 1.2 برای سوئیچ سپ 1 اینتک\r\n\r\nبا تجدید احترام\r\n', '202604-1495', 3, 31, 'condition_acepted_test_auto', 'high', NULL, '2026-04-12 08:28:12', '2026-05-17 09:46:03', NULL, NULL, ''),
	(1496, 'مستند شرکت قسطی کارت_ پروژه والد و فرزند', 'با سلام و احترام \r\nپیرو پیاده سازی مستند شرکت قسطی کارت جهت راه اندازی پروژه والد و فرزند بر روی سویییچ صادرکنندگی پرداخت نوین ، خواهشمند است API ارسالی شرکت قسطی کارت را بررسی نمایید و مشکلات و موارد احتمالی را جهت رفع توسط آن شرکت اعلام نمایید.\r\n\r\nآدرس API مطابق ذیل می باشد.\r\nhttps://auth.radpay.co/\r\n\r\nباسپاس', '202604-1496', 1, 25, 'Condition_regect', 'high', NULL, '2026-04-12 11:53:03', '2026-05-02 08:05:12', NULL, NULL, ''),
	(1497, 'ایجاد کاربر صندوق', 'باسلام و احترام\r\nخواهشمند است بر روی بک آفیس صادرکنندگی منوی &quot; حسابداری &quot; برای خانم سحر فروزان ،  صندوق کاربری ایجاد گردد.\r\nباسپاس', '202604-1497', 1, 25, 'condition_acepted_test_auto', 'high', NULL, '2026-04-13 07:34:13', '2026-05-10 14:58:14', NULL, NULL, ''),
	(1498, 'عدم امکان ثبت یوزر جدید در بک افیس جدید و عدم نمایش خطا', 'با سلام\r\nهنگام ثبت یوزر جدید در بک افیس جدید  خطا مشاهده میشود ولی در باکس خطا پیامی مشاهده نمیشود.\r\nبا سپاس', '202604-1498', 1, 10, 'condition_acepted_test_auto', 'medium', NULL, '2026-04-13 07:44:38', '2026-05-23 05:36:40', NULL, NULL, ''),
	(1499, 'ایجاد گزارش سرجمع واریز ، خرجکرد ،مانده به تفکیک گروه کارت', 'باسلام و احترام\r\nخواهشمند است گزارش &quot;سرجمع واریز ، خرجکرد ،مانده به تفکیک گروه کارت&quot; بر روی بک آفیس صادرکنندگی مطابق با فیلدهای فایل پیوست ایجاد گردد.\r\n\r\nخواهشمند است تراکنش های سروشی، سندهای برگشتی نیز بر رو گزارش مذکور در نظرفته شوند.\r\n\r\nباسپاس\r\n\r\n', '202604-1499', 1, 25, 'condition_acepted_test_auto', 'high', NULL, '2026-04-13 10:03:36', '2026-05-24 11:22:03', NULL, NULL, ''),
	(1500, 'گزارش سرجمع واریز ، خرجکرد ،مانده به تفکیک کارت', 'باسلام و احترام\r\nخواهشمند است گزارش &quot;سرجمع واریز ، خرجکرد ،مانده به تفکیک کارت&quot; بر روی بک آفیس صادرکنندگی مطابق با فیلدهای فایل پیوست ایجاد گردد.\r\n\r\nخواهشمند است تراکنش های سروشی، سندهای برگشتی نیز بر رو گزارش مذکور در نظر گرفته شوند.\r\n\r\nباسپاس\r\n', '202604-1500', 1, 25, 'condition_acepted_test_auto', 'high', NULL, '2026-04-13 10:07:27', '2026-05-24 11:22:03', NULL, NULL, ''),
	(1501, 'کندی گزارش شارژ کارت', 'باسلام و احترام \r\nبه استحضار می رساند بر روی گزارش شارژ کارت، دریافت خروجی csv/Excel بسیار زمانبر می باشد.\r\n\r\nخواهشمند است جهت بهینه سازی گزارش اقدامات مقتضی را مبذول نمایید.\r\n\r\nبه عنوان نمونه خروجی Excel  گزارش با فیلتر های ذیل پس از گذشت  10 دقیقه دانلود نگردید و همچنان پیغام &quot;لطفا تا آماده شدن فایل صبور باشید&quot;  نمایش داده میشود:\r\nبازه 22 فروردین تا 23 فروردین\r\nگروه کارت بن-قرارگاه سیدالشهدا\r\nحاوی 6320 رکورد می باشد\r\n\r\nباسپاس', '202604-1501', 1, 25, 'condition_in_progress', 'high', NULL, '2026-04-13 10:16:22', '2026-04-13 13:09:33', NULL, NULL, ''),
	(1502, 'عدم صحت گزارش سرجمع تراکنش به تفکیک گروه کارت', 'باسلام و احترام\r\nخواهشمند است موارد ذیل بر روی گزارش &quot;سرجمع تراکنش به تفکیک گروه کارت &quot; اعمال و اصلاح گردد:\r\n\r\n1. فیلتر &quot; وضعیت تراکنش  &quot; و &quot; نوع واریز برداشت &quot; حذف گردد و در خروجی تراکنش های موفق برداشت نمایش داده شود.\r\n\r\n2. تعداد و مبلغ نمایش داده شده در گزارش مذکور با گزارش &quot; تراکنش کارت &quot; مطابقت ندارد. اطلاعات گزارش تراکنش کارت صحیح می باشد.\r\n( به عنوان نمونه بر روی گزارش سرجمع تراکنش به تفکیک گروه کارت با انتخاب تاریخ 22 تا 23 فروردین و گروه کارت بن-پرسنل پرداخت نوین تعداد 104 می باشد و همین فیلتر بر  روی گزارش تراکنش دارای 60 رکورد می باشد )\r\n\r\nباسپاس\r\n\r\n', '202604-1502', 1, 25, 'condition_acepted_test_auto', 'high', NULL, '2026-04-13 10:25:26', '2026-05-24 11:22:03', NULL, NULL, ''),
	(1503, 'روت انیاک', 'با سلام و احترام\r\nترمینال های فایل پیوست جهت روت انیاک تقدیم حضورتان می شود. خواهشمند است در این خصوص اقدامات لازم را مبذول فرمایید.\r\nبا تشکر', '202604-1503', 1, 31, 'condition_acepted_test_auto', 'low', NULL, '2026-04-15 07:45:47', '2026-05-05 08:38:20', NULL, NULL, ''),
	(1504, 'درخواست لیست تراکنش‌های مانا', 'درخواست لیست تراکنش‌های مانا مطابق فایل پیوست\r\nدرخواست دهنده: حسین مرادی\r\nاندیکاتور: داخلی 821 - 05\r\n', '202604-1504', 4, 52, 'condition_acepted_test_auto', 'low', NULL, '2026-04-15 09:34:52', '2026-05-11 05:08:22', NULL, NULL, '821 '),
	(1505, 'درخواست روت ترمینال انیاک', 'با سلام و احترام\r\nترمینال های فایل پیوست جهت روت انیاک تقدیم حضورتان می شود. خواهشمند است در این خصوص اقدامات لازم را مبذول فرمایید.\r\nبا تشکر', '202604-1505', 1, 31, 'condition_acepted_test_auto', 'low', NULL, '2026-04-18 06:34:00', '2026-05-09 08:50:16', NULL, NULL, ''),
	(1506, 'روت ارتباط فردا', 'با سلام و عرض ادب\r\n\r\nاحتراماً، ترمینال های پیوست جهت روت، به حضورتان ارسال می گردد.\r\n', '202604-1506', 1, 31, 'condition_acepted_test_auto', 'low', NULL, '2026-04-19 11:01:19', '2026-05-09 08:50:16', NULL, NULL, ''),
	(1507, 'درخواست تغییر آدرس،نام کاربری و کلمه عبور سرویس شاهکار در سرویس های صدور کارت بک آفیس صادر کنندگی', 'بنا به اعلام آقای عاطفی و خانم تربتی و نیز تائیدیه جناب آقای رضائی ، این مورد در مدت بحران جنگ بصورت شفاهی در دستور کار قرار گرفته و این تیکت صرفا جهت درج در سوابق موارد توسعه ثبت می گردد', '202604-1507', 2, NULL, 'Condition_acepted_test', 'low', NULL, '2026-04-19 12:53:43', '2026-08-02 07:30:20', 16, 9, 'CR473705'),
	(1508, ' مسدود سازی امکان شارژ کارت های کادونا ( 202603-1480 )-درخواست ثبت شده توسط آقای عاطفی', '(این درخواست قبلا طی تیکت 1480 اینتک انجام شده ولی با توجه به نیاز توسعه ای و جهت ثبت در سوابق توسعه مجددا ثبت می گردد)\r\nبا سلام و احترام؛ خواهشمند است در خصوص سلب امکان شارژ تمامی کارت های کادونا که تا کنون شارژ نشده اند *** غیر از کار تهای فایل پیوست (آخرین درخواست کادونا 14041224 با شماره اندیکاتور)*** اقدام فرمایید. با سپاس', '202604-1508', 10, NULL, 'condition_acepted_test_auto', 'low', NULL, '2026-04-19 12:56:29', '2026-08-12 15:51:45', 16, 9, 'CR473659'),
	(1509, 'افزودن شماره موبایل در منوی کارت جهت جستجوی کارتهای متصل به آن', 'خواهشمند است در اینتک دارندگی قسمت کارت / کارت  / یک گزینه به نام شماره همراه (یا موبایل ) اضافه شود و امکان جستجوی  شماره کارتهای متصل به هر شماره همراه ایجاد شود.\r\n (همانند گزینه جستجوی کدملی ) در این قسمت تمام کارتهایی که با یک کد ملی ثبت شده نمایش داده میشود. باتشکر ', '202604-1509', 2, NULL, 'Condition_done', 'low', NULL, '2026-04-19 12:58:03', '2026-10-05 08:19:12', 16, 9, 'CR471770'),
	(1510, 'گزارش اعمال تغییرات توسط کاربر در بک آفیس', 'با سلام و احترام\r\nتمهیداتی بعمل آورید که تغییرات اعمالی توسط هر کاربر در بک آفیس بر روی هر ترمینال شامل تمامی آیتم ها ذخیره گردد، لازم به ذکر است در دیتابیس رفاه پردیس بصورت view در اختیار این شرکت قرار گیرد. \r\nبا تشکر\r\n', '202604-1510', 3, 26, 'condition_in_progress', 'low', NULL, '2026-04-19 13:18:44', '2026-04-20 06:51:36', NULL, NULL, ''),
	(1511, 'گزارش کلی تراکنش های سویچ', 'با سلام و احترام\r\nدرخواست گزارش از تاریخ 1404/12/09 تا 1405/01/31 تعداد کل تراکنش ها شامل موفق و ناموفق و میانگین زمان ریسپانس سوییچ ، به تفکیک هر روز \r\nدر اختیار این شرکت قرار گیرد. \r\nبا تشکر', '202604-1511', 3, 26, 'condition_acepted_test_auto', 'low', NULL, '2026-04-20 07:23:35', '2026-05-12 12:00:31', NULL, NULL, ''),
	(1512, 'محدود کردن مبلغ تراکنش بالای 200 میلیون تومان برای ترمینالهای لیست پیوست', 'با سلام\r\nخواهشمند است امکان انجام تراکنش با مبلغ  بالای 200 میلیون تومان برای ترمینالهای لیست پیوست وجود نداشته باشد.\r\nبا سپاس', '202604-1512', 3, 10, 'condition_acepted_test_auto', 'high', NULL, '2026-04-20 08:50:00', '2026-05-11 08:43:12', NULL, NULL, ''),
	(1513, 'درخواست شارژ', 'با سلام و احترام خواهشمند است در خصوص شارژ موارد فایل پیوست اقدام فرمایید. با سپاس', '202604-1513', 4, 52, 'condition_acepted_test_auto', 'low', NULL, '2026-04-20 10:32:59', '2026-05-11 05:08:22', NULL, NULL, '10384'),
	(1514, 'خطای شبا در گرارش همگام سازی', 'با سلام و احترام\r\nتعدادی از شباهایی که در تعریف ترمینال یا فرآیند تغییرحساب،حذف و اضافه شبا و... در گزارش همگام سازی سوییچ با خطای &quot;شبا یافت نشد و شماره شبا متعلق به مشتری نمی باشد &quot;می دهد و در اینتک شباها قابل مشاهده نیست خواهشمند است بررسی نمایید.\r\nترمینال نمونه در تعریف ترمینال\r\n15473502 IR120180000000005412700270\r\n15472079 IR680130100000000071041229\r\nترمینال نمونه در حذف و اضافه شبا\r\n31257529 IR130600460679708475234001\r\n13139214 IR520600760670414009761001\r\n---------------------------------------------------------\r\nبا سلام و احترام\r\n\r\nاین خطا به این دلیل است که مشتری که این شبا را دارد در سمت اینتک غیر فعال می باشد اما شماره شبا فعال می باشد و به این دلیل سرویس اینتک خطا می دهد و همچنین در بک آفیس ایتک قابل مشاهده نمی باشد. خواهشمند است از سمت اینتک پیگیری شود.\r\n\r\nبا تشکر\r\n\r\n\r\n\r\nبا تشکر', '202604-1514', 1, 31, 'condition_acepted_test_auto', 'medium', NULL, '2026-04-21 03:54:03', '2026-05-16 06:44:33', NULL, NULL, ''),
	(1515, 'ارسال نامعتبر Track2 در کارت های جدید بانک تجارت', 'با درود\r\nمطابق لاگ های ضمیمه و اطلاع رسانی بانک تجارت، در صورتی که تراکنش مربوطه با کارت جدید از روی نود پردازنده 2 و 3 و 26 برای شاپرک ارسال گردد تراکنش موفق است اما در صورتی که پردازنده تراکنش نود 23 گردد تراکنش از سوی صادر کننده با خطای 56 با کد علت 900 مواجه می گردد که بعد از پیگیری از بانک مشخص شده است دلیل ارائه خطا مربوط به نامعتبر ارسال شدن فیلد 35 و Track2 تراکنش است\r\nلازم به توضیح است پیشتر عملیات تست بر روی دستگاه ترمینال های متصل به نود 23 انیاک و خود سپ انجام شده است و Track2 ارسالی مقدار صحیح زیر را برای پردازنده ارسال کرده است، تست بر روی پردازنده داخلی سپ نیز انجام شده است که تراکنش موفق است\r\nمقدار Track2 صحیح\r\n5859831600010895=31041005622801842254\r\nتصاویر رسید تراکنش و لاگ پردازنده ها ضمیمه هستند\r\nخواهشمند است بررسی بفرمایید\r\nبا تشکر\r\n', '202604-1515', 3, 31, 'condition_acepted_test_auto', 'high', NULL, '2026-04-21 07:56:41', '2026-05-16 06:44:33', NULL, NULL, ''),
	(1516, 'روت ارتباط فردا', 'با سلام و عرض ادب\r\n\r\nاحتراماً، ترمینال های پیوست جهت روت، شرکت ارتباط فردا به حضورتان ارسال می گردد.\r\n\r\nبا سپاس', '202604-1516', 3, 31, 'condition_acepted_test_auto', 'low', NULL, '2026-04-21 11:20:54', '2026-05-11 12:02:42', NULL, NULL, ''),
	(1517, 'درخواست روت ترمینال انیاک', 'با سلام و احترام\r\nترمینال های فایل پیوست جهت روت انیاک تقدیم حضورتان می شود. خواهشمند است در این خصوص اقدامات لازم را مبذول فرمایید.\r\nبا تشکر', '202604-1517', 1, 31, 'condition_acepted_test_auto', 'low', NULL, '2026-04-22 05:45:57', '2026-05-11 12:02:42', NULL, NULL, ''),
	(1518, 'وضـعیت اسـتعلام مانا کارتها به همراه وضعیت سیستمی آنها (فعال/ غیرفعال)', 'با سلام و احترام؛\r\nگزارش درخواستی از\r\n[ 172.25.16.77].[dbo.ISSCard].[B2SCard]\r\nدریافت گردید لذا با توجه به خالی بودن فیلد ismana برای اکثر کارت ها، خواهشمند است رهنمود فرمایید.', '202604-1518', 4, 52, 'condition_acepted_test_auto', 'low', NULL, '2026-04-25 09:12:56', '2026-05-23 06:24:43', NULL, NULL, '2182 '),
	(1519, 'Amir Pay Api ', 'باسلام و احترام\r\nخواهشمند است در خصوص کالکشن ارسالی شرکت Amir Pay اعلام نظر بفرمایید.\r\nباسپاس', '202604-1519', 1, 25, 'Condition_regect', 'high', NULL, '2026-04-25 11:11:42', '2026-05-02 07:51:12', NULL, NULL, ''),
	(1520, 'درخواست روت ترمینال شرکت ارتباط فردا', 'با سلام و عرض ادب\r\n\r\nاحتراماً، ترمینال های پیوست جهت روت، شرکت ارتباط فردا به حضورتان ارسال می گردد.\r\n\r\nبا سپاس', '202604-1520', 3, 31, 'condition_acepted_test_auto', 'low', NULL, '2026-04-26 05:52:40', '2026-05-16 06:44:33', NULL, NULL, ''),
	(1521, 'گزارش رسوب و شارژ کارت فروردین ماه', '\r\nگزارش رسوب و شارژ کارت\r\n\r\n\r\nباسلام و احترام \r\nخواهشمند است :\r\n1. گزارش رسوب فروردین ماه از اول فروردین  ماه تا 31 فروردین ارسال گردد. گزارش شامل فیلدهای ذیل باشد: گروه کارت شماره کارت نوع کارت نام نمایندگی رسوب سود\r\n2. گزارش شارژ کارت اسفند ماه از اول فروردین  ماه تا 31 فروردین ارسال گردد. گزارش شامل فیلدهای ذیل باشد: گروه کارت شماره کارت نوع کارت نام نمایندگی مبلغ شارژ تاریخ شارژ ابزار شارژ\r\n\r\n باسپاس\r\n', '202604-1521', 1, 25, 'condition_acepted_test_auto', 'high', NULL, '2026-04-26 06:51:37', '2026-05-18 05:58:05', NULL, NULL, ''),
	(1522, 'پروتکل پوز به سوئیچ با قابلیت پرداخت از طریق NFC برای شرکت ebcom ', 'با سلام \r\nخواهشمند است مستند پروتکل ارتباطی پوز به سوئیچ با قابلیت پرداخت از طریق  NFC\r\nرا  جهت پیاده سازی امکان خرید شارژ در اپلیکیشن ebcom (شرکت همراه اول)  ارائه فرمایید.\r\nبا سپاس', '202604-1522', 11, 10, 'Condition_archive', 'high', NULL, '2026-04-26 10:47:07', '2026-08-01 10:38:33', NULL, NULL, ''),
	(1523, 'لاگ فیلد ۴۸ استعلام بسته اینترنتی', 'با سلام و احترام؛\r\n\r\nدر استعلام بسته‌های اینترنتی مربوط به ترمینال شماره ۱۳۵۵۸۵۵۵ و در فیلد ۴۸ آن مشکلی با شرح زیر وجود دارد:\r\nIrancell / postpaid / daily\r\n\r\nRequest (100):\r\nopertorId = 2 (Irancell)\r\nduration = 2 (daily)\r\ntype = 1 (postpaid)\r\n\r\nf48 = 2;2;1;\r\n\r\nResponse (110):\r\nF39: 00\r\nF48: 13742000000011880010C8D3CAE5373530E3900013743000000015433011C8D3CAE5312E3590ED9000\r\n\r\nF48Parse:\r\nChargeCode: 1374 (2 Bytes)\r\nPrice: 200000001188 (6 Bytes)\r\nTitleLen: 00 (1 Byte)\r\n\r\nهمانگونه که مشخص است، مقدار Price و TitleLen به اشتباه کد شده است. \r\nاین مشکل در همراه اول نیز وجود دارد اما در رایتل وجود ندارد.\r\n\r\n\r\nRightel / postpaid / daily\r\n\r\nF48 request: 3;2;1;\r\n\r\nF48 response: 034000000009647007C8353030E39000034100000012925006C83190ED9000034200000019778006C83390ED9000\r\n\r\nParse f48 for Rightel:\r\n\r\n0340\r\n000000096470\r\n07\r\nC8353030E39000\r\n\r\n0341\r\n000000129250\r\n06\r\nC83190ED9000\r\n\r\n0342\r\n000000197780\r\n06\r\nC83390ED9000\r\n', '202604-1523', 3, 31, 'condition_acepted_test_auto', 'low', NULL, '2026-04-26 11:31:10', '2026-05-23 06:56:02', NULL, NULL, ''),
	(1524, 'خطا در تعریف ترمینال', 'با سلام و احترام\r\nتعدادی از ترمینال ها در گزارش همگام سازی با نوع درخواست تعریف ترمینال در وضعیت ناموفق قرار می گیرد پس از چندین مرتبه ارسال هم تغییری در وضعیت رخ نمی دهدخواهشمند است علت را بررسی نمایید.\r\nترمینال نمونه: 15483808 ،15483807\r\nبا تشکر', '202604-1524', 1, 31, 'condition_acepted_test_auto', 'low', NULL, '2026-04-26 11:47:43', '2026-08-08 10:29:31', NULL, NULL, ''),
	(1525, 'درخواست روت ترمینال شرکت ارتباط فردا', 'با سلام و عرض ادب\r\n\r\nاحتراماً، ترمینال های پیوست جهت روت، شرکت ارتباط فردا به حضورتان ارسال می گردد.\r\n\r\nبا سپاس', '202604-1525', 1, 31, 'condition_acepted_test_auto', 'low', NULL, '2026-04-27 04:09:05', '2026-05-17 09:46:03', NULL, NULL, ''),
	(1526, 'خطای 57 ترمینال 30011416', 'با سلام\r\nترمینال  تستی  30011416\r\nروی کانال تستی 40800 خطای 57 در لاگان (Mti=800) دریافت می کند\r\nلطفا بررسی گردد.', '202604-1526', 3, 10, 'condition_acepted_test_auto', 'high', NULL, '2026-04-27 05:30:13', '2026-05-16 12:52:10', NULL, NULL, ''),
	(1527, ' ایجاد دسترسی با نقش رونوشت انفرادی', 'نام کاربری m.akbaripour با نقش رونوشت انفرادی ایجاد شده است لذا خواهشمند است در خصوص ایجاد تغییرات لازم جهت مشابهت با دسترسی e.ostovar اقدامات لازم را مبذول فرمایید. با سپاس', '202604-1527', 4, 52, 'condition_acepted_test_auto', 'low', NULL, '2026-04-27 06:33:47', '2026-05-16 14:35:42', NULL, NULL, ''),
	(1528, 'درخواست روت ترمینال انیاک', '\r\nجناب آقای پهلوان\r\nبا سلام و احترام\r\nترمینال های فایل پیوست جهت روت انیاک تقدیم حضورتان می شود. خواهشمند است در این خصوص اقدامات لازم را مبذول فرمایید.\r\nبا تشکر', '202604-1528', 1, 31, 'condition_acepted_test_auto', 'low', NULL, '2026-04-27 07:16:33', '2026-05-17 09:46:03', NULL, NULL, ''),
	(1529, 'افزایش سقف مبلغ تراکنش به 4,000,000,000  برای ثبت های جدید ', 'با سلام و احترام\r\nبا توجه به افزایش سقف مبلغ تراکنش به 4,000,000,000 مبلغ  ریال (در تاریخ  10 اسفند ماه 1404)، اما در خصوص ترمینال هایی جدید ثبت شده همچنان سقف مبلغ  2,000,000,000 ریال میباشد.\r\nخواهشمند است رفع گردد.\r\n', '202604-1529', 3, 10, 'condition_acepted_test_auto', 'medium', NULL, '2026-04-27 07:31:05', '2026-05-23 05:36:40', NULL, NULL, ''),
	(1530, 'ایجاد تب جدید  در بک افیس جهت تعیین سقف و کف مبلغ برای هر صنف ', 'با سلام  و احترام\r\nخواهشمند است تب جدیدی در بک افیس جهت تعیین سقف و کف مبلغ برای هر صنف ایجاد گردد.\r\nبا سپاس', '202604-1530', 1, 10, 'condition_in_progress', 'medium', NULL, '2026-04-27 09:02:08', '2026-04-27 10:38:19', NULL, NULL, ''),
	(1531, 'روت ارتباط فردا', '\r\nبا سلام و عرض ادب\r\n\r\nاحتراماً، ترمینال های پیوست جهت روت، شرکت ارتباط فردا به حضورتان ارسال می گردد.\r\n', '202604-1531', 1, 31, 'condition_acepted_test_auto', 'low', NULL, '2026-04-28 08:40:19', '2026-05-17 13:21:13', NULL, NULL, ''),
