	(1701, 'وضعیت بحرانی سرور 80.35', 'با سلام و احترام\r\nبا توجه به اینکه در تایم 00:00 الی 01:00 بامداد سرور 172.31.80.35 با افزایش cpu  مواجه می شود و تقریبا هر شب این اتفاق تکرار می شود و این مورد به صورت تلفنی به همکاران اینتک اطلاع داده شده ولی رفع نگردیده لطفا در سامانه تیکت اینتک این مورد را اعلام فرمایید\r\nبا تشکر\r\n', '806459358', 4, 31, 'condition_acepted_test_auto', 'high', NULL, '2026-06-08 10:07:38', '2026-06-27 07:30:46', NULL, 8, ''),
	(1702, 'پروژه ی کارت _ عدم وجود تراکنش ', 'باسلام و احترام\r\nتراکنش با مبلغ  104,488,000 و شماره مرجع 347885245068 با کارت 6274-1244-9134-2535  در تاریخ 18 خرداد اعمال شده است ولی بر روی بک آفیس نمایش داده نمی شود.\r\nلاگ وب سرویس پروژه ی کارت به پیوست ارسال می گردد.\r\nباسپاس', '406459519', 1, 25, 'condition_acepted_test_auto', 'high', NULL, '2026-06-09 08:25:56', '2026-06-20 08:07:07', NULL, 4, ''),
	(1703, 'تغییر سقف مبلغ تراکنش در سوییچ اینتک', 'با سلام و احترام\r\nلطفا برای آن دسته از ترمینال های سوییچ اینتک که سقف مبلغ تراکنش 2000000001 ریال است این مبلغ به 4000000001 ریال افزایش یابد', '806459835', 1, 31, 'condition_acepted_test_auto', 'medium', NULL, '2026-06-09 09:11:03', '2026-06-27 07:30:46', NULL, 8, ''),
	(1704, 'درخواست بررسی خطای تراکنش 58', 'با درود و احترام؛\r\nخواهشمند است خطای ترمینال 15554407 برای تراکنش هایی با مبلغ بالای 3.000.000.000 ریال را بررسی و اعلام نظر فرمایید.\r\n\r\nتراکنش بر روی نود 2 با کد مرجع 862189725567 موفق است اما کد مرجع 862189442520 بر روی نود3 خطای 58 دارد\r\n\r\nسقف پذیرنده مبلغ 400 میلیون تومان تعرفی شده است\r\nخواهشمند است بررسی بفرمایید\r\n\r\n\r\nبا سپاس', '806460183', 1, 31, 'condition_acepted_test_auto', 'medium', NULL, '2026-06-09 11:54:43', '2026-06-27 07:30:46', NULL, 8, ''),
	(1705, 'خطا در تراکنش ترمینال 58', 'با درود\r\nو موارد دیگری هستند که شبا اصلی پذیرنده در سوییچ سپ و سوییچ اینتک یکسان میباشد ولی زمان تراکنش باخطای &quot;58-6-حساب در جدول شماره حساب ها برای ترمینال یافت نشد&quot; می دهد\r\nترمینال نمونه:21025297\r\nخواهشمند است بررسی نمایید.', '806460470', 1, 31, 'condition_acepted_test_auto', 'medium', NULL, '2026-06-09 12:16:59', '2026-07-08 04:48:53', NULL, 8, ''),
	(1706, 'بررسی تغییر شبا', 'با سلام\r\nطی اعلام همکاران واحد توسعه در تماس با اینتک، همکاران اینتک اعلام داشتند که شباهای اعلامی ذیل در تاریخ های مشخص شده در سمت اینتک تغییرات داشته اند ولی در سمت سامانه های تاپ، لاگی از این تغییرات وجود ندارد لذا خواهشمند است یکی از همکاران مطلع  اینتک در ارتباط با آقای ثابت (همکاران توسعه نرم افزار تاپ) مورد را بصورت تلفنی و برخط بررسی نماید تا مشکل برطرف گردد.\r\n\r\nIR690180000000000572102327- 2026-06-09 13:39:04.067\r\n\r\nIR230180000000004333927085- 2026-06-09 13:39:00.003\r\n\r\nآقای ثابت - داخلی 3666\r\n\r\n ', '906460615', 4, 52, 'condition_acepted_test_auto', 'low', NULL, '2026-06-09 15:07:24', '2026-06-27 11:14:12', NULL, 9, ''),
	(1707, 'گزارش تراکنش کارت_ فیلتر موفق/ناموفق', 'باسلام و احترام\r\nخواهشمند است بر روی گزارش تراکنش کارت ، فیلتر موفق/ناموفق به گونه ای اضافه گردد که به ضورت پیش فرض گزارش مذکور تراکنش موفق را نمایش داده و با اعمال فیلتر &quot; ناموفق &quot; تراکنش های ناموفق نمایش داده شوند.\r\nباسپاس', '406460984', 1, 25, 'condition_in_progress', 'high', NULL, '2026-06-10 05:38:32', '2026-06-10 12:25:43', NULL, 4, ''),
	(1708, 'ایجاد دسترسی در اینتک جدید', 'با سلام \r\nخواهشمند است در خصوص ایجاد دسترسی های ذیل در سامانه جدید اینتک اقدام فرمایید:\r\n1. کیارش یوسفی ki.yousefi\r\n2. مریم سادات خزلی m.khazali\r\n3. حسام راحتی h.rahati\r\n\r\nبا سپاس', '906461282', 4, 52, 'condition_acepted_test_auto', 'low', NULL, '2026-06-10 06:14:53', '2026-06-27 11:14:12', NULL, 9, ''),
